INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Lc', 6, 'pt', '[{"numero": 1, "texto": "E aconteceu que, no segundo sábadodepois do primeiro, [Jesus] passou pelas plantações, e seus discípulos iam arrancando espigas, e comiam, debulhando-as com as mãos."}, {"numero": 2, "texto": "E alguns dos fariseus lhes disseram: Por que fazeis o que não é lícito fazer nos sábados?"}, {"numero": 3, "texto": "E Jesus lhes respondeu: Nunca lestes isto, o que Davi fez quando teve fome, ele e os que com ele estavam?"}, {"numero": 4, "texto": "Como entrou na casa de Deus, tomou, e comeu os pães da apresentação, e deu também aos que estavam com ele, [pães] que não é lícito comer, a não ser só os sacerdotes?"}, {"numero": 5, "texto": "E dizia-lhes: O Filho do homem é Senhor até do sábado."}, {"numero": 6, "texto": "E aconteceu também em outro sábado que entrou na sinagoga, e estava ensinado; e ali estava um homem que tinha a mão direita definhada."}, {"numero": 7, "texto": "E os escribas e fariseus o observavam, se o curaria no sábado; para acharem de que o acusar."}, {"numero": 8, "texto": "Mas ele bem sabia dos seus pensamentos; e disse ao homem que tinha a mão definhada: Levanta-te, e põe-te em pé no meio. E ele se levantou e se pôs de pé."}, {"numero": 9, "texto": "Então Jesus lhes disse: Uma coisa vos perguntarei: É lícito nos sábados fazer bem, ou fazer mal? Salvar uma pessoa, ou matá-la?"}, {"numero": 10, "texto": "E ele, olhando para todos em redor, disse ao homem: Estende a tua mão. E ele assim o fez; e a mão foi lhe restituída sã como a outra."}, {"numero": 11, "texto": "Então encheram-se de ira; e conversaram uns com os outros [sobre] o que fariam a Jesus."}, {"numero": 12, "texto": "E aconteceu que naqueles dias ele foi ao monte para orar; e passou a noite orando a Deus."}, {"numero": 13, "texto": "E quando já era dia, chamou a si os seus discípulos, e escolheu doze deles, a quem também chamou de apóstolos:"}, {"numero": 14, "texto": "Simão, a quem também chamou de Pedro, e seu irmão André; Tiago, e João; Filipe, e Bartolomeu."}, {"numero": 15, "texto": "Mateus, Tomé; Tiago [filho] de Alfeu, e Simão chamado “o Zelote”."}, {"numero": 16, "texto": "Judas de Tiago, e Judas Iscariotes, o mesmo que foi o traidor."}, {"numero": 17, "texto": "Ele desceu com eles, parou num lugar plano, e também [com ele] uma grande quantidade dos seus discípulos, e grande multidão do povo de toda a Judeia, de Jerusalém, da costa marítima de Tiro, e de Sidom,"}, {"numero": 18, "texto": "que tinham vindo para o ouvir, e para serem curados das suas enfermidades, como também os atormentados por espíritos imundos; e foram curados."}, {"numero": 19, "texto": "E toda a multidão procurava tocá-lo; porque dele saía poder, e curava a todos."}, {"numero": 20, "texto": "Ele levantou os olhos aos seus discípulos, e disse: Benditos sois vós, os pobres, porque o Reino de Deus é vosso."}, {"numero": 21, "texto": "Benditos sois vós que agora tendes fome, porque sereis saciados. Benditos sois vós que agora chorais, porque rireis."}, {"numero": 22, "texto": "Benditos sereis quando as pessoas vos odiarem, quando vos separarem, vos insultarem, e rejeitarem o vosso nome como mau, por causa do Filho do homem."}, {"numero": 23, "texto": "Contentai-vos nesse dia, e saltai de alegria, porque eis que grande é a vossa recompensa nos céus; pois assim os pais deles faziam aos profetas."}, {"numero": 24, "texto": "Mas ai de vós, ricos, porque já tendes a vossa consolação."}, {"numero": 25, "texto": "Ai de vós que estais saciados, porque tereis fome. Ai de vós que agora rides, porque lamentareis, e chorareis."}, {"numero": 26, "texto": "Ai de vós quando todas as pessoas falarem bem de vós; porque assim os pais deles faziam aos falsos profetas."}, {"numero": 27, "texto": "Mas a vós, que estais ouvindo, digo: amai os vossos inimigos; fazei bem aos que vos odeiam;"}, {"numero": 28, "texto": "bendizei aos que vos maldizem, e orai pelos que vos maltratam."}, {"numero": 29, "texto": "Ao que te ferir numa face, oferece-lhe também a outra; e ao que te tirar a capa, não recuses a túnica."}, {"numero": 30, "texto": "Dá a quem te pedir; e ao que te tomar o [que é] teu, não o peças de volta."}, {"numero": 31, "texto": "E como vós quereis que as pessoas vos façam, fazei-lhes vós também da mesma maneira."}, {"numero": 32, "texto": "E se amardes aos que vos amam, que mérito tereis? Pois também os pecadores amam os que os amam."}, {"numero": 33, "texto": "E se fizerdes bem aos que vos fazem bem, que mérito tereis? Pois também os pecadores fazem o mesmo."}, {"numero": 34, "texto": "E se emprestardes àqueles de quem esperais receber de volta, que mérito tereis? Pois também os pecadores emprestam aos pecadores, para receberam de volta o tanto equivalente."}, {"numero": 35, "texto": "Em vez disso, amai aos vossos inimigos, fazei o bem, e emprestai, sem nada esperar disso; e grande será a vossa recompensa, e sereis filhos do Altíssimo; porque é benigno [até] para com os ingratos e maus."}, {"numero": 36, "texto": "Portanto, sede misericordiosos, como também o vosso Pai é misericordioso."}, {"numero": 37, "texto": "Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; liberai, e vos liberarão."}, {"numero": 38, "texto": "Dai, e será vos dado; medida boa, comprimida, sacudida e transbordante vos darão no vosso colo; pois com a mesma medida que medirdes vos medirão de volta."}, {"numero": 39, "texto": "E disse-lhesuma parábola: Acaso pode o cego guiar [outro] cego? Não cairão ambos no buraco?"}, {"numero": 40, "texto": "O discípulo não está acima do seu mestre; mas todo aquele que estiver completamente capacitado será como o seu mestre."}, {"numero": 41, "texto": "E por que tu prestas atenção no cisco que está no olho do teu irmão, e não enxergas a trave que está no teu próprio olho?"}, {"numero": 42, "texto": "Ou como podes dizer a teu irmão: “Irmão, deixa-me tirar o cisco que está no teu olho”, se tu mesmo não prestas atenção na trave que está no teu olho? Hipócrita, tira primeiro a trave de teu olho, e então verás bem para tirar o cisco que está no olho do teu irmão."}, {"numero": 43, "texto": "Pois não há boa árvore que dê mau fruto, nem árvore má que dê bom fruto."}, {"numero": 44, "texto": "Porque cada árvore se conhece pelo seu próprio fruto; pois não se colhem figos dos espinheiros, nem se tiram uvas dos cardos."}, {"numero": 45, "texto": "A boa pessoa tira o bem do bom tesouro do seu coração, e a pessoa má tira o mal do mau tesouro do seu coração; pois a sua boca fala daquilo que o coração tem em abundância."}, {"numero": 46, "texto": "E por que me chamais: “Senhor!”, “Senhor!”, e não fazeis o que eu digo?"}, {"numero": 47, "texto": "Todo aquele que vem a mim, ouve as minhas palavras, e as pratica, eu vos mostrarei a quem é semelhante:"}, {"numero": 48, "texto": "Semelhante é ao homem que construiu uma casa, cavou, abriu bem fundo, e pôs o fundamento sobre a rocha; e quando veio a enchente, a corrente bateu com ímpeto naquela casa, e não a pôde abalar, porque estava fundada sobre a rocha."}, {"numero": 49, "texto": "Mas aquele que ouve e não pratica é semelhante ao homem que construiu uma casa sobre a terra, sem fundamento, na qual a corrente bateu com ímpeto, e logo caiu; e foi grande a queda daquela casa."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 6, 'en', '[{"numero": 1, "texto": "And it came to pass on the second sabbath after the first, that he went through the corn fields; and his disciples plucked the ears of corn, and did eat, rubbing them in their hands."}, {"numero": 2, "texto": "And certain of the Pharisees said unto them, Why do ye that which is not lawful to do on the sabbath days?"}, {"numero": 3, "texto": "And Jesus answering them said, Have ye not read so much as this, what David did, when himself was an hungred, and they which were with him;"}, {"numero": 4, "texto": "How he went into the house of God, and did take and eat the shewbread, and gave also to them that were with him; which it is not lawful to eat but for the priests alone?"}, {"numero": 5, "texto": "And he said unto them, That the Son of man is Lord also of the sabbath."}, {"numero": 6, "texto": "And it came to pass also on another sabbath, that he entered into the synagogue and taught: and there was a man whose right hand was withered."}, {"numero": 7, "texto": "And the scribes and Pharisees watched him, whether he would heal on the sabbath day; that they might find an accusation against him."}, {"numero": 8, "texto": "But he knew their thoughts, and said to the man which had the withered hand, Rise up, and stand forth in the midst. And he arose and stood forth."}, {"numero": 9, "texto": "Then said Jesus unto them, I will ask you one thing; Is it lawful on the sabbath days to do good, or to do evil? to save life, or to destroy it?"}, {"numero": 10, "texto": "And looking round about upon them all, he said unto the man, Stretch forth thy hand. And he did so: and his hand was restored whole as the other."}, {"numero": 11, "texto": "And they were filled with madness; and communed one with another what they might do to Jesus."}, {"numero": 12, "texto": "And it came to pass in those days, that he went out into a mountain to pray, and continued all night in prayer to God."}, {"numero": 13, "texto": "And when it was day, he called unto him his disciples: and of them he chose twelve, whom also he named apostles;"}, {"numero": 14, "texto": "Simon, (whom he also named Peter,) and Andrew his brother, James and John, Philip and Bartholomew,"}, {"numero": 15, "texto": "Matthew and Thomas, James the son of Alphaeus, and Simon called Zelotes,"}, {"numero": 16, "texto": "And Judas the brother of James, and Judas Iscariot, which also was the traitor."}, {"numero": 17, "texto": "And he came down with them, and stood in the plain, and the company of his disciples, and a great multitude of people out of all Judaea and Jerusalem, and from the sea coast of Tyre and Sidon, which came to hear him, and to be healed of their diseases;"}, {"numero": 18, "texto": "And they that were vexed with unclean spirits: and they were healed."}, {"numero": 19, "texto": "And the whole multitude sought to touch him: for there went virtue out of him, and healed them all."}, {"numero": 20, "texto": "And he lifted up his eyes on his disciples, and said, Blessed be ye poor: for yours is the kingdom of God."}, {"numero": 21, "texto": "Blessed are ye that hunger now: for ye shall be filled. Blessed are ye that weep now: for ye shall laugh."}, {"numero": 22, "texto": "Blessed are ye, when men shall hate you, and when they shall separate you from their company, and shall reproach you, and cast out your name as evil, for the Son of man''s sake."}, {"numero": 23, "texto": "Rejoice ye in that day, and leap for joy: for, behold, your reward is great in heaven: for in the like manner did their fathers unto the prophets."}, {"numero": 24, "texto": "But woe unto you that are rich! for ye have received your consolation."}, {"numero": 25, "texto": "Woe unto you that are full! for ye shall hunger. Woe unto you that laugh now! for ye shall mourn and weep."}, {"numero": 26, "texto": "Woe unto you, when all men shall speak well of you! for so did their fathers to the false prophets."}, {"numero": 27, "texto": "But I say unto you which hear, Love your enemies, do good to them which hate you,"}, {"numero": 28, "texto": "Bless them that curse you, and pray for them which despitefully use you."}, {"numero": 29, "texto": "And unto him that smiteth thee on the one cheek offer also the other; and him that taketh away thy cloak forbid not to take thy coat also."}, {"numero": 30, "texto": "Give to every man that asketh of thee; and of him that taketh away thy goods ask them not again."}, {"numero": 31, "texto": "And as ye would that men should do to you, do ye also to them likewise."}, {"numero": 32, "texto": "For if ye love them which love you, what thank have ye? for sinners also love those that love them."}, {"numero": 33, "texto": "And if ye do good to them which do good to you, what thank have ye? for sinners also do even the same."}, {"numero": 34, "texto": "And if ye lend to them of whom ye hope to receive, what thank have ye? for sinners also lend to sinners, to receive as much again."}, {"numero": 35, "texto": "But love ye your enemies, and do good, and lend, hoping for nothing again; and your reward shall be great, and ye shall be the children of the Highest: for he is kind unto the unthankful and to the evil."}, {"numero": 36, "texto": "Be ye therefore merciful, as your Father also is merciful."}, {"numero": 37, "texto": "Judge not, and ye shall not be judged: condemn not, and ye shall not be condemned: forgive, and ye shall be forgiven:"}, {"numero": 38, "texto": "Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom. For with the same measure that ye mete withal it shall be measured to you again."}, {"numero": 39, "texto": "And he spake a parable unto them, Can the blind lead the blind? shall they not both fall into the ditch?"}, {"numero": 40, "texto": "The disciple is not above his master: but every one that is perfect shall be as his master."}, {"numero": 41, "texto": "And why beholdest thou the mote that is in thy brother''s eye, but perceivest not the beam that is in thine own eye?"}, {"numero": 42, "texto": "Either how canst thou say to thy brother, Brother, let me pull out the mote that is in thine eye, when thou thyself beholdest not the beam that is in thine own eye? Thou hypocrite, cast out first the beam out of thine own eye, and then shalt thou see clearly to pull out the mote that is in thy brother''s eye."}, {"numero": 43, "texto": "For a good tree bringeth not forth corrupt fruit; neither doth a corrupt tree bring forth good fruit."}, {"numero": 44, "texto": "For every tree is known by his own fruit. For of thorns men do not gather figs, nor of a bramble bush gather they grapes."}, {"numero": 45, "texto": "A good man out of the good treasure of his heart bringeth forth that which is good; and an evil man out of the evil treasure of his heart bringeth forth that which is evil: for of the abundance of the heart his mouth speaketh."}, {"numero": 46, "texto": "And why call ye me, Lord, Lord, and do not the things which I say?"}, {"numero": 47, "texto": "Whosoever cometh to me, and heareth my sayings, and doeth them, I will shew you to whom he is like:"}, {"numero": 48, "texto": "He is like a man which built an house, and digged deep, and laid the foundation on a rock: and when the flood arose, the stream beat vehemently upon that house, and could not shake it: for it was founded upon a rock."}, {"numero": 49, "texto": "But he that heareth, and doeth not, is like a man that without a foundation built an house upon the earth; against which the stream did beat vehemently, and immediately it fell; and the ruin of that house was great."}]'::jsonb, 'King James Version'),
  ('Lc', 6, 'fr', '[{"numero": 1, "texto": "Il arriva, un jour de sabbat appelé second-premier, que Jésus traversait des champs de blé. Ses disciples arrachaient des épis et les mangeaient, après les avoir froissés dans leurs mains."}, {"numero": 2, "texto": "Quelques pharisiens leur dirent: Pourquoi faites-vous ce qu''''il n''''est pas permis de faire pendant le sabbat?"}, {"numero": 3, "texto": "Jésus leur répondit: N''''avez-vous pas lu ce que fit David, lorsqu''''il eut faim, lui et ceux qui étaient avec lui;"}, {"numero": 4, "texto": "comment il entra dans la maison de Dieu, prit les pains de proposition, en mangea, et en donna à ceux qui étaient avec lui, bien qu''''il ne soit permis qu''''aux sacrificateurs de les manger?"}, {"numero": 5, "texto": "Et il leur dit: Le Fils de l''''homme est maître même du sabbat."}, {"numero": 6, "texto": "Il arriva, un autre jour de sabbat, que Jésus entra dans la synagogue, et qu''''il enseignait. Il s''''y trouvait un homme dont la main droite était sèche."}, {"numero": 7, "texto": "Les scribes et les pharisiens observaient Jésus, pour voir s''''il ferait une guérison le jour du sabbat: c''''était afin d''''avoir sujet de l''''accuser."}, {"numero": 8, "texto": "Mais il connaissait leurs pensées, et il dit à l''''homme qui avait la main sèche: Lève-toi, et tiens-toi là au milieu. Il se leva, et se tint debout."}, {"numero": 9, "texto": "Et Jésus leur dit: Je vous demande s''''il est permis, le jour du sabbat, de faire du bien ou de faire du mal, de sauver une personne ou de la tuer."}, {"numero": 10, "texto": "Alors, promenant ses regards sur eux tous, il dit à l''''homme: Etends ta main. Il le fit, et sa main fut guérie."}, {"numero": 11, "texto": "Ils furent remplis de fureur, et ils se consultèrent pour savoir ce qu''''ils feraient à Jésus."}, {"numero": 12, "texto": "En ce temps-là, Jésus se rendit sur la montagne pour prier, et il passa toute la nuit à prier Dieu."}, {"numero": 13, "texto": "Quand le jour parut, il appela ses disciples, et il en choisit douze, auxquels il donna le nom d''''apôtres:"}, {"numero": 14, "texto": "Simon, qu''''il nomma Pierre; André, son frère; Jacques; Jean; Philippe; Barthélemy;"}, {"numero": 15, "texto": "Matthieu; Thomas; Jacques, fils d''''Alphée; Simon, appelé le zélote;"}, {"numero": 16, "texto": "Jude, fils de Jacques; et Judas Iscariot, qui devint traître."}, {"numero": 17, "texto": "Il descendit avec eux, et s''''arrêta sur un plateau, où se trouvaient une foule de ses disciples et une multitude de peuple de toute la Judée, de Jérusalem, et de la contrée maritime de Tyr et de Sidon. Ils étaient venus pour l''''entendre, et pour être guéris de leurs maladies."}, {"numero": 18, "texto": "Ceux qui étaient tourmentés par des esprits impurs étaient guéris."}, {"numero": 19, "texto": "Et toute la foule cherchait à le toucher, parce qu''''une force sortait de lui et les guérissait tous."}, {"numero": 20, "texto": "Alors Jésus, levant les yeux sur ses disciples, dit: Heureux vous qui êtes pauvres, car le royaume de Dieu est à vous!"}, {"numero": 21, "texto": "Heureux vous qui avez faim maintenant, car vous serez rassasiés! Heureux vous qui pleurez maintenant, car vous serez dans la joie!"}, {"numero": 22, "texto": "Heureux serez-vous, lorsque les hommes vous haïront, lorsqu''''on vous chassera, vous outragera, et qu''''on rejettera votre nom comme infâme, à cause du Fils de l''''homme!"}, {"numero": 23, "texto": "Réjouissez-vous en ce jour-là et tressaillez d''''allégresse, parce que votre récompense sera grande dans le ciel; car c''''est ainsi que leurs pères traitaient les prophètes."}, {"numero": 24, "texto": "Mais, malheur à vous, riches, car vous avez votre consolation!"}, {"numero": 25, "texto": "Malheur à vous qui êtes rassasiés, car vous aurez faim! Malheur à vous qui riez maintenant, car vous serez dans le deuil et dans les larmes!"}, {"numero": 26, "texto": "Malheur, lorsque tous les hommes diront du bien de vous, car c''''est ainsi qu''''agissaient leurs pères à l''''égard des faux prophètes!"}, {"numero": 27, "texto": "Mais je vous dis, à vous qui m''''écoutez: Aimez vos ennemis, faites du bien à ceux qui vous haïssent,"}, {"numero": 28, "texto": "bénissez ceux qui vous maudissent, priez pour ceux qui vous maltraitent."}, {"numero": 29, "texto": "Si quelqu''''un te frappe sur une joue, présente-lui aussi l''''autre. Si quelqu''''un prend ton manteau, ne l''''empêche pas de prendre encore ta tunique."}, {"numero": 30, "texto": "Donne à quiconque te demande, et ne réclame pas ton bien à celui qui s''''en empare."}, {"numero": 31, "texto": "Ce que vous voulez que les hommes fassent pour vous, faites-le de même pour eux."}, {"numero": 32, "texto": "Si vous aimez ceux qui vous aiment, quel gré vous en saura-t-on? Les pécheurs aussi aiment ceux qui les aiment."}, {"numero": 33, "texto": "Si vous faites du bien à ceux qui vous font du bien, quel gré vous en saura-t-on? Les pécheurs aussi agissent de même."}, {"numero": 34, "texto": "Et si vous prêtez à ceux de qui vous espérez recevoir, quel gré vous en saura-t-on? Les pécheurs aussi prêtent aux pécheurs, afin de recevoir la pareille."}, {"numero": 35, "texto": "Mais aimez vos ennemis, faites du bien, et prêtez sans rien espérer. Et votre récompense sera grande, et vous serez fils du Très-Haut, car il est bon pour les ingrats et pour les méchants."}, {"numero": 36, "texto": "Soyez donc miséricordieux, comme votre Père est miséricordieux."}, {"numero": 37, "texto": "Ne jugez point, et vous ne serez point jugés; ne condamnez point, et vous ne serez point condamnés; absolvez, et vous serez absous."}, {"numero": 38, "texto": "Donnez, et il vous sera donné: on versera dans votre sein une bonne mesure, serrée, secouée et qui déborde; car on vous mesurera avec la mesure dont vous vous serez servis."}, {"numero": 39, "texto": "Il leur dit aussi cette parabole: Un aveugle peut-il conduire un aveugle? Ne tomberont-ils pas tous deux dans une fosse?"}, {"numero": 40, "texto": "Le disciple n''''est pas plus que le maître; mais tout disciple accompli sera comme son maître."}, {"numero": 41, "texto": "Pourquoi vois-tu la paille qui est dans l''''oeil de ton frère, et n''''aperçois-tu pas la poutre qui est dans ton oeil?"}, {"numero": 42, "texto": "Ou comment peux-tu dire à ton frère: Frère, laisse-moi ôter la paille qui est dans ton oeil, toi qui ne vois pas la poutre qui est dans le tien? Hypocrite, ôte premièrement la poutre de ton oeil, et alors tu verras comment ôter la paille qui est dans l''''oeil de ton frère."}, {"numero": 43, "texto": "Ce n''''est pas un bon arbre qui porte du mauvais fruit, ni un mauvais arbre qui porte du bon fruit."}, {"numero": 44, "texto": "Car chaque arbre se connaît à son fruit. On ne cueille pas des figues sur des épines, et l''''on ne vendange pas des raisins sur des ronces."}, {"numero": 45, "texto": "L''''homme bon tire de bonnes choses du bon trésor de son coeur, et le méchant tire de mauvaises choses de son mauvais trésor; car c''''est de l''''abondance du coeur que la bouche parle."}, {"numero": 46, "texto": "Pourquoi m''''appelez-vous Seigneur, Seigneur! et ne faites-vous pas ce que je dis?"}, {"numero": 47, "texto": "Je vous montrerai à qui est semblable tout homme qui vient à moi, entend mes paroles, et les met en pratique."}, {"numero": 48, "texto": "Il est semblable à un homme qui, bâtissant une maison, a creusé, creusé profondément, et a posé le fondement sur le roc. Une inondation est venue, et le torrent s''''est jeté contre cette maison, sans pouvoir l''''ébranler, parce qu''''elle était bien bâtie."}, {"numero": 49, "texto": "Mais celui qui entend, et ne met pas en pratique, est semblable à un homme qui a bâti une maison sur la terre, sans fondement. Le torrent s''''est jeté contre elle: aussitôt elle est tombée, et la ruine de cette maison a été grande."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 6, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que pasando él por los sembrados en un sábado segundo del primero, sus discípulos arrancaban espigas, y comían, restregándolas con las manos."}, {"numero": 2, "texto": "Y algunos de los Fariseos les dijeron: ¿Por qué hacéis lo que no es lícito hacer en los sábados?"}, {"numero": 3, "texto": "Y respondiendo Jesús les dijo: ¿Ni aun esto habéis leído, qué hizo David cuando tuvo hambre, él, y los que con él estaban;"}, {"numero": 4, "texto": "Cómo entró en la casa de Dios, y tomó los panes de la proposición, y comió, y dió también á los que estaban con él, los cuales no era lícito comer, sino á solos los sacerdotes?"}, {"numero": 5, "texto": "Y les decía: El Hijo del hombre es Señor aun del sábado."}, {"numero": 6, "texto": "Y aconteció también en otro sábado, que él entró en la sinagoga y enseñaba; y estaba allí un hombre que tenía la mano derecha seca."}, {"numero": 7, "texto": "Y le acechaban los escribas y los Fariseos, si sanaría en sábado, por hallar de qué le acusasen."}, {"numero": 8, "texto": "Mas él sabía los pensamientos de ellos; y dijo al hombre que tenía la mano seca: Levántate, y ponte en medio. Y él levantándose, se puso en pie."}, {"numero": 9, "texto": "Entonces Jesús les dice: Os preguntaré una cosa: ¿Es lícito en sábados hacer bien, ó hacer mal? ¿salvar la vida, ó quitarla?"}, {"numero": 10, "texto": "Y mirándolos á todos alrededor, dice al hombre: Extiende tu mano. Y él lo hizo así, y su mano fué restaurada."}, {"numero": 11, "texto": "Y ellos se llenaron de rabia; y hablaban los unos á los otros qué harían á Jesús."}, {"numero": 12, "texto": "Y aconteció en aquellos días, que fué al monte á orar, y pasó la noche orando á Dios."}, {"numero": 13, "texto": "Y como fué de día, llamó á sus discípulos, y escogió doce de ellos, á los cuales también llamó apóstoles:"}, {"numero": 14, "texto": "A Simón, al cual también llamó Pedro, y á Andrés su hermano, Jacobo y Juan, Felipe y Bartolomé,"}, {"numero": 15, "texto": "Mateo y Tomás, Jacobo hijo de Alfeo, y Simón el que se llama Celador,"}, {"numero": 16, "texto": "Judas hermano de Jacobo, y Judas Iscariote, que también fué el traidor."}, {"numero": 17, "texto": "Y descendió con ellos, y se paró en un lugar llano, y la compañía de sus discípulos, y una grande multitud de pueblo de toda Judea y de Jerusalem, y de la costa de Tiro y de Sidón, que habían venido á oirle, y para ser sanados de sus enfermedades;"}, {"numero": 18, "texto": "Y los que habían sido atormentados de espíritus inmundos: y estaban curados."}, {"numero": 19, "texto": "Y toda la gente procuraba tocarle; porque salía de él virtud, y sanaba á todos."}, {"numero": 20, "texto": "Y alzando él los ojos á sus discípulos, decía: Bienaventurados vosotros los pobres; porque vuestro es el reino de Dios."}, {"numero": 21, "texto": "Bienaventurados los que ahora tenéis hambre; porque seréis saciados. Bienaventurados los que ahora lloráis, porque reiréis."}, {"numero": 22, "texto": "Bienaventurados seréis, cuando los hombres os aborrecieren, y cuando os apartaren de sí, y os denostaren, y desecharen vuestro nombre como malo, por el Hijo del hombre."}, {"numero": 23, "texto": "Gozaos en aquel día, y alegraos; porque he aquí vuestro galardón es grande en los cielos; porque así hacían sus padres á los profetas."}, {"numero": 24, "texto": "Mas ¡ay de vosotros, ricos! porque tenéis vuestro consuelo."}, {"numero": 25, "texto": "¡Ay de vosotros, los que estáis hartos! porque tendréis hambre. ¡Ay de vosotros, los que ahora reís! porque lamentaréis y lloraréis."}, {"numero": 26, "texto": "¡Ay de vosotros, cuando todos los hombres dijeren bien de vosotros! porque así hacían sus padres á los falsos profetas."}, {"numero": 27, "texto": "Mas á vosotros los que oís, digo: Amad á vuestros enemigos, haced bien á los que os aborrecen;"}, {"numero": 28, "texto": "Bendecid á los que os maldicen, y orad por los que os calumnian."}, {"numero": 29, "texto": "Y al que te hiriere en la mejilla, dale también la otra; y al que te quitare la capa, ni aun el sayo le defiendas."}, {"numero": 30, "texto": "Y á cualquiera que te pidiere, da; y al que tomare lo que es tuyo, no vuelvas á pedir."}, {"numero": 31, "texto": "Y como queréis que os hagan los hombres, así hacedles también vosotros:"}, {"numero": 32, "texto": "Porque si amáis á los que os aman, ¿qué gracias tendréis? porque también los pecadores aman á los que los aman."}, {"numero": 33, "texto": "Y si hiciereis bien á los que os hacen bien, ¿qué gracias tendréis? porque también los pecadores hacen lo mismo."}, {"numero": 34, "texto": "Y si prestareis á aquellos de quienes esperáis recibir, ¿qué gracias tendréis? porque también los pecadores prestan á los pecadores, para recibir otro tanto."}, {"numero": 35, "texto": "Amad, pues, á vuestros enemigos, y haced bien, y prestad, no esperando de ello nada; y será vuestro galardón grande, y seréis hijos del Altísimo: porque él es benigno para con los ingratos y malos."}, {"numero": 36, "texto": "Sed pues misericordiosos, como también vuestro Padre es misericordioso."}, {"numero": 37, "texto": "No juzguéis, y no seréis juzgados: no condenéis, y no seréis condenados: perdonad, y seréis perdonados."}, {"numero": 38, "texto": "Dad, y se os dará; medida buena, apretada, remecida, y rebosando darán en vuestro seno: porque con la misma medida que midiereis, os será vuelto á medir."}, {"numero": 39, "texto": "Y les decía una parábola: ¿Puede el ciego guiar al ciego? ¿No caerán ambos en el hoyo?"}, {"numero": 40, "texto": "El discípulo no es sobre su maestro; mas cualquiera que fuere como el maestro, será perfecto."}, {"numero": 41, "texto": "¿Por qué miras la paja que está en el ojo de tu hermano, y la viga que está en tu propio ojo no consideras?"}, {"numero": 42, "texto": "¿O cómo puedes decir á tu hermano: Hermano, deja, echaré fuera la paja que está en tu ojo, no mirando tú la viga que está en tu ojo? Hipócrita, echa primero fuera de tu ojo la viga, y entonces verás bien para sacar la paja que está en el ojo de tu hermano."}, {"numero": 43, "texto": "Porque no es buen árbol el que da malos frutos; ni árbol malo el que da buen fruto."}, {"numero": 44, "texto": "Porque cada árbol por su fruto es conocido: que no cogen higos de los espinos, ni vendimian uvas de las zarzas."}, {"numero": 45, "texto": "El buen hombre del buen tesoro de su corazón saca bien; y el mal hombre del mal tesoro de su corazón saca mal; porque de la abundancia del corazón habla su boca."}, {"numero": 46, "texto": "¿Por qué me llamáis, Señor, Señor, y no hacéis lo que digo?"}, {"numero": 47, "texto": "Todo aquel que viene á mí, y oye mis palabras, y las hace, os enseñaré á quién es semejante:"}, {"numero": 48, "texto": "Semejante es al hombre que edifica una casa, el cual cavó y ahondó, y puso el fundamento sobre la peña; y cuando vino una avenida, el río dió con ímpetu en aquella casa, mas no la pudo menear: porque estaba fundada sobre la peña."}, {"numero": 49, "texto": "Mas el que oyó y no hizo, semejante es al hombre que edificó su casa sobre tierra, sin fundamento; en la cual el río dió con ímpetu, y luego cayó; y fué grande la ruina de aquella casa."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 7, 'pt', '[{"numero": 1, "texto": "E depois de acabar todos os seus discursos aos ouvidos do povo, ele entrou em Cafarnaum."}, {"numero": 2, "texto": "E o servo de um certo centurião, a quem muito estimava, que estava doente, e a ponto de morrer."}, {"numero": 3, "texto": "E quando [o centurião] ouviu falar sobre Jesus, enviou-lhe uns anciãos dos judeus, rogando-lhe que viesse curar o seu servo."}, {"numero": 4, "texto": "Eles vieram a Jesus, e rogaram-lhe com urgência, dizendo: Ele é digno de lhe concederes isto,"}, {"numero": 5, "texto": "porque ele ama a nossa nação, e ele mesmo construiu a nossa sinagoga."}, {"numero": 6, "texto": "Jesus foi com eles; mas quando já não estava longe da casa, o centurião enviou-lhe uns amigos, dizendo-lhe: “Senhor, não te incomodes, porque não sou digno que entres abaixo do meu telhado."}, {"numero": 7, "texto": "Por isso que nem mesmo me considerei digno de vir a ti; mas diz uma palavra, e o meu servo sarará."}, {"numero": 8, "texto": "Porque também eu sou homem subordinado à autoridade, e tenho soldados sob o meu comando, e digo a este: ''Vai'', e ele vai; e a outro: ''Vem'', e ele vem; e a meu servo: ''Faz isto'', e ele faz”."}, {"numero": 9, "texto": "Quando Jesus ouviu isso, admirou-se dele; então se virou, e disse à multidão que o seguia: Digo-vos que nem mesmo em Israel achei tanta fé."}, {"numero": 10, "texto": "E quando os que foram enviados voltaram para casa, acharam com boa saúde o servo antes doente."}, {"numero": 11, "texto": "E aconteceu no dia seguinte, que [Jesus] ia a uma cidade chamada Naim, e com ele iam muitos de seus discípulos e uma grande multidão."}, {"numero": 12, "texto": "E quando chegou perto da porta da cidade, eis que levavam um defunto, filho único de sua mãe, que [era] viúva; e com ela [ia] grande multidão da cidade."}, {"numero": 13, "texto": "Quando o Senhor a viu, comoveu-se de intima compaixão por ela, e disse-lhe: Não chores."}, {"numero": 14, "texto": "Então se aproximou, tocou o caixão (e os que a levavam, pararam), e disse: Jovem, a ti eu digo: levanta-te."}, {"numero": 15, "texto": "E o defunto se sentou e começou a falar; e ele o entregou à sua mãe."}, {"numero": 16, "texto": "Todos se encheram de temor, e glorificavam a Deus, dizendo: “Um grande profeta se levantou entre nós, e Deus visitou o seu povo!”"}, {"numero": 17, "texto": "E essa sua fama correu por toda a Judeia, e por toda a região em redor."}, {"numero": 18, "texto": "E os discípulos de João lhe anunciaram essas coisas."}, {"numero": 19, "texto": "Então João chamou dois de seus discípulos, e os enviou a Jesus, dizendo: “És tu aquele que havia de vir, ou esperamos outro?”"}, {"numero": 20, "texto": "E quando aqueles homens vieram a ele, disseram: “João Batista nos enviou a ti, dizendo: ''És tu aquele que havia de vir, ou esperamos outro?''”"}, {"numero": 21, "texto": "E naquela mesma hora ele curou a muitos de enfermidades, males, e espíritos maus, e a deu vista a muitos cegos."}, {"numero": 22, "texto": "E Jesus lhes respondeu: Ide, e anunciai a João as coisas que tendes visto e ouvido: que os cegos veem, os mancos andam, os leprosos são purificados, os surdos ouvem, os mortos ressuscitam, e aos pobres é anunciado o Evangelho."}, {"numero": 23, "texto": "E bendito é aquele que não se ofender em mim."}, {"numero": 24, "texto": "E quando os mensageiros de João se foram, [Jesus] começou a dizer às multidões acerca de João: Que saístes para ver no deserto? Alguma cana sacudida pelo vento?"}, {"numero": 25, "texto": "Mas que saístes para ver? Um homem vestido de roupas delicadas? Eis que os que [vestem] roupas delicadas e vivem no luxo estão nos palácios reais."}, {"numero": 26, "texto": "Mas que saístes para ver? Um profeta? Sim, vos digo, e muito mais que profeta."}, {"numero": 27, "texto": "Este é aquele de quem está escrito: Eis que envio o meu mensageiro adiante de tua face, o qual preparará o teu caminho diante de ti."}, {"numero": 28, "texto": "Pois eu vos digo, que dentre os nascidos de mulheres, não há profeta maior que João, o Batista; mas o menor no reino dos céus é maior que ele."}, {"numero": 29, "texto": "E todo o povo e os publicanos ouviram, concordaram que Deus era justo, e foram batizados com o batismo de João."}, {"numero": 30, "texto": "Mas os fariseus e os estudiosos da Lei rejeitaram o conselho de Deus contra si mesmos, e não foram batizados por ele."}, {"numero": 31, "texto": "E o Senhor disse: “A quem, pois, compararei as pessoas desta geração? E a quem são semelhantes?"}, {"numero": 32, "texto": "São semelhantes às crianças sentadas na praça, que gritam umas às outras: ''Nós vos tocamos flautas, mas não dançastes; nós vos cantamos lamentações, mas não chorastes''."}, {"numero": 33, "texto": "Porque veio João Batista, que não comia pão, nem bebia vinho, e dizeis: ''Ele tem demônio'';"}, {"numero": 34, "texto": "Veio o Filho do homem, que come e bebe, e dizeis: ''Eis um homem comilão e bebedor de vinho, amigo dos publicanos e dos pecadores''."}, {"numero": 35, "texto": "Mas a sabedoria foi considerada justa por todos os seus filhos”."}, {"numero": 36, "texto": "E um dos fariseus lhe pediu que comesse com ele; então entrou na casa do fariseu, e sentou-se [à mesa] ."}, {"numero": 37, "texto": "E eis que uma mulher da cidade, que era pecadora, quando soube que ele estava na casa do fariseu, trouxe um vaso de alabastro de óleo perfumado."}, {"numero": 38, "texto": "E estando atrás, aos seus pés, chorando, começou a molhar-lhe os pés com lágrimas; e os enxugava com os cabelos da sua cabeça; e beijava-lhe os pés, e os ungia com o óleo perfumado."}, {"numero": 39, "texto": "E quando o fariseu que o havia convidado viu [isso] , falou consigo mesmo: Se ele fosse profeta, saberia quem e qual é a mulher que o toca; porque ela é pecadora."}, {"numero": 40, "texto": "E Jesus lhe respondeu: “Simão, tenho uma coisa a te dizer”; e ele disse: “Dize-a, Mestre”."}, {"numero": 41, "texto": "[Jesus] disse: “Certo credor tinha dois devedores. Um lhe devia quinhentas moedas de prata, e o outro cinquenta."}, {"numero": 42, "texto": "Como não tinham com que pagar, perdoou-lhes [a dívida] de ambos. Dize, pois, qual deles o amará mais?”"}, {"numero": 43, "texto": "Simão respondeu: Tenho para mim que aquele a quem mais perdoou. E ele lhe disse: Julgaste corretamente."}, {"numero": 44, "texto": "Ele se voltou à mulher, e disse a Simão: Vês tu esta mulher? Entrei na tua casa, e não me deste água para os pés; porém esta molhou os meus pés com lágrimas, e os enxugou com os seus cabelos da cabeça."}, {"numero": 45, "texto": "Tu não me beijaste; porém esta, desde que entrou, não parou de me beijar os pés."}, {"numero": 46, "texto": "Não ungiste a minha cabeça com óleo, porém esta ungiu os meus pés com óleo perfumado."}, {"numero": 47, "texto": "Por isso te digo, os muitos pecados dela são perdoados, porque muito amou; mas ao que pouco se perdoa, pouco ama."}, {"numero": 48, "texto": "E disse a ela: Os teus pecados são perdoados."}, {"numero": 49, "texto": "E os que estavam sentados começaram a dizer entre si: Quem é este, que até perdoa pecados?"}, {"numero": 50, "texto": "E disse à mulher: A tua fé te salvou; vai em paz."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 7, 'en', '[{"numero": 1, "texto": "Now when he had ended all his sayings in the audience of the people, he entered into Capernaum."}, {"numero": 2, "texto": "And a certain centurion''s servant, who was dear unto him, was sick, and ready to die."}, {"numero": 3, "texto": "And when he heard of Jesus, he sent unto him the elders of the Jews, beseeching him that he would come and heal his servant."}, {"numero": 4, "texto": "And when they came to Jesus, they besought him instantly, saying, That he was worthy for whom he should do this:"}, {"numero": 5, "texto": "For he loveth our nation, and he hath built us a synagogue."}, {"numero": 6, "texto": "Then Jesus went with them. And when he was now not far from the house, the centurion sent friends to him, saying unto him, Lord, trouble not thyself: for I am not worthy that thou shouldest enter under my roof:"}, {"numero": 7, "texto": "Wherefore neither thought I myself worthy to come unto thee: but say in a word, and my servant shall be healed."}, {"numero": 8, "texto": "For I also am a man set under authority, having under me soldiers, and I say unto one, Go, and he goeth; and to another, Come, and he cometh; and to my servant, Do this, and he doeth it."}, {"numero": 9, "texto": "When Jesus heard these things, he marvelled at him, and turned him about, and said unto the people that followed him, I say unto you, I have not found so great faith, no, not in Israel."}, {"numero": 10, "texto": "And they that were sent, returning to the house, found the servant whole that had been sick."}, {"numero": 11, "texto": "And it came to pass the day after, that he went into a city called Nain; and many of his disciples went with him, and much people."}, {"numero": 12, "texto": "Now when he came nigh to the gate of the city, behold, there was a dead man carried out, the only son of his mother, and she was a widow: and much people of the city was with her."}, {"numero": 13, "texto": "And when the Lord saw her, he had compassion on her, and said unto her, Weep not."}, {"numero": 14, "texto": "And he came and touched the bier: and they that bare him stood still. And he said, Young man, I say unto thee, Arise."}, {"numero": 15, "texto": "And he that was dead sat up, and began to speak. And he delivered him to his mother."}, {"numero": 16, "texto": "And there came a fear on all: and they glorified God, saying, That a great prophet is risen up among us; and, That God hath visited his people."}, {"numero": 17, "texto": "And this rumour of him went forth throughout all Judaea, and throughout all the region round about."}, {"numero": 18, "texto": "And the disciples of John shewed him of all these things."}, {"numero": 19, "texto": "And John calling unto him two of his disciples sent them to Jesus, saying, Art thou he that should come? or look we for another?"}, {"numero": 20, "texto": "When the men were come unto him, they said, John Baptist hath sent us unto thee, saying, Art thou he that should come? or look we for another?"}, {"numero": 21, "texto": "And in that same hour he cured many of their infirmities and plagues, and of evil spirits; and unto many that were blind he gave sight."}, {"numero": 22, "texto": "Then Jesus answering said unto them, Go your way, and tell John what things ye have seen and heard; how that the blind see, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised, to the poor the gospel is preached."}, {"numero": 23, "texto": "And blessed is he, whosoever shall not be offended in me."}, {"numero": 24, "texto": "And when the messengers of John were departed, he began to speak unto the people concerning John, What went ye out into the wilderness for to see? A reed shaken with the wind?"}, {"numero": 25, "texto": "But what went ye out for to see? A man clothed in soft raiment? Behold, they which are gorgeously apparelled, and live delicately, are in kings'' courts."}, {"numero": 26, "texto": "But what went ye out for to see? A prophet? Yea, I say unto you, and much more than a prophet."}, {"numero": 27, "texto": "This is he, of whom it is written, Behold, I send my messenger before thy face, which shall prepare thy way before thee."}, {"numero": 28, "texto": "For I say unto you, Among those that are born of women there is not a greater prophet than John the Baptist: but he that is least in the kingdom of God is greater than he."}, {"numero": 29, "texto": "And all the people that heard him, and the publicans, justified God, being baptized with the baptism of John."}, {"numero": 30, "texto": "But the Pharisees and lawyers rejected the counsel of God against themselves, being not baptized of him."}, {"numero": 31, "texto": "And the Lord said, Whereunto then shall I liken the men of this generation? and to what are they like?"}, {"numero": 32, "texto": "They are like unto children sitting in the marketplace, and calling one to another, and saying, We have piped unto you, and ye have not danced; we have mourned to you, and ye have not wept."}, {"numero": 33, "texto": "For John the Baptist came neither eating bread nor drinking wine; and ye say, He hath a devil."}, {"numero": 34, "texto": "The Son of man is come eating and drinking; and ye say, Behold a gluttonous man, and a winebibber, a friend of publicans and sinners!"}, {"numero": 35, "texto": "But wisdom is justified of all her children."}, {"numero": 36, "texto": "And one of the Pharisees desired him that he would eat with him. And he went into the Pharisee''s house, and sat down to meat."}, {"numero": 37, "texto": "And, behold, a woman in the city, which was a sinner, when she knew that Jesus sat at meat in the Pharisee''s house, brought an alabaster box of ointment,"}, {"numero": 38, "texto": "And stood at his feet behind him weeping, and began to wash his feet with tears, and did wipe them with the hairs of her head, and kissed his feet, and anointed them with the ointment."}, {"numero": 39, "texto": "Now when the Pharisee which had bidden him saw it, he spake within himself, saying, This man, if he were a prophet, would have known who and what manner of woman this is that toucheth him: for she is a sinner."}, {"numero": 40, "texto": "And Jesus answering said unto him, Simon, I have somewhat to say unto thee. And he saith, Master, say on."}, {"numero": 41, "texto": "There was a certain creditor which had two debtors: the one owed five hundred pence, and the other fifty."}, {"numero": 42, "texto": "And when they had nothing to pay, he frankly forgave them both. Tell me therefore, which of them will love him most?"}, {"numero": 43, "texto": "Simon answered and said, I suppose that he, to whom he forgave most. And he said unto him, Thou hast rightly judged."}, {"numero": 44, "texto": "And he turned to the woman, and said unto Simon, Seest thou this woman? I entered into thine house, thou gavest me no water for my feet: but she hath washed my feet with tears, and wiped them with the hairs of her head."}, {"numero": 45, "texto": "Thou gavest me no kiss: but this woman since the time I came in hath not ceased to kiss my feet."}, {"numero": 46, "texto": "My head with oil thou didst not anoint: but this woman hath anointed my feet with ointment."}, {"numero": 47, "texto": "Wherefore I say unto thee, Her sins, which are many, are forgiven; for she loved much: but to whom little is forgiven, the same loveth little."}, {"numero": 48, "texto": "And he said unto her, Thy sins are forgiven."}, {"numero": 49, "texto": "And they that sat at meat with him began to say within themselves, Who is this that forgiveth sins also?"}, {"numero": 50, "texto": "And he said to the woman, Thy faith hath saved thee; go in peace."}]'::jsonb, 'King James Version'),
  ('Lc', 7, 'fr', '[{"numero": 1, "texto": "Après avoir achevé tous ces discours devant le peuple qui l''''écoutait, Jésus entra dans Capernaüm."}, {"numero": 2, "texto": "Un centenier avait un serviteur auquel il était très attaché, et qui se trouvait malade, sur le point de mourir."}, {"numero": 3, "texto": "Ayant entendu parler de Jésus, il lui envoya quelques anciens des Juifs, pour le prier de venir guérir son serviteur."}, {"numero": 4, "texto": "Ils arrivèrent auprès de Jésus, et lui adressèrent d''''instantes supplications, disant: Il mérite que tu lui accordes cela;"}, {"numero": 5, "texto": "car il aime notre nation, et c''''est lui qui a bâti notre synagogue."}, {"numero": 6, "texto": "Jésus, étant allé avec eux, n''''était guère éloigné de la maison, quand le centenier envoya des amis pour lui dire: Seigneur, ne prends pas tant de peine; car je ne suis pas digne que tu entres sous mon toit."}, {"numero": 7, "texto": "C''''est aussi pour cela que je ne me suis pas cru digne d''''aller en personne vers toi. Mais dis un mot, et mon serviteur sera guéri."}, {"numero": 8, "texto": "Car, moi qui suis soumis à des supérieurs, j''''ai des soldats sous mes ordres; et je dis à l''''un: Va! et il va; à l''''autre: Viens! et il vient; et à mon serviteur: Fais cela! et il le fait."}, {"numero": 9, "texto": "Lorsque Jésus entendit ces paroles, il admira le centenier, et, se tournant vers la foule qui le suivait, il dit: Je vous le dis, même en Israël je n''''ai pas trouvé une aussi grande foi."}, {"numero": 10, "texto": "De retour à la maison, les gens envoyés par le centenier trouvèrent guéri le serviteur qui avait été malade."}, {"numero": 11, "texto": "Le jour suivant, Jésus alla dans une ville appelée Naïn; ses disciples et une grande foule faisaient route avec lui."}, {"numero": 12, "texto": "Lorsqu''''il fut près de la porte de la ville, voici, on portait en terre un mort, fils unique de sa mère, qui était veuve; et il y avait avec elle beaucoup de gens de la ville."}, {"numero": 13, "texto": "Le Seigneur, l''''ayant vue, fut ému de compassion pour elle, et lui dit: Ne pleure pas!"}, {"numero": 14, "texto": "Il s''''approcha, et toucha le cercueil. Ceux qui le portaient s''''arrêtèrent. Il dit: Jeune homme, je te le dis, lève-toi!"}, {"numero": 15, "texto": "Et le mort s''''assit, et se mit à parler. Jésus le rendit à sa mère."}, {"numero": 16, "texto": "Tous furent saisis de crainte, et ils glorifiaient Dieu, disant: Un grand prophète a paru parmi nous, et Dieu a visité son peuple."}, {"numero": 17, "texto": "Cette parole sur Jésus se répandit dans toute la Judée et dans tout le pays d''''alentour."}, {"numero": 18, "texto": "Jean fut informé de toutes ces choses par ses disciples."}, {"numero": 19, "texto": "Il en appela deux, et les envoya vers Jésus, pour lui dire: Es-tu celui qui doit venir, ou devons-nous en attendre un autre?"}, {"numero": 20, "texto": "Arrivés auprès de Jésus, ils dirent: Jean Baptiste nous a envoyés vers toi, pour dire: Es-tu celui qui doit venir, ou devons-nous en attendre un autre?"}, {"numero": 21, "texto": "A l''''heure même, Jésus guérit plusieurs personnes de maladies, d''''infirmités, et d''''esprits malins, et il rendit la vue à plusieurs aveugles."}, {"numero": 22, "texto": "Et il leur répondit: Allez rapporter à Jean ce que vous avez vu et entendu: les aveugles voient, les boiteux marchent, les lépreux sont purifiés, les sourds entendent, les morts ressuscitent, la bonne nouvelle est annoncée aux pauvres."}, {"numero": 23, "texto": "Heureux celui pour qui je ne serai pas une occasion de chute!"}, {"numero": 24, "texto": "Lorsque les envoyés de Jean furent partis, Jésus se mit à dire à la foule, au sujet de Jean: Qu''''êtes-vous allés voir au désert? un roseau agité par le vent?"}, {"numero": 25, "texto": "Mais, qu''''êtes-vous allés voir? un homme vêtu d''''habits précieux? Voici, ceux qui portent des habits magnifiques, et qui vivent dans les délices, sont dans les maisons des rois."}, {"numero": 26, "texto": "Qu''''êtes-vous donc allés voir? un prophète? Oui, vous dis-je, et plus qu''''un prophète."}, {"numero": 27, "texto": "C''''est celui dont il est écrit: Voici, j''''envoie mon messager devant ta face, Pour préparer ton chemin devant toi."}, {"numero": 28, "texto": "Je vous le dis, parmi ceux qui sont nés de femmes, il n''''y en a point de plus grand que Jean. Cependant, le plus petit dans le royaume de Dieu est plus grand que lui."}, {"numero": 29, "texto": "Et tout le peuple qui l''''a entendu et même les publicains ont justifié Dieu, en se faisant baptiser du baptême de Jean;"}, {"numero": 30, "texto": "mais les pharisiens et les docteurs de la loi, en ne se faisant pas baptiser par lui, ont rendu nul à leur égard le dessein de Dieu."}, {"numero": 31, "texto": "A qui donc comparerai-je les hommes de cette génération, et à qui ressemblent-ils?"}, {"numero": 32, "texto": "Ils ressemblent aux enfants assis dans la place publique, et qui, se parlant les uns aux autres, disent: Nous vous avons joué de la flûte, et vous n''''avez pas dansé; nous vous avons chanté des complaintes, et vous n''''avez pas pleuré."}, {"numero": 33, "texto": "Car Jean Baptiste est venu, ne mangeant pas de pain et ne buvant pas de vin, et vous dites: Il a un démon."}, {"numero": 34, "texto": "Le Fils de l''''homme est venu, mangeant et buvant, et vous dites: C''''est un mangeur et un buveur, un ami des publicains et des gens de mauvaise vie."}, {"numero": 35, "texto": "Mais la sagesse a été justifiée par tous ses enfants."}, {"numero": 36, "texto": "Un pharisien pria Jésus de manger avec lui. Jésus entra dans la maison du pharisien, et se mit à table."}, {"numero": 37, "texto": "Et voici, une femme pécheresse qui se trouvait dans la ville, ayant su qu''''il était à table dans la maison du pharisien, apporta un vase d''''albâtre plein de parfum,"}, {"numero": 38, "texto": "et se tint derrière, aux pieds de Jésus. Elle pleurait; et bientôt elle lui mouilla les pieds de ses larmes, puis les essuya avec ses cheveux, les baisa, et les oignit de parfum."}, {"numero": 39, "texto": "Le pharisien qui l''''avait invité, voyant cela, dit en lui-même: Si cet homme était prophète, il connaîtrait qui et de quelle espèce est la femme qui le touche, il connaîtrait que c''''est une pécheresse."}, {"numero": 40, "texto": "Jésus prit la parole, et lui dit: Simon, j''''ai quelque chose à te dire. - Maître, parle, répondit-il. -"}, {"numero": 41, "texto": "Un créancier avait deux débiteurs: l''''un devait cinq cents deniers, et l''''autre cinquante."}, {"numero": 42, "texto": "Comme ils n''''avaient pas de quoi payer, il leur remit à tous deux leur dette. Lequel l''''aimera le plus?"}, {"numero": 43, "texto": "Simon répondit: Celui, je pense, auquel il a le plus remis. Jésus lui dit: Tu as bien jugé."}, {"numero": 44, "texto": "Puis, se tournant vers la femme, il dit à Simon: Vois-tu cette femme? Je suis entré dans ta maison, et tu ne m''''as point donné d''''eau pour laver mes pieds; mais elle, elle les a mouillés de ses larmes, et les a essuyés avec ses cheveux."}, {"numero": 45, "texto": "Tu ne m''''as point donné de baiser; mais elle, depuis que je suis entré, elle n''''a point cessé de me baiser les pieds."}, {"numero": 46, "texto": "Tu n''''as point versé d''''huile sur ma tête; mais elle, elle a versé du parfum sur mes pieds."}, {"numero": 47, "texto": "C''''est pourquoi, je te le dis, ses nombreux péchés ont été pardonnés: car elle a beaucoup aimé. Mais celui à qui on pardonne peu aime peu."}, {"numero": 48, "texto": "Et il dit à la femme: Tes péchés sont pardonnés."}, {"numero": 49, "texto": "Ceux qui étaient à table avec lui se mirent à dire en eux-mêmes: Qui est celui-ci, qui pardonne même les péchés?"}, {"numero": 50, "texto": "Mais Jésus dit à la femme: Ta foi t''''a sauvée, va en paix."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 7, 'es', '[{"numero": 1, "texto": "Y COMO acabó todas sus palabras oyéndole el pueblo, entró en Capernaum."}, {"numero": 2, "texto": "Y el siervo de un centurión, al cual tenía él en estima, estaba enfermo y á punto de morir."}, {"numero": 3, "texto": "Y como oyó hablar de Jesús, envió á él los ancianos de los Judíos, rogándole que viniese y librase á su siervo."}, {"numero": 4, "texto": "Y viniendo ellos á Jesús, rogáronle con diligencia, diciéndole: Porque es digno de concederle esto;"}, {"numero": 5, "texto": "Que ama nuestra nación, y él nos edificó una sinagoga."}, {"numero": 6, "texto": "Y Jesús fué con ellos. Mas como ya no estuviesen lejos de su casa, envió el centurión amigos á él, diciéndole: Señor, no te incomodes, que no soy digno que entres debajo de mi tejado;"}, {"numero": 7, "texto": "Por lo cual ni aun me tuve por digno de venir á ti; mas di la palabra, y mi siervo será sano."}, {"numero": 8, "texto": "Porque también yo soy hombre puesto en potestad, que tengo debajo de mí soldados; y digo á éste: Ve, y va; y al otro: Ven, y viene; y á mi siervo: Haz esto, y lo hace."}, {"numero": 9, "texto": "Lo cual oyendo Jesús, se maravilló de él, y vuelto, dijo á las gentes que le seguían: Os digo que ni aun en Israel he hallado tanta fe."}, {"numero": 10, "texto": "Y vueltos á casa los que habían sido enviados, hallaron sano al siervo que había estado enfermo."}, {"numero": 11, "texto": "Y aconteció después, que él iba á la ciudad que se llama Naín, é iban con él muchos de sus discípulos, y gran compañía."}, {"numero": 12, "texto": "Y como llegó cerca de la puerta de la ciudad, he aquí que sacaban fuera á un difunto, unigénito de su madre, la cual también era viuda: y había con ella grande compañía de la ciudad."}, {"numero": 13, "texto": "Y como el Señor la vió, compadecióse de ella, y le dice: No llores."}, {"numero": 14, "texto": "Y acercándose, tocó el féretro: y los que lo llevaban, pararon. Y dice: Mancebo, á ti digo, levántate."}, {"numero": 15, "texto": "Entonces se incorporó el que había muerto, y comenzó á hablar. Y dióle á su madre."}, {"numero": 16, "texto": "Y todos tuvieron miedo, y glorificaban á Dios, diciendo: Que un gran profeta se ha levantado entre nosotros; y que Dios ha visitado á su pueblo."}, {"numero": 17, "texto": "Y salió esta fama de él por toda Judea, y por toda la tierra de alrededor."}, {"numero": 18, "texto": "Y sus discípulos dieron á Juan las nuevas de todas estas cosas: y llamó Juan á dos de sus discípulos,"}, {"numero": 19, "texto": "Y envió á Jesús, diciendo: ¿Eres tú aquél que había de venir, ó esperaremos á otro?"}, {"numero": 20, "texto": "Y como los hombres vinieron á él, dijeron: Juan el Bautista nos ha enviado á ti, diciendo: ¿Eres tú aquél que había de venir, ó esperaremos á otro?"}, {"numero": 21, "texto": "Y en la misma hora sanó á muchos de enfermedades y plagas, y de espíritus malos; y á muchos ciegos dió la vista."}, {"numero": 22, "texto": "Y respondiendo Jesús, les dijo: Id, dad las nuevas á Juan de lo que habéis visto y oído: que los ciegos ven, los cojos andan, los leprosos son limpiados, los sordos oyen, los muertos resucitan, á los pobres es anunciado el evangelio:"}, {"numero": 23, "texto": "Y bienaventurado es el que no fuere escandalizado en mí."}, {"numero": 24, "texto": "Y como se fueron los mensajeros de Juan, comenzó á hablar de Juan á las gentes: ¿Qué salisteis á ver al desierto? ¿una caña que es agitada por el viento?"}, {"numero": 25, "texto": "Mas ¿qué salisteis á ver? ¿un hombre cubierto de vestidos delicados? He aquí, los que están en vestido precioso, y viven en delicias, en los palacios de los reyes están."}, {"numero": 26, "texto": "Mas ¿qué salisteis á ver? ¿un profeta? También os digo, y aun más que profeta."}, {"numero": 27, "texto": "Este es de quien está escrito: He aquí, envío mi mensajero delante de tu faz, el cual aparejará tu camino delante de ti."}, {"numero": 28, "texto": "Porque os digo que entre los nacidos de mujeres, no hay mayor profeta que Juan el Bautista: mas el más pequeño en el reino de los cielos es mayor que él."}, {"numero": 29, "texto": "Y todo el pueblo oyéndole, y los publicanos, justificaron á Dios, bautizándose con el bautismo de Juan."}, {"numero": 30, "texto": "Mas los Fariseos y los sabios de la ley, desecharon el consejo de Dios contra sí mismos, no siendo bautizados de él."}, {"numero": 31, "texto": "Y dice el Señor: ¿A quién, pues, compararé los hombres de esta generación, y á qué son semejantes?"}, {"numero": 32, "texto": "Semejantes son á los muchachos sentados en la plaza, y que dan voces los unos á los otros, y dicen: Os tañimos con flautas, y no bailasteis: os endechamos, y no llorasteis."}, {"numero": 33, "texto": "Porque vino Juan el Bautista, que ni comía pan, ni bebía vino, y decís: Demonio tiene."}, {"numero": 34, "texto": "Vino el Hijo del hombre, que come y bebe, y decís: He aquí un hombre comilón, y bebedor de vino, amigo de publicanos y de pecadores."}, {"numero": 35, "texto": "Mas la sabiduría es justificada de todos sus hijos."}, {"numero": 36, "texto": "Y le rogó uno de los Fariseos, que comiese con él. Y entrado en casa del Fariseo, sentóse á la mesa."}, {"numero": 37, "texto": "Y he aquí una mujer que había sido pecadora en la ciudad, como entendió que estaba á la mesa en casa de aquel Fariseo, trajo un alabastro de ungüento,"}, {"numero": 38, "texto": "Y estando detrás á sus pies, comenzó llorando á regar con lágrimas sus pies, y los limpiaba con los cabellos de su cabeza; y besaba sus pies, y los ungía con el ungüento."}, {"numero": 39, "texto": "Y como vió esto el Fariseo que le había convidado, habló entre sí, diciendo: Este, si fuera profeta, conocería quién y cuál es la mujer que le toca, que es pecadora."}, {"numero": 40, "texto": "Entonces respondiendo Jesús, le dijo: Simón, una cosa tengo que decirte. Y él dice: Di, Maestro."}, {"numero": 41, "texto": "Un acreedor tenía dos deudores: el uno le debía quinientos denarios, y el otro cincuenta;"}, {"numero": 42, "texto": "Y no teniendo ellos de qué pagar, perdonó á ambos. Di, pues, ¿cuál de éstos le amará más?"}, {"numero": 43, "texto": "Y respondiendo Simón, dijo: Pienso que aquél al cual perdonó más. Y él le dijo: Rectamente has juzgado."}, {"numero": 44, "texto": "Y vuelto á la mujer, dijo á Simón: ¿Ves esta mujer? Entré en tu casa, no diste agua para mis pies; mas ésta ha regado mis pies con lágrimas, y los ha limpiado con los cabellos."}, {"numero": 45, "texto": "No me diste beso, mas ésta, desde que entré, no ha cesado de besar mis pies."}, {"numero": 46, "texto": "No ungiste mi cabeza con óleo; mas ésta ha ungido con ungüento mis pies."}, {"numero": 47, "texto": "Por lo cual te digo que sus muchos pecados son perdonados, porque amó mucho; mas al que se perdona poco, poco ama."}, {"numero": 48, "texto": "Y á ella dijo: Los pecados te son perdonados."}, {"numero": 49, "texto": "Y los que estaban juntamente sentados á la mesa, comenzaron á decir entre sí: ¿Quién es éste, que también perdona pecados?"}, {"numero": 50, "texto": "Y dijo á la mujer: Tu fe te ha salvado, ve en paz."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 8, 'pt', '[{"numero": 1, "texto": "E aconteceu depois disso, que [Jesus] andava de cidade em cidade, e de aldeia em aldeia, pregando e anunciando o evangelho do reino de Deus; e com ele os doze,"}, {"numero": 2, "texto": "e algumas mulheres que haviam sido curadas de espíritos malignos e de enfermidades: Maria, chamada Madalena, da qual saíram sete demônios;"}, {"numero": 3, "texto": "e Joana, a mulher de Cuza, mordomo de Herodes; e Susana, e muitas outras, que o serviam com seus bens."}, {"numero": 4, "texto": "E quando se ajuntou uma multidão, e vindo a ele de todas as cidades, disse por parábola:"}, {"numero": 5, "texto": "Saiu um semeador a semear sua semente; e quando semeava, caiu uma [parte] junto ao caminho, e foi pisada, e as aves do céu a comeram."}, {"numero": 6, "texto": "E outra [parte] caiu sobre a pedra; e nascida, secou-se, porque não tinha umidade."}, {"numero": 7, "texto": "E outra [parte] caiu entre espinhos, e nascendo com ela, os espinhos a sufocaram."}, {"numero": 8, "texto": "E outra [parte] caiu em boa terra, e nascida, produziu fruto a cem por um. Depois que disse coisas, exclamava: Quem tem ouvidos para ouvir, ouça."}, {"numero": 9, "texto": "E os seus discípulos lhe perguntaram: Que parábola é esta?"}, {"numero": 10, "texto": "Ele disse: A vós é dado conhecer os mistérios do reino de Deus; mas aos outros por parábolas, para que vendo, não vejam; e ouvindo, não entendam."}, {"numero": 11, "texto": "Esta é, pois, a parábola: a semente é a palavra de Deus."}, {"numero": 12, "texto": "Os que estão junto ao caminho são os que ouvem; depois vem o diabo, e tira-lhes do coração a palavra, para que não creiam nem se salvem."}, {"numero": 13, "texto": "E os que estão sobre a pedra são os que, quando ouvem, recebem a palavra com alegria, mas esses não têm raiz, pois creem por algum tempo, mas no tempo da tentação se desviam."}, {"numero": 14, "texto": "E o que caiu entre espinhos são os que ouviram, e indo, sufocam-se com as preocupações, e riquezas, e prazeres da vida, e não produzem bom fruto."}, {"numero": 15, "texto": "E o que caiu em boa terra, estes são os que, ouvindo a palavra, conservam-na num coração honesto e bom, e dão fruto que permanece."}, {"numero": 16, "texto": "E ninguém, quando acende uma lâmpada, cobre-a com algum vaso, ou a põe debaixo da cama; em vez disso põe na luminária, para que os que entram vejam a luz."}, {"numero": 17, "texto": "Porque não há coisa oculta que não venha a se manifestar; nem coisa escondida que não venha a ser conhecida, e chegada à luz."}, {"numero": 18, "texto": "Portanto, prestai atenção a como ouvis; pois àquele que tiver lhe será dado; e àquele que não tiver, até o que lhe parece ter, dele será tirado."}, {"numero": 19, "texto": "E vieram a ele sua mãe e seus irmãos, mas não conseguiam chegar a ele por causa da multidão."}, {"numero": 20, "texto": "E foi-lhe anunciado, dizendo: “Tua mãe e teus irmãos estão fora, e querem te ver”."}, {"numero": 21, "texto": "Porém, ele lhes respondeu: “Minha mãe e meus irmãos são aqueles que ouvem a palavra de Deus e a praticam”."}, {"numero": 22, "texto": "E aconteceu, num daqueles dias, que [Jesus] entrou em um barco com seus discípulos, e disse-lhes: “Passemos para o outro lado do lago”. E partiram."}, {"numero": 23, "texto": "E enquanto navegavam, [Jesus] adormeceu; então desceu uma tempestade de vento no lago, e enchiam-se [de água] , e estavam em perigo."}, {"numero": 24, "texto": "Então se aproximaram dele e o despertaram, dizendo: “Mestre, Mestre, estamos perecendo!” E ele se levantou, repreendeu o vento e as ondas da água; e pararam, e fez-se bonança."}, {"numero": 25, "texto": "E disse-lhes: “Onde está a vossa fé?” Mas eles, temendo, admiravam-se, e diziam uns aos outros: “Quem é este, que manda até aos ventos, e à água, e lhe obedecem?”"}, {"numero": 26, "texto": "E navegaram para a terra dos gadarenos, que é do lado oposto à Galileia."}, {"numero": 27, "texto": "E quando ele desceu à terra, veio da cidade ao seu encontro um homem, que havia muito tempo que tinha demônios, e não andava vestido, nem habitava em casa nenhuma, mas sim, nos sepulcros."}, {"numero": 28, "texto": "Ele viu Jesus, então exclamou, prostrou-se diante dele, e disse com grande voz: “O que eu tenho contigo, Jesus, Filho do Deus Altíssimo? Rogo-te que não me atormentes.”"}, {"numero": 29, "texto": "Porque ele havia mandado ao espírito imundo que saísse daquele homem; pois muitas vezes apoderava-se dele. E o mantinham preso com cadeias e grilhões; porém ele quebrava o que lhe prendia, e era conduzido pelo demônio aos desertos."}, {"numero": 30, "texto": "E Jesus lhe perguntou: “Qual é teu nome?” E ele disse: “Legião” (porque muitos demônios tinham entrado nele)."}, {"numero": 31, "texto": "E rogavam-lhe que não os mandasse ir para o abismo."}, {"numero": 32, "texto": "E havia ali uma manada de muitos porcos, que pastavam no monte; e rogaram-lhe que lhes concedesse entrar neles; e ele lhes concedeu."}, {"numero": 33, "texto": "Os demônios saíram daquele homem e entraram nos porcos; e a manada se lançou de um precipício no lago e se afogou."}, {"numero": 34, "texto": "Quando os que cuidavam [dos porcos] viram o que havia acontecido, fugiram; então foram anunciar na cidade e nos campos."}, {"numero": 35, "texto": "E saíram para ver o acontecido, e vieram até Jesus; e acharam ao homem de quem os demônios tinham saído, vestido e em pleno juízo, sentado aos pés de Jesus; e temeram."}, {"numero": 36, "texto": "E os que tinham visto contaram-lhes também como aquele endemoninhado havia sido liberto."}, {"numero": 37, "texto": "E toda o povo da terra dos gadarenos ao redor lhe rogou que se retirasse deles; porque foram tomados por grande temor. Então ele entrou no barco e voltou."}, {"numero": 38, "texto": "E aquele homem, de quem os demônios tinham saído, rogou-lhe para que lhe permitisse estar com ele; mas Jesus o despediu, dizendo:"}, {"numero": 39, "texto": "“Volta para tua casa, e conta como foram grandes as coisas que Deus te fez”. Ele se foi, e pregou por toda a cidade, como foram grandes as coisas que Jesus lhe tinha feito."}, {"numero": 40, "texto": "E aconteceu que, quando Jesus voltou, a multidão o recebeu; porque todos o estavam esperando."}, {"numero": 41, "texto": "E eis que chegou um homem, cujo nome era Jairo, e era chefe da sinagoga. Então ele se prostrou aos pés de Jesus e rogou-lhe que entrasse em sua casa;"}, {"numero": 42, "texto": "porque tinha uma filha única, com doze anos de idade, que estava a ponto de morrer. E enquanto ele ia, as multidões o apertavam."}, {"numero": 43, "texto": "E uma mulher que tinha um fluxo de sangue, havia doze anos, e já tinha gastado todos os seus pertences com médicos, e não pôde ser curada por nenhum."}, {"numero": 44, "texto": "Ela se aproximou [de Jesus] por detrás, e tocou a borda de sua roupa; e logo o fluxo de seu sangue parou."}, {"numero": 45, "texto": "E Jesus disse: “Quem me tocou?” Enquanto todos negavam, disse Pedro e os que com ele estavam: Mestre, as multidões te apertam e empurram, e dizes: Quem me tocou?"}, {"numero": 46, "texto": "Jesus disse: “Alguém me tocou, pois sei que poder saiu de mim”."}, {"numero": 47, "texto": "Então a mulher, vendo que não podia se esconder, veio tremendo, prostrou-se diante dele, e declarou-lhe diante de todo o povo a causa por que o havia tocado, e como logo havia sarado."}, {"numero": 48, "texto": "E ele lhe disse: “Tem bom ânimo, filha; a tua fé te sarou; vai em paz”."}, {"numero": 49, "texto": "Estando ele ainda falando, veio um da [casa] do chefe da sinagoga, que lhe disse: “Tua filha já está morta, não incomodes o Mestre.”"}, {"numero": 50, "texto": "Porém quando Jesus o ouviu, respondeu-lhe: “Não temas; crê somente, e ela será curada”."}, {"numero": 51, "texto": "E quando entrou na casa, a ninguém deixou entrar, a não ser a Pedro, Tiago, João, e ao pai e à mãe da menina."}, {"numero": 52, "texto": "E todos choravam e lamentavam por ela; mas ele disse: “Não choreis; ela não está morta, mas dorme”."}, {"numero": 53, "texto": "E riam dele, porque sabiam que estava morta."}, {"numero": 54, "texto": "Porém ele, depois de expulsá-los todos, segurou a mão dela e clamou: “Levanta-te, menina”."}, {"numero": 55, "texto": "Então seu espírito voltou, e ela logo se levantou; e [Jesus] mandou que dessem de comer a ela."}, {"numero": 56, "texto": "E seus pais ficaram maravilhados, mas ele lhes mandou que a ninguém dissessem o que havia acontecido."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 8, 'en', '[{"numero": 1, "texto": "And it came to pass afterward, that he went throughout every city and village, preaching and shewing the glad tidings of the kingdom of God: and the twelve were with him,"}, {"numero": 2, "texto": "And certain women, which had been healed of evil spirits and infirmities, Mary called Magdalene, out of whom went seven devils,"}, {"numero": 3, "texto": "And Joanna the wife of Chuza Herod''s steward, and Susanna, and many others, which ministered unto him of their substance."}, {"numero": 4, "texto": "And when much people were gathered together, and were come to him out of every city, he spake by a parable:"}, {"numero": 5, "texto": "A sower went out to sow his seed: and as he sowed, some fell by the way side; and it was trodden down, and the fowls of the air devoured it."}, {"numero": 6, "texto": "And some fell upon a rock; and as soon as it was sprung up, it withered away, because it lacked moisture."}, {"numero": 7, "texto": "And some fell among thorns; and the thorns sprang up with it, and choked it."}, {"numero": 8, "texto": "And other fell on good ground, and sprang up, and bare fruit an hundredfold. And when he had said these things, he cried, He that hath ears to hear, let him hear."}, {"numero": 9, "texto": "And his disciples asked him, saying, What might this parable be?"}, {"numero": 10, "texto": "And he said, Unto you it is given to know the mysteries of the kingdom of God: but to others in parables; that seeing they might not see, and hearing they might not understand."}, {"numero": 11, "texto": "Now the parable is this: The seed is the word of God."}, {"numero": 12, "texto": "Those by the way side are they that hear; then cometh the devil, and taketh away the word out of their hearts, lest they should believe and be saved."}, {"numero": 13, "texto": "They on the rock are they, which, when they hear, receive the word with joy; and these have no root, which for a while believe, and in time of temptation fall away."}, {"numero": 14, "texto": "And that which fell among thorns are they, which, when they have heard, go forth, and are choked with cares and riches and pleasures of this life, and bring no fruit to perfection."}, {"numero": 15, "texto": "But that on the good ground are they, which in an honest and good heart, having heard the word, keep it, and bring forth fruit with patience."}, {"numero": 16, "texto": "No man, when he hath lighted a candle, covereth it with a vessel, or putteth it under a bed; but setteth it on a candlestick, that they which enter in may see the light."}, {"numero": 17, "texto": "For nothing is secret, that shall not be made manifest; neither any thing hid, that shall not be known and come abroad."}, {"numero": 18, "texto": "Take heed therefore how ye hear: for whosoever hath, to him shall be given; and whosoever hath not, from him shall be taken even that which he seemeth to have."}, {"numero": 19, "texto": "Then came to him his mother and his brethren, and could not come at him for the press."}, {"numero": 20, "texto": "And it was told him by certain which said, Thy mother and thy brethren stand without, desiring to see thee."}, {"numero": 21, "texto": "And he answered and said unto them, My mother and my brethren are these which hear the word of God, and do it."}, {"numero": 22, "texto": "Now it came to pass on a certain day, that he went into a ship with his disciples: and he said unto them, Let us go over unto the other side of the lake. And they launched forth."}, {"numero": 23, "texto": "But as they sailed he fell asleep: and there came down a storm of wind on the lake; and they were filled with water, and were in jeopardy."}, {"numero": 24, "texto": "And they came to him, and awoke him, saying, Master, master, we perish. Then he arose, and rebuked the wind and the raging of the water: and they ceased, and there was a calm."}, {"numero": 25, "texto": "And he said unto them, Where is your faith? And they being afraid wondered, saying one to another, What manner of man is this! for he commandeth even the winds and water, and they obey him."}, {"numero": 26, "texto": "And they arrived at the country of the Gadarenes, which is over against Galilee."}, {"numero": 27, "texto": "And when he went forth to land, there met him out of the city a certain man, which had devils long time, and ware no clothes, neither abode in any house, but in the tombs."}, {"numero": 28, "texto": "When he saw Jesus, he cried out, and fell down before him, and with a loud voice said, What have I to do with thee, Jesus, thou Son of God most high? I beseech thee, torment me not."}, {"numero": 29, "texto": "(For he had commanded the unclean spirit to come out of the man. For oftentimes it had caught him: and he was kept bound with chains and in fetters; and he brake the bands, and was driven of the devil into the wilderness.)"}, {"numero": 30, "texto": "And Jesus asked him, saying, What is thy name? And he said, Legion: because many devils were entered into him."}, {"numero": 31, "texto": "And they besought him that he would not command them to go out into the deep."}, {"numero": 32, "texto": "And there was there an herd of many swine feeding on the mountain: and they besought him that he would suffer them to enter into them. And he suffered them."}, {"numero": 33, "texto": "Then went the devils out of the man, and entered into the swine: and the herd ran violently down a steep place into the lake, and were choked."}, {"numero": 34, "texto": "When they that fed them saw what was done, they fled, and went and told it in the city and in the country."}, {"numero": 35, "texto": "Then they went out to see what was done; and came to Jesus, and found the man, out of whom the devils were departed, sitting at the feet of Jesus, clothed, and in his right mind: and they were afraid."}, {"numero": 36, "texto": "They also which saw it told them by what means he that was possessed of the devils was healed."}, {"numero": 37, "texto": "Then the whole multitude of the country of the Gadarenes round about besought him to depart from them; for they were taken with great fear: and he went up into the ship, and returned back again."}, {"numero": 38, "texto": "Now the man out of whom the devils were departed besought him that he might be with him: but Jesus sent him away, saying,"}, {"numero": 39, "texto": "Return to thine own house, and shew how great things God hath done unto thee. And he went his way, and published throughout the whole city how great things Jesus had done unto him."}, {"numero": 40, "texto": "And it came to pass, that, when Jesus was returned, the people gladly received him: for they were all waiting for him."}, {"numero": 41, "texto": "And, behold, there came a man named Jairus, and he was a ruler of the synagogue: and he fell down at Jesus'' feet, and besought him that he would come into his house:"}, {"numero": 42, "texto": "For he had one only daughter, about twelve years of age, and she lay a dying. But as he went the people thronged him."}, {"numero": 43, "texto": "And a woman having an issue of blood twelve years, which had spent all her living upon physicians, neither could be healed of any,"}, {"numero": 44, "texto": "Came behind him, and touched the border of his garment: and immediately her issue of blood stanched."}, {"numero": 45, "texto": "And Jesus said, Who touched me? When all denied, Peter and they that were with him said, Master, the multitude throng thee and press thee, and sayest thou, Who touched me?"}, {"numero": 46, "texto": "And Jesus said, Somebody hath touched me: for I perceive that virtue is gone out of me."}, {"numero": 47, "texto": "And when the woman saw that she was not hid, she came trembling, and falling down before him, she declared unto him before all the people for what cause she had touched him, and how she was healed immediately."}, {"numero": 48, "texto": "And he said unto her, Daughter, be of good comfort: thy faith hath made thee whole; go in peace."}, {"numero": 49, "texto": "While he yet spake, there cometh one from the ruler of the synagogue''s house, saying to him, Thy daughter is dead; trouble not the Master."}, {"numero": 50, "texto": "But when Jesus heard it, he answered him, saying, Fear not: believe only, and she shall be made whole."}, {"numero": 51, "texto": "And when he came into the house, he suffered no man to go in, save Peter, and James, and John, and the father and the mother of the maiden."}, {"numero": 52, "texto": "And all wept, and bewailed her: but he said, Weep not; she is not dead, but sleepeth."}, {"numero": 53, "texto": "And they laughed him to scorn, knowing that she was dead."}, {"numero": 54, "texto": "And he put them all out, and took her by the hand, and called, saying, Maid, arise."}, {"numero": 55, "texto": "And her spirit came again, and she arose straightway: and he commanded to give her meat."}, {"numero": 56, "texto": "And her parents were astonished: but he charged them that they should tell no man what was done."}]'::jsonb, 'King James Version'),
  ('Lc', 8, 'fr', '[{"numero": 1, "texto": "Ensuite, Jésus allait de ville en ville et de village en village, prêchant et annonçant la bonne nouvelle du royaume de Dieu."}, {"numero": 2, "texto": "Les douze étaient avec lui et quelques femmes qui avaient été guéries d''''esprits malins et de maladies: Marie, dite de Magdala, de laquelle étaient sortis sept démons,"}, {"numero": 3, "texto": "Jeanne, femme de Chuza, intendant d''''Hérode, Susanne, et plusieurs autres, qui l''''assistaient de leurs biens."}, {"numero": 4, "texto": "Une grande foule s''''étant assemblée, et des gens étant venus de diverses villes auprès de lui, il dit cette parabole:"}, {"numero": 5, "texto": "Un semeur sortit pour semer sa semence. Comme il semait, une partie de la semence tomba le long du chemin: elle fut foulée aux pieds, et les oiseaux du ciel la mangèrent."}, {"numero": 6, "texto": "Une autre partie tomba sur le roc: quand elle fut levée, elle sécha, parce qu''''elle n''''avait point d''''humidité."}, {"numero": 7, "texto": "Une autre partie tomba au milieu des épines: les épines crûrent avec elle, et l''''étouffèrent."}, {"numero": 8, "texto": "Une autre partie tomba dans la bonne terre: quand elle fut levée, elle donna du fruit au centuple. Après avoir ainsi parlé, Jésus dit à haute voix: Que celui qui a des oreilles pour entendre entende!"}, {"numero": 9, "texto": "Ses disciples lui demandèrent ce que signifiait cette parabole."}, {"numero": 10, "texto": "Il répondit: Il vous a été donné de connaître les mystères du royaume de Dieu; mais pour les autres, cela leur est dit en paraboles, afin qu''''en voyant ils ne voient point, et qu''''en entendant ils ne comprennent point."}, {"numero": 11, "texto": "Voici ce que signifie cette parabole: La semence, c''''est la parole de Dieu."}, {"numero": 12, "texto": "Ceux qui sont le long du chemin, ce sont ceux qui entendent; puis le diable vient, et enlève de leur coeur la parole, de peur qu''''ils ne croient et soient sauvés."}, {"numero": 13, "texto": "Ceux qui sont sur le roc, ce sont ceux qui, lorsqu''''ils entendent la parole, la reçoivent avec joie; mais ils n''''ont point de racine, ils croient pour un temps, et ils succombent au moment de la tentation."}, {"numero": 14, "texto": "Ce qui est tombé parmi les épines, ce sont ceux qui, ayant entendu la parole, s''''en vont, et la laissent étouffer par les soucis, les richesses et les plaisirs de la vie, et ils ne portent point de fruit qui vienne à maturité."}, {"numero": 15, "texto": "Ce qui est tombé dans la bonne terre, ce sont ceux qui, ayant entendu la parole avec un coeur honnête et bon, la retiennent, et portent du fruit avec persévérance."}, {"numero": 16, "texto": "Personne, après avoir allumé une lampe, ne la couvre d''''un vase, ou ne la met sous un lit; mais il la met sur un chandelier, afin que ceux qui entrent voient la lumière."}, {"numero": 17, "texto": "Car il n''''est rien de caché qui ne doive être découvert, rien de secret qui ne doive être connu et mis au jour."}, {"numero": 18, "texto": "Prenez donc garde à la manière dont vous écoutez; car on donnera à celui qui a, mais à celui qui n''''a pas on ôtera même ce qu''''il croit avoir."}, {"numero": 19, "texto": "La mère et les frères de Jésus vinrent le trouver; mais ils ne purent l''''aborder, à cause de la foule."}, {"numero": 20, "texto": "On lui dit: Ta mère et tes frères sont dehors, et ils désirent te voir."}, {"numero": 21, "texto": "Mais il répondit: Ma mère et mes frères, ce sont ceux qui écoutent la parole de Dieu, et qui la mettent en pratique."}, {"numero": 22, "texto": "Un jour, Jésus monta dans une barque avec ses disciples. Il leur dit: Passons de l''''autre côté du lac. Et ils partirent."}, {"numero": 23, "texto": "Pendant qu''''ils naviguaient, Jésus s''''endormit. Un tourbillon fondit sur le lac, la barque se remplissait d''''eau, et ils étaient en péril."}, {"numero": 24, "texto": "Ils s''''approchèrent et le réveillèrent, en disant: Maître, maître, nous périssons! S''''étant réveillé, il menaça le vent et les flots, qui s''''apaisèrent, et le calme revint."}, {"numero": 25, "texto": "Puis il leur dit: Où est votre foi? Saisis de frayeur et d''''étonnement, ils se dirent les uns aux autres: Quel est donc celui-ci, qui commande même au vent et à l''''eau, et à qui ils obéissent?"}, {"numero": 26, "texto": "Ils abordèrent dans le pays des Géraséniens, qui est vis-à-vis de la Galilée."}, {"numero": 27, "texto": "Lorsque Jésus fut descendu à terre, il vint au-devant de lui un homme de la ville, qui était possédé de plusieurs démons. Depuis longtemps il ne portait point de vêtement, et avait sa demeure non dans une maison, mais dans les sépulcres."}, {"numero": 28, "texto": "Ayant vu Jésus, il poussa un cri, se jeta à ses pieds, et dit d''''une voix forte: Qu''''y a-t-il entre moi et toi, Jésus, Fils du Dieu Très-Haut? Je t''''en supplie, ne me tourmente pas."}, {"numero": 29, "texto": "Car Jésus commandait à l''''esprit impur de sortir de cet homme, dont il s''''était emparé depuis longtemps; on le gardait lié de chaînes et les fers aux pieds, mais il rompait les liens, et il était entraîné par le démon dans les déserts."}, {"numero": 30, "texto": "Jésus lui demanda: Quel est ton nom? Légion, répondit-il. Car plusieurs démons étaient entrés en lui."}, {"numero": 31, "texto": "Et ils priaient instamment Jésus de ne pas leur ordonner d''''aller dans l''''abîme."}, {"numero": 32, "texto": "Il y avait là, dans la montagne, un grand troupeau de pourceaux qui paissaient. Et les démons supplièrent Jésus de leur permettre d''''entrer dans ces pourceaux. Il le leur permit."}, {"numero": 33, "texto": "Les démons sortirent de cet homme, entrèrent dans les pourceaux, et le troupeau se précipita des pentes escarpées dans le lac, et se noya."}, {"numero": 34, "texto": "Ceux qui les faisaient paître, voyant ce qui était arrivé, s''''enfuirent, et répandirent la nouvelle dans la ville et dans les campagnes."}, {"numero": 35, "texto": "Les gens allèrent voir ce qui était arrivé. Ils vinrent auprès de Jésus, et ils trouvèrent l''''homme de qui étaient sortis les démons, assis à ses pieds, vêtu, et dans son bon sens; et ils furent saisis de frayeur."}, {"numero": 36, "texto": "Ceux qui avaient vu ce qui s''''était passé leur racontèrent comment le démoniaque avait été guéri."}, {"numero": 37, "texto": "Tous les habitants du pays des Géraséniens prièrent Jésus de s''''éloigner d''''eux, car ils étaient saisis d''''une grande crainte. Jésus monta dans la barque, et s''''en retourna."}, {"numero": 38, "texto": "L''''homme de qui étaient sortis les démons lui demandait la permission de rester avec lui. Mais Jésus le renvoya, en disant:"}, {"numero": 39, "texto": "Retourne dans ta maison, et raconte tout ce que Dieu t''''a fait. Il s''''en alla, et publia par toute la ville tout ce que Jésus avait fait pour lui."}, {"numero": 40, "texto": "A son retour, Jésus fut reçu par la foule, car tous l''''attendaient."}, {"numero": 41, "texto": "Et voici, il vint un homme, nommé Jaïrus, qui était chef de la synagogue. Il se jeta à ses pieds, et le supplia d''''entrer dans sa maison,"}, {"numero": 42, "texto": "parce qu''''il avait une fille unique d''''environ douze ans qui se mourait. Pendant que Jésus y allait, il était pressé par la foule."}, {"numero": 43, "texto": "Or, il y avait une femme atteinte d''''une perte de sang depuis douze ans, et qui avait dépensé tout son bien pour les médecins, sans qu''''aucun ait pu la guérir."}, {"numero": 44, "texto": "Elle s''''approcha par derrière, et toucha le bord du vêtement de Jésus. Au même instant la perte de sang s''''arrêta."}, {"numero": 45, "texto": "Et Jésus dit: Qui m''''a touché? Comme tous s''''en défendaient, Pierre et ceux qui étaient avec lui dirent: Maître, la foule t''''entoure et te presse, et tu dis: Qui m''''a touché?"}, {"numero": 46, "texto": "Mais Jésus répondit: Quelqu''''un m''''a touché, car j''''ai connu qu''''une force était sortie de moi."}, {"numero": 47, "texto": "La femme, se voyant découverte, vint toute tremblante se jeter à ses pieds, et déclara devant tout le peuple pourquoi elle l''''avait touché, et comment elle avait été guérie à l''''instant."}, {"numero": 48, "texto": "Jésus lui dit: Ma fille, ta foi t''''a sauvée; va en paix."}, {"numero": 49, "texto": "Comme il parlait encore, survint de chez le chef de la synagogue quelqu''''un disant: Ta fille est morte; n''''importune pas le maître."}, {"numero": 50, "texto": "Mais Jésus, ayant entendu cela, dit au chef de la synagogue: Ne crains pas, crois seulement, et elle sera sauvée."}, {"numero": 51, "texto": "Lorsqu''''il fut arrivé à la maison, il ne permit à personne d''''entrer avec lui, si ce n''''est à Pierre, à Jean et à Jacques, et au père et à la mère de l''''enfant."}, {"numero": 52, "texto": "Tous pleuraient et se lamentaient sur elle. Alors Jésus dit: Ne pleurez pas; elle n''''est pas morte, mais elle dort."}, {"numero": 53, "texto": "Et ils se moquaient de lui, sachant qu''''elle était morte."}, {"numero": 54, "texto": "Mais il la saisit par la main, et dit d''''une voix forte: Enfant, lève-toi."}, {"numero": 55, "texto": "Et son esprit revint en elle, et à l''''instant elle se leva; et Jésus ordonna qu''''on lui donnât à manger."}, {"numero": 56, "texto": "Les parents de la jeune fille furent dans l''''étonnement, et il leur recommanda de ne dire à personne ce qui était arrivé."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 8, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ después, que él caminaba por todas las ciudades y aldeas, predicando y anunciando el evangelio del reino de Dios, y los doce con él,"}, {"numero": 2, "texto": "Y algunas mujeres que habían sido curadas de malos espíritus y de enfermedades: María, que se llamaba Magdalena, de la cual habían salido siete demonios,"}, {"numero": 3, "texto": "Y Juana, mujer de Chuza, procurador de Herodes, y Susana, y otras muchas que le servían de sus haciendas."}, {"numero": 4, "texto": "Y como se juntó una grande compañía, y los que estaban en cada ciudad vinieron á él, dijo por una parábola:"}, {"numero": 5, "texto": "Uno que sembraba, salió á sembrar su simiente; y sembrando, una parte cayó junto al camino, y fué hollada; y las aves del cielo la comieron."}, {"numero": 6, "texto": "Y otra parte cayó sobre la piedra; y nacida, se secó, porque no tenía humedad."}, {"numero": 7, "texto": "Y otra parte cayó entre las espinas; y naciendo las espinas juntamente, la ahogaron."}, {"numero": 8, "texto": "Y otra parte cayó en buena tierra, y cuando fué nacida, llevó fruto á ciento por uno. Diciendo estas cosas clamaba: El que tiene oídos para oir, oiga."}, {"numero": 9, "texto": "Y sus discípulos le preguntaron, diciendo, qué era esta parábola."}, {"numero": 10, "texto": "Y él dijo: A vosotros es dado conocer los misterios del reino de Dios; mas á los otros por parábolas, para que viendo no vean, y oyendo no entiendan."}, {"numero": 11, "texto": "Es pues ésta la parábola: La simiente es la palabra de Dios."}, {"numero": 12, "texto": "Y los de junto al camino, éstos son los que oyen; y luego viene el diablo, y quita la palabra de su corazón, porque no crean y se salven."}, {"numero": 13, "texto": "Y los de sobre la piedra, son los que habiendo oído, reciben la palabra con gozo; mas éstos no tienen raíces; que á tiempo creen, y en el tiempo de la tentación se apartan."}, {"numero": 14, "texto": "Y la que cayó entre las espinas, éstos son los que oyeron; mas yéndose, son ahogados de los cuidados y de las riquezas y de los pasatiempos de la vida, y no llevan fruto."}, {"numero": 15, "texto": "Mas la que en buena tierra, éstos son los que con corazón bueno y recto retienen la palabra oída, y llevan fruto en paciencia."}, {"numero": 16, "texto": "Ninguno que enciende la antorcha la cubre con vasija, ó la pone debajo de la cama; mas la pone en un candelero, para que los que entran vean la luz."}, {"numero": 17, "texto": "Porque no hay cosa oculta, que no haya de ser manifestada; ni cosa escondida, que no haya de ser entendida, y de venir á luz."}, {"numero": 18, "texto": "Mirad pues cómo oís; porque á cualquiera que tuviere, le será dado; y á cualquiera que no tuviere, aun lo que parece tener le será quitado."}, {"numero": 19, "texto": "Y vinieron á él su madre y hermanos; y no podían llegar á él por causa de la multitud."}, {"numero": 20, "texto": "Y le fué dado aviso, diciendo: Tu madre y tus hermanos están fuera, que quieren verte."}, {"numero": 21, "texto": "El entonces respondiendo, les dijo: Mi madre y mis hermanos son los que oyen la palabra de Dios, y la ejecutan."}, {"numero": 22, "texto": "Y aconteció un día que él entró en un barco con sus discípulos, y les dijo: Pasemos á la otra parte del lago. Y partieron."}, {"numero": 23, "texto": "Pero mientras ellos navegaban, él se durmió. Y sobrevino una tempestad de viento en el lago; y henchían de agua, y peligraban."}, {"numero": 24, "texto": "Y llegándose á él, le despertaron, diciendo: ¡Maestro, Maestro, que perecemos! Y despertado él, increpó al viento y á la tempestad del agua; y cesaron, y fué hecha bonanza."}, {"numero": 25, "texto": "Y les dijo: ¿Qué es de vuestra fe? Y atemorizados, se maravillaban, diciendo los unos á los otros: ¿Quién es éste, que aun á los vientos y al agua manda, y le obedecen?"}, {"numero": 26, "texto": "Y navegaron á la tierra de los Gadarenos, que está delante de Galilea."}, {"numero": 27, "texto": "Y saliendo él á tierra, le vino al encuentro de la ciudad un hombre que tenía demonios ya de mucho tiempo; y no vestía vestido, ni estaba en casa, sino por los sepulcros."}, {"numero": 28, "texto": "El cual, como vió á Jesús, exclamó y se postró delante de él, y dijo á gran voz: ¿Qué tengo yo contigo, Jesús, Hijo del Dios Altísimo? Ruégote que no me atormentes."}, {"numero": 29, "texto": "(Porque mandaba al espíritu inmundo que saliese del hombre: porque ya de mucho tiempo le arrebataba; y le guardaban preso con cadenas y grillos; mas rompiendo las prisiones, era agitado del demonio por los desiertos.)"}, {"numero": 30, "texto": "Y le preguntó Jesús, diciendo: ¿Qué nombre tienes? Y él dijo: Legión. Porque muchos demonios habían entrado en él."}, {"numero": 31, "texto": "Y le rogaban que no les mandase ir al abismo."}, {"numero": 32, "texto": "Y había allí un hato de muchos puercos que pacían en el monte; y le rogaron que los dejase entrar en ellos; y los dejó."}, {"numero": 33, "texto": "Y salidos los demonios del hombre, entraron en los puercos; y el hato se arrojó de un despeñadero en el lago, y ahogóse."}, {"numero": 34, "texto": "Y los pastores, como vieron lo que había acontecido, huyeron, y yendo dieron aviso en la ciudad y por las heredades."}, {"numero": 35, "texto": "Y salieron á ver lo que había acontecido; y vinieron á Jesús, y hallaron sentado al hombre de quien habían salido los demonios, vestido, y en su juicio, á los pies de Jesús; y tuvieron miedo."}, {"numero": 36, "texto": "Y les contaron los que lo habían visto, cómo había sido salvado aquel endemoniado."}, {"numero": 37, "texto": "Entonces toda la multitud de la tierra de los Gadarenos alrededor, le rogaron que se fuese de ellos; porque tenían gran temor. Y él, subiendo en el barco, volvióse."}, {"numero": 38, "texto": "Y aquel hombre, de quien habían salido los demonios, le rogó para estar con él; mas Jesús le despidió, diciendo:"}, {"numero": 39, "texto": "Vuélvete á tu casa, y cuenta cuán grandes cosas ha hecho Dios contigo. Y él se fué, publicando por toda la ciudad cuán grandes cosas había hecho Jesús con él."}, {"numero": 40, "texto": "Y aconteció que volviendo Jesús, recibióle la gente; porque todos le esperaban."}, {"numero": 41, "texto": "Y he aquí un varón, llamado Jairo, y que era príncipe de la sinagoga, vino, y cayendo á los pies de Jesús, le rogaba que entrase en su casa;"}, {"numero": 42, "texto": "Porque tenía una hija única, como de doce años, y ella se estaba muriendo. Y yendo, le apretaba la compañía."}, {"numero": 43, "texto": "Y una mujer, que tenía flujo de sangre hacía ya doce años, la cual había gastado en médicos toda su hacienda, y por ninguno había podido ser curada,"}, {"numero": 44, "texto": "Llegándose por las espaldas, tocó el borde de su vestido; y luego se estancó el flujo de su sangre."}, {"numero": 45, "texto": "Entonces Jesús dijo: ¿Quién es el que me ha tocado? Y negando todos, dijo Pedro y los que estaban con él: Maestro, la compañía te aprieta y oprime, y dices: ¿Quién es el que me ha tocado?"}, {"numero": 46, "texto": "Y Jesús dijo: Me ha tocado alguien; porque yo he conocido que ha salido virtud de mí."}, {"numero": 47, "texto": "Entonces, como la mujer vió que no se había ocultado, vino temblando, y postrándose delante de él declaróle delante de todo el pueblo la causa por qué le había tocado, y cómo luego había sido sana."}, {"numero": 48, "texto": "Y él le dijo: Hija, tu fe te ha salvado: ve en paz."}, {"numero": 49, "texto": "Estando aún él hablando, vino uno del príncipe de la sinagoga á decirle: Tu hija es muerta, no des trabajo al Maestro."}, {"numero": 50, "texto": "Y oyéndolo Jesús, le respondió: No temas: cree solamente, y será salva."}, {"numero": 51, "texto": "Y entrado en casa, no dejó entrar á nadie consigo, sino á Pedro, y á Jacobo, y á Juan, y al padre y á la madre de la moza."}, {"numero": 52, "texto": "Y lloraban todos, y la plañían. Y él dijo: No lloréis; no es muerta, sino que duerme."}, {"numero": 53, "texto": "Y hacían burla de él, sabiendo que estaba muerta."}, {"numero": 54, "texto": "Mas él, tomándola de la mano, clamó, diciendo: Muchacha, levántate."}, {"numero": 55, "texto": "Entonces su espíritu volvió, y se levantó luego: y él mandó que le diesen de comer."}, {"numero": 56, "texto": "Y sus padres estaban atónitos; á los cuales él mandó, que á nadie dijesen lo que había sido hecho."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 9, 'pt', '[{"numero": 1, "texto": "[Jesus] convocou seus doze discípulos, e lhes deu poder e autoridade sobre todos os demônios, e para curarem enfermidades."}, {"numero": 2, "texto": "E os enviou para pregar o reino de Deus e para curar os enfermos."}, {"numero": 3, "texto": "E disse-lhes: “Não tomeis nada convosco para o caminho: nem vara, nem bolsa, nem pão, nem dinheiro, nem tenhais duas túnicas cada um."}, {"numero": 4, "texto": "E em qualquer casa que entrardes, ficai ali, e dali saí."}, {"numero": 5, "texto": "E a todo os que não vos receberem, quando sairdes daquela cidade, sacudi até o pó dos vossos pés, em testemunho contra eles”."}, {"numero": 6, "texto": "Então eles partiram, e percorreram todas as aldeias, anunciando o Evangelho, e curando em todos os lugares."}, {"numero": 7, "texto": "E o tetrarca Herodes ouvia falar todas as coisas que ele fazia; e estava perplexo, porque alguns diziam que João tinha ressuscitado dos mortos;"}, {"numero": 8, "texto": "e outros, que Elias havia aparecido; e outros, que algum profeta dos antigos havia ressuscitado."}, {"numero": 9, "texto": "E Herodes disse: “A João mandei degolar; quem, pois, é este, de quem tais coisas ouço?” E procurava vê-lo."}, {"numero": 10, "texto": "E quando os apóstolos, voltaram, contaram [a Jesus] todas as coisas que tinham feito. Então ele os tomou consigo, e retirou-se à parte a um lugar deserto de uma cidade chamada Betsaida."}, {"numero": 11, "texto": "E quando as multidões souberam, seguiram-no. Ele as recebeu, e lhes falava do Reino de Deus, e curava aos que precisavam de cura."}, {"numero": 12, "texto": "E o dia já começava a declinar. Então os doze se aproximaram dele, e lhe disseram: “Despede a multidão, para irem aos lugares e aldeias ao redor, se agasalhem, e achem o que comer; porque aqui estamos em lugar deserto”."}, {"numero": 13, "texto": "Mas ele lhes disse: “Dai-lhes vós de comer”. E eles disseram: “Não temos mais que cinco pães e dois peixes; a não ser se formos nós mesmos comprar de comer para todo este povo”."}, {"numero": 14, "texto": "Porque havia ali quase cinco mil homens. Então disse aos seus discípulos: “Fazei-os se sentarem em grupos de cinquenta em cinquenta”."}, {"numero": 15, "texto": "E assim procederam, fazendo todos se sentarem."}, {"numero": 16, "texto": "Então ele tomou os cinco pães e os dois peixes e, olhando para o céu, abençoou-os e partiu-os, e os deu a seus discípulos, para [os] porem diante da multidão."}, {"numero": 17, "texto": "E todos comeram, e saciaram-se; e levantaram doze cestos de pedaços que sobraram."}, {"numero": 18, "texto": "E aconteceu que, quando ele estava orando só, e seus discípulos estavam com ele, que ele lhes perguntou: “Quem as multidões dizem que eu sou?”"}, {"numero": 19, "texto": "E eles responderam: “[Uns] , João Batista; outros, Elias; e outros, que algum dos profetas antigos ressuscitou”."}, {"numero": 20, "texto": "E disse-lhes: “E vós, quem dizeis que eu sou?” E Pedro respondeu: “O Cristo de Deus”."}, {"numero": 21, "texto": "Então ele os alertou, e mandou-lhes que não dissessem a ninguém,"}, {"numero": 22, "texto": "dizendo: “É necessário que o Filho do homem sofra muitas coisas; que seja rejeitado pelos anciãos, pelos chefes dos sacerdotes, e pelos escribas; que seja morto, e que seja ressuscitado ao terceiro dia”."}, {"numero": 23, "texto": "E dizia a todos: “Se alguém quer vir após mim, negue-se a si mesmo, tome cada dia sua cruz, e siga- me."}, {"numero": 24, "texto": "Pois quem quiser salvar sua vida a perderá; porém quem, por minha causa, perder a sua vida, esse a salvará."}, {"numero": 25, "texto": "Porque, que aproveita para alguém ganhar o mundo todo, e perder ou prejudicar a si mesmo?"}, {"numero": 26, "texto": "Pois quem se envergonhar de mim e das minhas palavras, dele o Filho do homem se envergonhará, quando vier na sua glória, e na do Pai, e dos santos anjos."}, {"numero": 27, "texto": "E em verdade vos digo que, dentre os que aqui estão, há alguns que não experimentarão a morte, até que vejam o Reino de Deus”."}, {"numero": 28, "texto": "E aconteceu que, quase oito dias depois dessas palavras, ele tomou consigo a Pedro, João, e a Jacó, e subiu ao monte para orar."}, {"numero": 29, "texto": "E ele, enquanto estava orando, a aparência do seu rosto se transfigurou, e sua roupa [ficou] branca e brilhante."}, {"numero": 30, "texto": "E eis que estavam falando com ele dois homens, que eram Moisés e Elias,"}, {"numero": 31, "texto": "os quais apareceram com glória, e falavam de sua partida, que estava para se cumprir em Jerusalém."}, {"numero": 32, "texto": "Pedro e os que estavam com ele estavam cheios de sono; e quando despertaram, viram a glória dele, e aqueles dois homens que estavam com ele."}, {"numero": 33, "texto": "E aconteceu que, quando eles estavam saíndo da presença dele, Pedro disse a Jesus: “Mestre, é bom estarmos nós aqui. Façamos três tendas, uma para ti, uma para Moisés, e uma para Elias”, não sabendo o que dizia."}, {"numero": 34, "texto": "E enquanto ele dizia isso, veio uma nuvem que os cobriu com a sua sombra; e, quando entraram na nuvem, temeram."}, {"numero": 35, "texto": "E veio uma voz da nuvem, que dizia: “Este é o meu Filho amado; a ele ouvi”."}, {"numero": 36, "texto": "E, depois de terminada aquela voz, Jesus se encontrava só; e eles se calaram, e por aqueles dias não contaram a ninguém nada do que tinham visto."}, {"numero": 37, "texto": "E aconteceu no dia seguinte que, descendo eles do monte, uma grande multidão lhe saiu ao encontro."}, {"numero": 38, "texto": "E eis que um homem da multidão clamou: “Mestre, rogo-te que vejas a meu filho, que é o único que tenho,"}, {"numero": 39, "texto": "e eis que um espírito o toma, e de repente grita, e o convulsiona até espumar, e somente sai dele quando o maltrata severamente."}, {"numero": 40, "texto": "E roguei aos teus discípulos que o exupulsassem, mas não conseguiram”."}, {"numero": 41, "texto": "E Jesus respondeu: “Ó geração incrédula e perversa! Até quando estarei ainda convosco, e vos suportarei? Traze aqui teu filho”."}, {"numero": 42, "texto": "E quando ainda vinha chegando, o demônio o derrubou, e o convulsionou. Porém Jesus repreendeu o espírito imundo, curou ao menino, e o devolveu ao seu pai."}, {"numero": 43, "texto": "E todos ficaram perplexos com a grandeza de Deus. E enquanto todos se maravilhavam de tudo o que Jesus fazia, disse aos seus discípulos:"}, {"numero": 44, "texto": "“Ponde vós em vossos ouvidos estas palavras: que o Filho do homem será entregue nas mãos dos homens”."}, {"numero": 45, "texto": "Mas eles não entendiam essa palavra, e era-lhes encoberta, para que não a compreendessem; e temiam perguntar-lhe sobre essa palavra."}, {"numero": 46, "texto": "E levantou-se entre eles uma discussão sobre qual deles seria o maior."}, {"numero": 47, "texto": "Mas Jesus, conhecendo o pensamento de seus corações, pegou uma criança, e a pôs junto a si."}, {"numero": 48, "texto": "Então disse-lhes: “Quem receber esta criança em meu nome, a mim me recebe; e quem receber a mim, recebe o que me enviou; porque aquele que entre todos vós for o menor, esse será grande”."}, {"numero": 49, "texto": "João respondeu: “Mestre, vimos um que em teu nome expulsava os demônios, e nós o proibimos, porque não segue conosco”."}, {"numero": 50, "texto": "E Jesus lhe disse: “Não o proibais, porque quem não é contra nós, é por nós”."}, {"numero": 51, "texto": "E aconteceu que, quando completaram-se os dias em que ele viria a ser recebido no alto, ele se determinou a ir para Jerusalém."}, {"numero": 52, "texto": "E mandou mensageiros adiante de si; e eles se foram, e entraram numa aldeia de samaritanos, para lhe fazerem os preparativos."}, {"numero": 53, "texto": "Mas não o receberam, porque seu rosto demonstrava que ele ia para Jerusalém."}, {"numero": 54, "texto": "Quando seus discípulos, Tiago e João, viram [isso] , disseram: “Senhor, queres que digamos que desça fogo do céu e os consuma, como Elias também fez?”"}, {"numero": 55, "texto": "Porém ele se virou, repreendeu-os, e disse: Vós não sabeis de que espírito sois."}, {"numero": 56, "texto": "Porque o Filho do homem não veio para destruir as almas dos seres humanos, mas sim para salvá-las.E foram para outra aldeia."}, {"numero": 57, "texto": "E aconteceu que, enquanto eles iam pelo caminho, alguém lhe disse: “Senhor, eu te seguirei para onde quer que fores”."}, {"numero": 58, "texto": "E Jesus lhe disse: “As raposas têm tocas, e as aves do céu, ninhos; mas o Filho do homem não tem onde deitar a cabeça”."}, {"numero": 59, "texto": "E disse a outro: “Segue-me”. Porém ele disse: “Senhor, deixa-me que primeiro eu vá, e eu enterre meu pai”."}, {"numero": 60, "texto": "Mas Jesus lhe disse: “Deixa os mortos enterrarem os seus próprios mortos; tu, porém, vai, e anuncia o reino de Deus”."}, {"numero": 61, "texto": "E outro também disse: “Senhor, eu te seguirei; mas deixa-me primeiro despedir dos que estão em minha casa”."}, {"numero": 62, "texto": "E Jesus lhe disse: “Ninguém que colocar a sua mão no arado e olhar para trás é apto para o reino de Deus”."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 9, 'en', '[{"numero": 1, "texto": "Then he called his twelve disciples together, and gave them power and authority over all devils, and to cure diseases."}, {"numero": 2, "texto": "And he sent them to preach the kingdom of God, and to heal the sick."}, {"numero": 3, "texto": "And he said unto them, Take nothing for your journey, neither staves, nor scrip, neither bread, neither money; neither have two coats apiece."}, {"numero": 4, "texto": "And whatsoever house ye enter into, there abide, and thence depart."}, {"numero": 5, "texto": "And whosoever will not receive you, when ye go out of that city, shake off the very dust from your feet for a testimony against them."}, {"numero": 6, "texto": "And they departed, and went through the towns, preaching the gospel, and healing every where."}, {"numero": 7, "texto": "Now Herod the tetrarch heard of all that was done by him: and he was perplexed, because that it was said of some, that John was risen from the dead;"}, {"numero": 8, "texto": "And of some, that Elias had appeared; and of others, that one of the old prophets was risen again."}, {"numero": 9, "texto": "And Herod said, John have I beheaded: but who is this, of whom I hear such things? And he desired to see him."}, {"numero": 10, "texto": "And the apostles, when they were returned, told him all that they had done. And he took them, and went aside privately into a desert place belonging to the city called Bethsaida."}, {"numero": 11, "texto": "And the people, when they knew it, followed him: and he received them, and spake unto them of the kingdom of God, and healed them that had need of healing."}, {"numero": 12, "texto": "And when the day began to wear away, then came the twelve, and said unto him, Send the multitude away, that they may go into the towns and country round about, and lodge, and get victuals: for we are here in a desert place."}, {"numero": 13, "texto": "But he said unto them, Give ye them to eat. And they said, We have no more but five loaves and two fishes; except we should go and buy meat for all this people."}, {"numero": 14, "texto": "For they were about five thousand men. And he said to his disciples, Make them sit down by fifties in a company."}, {"numero": 15, "texto": "And they did so, and made them all sit down."}, {"numero": 16, "texto": "Then he took the five loaves and the two fishes, and looking up to heaven, he blessed them, and brake, and gave to the disciples to set before the multitude."}, {"numero": 17, "texto": "And they did eat, and were all filled: and there was taken up of fragments that remained to them twelve baskets."}, {"numero": 18, "texto": "And it came to pass, as he was alone praying, his disciples were with him: and he asked them, saying, Whom say the people that I am?"}, {"numero": 19, "texto": "They answering said, John the Baptist; but some say, Elias; and others say, that one of the old prophets is risen again."}, {"numero": 20, "texto": "He said unto them, But whom say ye that I am? Peter answering said, The Christ of God."}, {"numero": 21, "texto": "And he straitly charged them, and commanded them to tell no man that thing;"}, {"numero": 22, "texto": "Saying, The Son of man must suffer many things, and be rejected of the elders and chief priests and scribes, and be slain, and be raised the third day."}, {"numero": 23, "texto": "And he said to them all, If any man will come after me, let him deny himself, and take up his cross daily, and follow me."}, {"numero": 24, "texto": "For whosoever will save his life shall lose it: but whosoever will lose his life for my sake, the same shall save it."}, {"numero": 25, "texto": "For what is a man advantaged, if he gain the whole world, and lose himself, or be cast away?"}, {"numero": 26, "texto": "For whosoever shall be ashamed of me and of my words, of him shall the Son of man be ashamed, when he shall come in his own glory, and in his Father''s, and of the holy angels."}, {"numero": 27, "texto": "But I tell you of a truth, there be some standing here, which shall not taste of death, till they see the kingdom of God."}, {"numero": 28, "texto": "And it came to pass about an eight days after these sayings, he took Peter and John and James, and went up into a mountain to pray."}, {"numero": 29, "texto": "And as he prayed, the fashion of his countenance was altered, and his raiment was white and glistering."}, {"numero": 30, "texto": "And, behold, there talked with him two men, which were Moses and Elias:"}, {"numero": 31, "texto": "Who appeared in glory, and spake of his decease which he should accomplish at Jerusalem."}, {"numero": 32, "texto": "But Peter and they that were with him were heavy with sleep: and when they were awake, they saw his glory, and the two men that stood with him."}, {"numero": 33, "texto": "And it came to pass, as they departed from him, Peter said unto Jesus, Master, it is good for us to be here: and let us make three tabernacles; one for thee, and one for Moses, and one for Elias: not knowing what he said."}, {"numero": 34, "texto": "While he thus spake, there came a cloud, and overshadowed them: and they feared as they entered into the cloud."}, {"numero": 35, "texto": "And there came a voice out of the cloud, saying, This is my beloved Son: hear him."}, {"numero": 36, "texto": "And when the voice was past, Jesus was found alone. And they kept it close, and told no man in those days any of those things which they had seen."}, {"numero": 37, "texto": "And it came to pass, that on the next day, when they were come down from the hill, much people met him."}, {"numero": 38, "texto": "And, behold, a man of the company cried out, saying, Master, I beseech thee, look upon my son: for he is mine only child."}, {"numero": 39, "texto": "And, lo, a spirit taketh him, and he suddenly crieth out; and it teareth him that he foameth again, and bruising him hardly departeth from him."}, {"numero": 40, "texto": "And I besought thy disciples to cast him out; and they could not."}, {"numero": 41, "texto": "And Jesus answering said, O faithless and perverse generation, how long shall I be with you, and suffer you? Bring thy son hither."}, {"numero": 42, "texto": "And as he was yet a coming, the devil threw him down, and tare him. And Jesus rebuked the unclean spirit, and healed the child, and delivered him again to his father."}, {"numero": 43, "texto": "And they were all amazed at the mighty power of God. But while they wondered every one at all things which Jesus did, he said unto his disciples,"}, {"numero": 44, "texto": "Let these sayings sink down into your ears: for the Son of man shall be delivered into the hands of men."}, {"numero": 45, "texto": "But they understood not this saying, and it was hid from them, that they perceived it not: and they feared to ask him of that saying."}, {"numero": 46, "texto": "Then there arose a reasoning among them, which of them should be greatest."}, {"numero": 47, "texto": "And Jesus, perceiving the thought of their heart, took a child, and set him by him,"}, {"numero": 48, "texto": "And said unto them, Whosoever shall receive this child in my name receiveth me: and whosoever shall receive me receiveth him that sent me: for he that is least among you all, the same shall be great."}, {"numero": 49, "texto": "And John answered and said, Master, we saw one casting out devils in thy name; and we forbad him, because he followeth not with us."}, {"numero": 50, "texto": "And Jesus said unto him, Forbid him not: for he that is not against us is for us."}, {"numero": 51, "texto": "And it came to pass, when the time was come that he should be received up, he stedfastly set his face to go to Jerusalem,"}, {"numero": 52, "texto": "And sent messengers before his face: and they went, and entered into a village of the Samaritans, to make ready for him."}, {"numero": 53, "texto": "And they did not receive him, because his face was as though he would go to Jerusalem."}, {"numero": 54, "texto": "And when his disciples James and John saw this, they said, Lord, wilt thou that we command fire to come down from heaven, and consume them, even as Elias did?"}, {"numero": 55, "texto": "But he turned, and rebuked them, and said, Ye know not what manner of spirit ye are of."}, {"numero": 56, "texto": "For the Son of man is not come to destroy men''s lives, but to save them. And they went to another village."}, {"numero": 57, "texto": "And it came to pass, that, as they went in the way, a certain man said unto him, Lord, I will follow thee whithersoever thou goest."}, {"numero": 58, "texto": "And Jesus said unto him, Foxes have holes, and birds of the air have nests; but the Son of man hath not where to lay his head."}, {"numero": 59, "texto": "And he said unto another, Follow me. But he said, Lord, suffer me first to go and bury my father."}, {"numero": 60, "texto": "Jesus said unto him, Let the dead bury their dead: but go thou and preach the kingdom of God."}, {"numero": 61, "texto": "And another also said, Lord, I will follow thee; but let me first go bid them farewell, which are at home at my house."}, {"numero": 62, "texto": "And Jesus said unto him, No man, having put his hand to the plough, and looking back, is fit for the kingdom of God."}]'::jsonb, 'King James Version'),
  ('Lc', 9, 'fr', '[{"numero": 1, "texto": "Jésus, ayant assemblé les douze, leur donna force et pouvoir sur tous les démons, avec la puissance de guérir les maladies."}, {"numero": 2, "texto": "Il les envoya prêcher le royaume de Dieu, et guérir les malades."}, {"numero": 3, "texto": "Ne prenez rien pour le voyage, leur dit-il, ni bâton, ni sac, ni pain, ni argent, et n''''ayez pas deux tuniques."}, {"numero": 4, "texto": "Dans quelque maison que vous entriez, restez-y; et c''''est de là que vous partirez."}, {"numero": 5, "texto": "Et, si les gens ne vous reçoivent pas, sortez de cette ville, et secouez la poussière de vos pieds, en témoignage contre eux."}, {"numero": 6, "texto": "Ils partirent, et ils allèrent de village en village, annonçant la bonne nouvelle et opérant partout des guérisons."}, {"numero": 7, "texto": "Hérode le tétrarque entendit parler de tout ce qui se passait, et il ne savait que penser. Car les uns disaient que Jean était ressuscité des morts;"}, {"numero": 8, "texto": "d''''autres, qu''''Elie était apparu; et d''''autres, qu''''un des anciens prophètes était ressuscité."}, {"numero": 9, "texto": "Mais Hérode disait: J''''ai fait décapiter Jean; qui donc est celui-ci, dont j''''entends dire de telles choses? Et il cherchait à le voir."}, {"numero": 10, "texto": "Les apôtres, étant de retour, racontèrent à Jésus tout ce qu''''ils avaient fait. Il les prit avec lui, et se retira à l''''écart, du côté d''''une ville appelée Bethsaïda."}, {"numero": 11, "texto": "Les foules, l''''ayant su, le suivirent. Jésus les accueillit, et il leur parlait du royaume de Dieu; il guérit aussi ceux qui avaient besoin d''''être guéris."}, {"numero": 12, "texto": "Comme le jour commençait à baisser, les douze s''''approchèrent, et lui dirent: Renvoie la foule, afin qu''''elle aille dans les villages et dans les campagnes des environs, pour se loger et pour trouver des vivres; car nous sommes ici dans un lieu désert."}, {"numero": 13, "texto": "Jésus leur dit: Donnez-leur vous-mêmes à manger. Mais ils répondirent: Nous n''''avons que cinq pains et deux poissons, à moins que nous n''''allions nous-mêmes acheter des vivres pour tout ce peuple."}, {"numero": 14, "texto": "Or, il y avait environ cinq mille hommes. Jésus dit à ses disciples: Faites-les asseoir par rangées de cinquante."}, {"numero": 15, "texto": "Ils firent ainsi, ils les firent tous asseoir."}, {"numero": 16, "texto": "Jésus prit les cinq pains et les deux poissons, et, levant les yeux vers le ciel, il les bénit. Puis, il les rompit, et les donna aux disciples, afin qu''''ils les distribuassent à la foule."}, {"numero": 17, "texto": "Tous mangèrent et furent rassasiés, et l''''on emporta douze paniers pleins des morceaux qui restaient."}, {"numero": 18, "texto": "Un jour que Jésus priait à l''''écart, ayant avec lui ses disciples, il leur posa cette question: Qui dit-on que je suis?"}, {"numero": 19, "texto": "Ils répondirent: Jean Baptiste; les autres, Elie; les autres, qu''''un des anciens prophètes est ressuscité."}, {"numero": 20, "texto": "Et vous, leur demanda-t-il, qui dites-vous que je suis? Pierre répondit: Le Christ de Dieu."}, {"numero": 21, "texto": "Jésus leur recommanda sévèrement de ne le dire à personne."}, {"numero": 22, "texto": "Il ajouta qu''''il fallait que le Fils de l''''homme souffrît beaucoup, qu''''il fût rejeté par les anciens, par les principaux sacrificateurs et par les scribes, qu''''il fût mis à mort, et qu''''il ressuscitât le troisième jour."}, {"numero": 23, "texto": "Puis il dit à tous: Si quelqu''''un veut venir après moi, qu''''il renonce à lui-même, qu''''il se charge chaque jour de sa croix, et qu''''il me suive."}, {"numero": 24, "texto": "Car celui qui voudra sauver sa vie la perdra, mais celui qui la perdra à cause de moi la sauvera."}, {"numero": 25, "texto": "Et que servirait-il à un homme de gagner tout le monde, s''''il se détruisait ou se perdait lui-même?"}, {"numero": 26, "texto": "Car quiconque aura honte de moi et de mes paroles, le Fils de l''''homme aura honte de lui, quand il viendra dans sa gloire, et dans celle du Père et des saints anges."}, {"numero": 27, "texto": "Je vous le dis en vérité, quelques-uns de ceux qui sont ici ne mourront point qu''''ils n''''aient vu le royaume de Dieu."}, {"numero": 28, "texto": "Environ huit jours après qu''''il eut dit ces paroles, Jésus prit avec lui Pierre, Jean et Jacques, et il monta sur la montagne pour prier."}, {"numero": 29, "texto": "Pendant qu''''il priait, l''''aspect de son visage changea, et son vêtement devint d''''une éclatante blancheur."}, {"numero": 30, "texto": "Et voici, deux hommes s''''entretenaient avec lui: c''''étaient Moïse et Elie,"}, {"numero": 31, "texto": "qui, apparaissant dans la gloire, parlaient de son départ qu''''il allait accomplir à Jérusalem."}, {"numero": 32, "texto": "Pierre et ses compagnons étaient appesantis par le sommeil; mais, s''''étant tenus éveillés, ils virent la gloire de Jésus et les deux hommes qui étaient avec lui."}, {"numero": 33, "texto": "Au moment où ces hommes se séparaient de Jésus, Pierre lui dit: Maître, il est bon que nous soyons ici; dressons trois tentes, une pour toi, une pour Moïse, et une pour Elie. Il ne savait ce qu''''il disait."}, {"numero": 34, "texto": "Comme il parlait ainsi, une nuée vint les couvrir; et les disciples furent saisis de frayeur en les voyant entrer dans la nuée."}, {"numero": 35, "texto": "Et de la nuée sortit une voix, qui dit: Celui-ci est mon Fils élu: écoutez-le!"}, {"numero": 36, "texto": "Quand la voix se fit entendre, Jésus se trouva seul. Les disciples gardèrent le silence, et ils ne racontèrent à personne, en ce temps-là, rien de ce qu''''ils avaient vu."}, {"numero": 37, "texto": "Le lendemain, lorsqu''''ils furent descendus de la montagne, une grande foule vint au-devant de Jésus."}, {"numero": 38, "texto": "Et voici, du milieu de la foule un homme s''''écria: Maître, je t''''en prie, porte les regards sur mon fils, car c''''est mon fils unique."}, {"numero": 39, "texto": "Un esprit le saisit, et aussitôt il pousse des cris; et l''''esprit l''''agite avec violence, le fait écumer, et a de la peine à se retirer de lui, après l''''avoir tout brisé."}, {"numero": 40, "texto": "J''''ai prié tes disciples de le chasser, et ils n''''ont pas pu."}, {"numero": 41, "texto": "Race incrédule et perverse, répondit Jésus, jusqu''''à quand serai-je avec vous, et vous supporterai-je? Amène ici ton fils."}, {"numero": 42, "texto": "Comme il approchait, le démon le jeta par terre, et l''''agita avec violence. Mais Jésus menaça l''''esprit impur, guérit l''''enfant, et le rendit à son père."}, {"numero": 43, "texto": "Et tous furent frappés de la grandeur de Dieu. Tandis que chacun était dans l''''admiration de tout ce que faisait Jésus, il dit à ses disciples:"}, {"numero": 44, "texto": "Pour vous, écoutez bien ceci: Le Fils de l''''homme doit être livré entre les mains des hommes."}, {"numero": 45, "texto": "Mais les disciples ne comprenaient pas cette parole; elle était voilée pour eux, afin qu''''ils n''''en eussent pas le sens; et ils craignaient de l''''interroger à ce sujet."}, {"numero": 46, "texto": "Or, une pensée leur vint à l''''esprit, savoir lequel d''''entre eux était le plus grand."}, {"numero": 47, "texto": "Jésus, voyant la pensée de leur coeur, prit un petit enfant, le plaça près de lui,"}, {"numero": 48, "texto": "et leur dit: Quiconque reçoit en mon nom ce petit enfant me reçoit moi-même; et quiconque me reçoit reçoit celui qui m''''a envoyé. Car celui qui est le plus petit parmi vous tous, c''''est celui-là qui est grand."}, {"numero": 49, "texto": "Jean prit la parole, et dit: Maître, nous avons vu un homme qui chasse des démons en ton nom; et nous l''''en avons empêché, parce qu''''il ne nous suit pas."}, {"numero": 50, "texto": "Ne l''''en empêchez pas, lui répondit Jésus; car qui n''''est pas contre vous est pour vous."}, {"numero": 51, "texto": "Lorsque le temps où il devait être enlevé du monde approcha, Jésus prit la résolution de se rendre à Jérusalem."}, {"numero": 52, "texto": "Il envoya devant lui des messagers, qui se mirent en route et entrèrent dans un bourg des Samaritains, pour lui préparer un logement."}, {"numero": 53, "texto": "Mais on ne le reçut pas, parce qu''''il se dirigeait sur Jérusalem."}, {"numero": 54, "texto": "Les disciples Jacques et Jean, voyant cela, dirent: Seigneur, veux-tu que nous commandions que le feu descende du ciel et les consume?"}, {"numero": 55, "texto": "Jésus se tourna vers eux, et les réprimanda, disant: Vous ne savez de quel esprit vous êtes animés."}, {"numero": 56, "texto": "Car le Fils de l''''homme est venu, non pour perdre les âmes des hommes, mais pour les sauver. Et ils allèrent dans un autre bourg."}, {"numero": 57, "texto": "Pendant qu''''ils étaient en chemin, un homme lui dit: Seigneur, je te suivrai partout où tu iras."}, {"numero": 58, "texto": "Jésus lui répondit: Les renards ont des tanières, et les oiseaux du ciel ont des nids: mais le Fils de l''''homme n''''a pas un lieu où il puisse reposer sa tête."}, {"numero": 59, "texto": "Il dit à un autre: Suis-moi. Et il répondit: Seigneur, permets-moi d''''aller d''''abord ensevelir mon père."}, {"numero": 60, "texto": "Mais Jésus lui dit: Laisse les morts ensevelir leurs morts; et toi, va annoncer le royaume de Dieu."}, {"numero": 61, "texto": "Un autre dit: Je te suivrai, Seigneur, mais permets-moi d''''aller d''''abord prendre congé de ceux de ma maison."}, {"numero": 62, "texto": "Jésus lui répondit: Quiconque met la main à la charrue, et regarde en arrière, n''''est pas propre au royaume de Dieu."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 9, 'es', '[{"numero": 1, "texto": "Y JUNTANDO á sus doce discípulos, les dió virtud y potestad sobre todos los demonios, y que sanasen enfermedades."}, {"numero": 2, "texto": "Y los envió á que predicasen el reino de Dios, y que sanasen á los enfermos."}, {"numero": 3, "texto": "Y les dice: No toméis nada para el camino, ni báculo, ni alforja, ni pan, ni dinero; ni tengáis dos vestidos cada uno."}, {"numero": 4, "texto": "Y en cualquiera casa en que entrareis, quedad allí, y de allí salid."}, {"numero": 5, "texto": "Y todos los que no os recibieren, saliéndoos de aquella ciudad, aun el polvo sacudid de vuestros pies en testimonio contra ellos."}, {"numero": 6, "texto": "Y saliendo, rodeaban por todas las aldeas, anunciando el evangelio, y sanando por todas partes."}, {"numero": 7, "texto": "Y oyó Herodes el tetrarca todas las cosas que hacía; y estaba en duda, porque decían algunos: Juan ha resucitado de los muertos;"}, {"numero": 8, "texto": "Y otros: Elías ha aparecido; y otros: Algún profeta de los antiguos ha resucitado."}, {"numero": 9, "texto": "Y dijo Herodes: A Juan yo degollé: ¿quién pues será éste, de quien yo oigo tales cosas? Y procuraba verle."}, {"numero": 10, "texto": "Y vueltos los apóstoles, le contaron todas las cosas que habían hecho. Y tomándolos, se retiró aparte á un lugar desierto de la ciudad que se llama Bethsaida."}, {"numero": 11, "texto": "Y como lo entendieron las gentes, le siguieron; y él las recibió, y les hablaba del reino de Dios, y sanaba á los que tenían necesidad de cura."}, {"numero": 12, "texto": "Y el día había comenzado á declinar; y llegándose los doce, le dijeron: Despide á las gentes, para que yendo á las aldeas y heredades de alrededor, procedan á alojarse y hallen viandas; porque aquí estamos en lugar desierto."}, {"numero": 13, "texto": "Y les dice: Dadles vosotros de comer. Y dijeron ellos: No tenemos más que cinco panes y dos pescados, si no vamos nosotros á comprar viandas para toda esta compañía."}, {"numero": 14, "texto": "Y eran como cinco mil hombres. Entonces dijo á sus discípulos: Hacedlos sentar en ranchos, de cincuenta en cincuenta."}, {"numero": 15, "texto": "Y así lo hicieron, haciéndolos sentar á todos."}, {"numero": 16, "texto": "Y tomando los cinco panes y los dos pescados, mirando al cielo los bendijo, y partió, y dió á sus discípulos para que pusiesen delante de las gentes."}, {"numero": 17, "texto": "Y comieron todos, y se hartaron; y alzaron lo que les sobró, doce cestos de pedazos."}, {"numero": 18, "texto": "Y aconteció que estando él solo orando, estaban con él los discípulos; y les preguntó diciendo: ¿Quién dicen las gentes que soy?"}, {"numero": 19, "texto": "Y ellos respondieron, y dijeron: Juan el Bautista; y otros, Elías; y otros, que algún profeta de los antiguos ha resucitado."}, {"numero": 20, "texto": "Y les dijo: ¿Y vosotros, quién decís que soy? Entonces respondiendo Simón Pedro, dijo: El Cristo de Dios."}, {"numero": 21, "texto": "Mas él, conminándolos, mandó que á nadie dijesen esto;"}, {"numero": 22, "texto": "Diciendo: Es necesario que el Hijo del hombre padezca muchas cosas, y sea desechado de los ancianos, y de los príncipes de los sacerdotes, y de los escribas, y que sea muerto, y resucite al tercer día."}, {"numero": 23, "texto": "Y decía á todos: Si alguno quiere venir en pos de mí, niéguese á sí mismo, y tome su cruz cada día, y sígame."}, {"numero": 24, "texto": "Porque cualquiera que quisiere salvar su vida, la perderá; y cualquiera que perdiere su vida por causa de mí, éste la salvará."}, {"numero": 25, "texto": "Porque ¿qué aprovecha al hombre, si granjeare todo el mundo, y se pierda él á sí mismo, ó corra peligro de sí?"}, {"numero": 26, "texto": "Porque el que se avergonzare de mí y de mis palabras, de este tal el Hijo del hombre se avergonzará cuando viniere en su gloria, y del Padre, y de los santos ángeles."}, {"numero": 27, "texto": "Y os digo en verdad, que hay algunos de los que están aquí, que no gustarán la muerte, hasta que vean el reino de Dios."}, {"numero": 28, "texto": "Y aconteció como ocho días después de estas palabras, que tomó á Pedro y á Juan y á Jacobo, y subió al monte á orar."}, {"numero": 29, "texto": "Y entre tanto que oraba, la apariencia de su rostro se hizo otra, y su vestido blanco y resplandeciente."}, {"numero": 30, "texto": "Y he aquí dos varones que hablaban con él, los cuales eran Moisés y Elías;"}, {"numero": 31, "texto": "Que aparecieron en majestad, y hablaban de su salida, la cual había de cumplir en Jerusalem."}, {"numero": 32, "texto": "Y Pedro y los que estaban con él, estaban cargados de sueño: y como despertaron, vieron su majestad, y á aquellos dos varones que estaban con él."}, {"numero": 33, "texto": "Y aconteció, que apartándose ellos de él, Pedro dice á Jesús: Maestro, bien es que nos quedemos aquí: y hagamos tres pabellones, uno para ti, y uno para Moisés, y uno para Elías; no sabiendo lo que se decía."}, {"numero": 34, "texto": "Y estando él hablando esto, vino una nube que los cubrió; y tuvieron temor, entrando ellos en la nube."}, {"numero": 35, "texto": "Y vino una voz de la nube, que decía: Este es mi Hijo amado; á él oid."}, {"numero": 36, "texto": "Y pasada aquella voz, Jesús fué hallado solo: y ellos callaron; y por aquellos días no dijeron nada á nadie de lo que habían visto."}, {"numero": 37, "texto": "Y aconteció al día siguiente, que apartándose ellos del monte, gran compañía les salió al encuentro."}, {"numero": 38, "texto": "Y he aquí, un hombre de la compañía clamó, diciendo: Maestro, ruégote que veas á mi hijo; que es el único que tengo:"}, {"numero": 39, "texto": "Y he aquí un espíritu le toma, y de repente da voces; y le despedaza y hace echar espuma, y apenas se aparta de él quebrantándole."}, {"numero": 40, "texto": "Y rogué á tus discípulos que le echasen fuera, y no pudieron."}, {"numero": 41, "texto": "Y respondiendo Jesús, dice: ¡Oh generación infiel y perversa! ¿hasta cuándo tengo de estar con vosotros, y os sufriré? Trae tu hijo acá."}, {"numero": 42, "texto": "Y como aun se acercaba, el demonio le derribó y despedazó: mas Jesús increpó al espíritu inmundo, y sanó al muchacho, y se lo volvió á su padre."}, {"numero": 43, "texto": "Y todos estaban atónitos de la grandeza de Dios. Y maravillándose todos de todas las cosas que hacía, dijo á sus discípulos:"}, {"numero": 44, "texto": "Poned vosotros en vuestros oídos estas palabras; porque ha de acontecer que el Hijo del hombre será entregado en manos de hombres."}, {"numero": 45, "texto": "Mas ellos no entendían esta palabra, y les era encubierta para que no la entendiesen; y temían preguntarle de esta palabra."}, {"numero": 46, "texto": "Entonces entraron en disputa, cuál de ellos sería el mayor."}, {"numero": 47, "texto": "Mas Jesús, viendo los pensamientos del corazón de ellos, tomó un niño, y púsole junto á sí,"}, {"numero": 48, "texto": "Y les dice: Cualquiera que recibiere este niño en mi nombre, á mí recibe; y cualquiera que me recibiere á mí, recibe al que me envió; porque el que fuere el menor entre todos vosotros, éste será el grande."}, {"numero": 49, "texto": "Entonces respondiendo Juan, dijo: Maestro, hemos visto á uno que echaba fuera demonios en tu nombre; y se lo prohibimos, porque no sigue con nosotros."}, {"numero": 50, "texto": "Jesús le dijo: No se lo prohibáis; porque el que no es contra nosotros, por nosotros es."}, {"numero": 51, "texto": "Y aconteció que, como se cumplió el tiempo en que había de ser recibido arriba, él afirmó su rostro para ir á Jerusalem."}, {"numero": 52, "texto": "Y envió mensajeros delante de sí, los cuales fueron y entraron en una ciudad de los Samaritanos, para prevenirle."}, {"numero": 53, "texto": "Mas no le recibieron, porque era su traza de ir á Jerusalem."}, {"numero": 54, "texto": "Y viendo esto sus discípulos Jacobo y Juan, dijeron: Señor, ¿quieres que mandemos que descienda fuego del cielo, y los consuma, como hizo Elías?"}, {"numero": 55, "texto": "Entonces volviéndose él, los reprendió, diciendo: Vosotros no sabéis de qué espíritu sois;"}, {"numero": 56, "texto": "Porque el Hijo del hombre no ha venido para perder las almas de los hombres, sino para salvarlas. Y se fueron á otra aldea."}, {"numero": 57, "texto": "Y aconteció que yendo ellos, uno le dijo en el camino: Señor, te seguiré donde quiera que fueres."}, {"numero": 58, "texto": "Y le dijo Jesús: Las zorras tienen cuevas, y las aves de los cielos nidos; mas el Hijo del hombre no tiene donde recline la cabeza."}, {"numero": 59, "texto": "Y dijo á otro: Sígueme. Y él dijo: Señor, déjame que primero vaya y entierre á mi padre."}, {"numero": 60, "texto": "Y Jesús le dijo: Deja los muertos que entierren á sus muertos; y tú, ve, y anuncia el reino de Dios."}, {"numero": 61, "texto": "Entonces también dijo otro: Te seguiré, Señor; mas déjame que me despida primero de los que están en mi casa."}, {"numero": 62, "texto": "Y Jesús le dijo: Ninguno que poniendo su mano al arado mira atrás, es apto para el reino de Dios."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 10, 'pt', '[{"numero": 1, "texto": "E depois disso, o Senhor ordenou ainda outros setenta, e os mandou de dois em dois adiante de sua face, para toda cidade e lugar aonde ele havia de vir."}, {"numero": 2, "texto": "E lhes dizia: “A colheita verdadeiramente é grande, mas os trabalhadores são poucos; portanto rogai ao Senhor da colheita para que ele envie trabalhadores para a sua colheita."}, {"numero": 3, "texto": "Ide; eis que eu vos mando como cordeiros no meio dos lobos."}, {"numero": 4, "texto": "Não leveis bolsa, nem sacola, nem sandálias; e a ninguém saudeis pelo caminho."}, {"numero": 5, "texto": "E em qualquer casa que entrardes, dizei primeiro: Paz [seja] nesta casa."}, {"numero": 6, "texto": "E se ali houver algum filho da paz, a vossa paz repousará sobre ele; e se não, ela voltará para vós mesmos."}, {"numero": 7, "texto": "E ficai na mesma casa, comendo e bebendo do que eles vos derem; pois o trabalhador é digno do seu salário. Não vos mudeis de casa em casa."}, {"numero": 8, "texto": "E em qualquer cidade que entrardes, e vos receberem, comei do que puserem diante de vós."}, {"numero": 9, "texto": "E curai os enfermos que nela houver, e dizei-lhes: Chegado é para vós o reino de Deus."}, {"numero": 10, "texto": "Mas em qualquer cidade em que entrardes e não vos receberem, saí pelas ruas, e dizei:"}, {"numero": 11, "texto": "Até o pó da vossa cidade que ficou em nós, sacudimos sobre vós; porém disto sabeis, que o reino de Deus é chegado até vós."}, {"numero": 12, "texto": "E eu vos digo, que mais tolerável será naquele dia para Sodoma, do que para aquela cidade."}, {"numero": 13, "texto": "Ai de ti, Corazim! Ai de ti, Betsaida! Porque se em Tiro e em Sidom tivessem sido feitas as maravilhas que foram feitas entre vós, há muito tempo que teriam se arrependido em saco e em cinza."}, {"numero": 14, "texto": "Portanto, para Tiro e Sidom será mais tolerável no juízo, do que para vós."}, {"numero": 15, "texto": "E tu, Cafarnaum, que [pensas ] estar elevada ao céu, até o Xeol serás derrubada!"}, {"numero": 16, "texto": "Quem vos ouve, ouve a mim; e quem vos rejeita, rejeita a mim; e quem me rejeita, rejeita aquele que me enviou."}, {"numero": 17, "texto": "E os setenta voltaram com alegria, dizendo: Senhor, até os demônios se sujeitam a nós por teu nome."}, {"numero": 18, "texto": "E disse-lhes: Eu vi a Satanás, que caía do céu como um raio."}, {"numero": 19, "texto": "Eis que vos dou poder para pisar sobre serpentes e escorpiões, e sobre toda a força do inimigo, e nada vos fará dano nenhum."}, {"numero": 20, "texto": "Mas não vos alegreis de que os espíritos se sujeitem a vós; em vez disso, alegrai-vos por vossos nomes estarem escritos nos céus."}, {"numero": 21, "texto": "Naquela hora Jesus se alegrou em espírito, e disse: Graças te dou, o Pai, Senhor do céu e da terra; porque tu escondeste estas coisas aos sábios e instruídos, e as revelaste às crianças. Sim, Pai, porque assim lhe agradou diante de ti."}, {"numero": 22, "texto": "Todas as coisas me foram entregues pelo meu Pai; e ninguém sabe quem é o Filho, a não ser o Pai; nem quem é o Pai, a não ser o Filho, e a quem o Filho o quiser revelar."}, {"numero": 23, "texto": "E virando-se para seus discípulos, disse [-lhes] à parte: Bem-aventurados os olhos que veem o que vós vedes."}, {"numero": 24, "texto": "Porque vos digo, que muitos profetas e reis desejaram ver o que vós vedes, e não o viram; o ouvir o que vós ouvis, e não o ouviram."}, {"numero": 25, "texto": "E eis que um certo estudioso da Lei se levantou, tentando-o, e dizendo: Mestre, o que devo fazer para ter para herdar a vida eterna?"}, {"numero": 26, "texto": "E ele lhe disse: O que está escrito na Lei? Como tu [a] lês?"}, {"numero": 27, "texto": "E respondendo ele, disse: Amarás ao Senhor teu Deus de todo teu coração, e de toda tua alma, e de todas tuas forças, e de todo teu entendimento; e [amarás] a teu próximo como a ti mesmo."}, {"numero": 28, "texto": "E disse-lhe: Respondeste bem; faze isso, e viverás."}, {"numero": 29, "texto": "Mas ele, querendo se justificar, disse a Jesus: E quem é o meu próximo?"}, {"numero": 30, "texto": "E respondendo Jesus, disse: Um homem descia de Jerusalém a Jericó, e foi atacado por assaltantes, que também tiraram suas roupas, espancaram-no, e se foram, deixando-o meio morto."}, {"numero": 31, "texto": "E por acaso descia um certo sacerdote pelo mesmo caminho, e vendo-o, passou longe [dele] ."}, {"numero": 32, "texto": "E semelhantemente também um levita, chegando junto a aquele lugar, veio, e vendo-o, passou longe [dele]"}, {"numero": 33, "texto": "Porém um certo samaritano, que ia pelo caminho, veio junto a ele, e vendo-o, teve compaixão [dele] ."}, {"numero": 34, "texto": "E chegando-se, amarrou-lhe [um curativo] nas feridas, pondo-lhe nelas azeite e vinho; e pondo-o sobre o animal que o transportava, levou-o para uma hospedaria, e cuidou dele."}, {"numero": 35, "texto": "E partindo-se no outro dia, tirou dois dinheiros, e os deu para o hospedeiro; e disse-lhe: Cuide dele; e tudo o que gastares a mais, eu te pagarei quando voltar."}, {"numero": 36, "texto": "Quem, pois, destes três te parece que foi o próximo daquele que foi atacado por assaltantes?"}, {"numero": 37, "texto": "Ele disse: Aquele que agiu tendo misericórdia com ele.Então Jesus lhe disse: Vai, e faze da mesma maneira."}, {"numero": 38, "texto": "E aconteceu que eles, enquanto eles caminhavam, ele entrou em uma aldeia; e uma certa mulher, de nome Marta, o recebeu em sua casa."}, {"numero": 39, "texto": "E esta tinha uma irmã, chamada Maria, a qual, sentando-se também aos pés de Jesus, ouvia sua palavra."}, {"numero": 40, "texto": "Marta, porém, ficava muito ocupada com muitos serviços; e ela, vindo, disse: Senhor, não te importas que minha irmã me deixe sozinha para servir? Dize a ela, pois, que me ajude."}, {"numero": 41, "texto": "E respondendo Jesus, disse-lhe: Marta, Marta, [tu és] preocupada com muitas coisas, e perturbada por elas;"}, {"numero": 42, "texto": "Mas [somente] uma coisa é necessária. E Maria escolheu a parte boa, a qual não lhe será tirada."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 10, 'en', '[{"numero": 1, "texto": "After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come."}, {"numero": 2, "texto": "Therefore said he unto them, The harvest truly is great, but the labourers are few: pray ye therefore the Lord of the harvest, that he would send forth labourers into his harvest."}, {"numero": 3, "texto": "Go your ways: behold, I send you forth as lambs among wolves."}, {"numero": 4, "texto": "Carry neither purse, nor scrip, nor shoes: and salute no man by the way."}, {"numero": 5, "texto": "And into whatsoever house ye enter, first say, Peace be to this house."}, {"numero": 6, "texto": "And if the son of peace be there, your peace shall rest upon it: if not, it shall turn to you again."}, {"numero": 7, "texto": "And in the same house remain, eating and drinking such things as they give: for the labourer is worthy of his hire. Go not from house to house."}, {"numero": 8, "texto": "And into whatsoever city ye enter, and they receive you, eat such things as are set before you:"}, {"numero": 9, "texto": "And heal the sick that are therein, and say unto them, The kingdom of God is come nigh unto you."}, {"numero": 10, "texto": "But into whatsoever city ye enter, and they receive you not, go your ways out into the streets of the same, and say,"}, {"numero": 11, "texto": "Even the very dust of your city, which cleaveth on us, we do wipe off against you: notwithstanding be ye sure of this, that the kingdom of God is come nigh unto you."}, {"numero": 12, "texto": "But I say unto you, that it shall be more tolerable in that day for Sodom, than for that city."}, {"numero": 13, "texto": "Woe unto thee, Chorazin! woe unto thee, Bethsaida! for if the mighty works had been done in Tyre and Sidon, which have been done in you, they had a great while ago repented, sitting in sackcloth and ashes."}, {"numero": 14, "texto": "But it shall be more tolerable for Tyre and Sidon at the judgment, than for you."}, {"numero": 15, "texto": "And thou, Capernaum, which art exalted to heaven, shalt be thrust down to hell."}, {"numero": 16, "texto": "He that heareth you heareth me; and he that despiseth you despiseth me; and he that despiseth me despiseth him that sent me."}, {"numero": 17, "texto": "And the seventy returned again with joy, saying, Lord, even the devils are subject unto us through thy name."}, {"numero": 18, "texto": "And he said unto them, I beheld Satan as lightning fall from heaven."}, {"numero": 19, "texto": "Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy: and nothing shall by any means hurt you."}, {"numero": 20, "texto": "Notwithstanding in this rejoice not, that the spirits are subject unto you; but rather rejoice, because your names are written in heaven."}, {"numero": 21, "texto": "In that hour Jesus rejoiced in spirit, and said, I thank thee, O Father, Lord of heaven and earth, that thou hast hid these things from the wise and prudent, and hast revealed them unto babes: even so, Father; for so it seemed good in thy sight."}, {"numero": 22, "texto": "All things are delivered to me of my Father: and no man knoweth who the Son is, but the Father; and who the Father is, but the Son, and he to whom the Son will reveal him."}, {"numero": 23, "texto": "And he turned him unto his disciples, and said privately, Blessed are the eyes which see the things that ye see:"}, {"numero": 24, "texto": "For I tell you, that many prophets and kings have desired to see those things which ye see, and have not seen them; and to hear those things which ye hear, and have not heard them."}, {"numero": 25, "texto": "And, behold, a certain lawyer stood up, and tempted him, saying, Master, what shall I do to inherit eternal life?"}, {"numero": 26, "texto": "He said unto him, What is written in the law? how readest thou?"}, {"numero": 27, "texto": "And he answering said, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy strength, and with all thy mind; and thy neighbour as thyself."}, {"numero": 28, "texto": "And he said unto him, Thou hast answered right: this do, and thou shalt live."}, {"numero": 29, "texto": "But he, willing to justify himself, said unto Jesus, And who is my neighbour?"}, {"numero": 30, "texto": "And Jesus answering said, A certain man went down from Jerusalem to Jericho, and fell among thieves, which stripped him of his raiment, and wounded him, and departed, leaving him half dead."}, {"numero": 31, "texto": "And by chance there came down a certain priest that way: and when he saw him, he passed by on the other side."}, {"numero": 32, "texto": "And likewise a Levite, when he was at the place, came and looked on him, and passed by on the other side."}, {"numero": 33, "texto": "But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion on him,"}, {"numero": 34, "texto": "And went to him, and bound up his wounds, pouring in oil and wine, and set him on his own beast, and brought him to an inn, and took care of him."}, {"numero": 35, "texto": "And on the morrow when he departed, he took out two pence, and gave them to the host, and said unto him, Take care of him; and whatsoever thou spendest more, when I come again, I will repay thee."}, {"numero": 36, "texto": "Which now of these three, thinkest thou, was neighbour unto him that fell among the thieves?"}, {"numero": 37, "texto": "And he said, He that shewed mercy on him. Then said Jesus unto him, Go, and do thou likewise."}, {"numero": 38, "texto": "Now it came to pass, as they went, that he entered into a certain village: and a certain woman named Martha received him into her house."}, {"numero": 39, "texto": "And she had a sister called Mary, which also sat at Jesus'' feet, and heard his word."}, {"numero": 40, "texto": "But Martha was cumbered about much serving, and came to him, and said, Lord, dost thou not care that my sister hath left me to serve alone? bid her therefore that she help me."}, {"numero": 41, "texto": "And Jesus answered and said unto her, Martha, Martha, thou art careful and troubled about many things:"}, {"numero": 42, "texto": "But one thing is needful: and Mary hath chosen that good part, which shall not be taken away from her."}]'::jsonb, 'King James Version'),
  ('Lc', 10, 'fr', '[{"numero": 1, "texto": "Après cela, le Seigneur désigna encore soixante-dix autres disciples, et il les envoya deux à deux devant lui dans toutes les villes et dans tous les lieux où lui-même devait aller."}, {"numero": 2, "texto": "Il leur dit: La moisson est grande, mais il y a peu d''''ouvriers. Priez donc le maître de la moisson d''''envoyer des ouvriers dans sa moisson."}, {"numero": 3, "texto": "Partez; voici, je vous envoie comme des agneaux au milieu des loups."}, {"numero": 4, "texto": "Ne portez ni bourse, ni sac, ni souliers, et ne saluez personne en chemin."}, {"numero": 5, "texto": "Dans quelque maison que vous entriez, dites d''''abord: Que la paix soit sur cette maison!"}, {"numero": 6, "texto": "Et s''''il se trouve là un enfant de paix, votre paix reposera sur lui; sinon, elle reviendra à vous."}, {"numero": 7, "texto": "Demeurez dans cette maison-là, mangeant et buvant ce qu''''on vous donnera; car l''''ouvrier mérite son salaire. N''''allez pas de maison en maison."}, {"numero": 8, "texto": "Dans quelque ville que vous entriez, et où l''''on vous recevra, mangez ce qui vous sera présenté,"}, {"numero": 9, "texto": "guérissez les malades qui s''''y trouveront, et dites-leur: Le royaume de Dieu s''''est approché de vous."}, {"numero": 10, "texto": "Mais dans quelque ville que vous entriez, et où l''''on ne vous recevra pas, allez dans ses rues, et dites:"}, {"numero": 11, "texto": "Nous secouons contre vous la poussière même de votre ville qui s''''est attachée à nos pieds; sachez cependant que le royaume de Dieu s''''est approché."}, {"numero": 12, "texto": "Je vous dis qu''''en ce jour Sodome sera traitée moins rigoureusement que cette ville-là."}, {"numero": 13, "texto": "Malheur à toi, Chorazin! malheur à toi, Bethsaïda! car, si les miracles qui ont été faits au milieu de vous avaient été faits dans Tyr et dans Sidon, il y a longtemps qu''''elles se seraient repenties, en prenant le sac et la cendre."}, {"numero": 14, "texto": "C''''est pourquoi, au jour du jugement, Tyr et Sidon seront traitées moins rigoureusement que vous."}, {"numero": 15, "texto": "Et toi, Capernaüm, qui as été élevée jusqu''''au ciel, tu seras abaissée jusqu''''au séjour des morts."}, {"numero": 16, "texto": "Celui qui vous écoute m''''écoute, et celui qui vous rejette me rejette; et celui qui me rejette rejette celui qui m''''a envoyé."}, {"numero": 17, "texto": "Les soixante-dix revinrent avec joie, disant: Seigneur, les démons mêmes nous sont soumis en ton nom."}, {"numero": 18, "texto": "Jésus leur dit: Je voyais Satan tomber du ciel comme un éclair."}, {"numero": 19, "texto": "Voici, je vous ai donné le pouvoir de marcher sur les serpents et les scorpions, et sur toute la puissance de l''''ennemi; et rien ne pourra vous nuire."}, {"numero": 20, "texto": "Cependant, ne vous réjouissez pas de ce que les esprits vous sont soumis; mais réjouissez-vous de ce que vos noms sont écrits dans les cieux."}, {"numero": 21, "texto": "En ce moment même, Jésus tressaillit de joie par le Saint-Esprit, et il dit: Je te loue, Père, Seigneur du ciel et de la terre, de ce que tu as caché ces choses aux sages et aux intelligents, et de ce que tu les as révélées aux enfants. Oui, Père, je te loue de ce que tu l''''as voulu ainsi."}, {"numero": 22, "texto": "Toutes choses m''''ont été données par mon Père, et personne ne connaît qui est le Fils, si ce n''''est le Père, ni qui est le Père, si ce n''''est le Fils et celui à qui le Fils veut le révéler."}, {"numero": 23, "texto": "Et, se tournant vers les disciples, il leur dit en particulier: Heureux les yeux qui voient ce que vous voyez!"}, {"numero": 24, "texto": "Car je vous dis que beaucoup de prophètes et de rois ont désiré voir ce que vous voyez, et ne l''''ont pas vu, entendre ce que vous entendez, et ne l''''ont pas entendu."}, {"numero": 25, "texto": "Un docteur de la loi se leva, et dit à Jésus, pour l''''éprouver: Maître, que dois-je faire pour hériter la vie éternelle?"}, {"numero": 26, "texto": "Jésus lui dit: Qu''''est-il écrit dans la loi? Qu''''y lis-tu?"}, {"numero": 27, "texto": "Il répondit: Tu aimeras le Seigneur, ton Dieu, de tout ton coeur, de toute ton âme, de toute ta force, et de toute ta pensée; et ton prochain comme toi-même."}, {"numero": 28, "texto": "Tu as bien répondu, lui dit Jésus; fais cela, et tu vivras."}, {"numero": 29, "texto": "Mais lui, voulant se justifier, dit à Jésus: Et qui est mon prochain?"}, {"numero": 30, "texto": "Jésus reprit la parole, et dit: Un homme descendait de Jérusalem à Jéricho. Il tomba au milieu des brigands, qui le dépouillèrent, le chargèrent de coups, et s''''en allèrent, le laissant à demi mort."}, {"numero": 31, "texto": "Un sacrificateur, qui par hasard descendait par le même chemin, ayant vu cet homme, passa outre."}, {"numero": 32, "texto": "Un Lévite, qui arriva aussi dans ce lieu, l''''ayant vu, passa outre."}, {"numero": 33, "texto": "Mais un Samaritain, qui voyageait, étant venu là, fut ému de compassion lorsqu''''il le vit."}, {"numero": 34, "texto": "Il s''''approcha, et banda ses plaies, en y versant de l''''huile et du vin; puis il le mit sur sa propre monture, le conduisit à une hôtellerie, et prit soin de lui."}, {"numero": 35, "texto": "Le lendemain, il tira deux deniers, les donna à l''''hôte, et dit: Aie soin de lui, et ce que tu dépenseras de plus, je te le rendrai à mon retour."}, {"numero": 36, "texto": "Lequel de ces trois te semble avoir été le prochain de celui qui était tombé au milieu des brigands?"}, {"numero": 37, "texto": "C''''est celui qui a exercé la miséricorde envers lui, répondit le docteur de la loi. Et Jésus lui dit: Va, et toi, fais de même."}, {"numero": 38, "texto": "Comme Jésus était en chemin avec ses disciples, il entra dans un village, et une femme, nommée Marthe, le reçut dans sa maison."}, {"numero": 39, "texto": "Elle avait une soeur, nommée Marie, qui, s''''étant assise aux pieds du Seigneur, écoutait sa parole."}, {"numero": 40, "texto": "Marthe, occupée à divers soins domestiques, survint et dit: Seigneur, cela ne te fait-il rien que ma soeur me laisse seule pour servir? Dis-lui donc de m''''aider."}, {"numero": 41, "texto": "Le Seigneur lui répondit: Marthe, Marthe, tu t''''inquiètes et tu t''''agites pour beaucoup de choses."}, {"numero": 42, "texto": "Une seule chose est nécessaire. Marie a choisi la bonne part, qui ne lui sera point ôtée."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 10, 'es', '[{"numero": 1, "texto": "Y DESPUÉS de estas cosas, designó el Señor aun otros setenta, los cuales envió de dos en dos delante de sí, á toda ciudad y lugar á donde él había de venir."}, {"numero": 2, "texto": "Y les decía: La mies á la verdad es mucha, mas los obreros pocos; por tanto, rogad al Señor de la mies que envíe obreros á su mies."}, {"numero": 3, "texto": "Andad, he aquí yo os envío como corderos en medio de lobos."}, {"numero": 4, "texto": "No llevéis bolsa, ni alforja, ni calzado; y á nadie saludéis en el camino."}, {"numero": 5, "texto": "En cualquiera casa donde entrareis, primeramente decid: Paz sea á esta casa."}, {"numero": 6, "texto": "Y si hubiere allí algún hijo de paz, vuestra paz reposará sobre él; y si no, se volverá á vosotros."}, {"numero": 7, "texto": "Y posad en aquella misma casa, comiendo y bebiendo lo que os dieren; porque el obrero digno es de su salario. No os paséis de casa en casa."}, {"numero": 8, "texto": "Y en cualquier ciudad donde entrareis, y os recibieren, comed lo que os pusieren delante;"}, {"numero": 9, "texto": "Y sanad los enfermos que en ella hubiere, y decidles: Se ha llegado á vosotros el reino de Dios."}, {"numero": 10, "texto": "Mas en cualquier ciudad donde entrareis, y no os recibieren, saliendo por sus calles, decid:"}, {"numero": 11, "texto": "Aun el polvo que se nos ha pegado de vuestra ciudad á nuestros pies, sacudimos en vosotros: esto empero sabed, que el reino de los cielos se ha llegado á vosotros."}, {"numero": 12, "texto": "Y os digo que los de Sodoma tendrán más remisión aquel día, que aquella ciudad."}, {"numero": 13, "texto": "¡Ay de ti, Corazín! ¡Ay de ti, Bethsaida! que si en Tiro y en Sidón hubieran sido hechas las maravillas que se han hecho en vosotras, ya días ha que, sentados en cilicio y ceniza, se habrían arrepentido."}, {"numero": 14, "texto": "Por tanto, Tiro y Sidón tendrán más remisión que vosotras en el juicio."}, {"numero": 15, "texto": "Y tú, Capernaum, que hasta los cielos estás levantada, hasta los infiernos serás abajada."}, {"numero": 16, "texto": "El que á vosotros oye, á mí oye; y el que á vosotros desecha, á mí desecha; y el que á mí desecha, desecha al que me envió."}, {"numero": 17, "texto": "Y volvieron los setenta con gozo, diciendo: Señor, aun los demonios se nos sujetan en tu nombre."}, {"numero": 18, "texto": "Y les dijo: Yo veía á Satanás, como un rayo, que caía del cielo."}, {"numero": 19, "texto": "He aquí os doy potestad de hollar sobre las serpientes y sobre los escorpiones, y sobre toda fuerza del enemigo, y nada os dañará."}, {"numero": 20, "texto": "Mas no os gocéis de esto, que los espíritus se os sujetan; antes gozaos de que vuestros nombres están escritos en los cielos."}, {"numero": 21, "texto": "En aquella misma hora Jesús se alegró en espíritu, y dijo: Yo te alabo, oh Padre, Señor del cielo y de la tierra, que escondiste estas cosas á los sabios y entendidos, y las has revelado á los pequeños: así, Padre, porque así te agradó."}, {"numero": 22, "texto": "Todas las cosas me son entregadas de mi Padre: y nadie sabe quién sea el Hijo sino el Padre; ni quién sea el Padre, sino el Hijo, y á quien el Hijo lo quisiere revelar."}, {"numero": 23, "texto": "Y vuelto particularmente á los discípulos, dijo: Bienaventurados los ojos que ven lo que vosotros veis:"}, {"numero": 24, "texto": "Porque os digo que muchos profetas y reyes desearon ver lo que vosotros veis, y no lo vieron; y oir lo que oís, y no lo oyeron."}, {"numero": 25, "texto": "Y he aquí, un doctor de la ley se levantó, tentándole y diciendo: Maestro, ¿haciendo qué cosa poseeré la vida eterna?"}, {"numero": 26, "texto": "Y él le dijo: ¿Qué está escrito en la ley? ¿cómo lees?"}, {"numero": 27, "texto": "Y él respondiendo, dijo: Amarás al Señor tu Dios de todo tu corazón, y de toda tu alma, y de todas tus fuerzas, y de todo tu entendimiento; y á tu prójimo como á ti mismo."}, {"numero": 28, "texto": "Y díjole: Bien has respondido: haz esto, y vivirás."}, {"numero": 29, "texto": "Mas él, queriéndose justificar á sí mismo, dijo á Jesús: ¿Y quién es mi prójimo?"}, {"numero": 30, "texto": "Y respondiendo Jesús, dijo: Un hombre descendía de Jerusalem á Jericó, y cayó en manos de ladrones, los cuales le despojaron; é hiriéndole, se fueron, dejándole medio muerto."}, {"numero": 31, "texto": "Y aconteció, que descendió un sacerdote por aquel camino, y viéndole, se pasó de un lado."}, {"numero": 32, "texto": "Y asimismo un Levita, llegando cerca de aquel lugar, y viéndole, se pasó de un lado."}, {"numero": 33, "texto": "Mas un Samaritano que transitaba, viniendo cerca de él, y viéndole, fué movido á misericordia;"}, {"numero": 34, "texto": "Y llegándose, vendó sus heridas, echándoles aceite y vino; y poniéndole sobre su cabalgadura, llevóle al mesón, y cuidó de él."}, {"numero": 35, "texto": "Y otro día al partir, sacó dos denarios, y diólos al huésped, y le dijo: Cuídamele; y todo lo que de más gastares, yo cuando vuelva te lo pagaré."}, {"numero": 36, "texto": "¿Quién, pues, de estos tres te parece que fué el prójimo de aquél que cayó en manos de los ladrones?"}, {"numero": 37, "texto": "Y él dijo: El que usó con él de misericordia. Entonces Jesús le dijo: Ve, y haz tú lo mismo."}, {"numero": 38, "texto": "Y aconteció que yendo, entró él en una aldea: y una mujer llamada Marta, le recibió en su casa."}, {"numero": 39, "texto": "Y ésta tenía una hermana que se llamaba María, la cual sentándose á los pies de Jesús, oía su palabra."}, {"numero": 40, "texto": "Empero Marta se distraía en muchos servicios; y sobreviniendo, dice: Señor, ¿no tienes cuidado que mi hermana me deja servir sola? Dile pues, que me ayude."}, {"numero": 41, "texto": "Pero respondiendo Jesús, le dijo: Marta, Marta, cuidadosa estás, y con las muchas cosas estás turbada:"}, {"numero": 42, "texto": "Empero una cosa es necesaria; y María escogió la buena parte, la cual no le será quitada."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 11, 'pt', '[{"numero": 1, "texto": "E aconteceu que ele estava orando em um certo lugar. Quando terminou, lhe disse um de seus discípulos: Senhor, ensina-nos a orar, como João também ensinou a seus discípulos."}, {"numero": 2, "texto": "E ele lhes disse: Quando orardes, dizei: Pai nosso, que [estás] nos céus, santificado seja o teu nome; venha o teu Reino; seja feita a tua vontade, [assim] na terra como no céu."}, {"numero": 3, "texto": "Dá-nos cada dia nosso pão diário."}, {"numero": 4, "texto": "E perdoa-nos nossos pecados, pois também perdoamos a todo aquele que nos deve. E não nos ponhas em tentação, mas livra-nos do mal."}, {"numero": 5, "texto": "Disse-lhes também: Qual de vós que, tendo um amigo, se for a ele à meia-noite, e lhe disser: Amigo, empresta-me três pães."}, {"numero": 6, "texto": "Porque um amigo meu veio de viagem até mim, e nada tenho para lhe apresentar."}, {"numero": 7, "texto": "E ele de dentro, respondendo, disser: Não me perturbe! A porta já está fechada, e meus filhos estão comigo na cama; não posso me levantar para te dar."}, {"numero": 8, "texto": "Digo-vos, que ainda que ele não se levante para lhe dar por seu seu amigo, contudo, por sua teimosia ele se levantará, e lhe dará tudo quanto ele precisar."}, {"numero": 9, "texto": "E eu vos digo: pedi, e será vos dado; buscai, e achareis; batei, e vos será aberto."}, {"numero": 10, "texto": "Porque todo o que pede, recebe; e quem busca, acha; e quem bate, lhe será aberto."}, {"numero": 11, "texto": "E que pai, dentre vós, a quem o filho pedir pão, lhe dará uma pedra? Ou, se também [lhe pedir] peixe, no lugar do peixe lhe dará uma serpente?"}, {"numero": 12, "texto": "Ou se também pedir um ovo, lhe dará um escorpião?"}, {"numero": 13, "texto": "Pois se vós, sendo maus, sabeis dar bons presentes para vossos filhos, quanto mais dará [vosso] Pai celestial, o Espírito Santo, a aqueles que lhe pedirem?"}, {"numero": 14, "texto": "E [Jesus] estava expulsando um demônio, e [este] era mudo. E aconteceu que, saindo o demônio, o mudo falou, e as multidões se maravilharam."}, {"numero": 15, "texto": "Porém alguns deles diziam: Ele expulsa aos demônios por Belzebu, príncipe dos demônios!"}, {"numero": 16, "texto": "E outros, tentando [-o] ,pediam-lhe um sinal do céu."}, {"numero": 17, "texto": "Mas ele, conhecendo seus pensamentos, disse-lhes: Todo reino dividido contra si mesmo é transformado num vazio, e a casa contra casa cai."}, {"numero": 18, "texto": "E se também Satanás está dividido contra si mesmo, como durará o seu reino? Porque dizeis: Por Belzebu ele expulsa aos demônios."}, {"numero": 19, "texto": "E se eu expulso aos demônios por Belzebu, por quem os seus filhos expulsam? Portanto eles serão vossos juízes."}, {"numero": 20, "texto": "Mas se eu expulso aos demônios pelo dedo de Deus, portanto o Reino de Deus chegou a vós."}, {"numero": 21, "texto": "Quando o valente, armado, guarda seu palácio, seus bens estão em paz."}, {"numero": 22, "texto": "Mas vindo outro mais valente que ele, e vencendo-o, toma [-lhe] toda sua armadura, em que confiava, e reparte seus despojos."}, {"numero": 23, "texto": "Quem não é comigo, é contra mim; e quem comigo não ajunta, espalha."}, {"numero": 24, "texto": "Quando o espírito imundo tem saído da pessoa, ele anda por lugares secos, buscando repouso; e não [o] achando, diz: Voltarei para minha casa, de onde saí."}, {"numero": 25, "texto": "E vindo, acha-a varrida e adornada."}, {"numero": 26, "texto": "Então vai, e toma consigo outros sete espíritos piores que ele, e entrando, habitam ali; e as últimas coisas de tal pessoa são piores que as primeiras."}, {"numero": 27, "texto": "E aconteceu que, dizendo ele estas coisas, uma mulher da multidão, levantando a voz, lhe disse: Bem-aventurado o ventre que te trouxe, e os peitos que mamaste!"}, {"numero": 28, "texto": "Mas ele disse: Antes bem-aventurados os que ouvem a palavra de Deus, e a guardam."}, {"numero": 29, "texto": "E ajuntando as multidões, começou a dizer: Maligna é esta geração; busca sinal, mas sinal não lhe será dado, a não ser o sinal de Jonas o profeta."}, {"numero": 30, "texto": "Porque como Jonas foi sinal para os ninivitas, assim também será o Filho do homem para esta geração."}, {"numero": 31, "texto": "A rainha do Sul se levantará em juízo com as pessoas desta geração, e as condenará; pois até dos fins da terra veio para ouvir a sabedoria de Salomão; e eis que mais que Salomão está aqui."}, {"numero": 32, "texto": "Os homens de Nínive se levantarão em juízo com esta geração, e a condenarão; pois com a pregação de Jonas se converteram; e eis que mais que Jonas está aqui."}, {"numero": 33, "texto": "E ninguém, acendendo a lâmpada, [a] põe em [lugar] oculto, nem debaixo da caixa, mas na luminária, para que os que entrarem vejam a luz."}, {"numero": 34, "texto": "A lâmpada do corpo é o olho. Sendo pois teu olho bom, também todo teu corpo será luminoso; porém se for mau, também [todo] teu corpo será tenebroso."}, {"numero": 35, "texto": "Olha pois que a luz que em ti há não sejam trevas."}, {"numero": 36, "texto": "Então se sendo teu corpo todo luminoso, não tendo parte alguma escura, ele todo será iluminado, como quando a lâmpada com [seu] brilho te ilumina."}, {"numero": 37, "texto": "E estando ele [ainda] falando, um fariseu lhe rogou que viesse para jantar com ele; e entrando, sentou-se [à mesa] ;"}, {"numero": 38, "texto": "E vendo [-o] o fariseu, maravilhou-se de que não tinha se lavado antes de jantar."}, {"numero": 39, "texto": "E o Senhor lhe disse: Agora vós, os fariseus, limpais o exterior do copo e do prato; porém vosso interior está cheio de roubo e maldade."}, {"numero": 40, "texto": "Loucos, o que fez o exterior não fez também o interior?"}, {"numero": 41, "texto": "Porém daí de esmola o que tendes; e eis que tudo vos será limpo."}, {"numero": 42, "texto": "Mais ai de vós, fariseus, que dizimais a hortelã, e a arruda, e toda hortaliça; e pelo juízo e amor de Deus passais longe. Estas coisas era necessário fazer, e não deixar as outras."}, {"numero": 43, "texto": "Ai de vós, fariseus, que amais os primeiros assentos nas sinagogas, e as saudações nas praças."}, {"numero": 44, "texto": "Ai de vós, escribas e fariseus, hipócritas, que sois como as sepulturas disfarçadas, e as pessoas que andam sobre elas não sabem."}, {"numero": 45, "texto": "E respondendo um dos estudiosos da Lei, disse-lhe: Mestre, quando dizes isto também afrontas a nós."}, {"numero": 46, "texto": "Porém ele disse: Ai de vós também, estudiosos da Lei, que carregais as pessoas com cargas pesadas para levar, e vós mesmos nem ainda com um de vossos dedos tais cargas tocais."}, {"numero": 47, "texto": "Ai de vós, que construís os sepulcros dos profetas, e vossos pais os mataram."}, {"numero": 48, "texto": "Bem testemunhais pois, que também consentis nas obras de vossos pais; porque eles os mataram, e vós edificais seus sepulcros."}, {"numero": 49, "texto": "Portanto também diz a sabedoria de Deus: Profetas e apóstolos lhes mandarei; e deles a [uns] matarão, e a [outros] lançarão fora;"}, {"numero": 50, "texto": "Para que desta geração seja requerido o sangue de todos os profetas, que foi derramado desde a fundação do mundo;"}, {"numero": 51, "texto": "Desde o sangue de Abel, até o sangue de Zacarias, que foi morto entre o altar e a casa [de Deus] ; assim vos digo, será requerido desta geração."}, {"numero": 52, "texto": "Ai de vós, estudiosos da Lei, que tomastes a chave do conhecimento; vós mesmos não entrastes, e impedistes aos que estavam entrando."}, {"numero": 53, "texto": "E dizendo-lhes estas coisas, os escribas e os fariseus começaram a apertá-lo fortemente, e tentar lhe fazer falar de muitas coisas,"}, {"numero": 54, "texto": "armando-lhe ciladas, e procurando caçar alguma coisa de sua boca, para o poderem acusar."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 11, 'en', '[{"numero": 1, "texto": "And it came to pass, that, as he was praying in a certain place, when he ceased, one of his disciples said unto him, Lord, teach us to pray, as John also taught his disciples."}, {"numero": 2, "texto": "And he said unto them, When ye pray, say, Our Father which art in heaven, Hallowed be thy name. Thy kingdom come. Thy will be done, as in heaven, so in earth."}, {"numero": 3, "texto": "Give us day by day our daily bread."}, {"numero": 4, "texto": "And forgive us our sins; for we also forgive every one that is indebted to us. And lead us not into temptation; but deliver us from evil."}, {"numero": 5, "texto": "And he said unto them, Which of you shall have a friend, and shall go unto him at midnight, and say unto him, Friend, lend me three loaves;"}, {"numero": 6, "texto": "For a friend of mine in his journey is come to me, and I have nothing to set before him?"}, {"numero": 7, "texto": "And he from within shall answer and say, Trouble me not: the door is now shut, and my children are with me in bed; I cannot rise and give thee."}, {"numero": 8, "texto": "I say unto you, Though he will not rise and give him, because he is his friend, yet because of his importunity he will rise and give him as many as he needeth."}, {"numero": 9, "texto": "And I say unto you, Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you."}, {"numero": 10, "texto": "For every one that asketh receiveth; and he that seeketh findeth; and to him that knocketh it shall be opened."}, {"numero": 11, "texto": "If a son shall ask bread of any of you that is a father, will he give him a stone? or if he ask a fish, will he for a fish give him a serpent?"}, {"numero": 12, "texto": "Or if he shall ask an egg, will he offer him a scorpion?"}, {"numero": 13, "texto": "If ye then, being evil, know how to give good gifts unto your children: how much more shall your heavenly Father give the Holy Spirit to them that ask him?"}, {"numero": 14, "texto": "And he was casting out a devil, and it was dumb. And it came to pass, when the devil was gone out, the dumb spake; and the people wondered."}, {"numero": 15, "texto": "But some of them said, He casteth out devils through Beelzebub the chief of the devils."}, {"numero": 16, "texto": "And others, tempting him, sought of him a sign from heaven."}, {"numero": 17, "texto": "But he, knowing their thoughts, said unto them, Every kingdom divided against itself is brought to desolation; and a house divided against a house falleth."}, {"numero": 18, "texto": "If Satan also be divided against himself, how shall his kingdom stand? because ye say that I cast out devils through Beelzebub."}, {"numero": 19, "texto": "And if I by Beelzebub cast out devils, by whom do your sons cast them out? therefore shall they be your judges."}, {"numero": 20, "texto": "But if I with the finger of God cast out devils, no doubt the kingdom of God is come upon you."}, {"numero": 21, "texto": "When a strong man armed keepeth his palace, his goods are in peace:"}, {"numero": 22, "texto": "But when a stronger than he shall come upon him, and overcome him, he taketh from him all his armour wherein he trusted, and divideth his spoils."}, {"numero": 23, "texto": "He that is not with me is against me: and he that gathereth not with me scattereth."}, {"numero": 24, "texto": "When the unclean spirit is gone out of a man, he walketh through dry places, seeking rest; and finding none, he saith, I will return unto my house whence I came out."}, {"numero": 25, "texto": "And when he cometh, he findeth it swept and garnished."}, {"numero": 26, "texto": "Then goeth he, and taketh to him seven other spirits more wicked than himself; and they enter in, and dwell there: and the last state of that man is worse than the first."}, {"numero": 27, "texto": "And it came to pass, as he spake these things, a certain woman of the company lifted up her voice, and said unto him, Blessed is the womb that bare thee, and the paps which thou hast sucked."}, {"numero": 28, "texto": "But he said, Yea rather, blessed are they that hear the word of God, and keep it."}, {"numero": 29, "texto": "And when the people were gathered thick together, he began to say, This is an evil generation: they seek a sign; and there shall no sign be given it, but the sign of Jonas the prophet."}, {"numero": 30, "texto": "For as Jonas was a sign unto the Ninevites, so shall also the Son of man be to this generation."}, {"numero": 31, "texto": "The queen of the south shall rise up in the judgment with the men of this generation, and condemn them: for she came from the utmost parts of the earth to hear the wisdom of Solomon; and, behold, a greater than Solomon is here."}, {"numero": 32, "texto": "The men of Nineve shall rise up in the judgment with this generation, and shall condemn it: for they repented at the preaching of Jonas; and, behold, a greater than Jonas is here."}, {"numero": 33, "texto": "No man, when he hath lighted a candle, putteth it in a secret place, neither under a bushel, but on a candlestick, that they which come in may see the light."}, {"numero": 34, "texto": "The light of the body is the eye: therefore when thine eye is single, thy whole body also is full of light; but when thine eye is evil, thy body also is full of darkness."}, {"numero": 35, "texto": "Take heed therefore that the light which is in thee be not darkness."}, {"numero": 36, "texto": "If thy whole body therefore be full of light, having no part dark, the whole shall be full of light, as when the bright shining of a candle doth give thee light."}, {"numero": 37, "texto": "And as he spake, a certain Pharisee besought him to dine with him: and he went in, and sat down to meat."}, {"numero": 38, "texto": "And when the Pharisee saw it, he marvelled that he had not first washed before dinner."}, {"numero": 39, "texto": "And the Lord said unto him, Now do ye Pharisees make clean the outside of the cup and the platter; but your inward part is full of ravening and wickedness."}, {"numero": 40, "texto": "Ye fools, did not he that made that which is without make that which is within also?"}, {"numero": 41, "texto": "But rather give alms of such things as ye have; and, behold, all things are clean unto you."}, {"numero": 42, "texto": "But woe unto you, Pharisees! for ye tithe mint and rue and all manner of herbs, and pass over judgment and the love of God: these ought ye to have done, and not to leave the other undone."}, {"numero": 43, "texto": "Woe unto you, Pharisees! for ye love the uppermost seats in the synagogues, and greetings in the markets."}, {"numero": 44, "texto": "Woe unto you, scribes and Pharisees, hypocrites! for ye are as graves which appear not, and the men that walk over them are not aware of them."}, {"numero": 45, "texto": "Then answered one of the lawyers, and said unto him, Master, thus saying thou reproachest us also."}, {"numero": 46, "texto": "And he said, Woe unto you also, ye lawyers! for ye lade men with burdens grievous to be borne, and ye yourselves touch not the burdens with one of your fingers."}, {"numero": 47, "texto": "Woe unto you! for ye build the sepulchres of the prophets, and your fathers killed them."}, {"numero": 48, "texto": "Truly ye bear witness that ye allow the deeds of your fathers: for they indeed killed them, and ye build their sepulchres."}, {"numero": 49, "texto": "Therefore also said the wisdom of God, I will send them prophets and apostles, and some of them they shall slay and persecute:"}, {"numero": 50, "texto": "That the blood of all the prophets, which was shed from the foundation of the world, may be required of this generation;"}, {"numero": 51, "texto": "From the blood of Abel unto the blood of Zacharias which perished between the altar and the temple: verily I say unto you, It shall be required of this generation."}, {"numero": 52, "texto": "Woe unto you, lawyers! for ye have taken away the key of knowledge: ye entered not in yourselves, and them that were entering in ye hindered."}, {"numero": 53, "texto": "And as he said these things unto them, the scribes and the Pharisees began to urge him vehemently, and to provoke him to speak of many things:"}, {"numero": 54, "texto": "Laying wait for him, and seeking to catch something out of his mouth, that they might accuse him."}]'::jsonb, 'King James Version'),
  ('Lc', 11, 'fr', '[{"numero": 1, "texto": "Jésus priait un jour en un certain lieu. Lorsqu''''il eut achevé, un de ses disciples lui dit: Seigneur, enseigne-nous à prier, comme Jean l''''a enseigné à ses disciples."}, {"numero": 2, "texto": "Il leur dit: Quand vous priez, dites: Père! Que ton nom soit sanctifié; que ton règne vienne."}, {"numero": 3, "texto": "Donne-nous chaque jour notre pain quotidien;"}, {"numero": 4, "texto": "pardonne-nous nos péchés, car nous aussi nous pardonnons à quiconque nous offense; et ne nous induis pas en tentation."}, {"numero": 5, "texto": "Il leur dit encore: Si l''''un de vous a un ami, et qu''''il aille le trouver au milieu de la nuit pour lui dire: Ami, prête-moi trois pains,"}, {"numero": 6, "texto": "car un de mes amis est arrivé de voyage chez moi, et je n''''ai rien à lui offrir,"}, {"numero": 7, "texto": "et si, de l''''intérieur de sa maison, cet ami lui répond: Ne m''''importune pas, la porte est déjà fermée, mes enfants et moi sommes au lit, je ne puis me lever pour te donner des pains, -"}, {"numero": 8, "texto": "je vous le dis, même s''''il ne se levait pas pour les lui donner parce que c''''est son ami, il se lèverait à cause de son importunité et lui donnerait tout ce dont il a besoin."}, {"numero": 9, "texto": "Et moi, je vous dis: Demandez, et l''''on vous donnera; cherchez, et vous trouverez; frappez, et l''''on vous ouvrira."}, {"numero": 10, "texto": "Car quiconque demande reçoit, celui qui cherche trouve, et l''''on ouvre à celui qui frappe."}, {"numero": 11, "texto": "Quel est parmi vous le père qui donnera une pierre à son fils, s''''il lui demande du pain? Ou, s''''il demande un poisson, lui donnera-t-il un serpent au lieu d''''un poisson?"}, {"numero": 12, "texto": "Ou, s''''il demande un oeuf, lui donnera-t-il un scorpion?"}, {"numero": 13, "texto": "Si donc, méchants comme vous l''''êtes, vous savez donner de bonnes choses à vos enfants, à combien plus forte raison le Père céleste donnera-t-il le Saint-Esprit à ceux qui le lui demandent."}, {"numero": 14, "texto": "Jésus chassa un démon qui était muet. Lorsque le démon fut sorti, le muet parla, et la foule fut dans l''''admiration."}, {"numero": 15, "texto": "Mais quelques-uns dirent: c''''est par Béelzébul, le prince des démons, qu''''il chasse les démons."}, {"numero": 16, "texto": "Et d''''autres, pour l''''éprouver, lui demandèrent un signe venant du ciel."}, {"numero": 17, "texto": "Comme Jésus connaissait leurs pensées, il leur dit: Tout royaume divisé contre lui-même est dévasté, et une maison s''''écroule sur une autre."}, {"numero": 18, "texto": "Si donc Satan est divisé contre lui-même, comment son royaume subsistera-t-il, puisque vous dites que je chasse les démons par Béelzébul?"}, {"numero": 19, "texto": "Et si moi, je chasse les démons par Béelzébul, vos fils, par qui les chassent-ils? C''''est pourquoi ils seront eux-mêmes vos juges."}, {"numero": 20, "texto": "Mais, si c''''est par le doigt de Dieu que je chasse les démons, le royaume de Dieu est donc venu vers vous."}, {"numero": 21, "texto": "Lorsqu''''un homme fort et bien armé garde sa maison, ce qu''''il possède est en sûreté."}, {"numero": 22, "texto": "Mais, si un plus fort que lui survient et le dompte, il lui enlève toutes les armes dans lesquelles il se confiait, et il distribue ses dépouilles."}, {"numero": 23, "texto": "Celui qui n''''est pas avec moi est contre moi, et celui qui n''''assemble pas avec moi disperse."}, {"numero": 24, "texto": "Lorsque l''''esprit impur est sorti d''''un homme, il va dans des lieux arides, pour chercher du repos. N''''en trouvant point, il dit: Je retournerai dans ma maison d''''où je suis sorti;"}, {"numero": 25, "texto": "et, quand il arrive, il la trouve balayée et ornée."}, {"numero": 26, "texto": "Alors il s''''en va, et il prend sept autres esprits plus méchants que lui; ils entrent dans la maison, s''''y établissent, et la dernière condition de cet homme est pire que la première."}, {"numero": 27, "texto": "Tandis que Jésus parlait ainsi, une femme, élevant la voix du milieu de la foule, lui dit: Heureux le sein qui t''''a porté! heureuses les mamelles qui t''''ont allaité!"}, {"numero": 28, "texto": "Et il répondit: Heureux plutôt ceux qui écoutent la parole de Dieu, et qui la gardent!"}, {"numero": 29, "texto": "Comme le peuple s''''amassait en foule, il se mit à dire: Cette génération est une génération méchante; elle demande un miracle; il ne lui sera donné d''''autre miracle que celui de Jonas."}, {"numero": 30, "texto": "Car, de même que Jonas fut un signe pour les Ninivites, de même le Fils de l''''homme en sera un pour cette génération."}, {"numero": 31, "texto": "La reine du Midi se lèvera, au jour du jugement, avec les hommes de cette génération et les condamnera, parce qu''''elle vint des extrémités de la terre pour entendre la sagesse de Salomon; et voici, il y a ici plus que Salomon."}, {"numero": 32, "texto": "Les hommes de Ninive se lèveront, au jour du jugement, avec cette génération et la condamneront, parce qu''''ils se repentirent à la prédication de Jonas; et voici, il y a ici plus que Jonas."}, {"numero": 33, "texto": "Personne n''''allume une lampe pour la mettre dans un lieu caché ou sous le boisseau, mais on la met sur le chandelier, afin que ceux qui entrent voient la lumière."}, {"numero": 34, "texto": "Ton oeil est la lampe de ton corps. Lorsque ton oeil est en bon état, tout ton corps est éclairé; mais lorsque ton oeil est en mauvais état, ton corps est dans les ténèbres."}, {"numero": 35, "texto": "Prends donc garde que la lumière qui est en toi ne soit ténèbres."}, {"numero": 36, "texto": "Si donc tout ton corps est éclairé, n''''ayant aucune partie dans les ténèbres, il sera entièrement éclairé, comme lorsque la lampe t''''éclaire de sa lumière."}, {"numero": 37, "texto": "Pendant que Jésus parlait, un pharisien le pria de dîner chez lui. Il entra, et se mit à table."}, {"numero": 38, "texto": "Le pharisien vit avec étonnement qu''''il ne s''''était pas lavé avant le repas."}, {"numero": 39, "texto": "Mais le Seigneur lui dit: Vous, pharisiens, vous nettoyez le dehors de la coupe et du plat, et à l''''intérieur vous êtes pleins de rapine et de méchanceté."}, {"numero": 40, "texto": "Insensés! celui qui a fait le dehors n''''a-t-il pas fait aussi le dedans?"}, {"numero": 41, "texto": "Donnez plutôt en aumônes ce qui est dedans, et voici, toutes choses seront pures pour vous."}, {"numero": 42, "texto": "Mais malheur à vous, pharisiens! parce que vous payez la dîme de la menthe, de la rue, et de toutes les herbes, et que vous négligez la justice et l''''amour de Dieu: c''''est là ce qu''''il fallait pratiquer, sans omettre les autres choses."}, {"numero": 43, "texto": "Malheur à vous, pharisiens! parce que vous aimez les premiers sièges dans les synagogues, et les salutations dans les places publiques."}, {"numero": 44, "texto": "Malheur à vous! parce que vous êtes comme les sépulcres qui ne paraissent pas, et sur lesquels on marche sans le savoir."}, {"numero": 45, "texto": "Un des docteurs de la loi prit la parole, et lui dit: Maître, en parlant de la sorte, c''''est aussi nous que tu outrages."}, {"numero": 46, "texto": "Et Jésus répondit: Malheur à vous aussi, docteurs de la loi! parce que vous chargez les hommes de fardeaux difficiles à porter, et que vous ne touchez pas vous-mêmes de l''''un de vos doigts."}, {"numero": 47, "texto": "Malheur à vous! parce que vous bâtissez les tombeaux des prophètes, que vos pères ont tués."}, {"numero": 48, "texto": "Vous rendez donc témoignage aux oeuvres de vos pères, et vous les approuvez; car eux, ils ont tué les prophètes, et vous, vous bâtissez leurs tombeaux."}, {"numero": 49, "texto": "C''''est pourquoi la sagesse de Dieu a dit: Je leur enverrai des prophètes et des apôtres; ils tueront les uns et persécuteront les autres,"}, {"numero": 50, "texto": "afin qu''''il soit demandé compte à cette génération du sang de tous les prophètes qui a été répandu depuis la création du monde,"}, {"numero": 51, "texto": "depuis le sang d''''Abel jusqu''''au sang de Zacharie, tué entre l''''autel et le temple; oui, je vous le dis, il en sera demandé compte à cette génération."}, {"numero": 52, "texto": "Malheur à vous, docteurs de la loi! parce que vous avez enlevé la clef de la science; vous n''''êtes pas entrés vous-mêmes, et vous avez empêché d''''entrer ceux qui le voulaient."}, {"numero": 53, "texto": "Quand il fut sorti de là, les scribes et les pharisiens commencèrent à le presser violemment, et à le faire parler sur beaucoup de choses,"}, {"numero": 54, "texto": "lui tendant des pièges, pour surprendre quelque parole sortie de sa bouche."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 11, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que estando él orando en un lugar, como acabó, uno de sus discípulos le dijo: Señor, enséñanos á orar, como también Juan enseñó á sus discípulos."}, {"numero": 2, "texto": "Y les dijo: Cuando orareis, decid: Padre nuestro que estás en los cielos; sea tu nombre santificado. Venga tu reino. Sea hecha tu voluntad, como en el cielo, así también en la tierra."}, {"numero": 3, "texto": "El pan nuestro de cada día, dánoslo hoy."}, {"numero": 4, "texto": "Y perdónanos nuestros pecados, porque también nosotros perdonamos á todos los que nos deben. Y no nos metas en tentación, mas líbranos del malo."}, {"numero": 5, "texto": "Díjoles también: ¿Quién de vosotros tendrá un amigo, é irá á él á media noche, y le dirá: Amigo, préstame tres panes,"}, {"numero": 6, "texto": "Porque un amigo mío ha venido á mí de camino, y no tengo qué ponerle delante;"}, {"numero": 7, "texto": "Y el de dentro respondiendo, dijere: No me seas molesto; la puerta está ya cerrada, y mis niños están conmigo en cama; no puedo levantarme, y darte?"}, {"numero": 8, "texto": "Os digo, que aunque no se levante á darle por ser su amigo, cierto por su importunidad se levantará, y le dará todo lo que habrá menester."}, {"numero": 9, "texto": "Y yo os digo: Pedid, y se os dará; buscad, y hallaréis; llamad, y os será abierto."}, {"numero": 10, "texto": "Porque todo aquel que pide, recibe; y el que busca, halla; y al que llama, se abre."}, {"numero": 11, "texto": "¿Y cuál padre de vosotros, si su hijo le pidiere pan, le dará una piedra? ó, si pescado, ¿en lugar de pescado, le dará una serpiente?"}, {"numero": 12, "texto": "O, si le pidiere un huevo, ¿le dará un escorpión?"}, {"numero": 13, "texto": "Pues si vosotros, siendo malos, sabéis dar buenas dádivas á vuestros hijos, ¿cuánto más vuestro Padre celestial dará el Espíritu Santo á los que lo pidieren de él?"}, {"numero": 14, "texto": "Y estaba él lanzando un demonio, el cual era mudo: y aconteció que salido fuera el demonio, el mudo habló, y las gentes se maravillaron."}, {"numero": 15, "texto": "Mas algunos de ellos decían: En Beelzebub, príncipe de los demonios, echa fuera los demonios."}, {"numero": 16, "texto": "Y otros, tentando, pedían de él señal del cielo."}, {"numero": 17, "texto": "Mas él, conociendo los pensamientos de ellos, les dijo: Todo reino dividido contra sí mismo, es asolado; y una casa dividida contra sí misma, cae."}, {"numero": 18, "texto": "Y si también Satanás está dividido contra sí mismo, ¿cómo estará en pie su reino? porque decís que en Beelzebub echo yo fuera los demonios."}, {"numero": 19, "texto": "Pues si yo echo fuera los demonios en Beelzebub, ¿vuestros hijos en quién los echan fuera? Por tanto, ellos serán vuestros jueces."}, {"numero": 20, "texto": "Mas si por el dedo de Dios echo yo fuera los demonios, cierto el reino de Dios ha llegado á vosotros."}, {"numero": 21, "texto": "Cuando el fuerte armado guarda su atrio, en paz está lo que posee."}, {"numero": 22, "texto": "Mas si sobreviniendo otro más fuerte que él, le venciere, le toma todas sus armas en que confiaba, y reparte sus despojos."}, {"numero": 23, "texto": "El que no es conmigo, contra mí es; y el que conmigo no recoge, desparrama."}, {"numero": 24, "texto": "Cuando el espíritu inmundo saliere del hombre, anda por lugares secos, buscando reposo; y no hallándolo, dice: Me volveré á mi casa de donde salí."}, {"numero": 25, "texto": "Y viniendo, la halla barrida y adornada."}, {"numero": 26, "texto": "Entonces va, y toma otros siete espíritus peores que él; y entrados, habitan allí: y lo postrero del tal hombre es peor que lo primero."}, {"numero": 27, "texto": "Y aconteció que diciendo estas cosas, una mujer de la compañía, levantando la voz, le dijo: Bienaventurado el vientre que te trajo, y los pechos que mamaste."}, {"numero": 28, "texto": "Y él dijo: Antes bienaventurados los que oyen la palabra de Dios, y la guardan."}, {"numero": 29, "texto": "Y juntándose las gentes á él, comenzó á decir: Esta generación mala es: señal busca, mas señal no le será dada, sino la señal de Jonás."}, {"numero": 30, "texto": "Porque como Jonás fué señal á los Ninivitas, así también será el Hijo del hombre á esta generación."}, {"numero": 31, "texto": "La reina del Austro se levantará en juicio con los hombres de esta generación, y los condenará; porque vino de los fines de la tierra á oir la sabiduría de Salomón; y he aquí más que Salomón en este lugar."}, {"numero": 32, "texto": "Los hombres de Nínive se levantarán en juicio con esta generación, y la condenarán; porque á la predicación de Jonás se arrepintieron; y he aquí más que Jonás en este lugar."}, {"numero": 33, "texto": "Nadie pone en oculto la antorcha encendida, ni debajo del almud, sino en el candelero, para que los que entran vean la luz."}, {"numero": 34, "texto": "La antorcha del cuerpo es el ojo: pues si tu ojo fuere simple, también todo tu cuerpo será resplandeciente; mas si fuere malo, también tu cuerpo será tenebroso."}, {"numero": 35, "texto": "Mira pues, si la lumbre que en ti hay, es tinieblas."}, {"numero": 36, "texto": "Así que, siendo todo tu cuerpo resplandeciente, no teniendo alguna parte de tinieblas, será todo luminoso, como cuando una antorcha de resplandor te alumbra."}, {"numero": 37, "texto": "Y luego que hubo hablado, rogóle un Fariseo que comiese con él: y entrado Jesús, se sentó á la mesa."}, {"numero": 38, "texto": "Y el Fariseo, como lo vió, maravillóse de que no se lavó antes de comer."}, {"numero": 39, "texto": "Y el Señor le dijo: Ahora vosotros los Fariseos lo de fuera del vaso y del plato limpiáis; mas lo interior de vosotros está lleno de rapiña y de maldad."}, {"numero": 40, "texto": "Necios, ¿el que hizo lo de fuera, no hizo también lo de dentro?"}, {"numero": 41, "texto": "Empero de lo que os resta, dad limosna; y he aquí todo os será limpio."}, {"numero": 42, "texto": "Mas ¡ay de vosotros, Fariseos! que diezmáis la menta, y la ruda, y toda hortaliza; mas el juicio y la caridad de Dios pasáis de largo. Pues estas cosas era necesario hacer, y no dejar las otras."}, {"numero": 43, "texto": "¡Ay de vosotros, Fariseos! que amáis las primeras sillas en las sinagogas, y las salutaciones en las plazas."}, {"numero": 44, "texto": "¡Ay de vosotros, escribas y Fariseos, hipócritas! que sois como sepulcros que no se ven, y los hombres que andan encima no lo saben."}, {"numero": 45, "texto": "Y respondiendo uno de los doctores de la ley, le dice: Maestro, cuando dices esto, también nos afrentas á nosotros."}, {"numero": 46, "texto": "Y él dijo: ¡Ay de vosotros también, doctores de la ley! que cargáis á los hombres con cargas que no pueden llevar; mas vosotros ni aun con un dedo tocáis las cargas."}, {"numero": 47, "texto": "¡Ay de vosotros! que edificáis los sepulcros de los profetas, y los mataron vuestros padres."}, {"numero": 48, "texto": "De cierto dais testimonio que consentís en los hechos de vuestros padres; porque á la verdad ellos los mataron, mas vosotros edificáis sus sepulcros."}, {"numero": 49, "texto": "Por tanto, la sabiduría de Dios también dijo: Enviaré á ellos profetas y apóstoles; y de ellos á unos matarán y á otros perseguirán;"}, {"numero": 50, "texto": "Para que de esta generación sea demandada la sangre de todos los profetas, que ha sido derramada desde la fundación del mundo;"}, {"numero": 51, "texto": "Desde la sangre de Abel, hasta la sangre de Zacarías, que murió entre el altar y el templo: así os digo, será demandada de esta generación."}, {"numero": 52, "texto": "¡Ay de vosotros, doctores de la ley! que habéis quitado la llave de la ciencia; vosotros mismos no entrasteis, y á los que entraban impedisteis."}, {"numero": 53, "texto": "Y diciéndoles estas cosas, los escribas y los Fariseos comenzaron á apretarle en gran manera, y á provocarle á que hablase de muchas cosas;"}, {"numero": 54, "texto": "Acechándole, y procurando cazar algo de su boca para acusarle."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 12, 'pt', '[{"numero": 1, "texto": "Juntando-se, entretanto, muitos milhares da multidão, tanto que se atropelavam uns aos outros, começou a dizer primeiramente a seus discípulos: Guardai-vos do fermento dos fariseus, que é hipocrisia."}, {"numero": 2, "texto": "E nada há encoberto que não haja de ser descoberto; nem oculto que não haja de ser sabido."}, {"numero": 3, "texto": "Portanto tudo o que dissestes nas trevas, será ouvido na luz; e o que falastes ao ouvido nos quartos, será pregado sobre os telhados."}, {"numero": 4, "texto": "E digo-vos, amigos meus, não temais aos que matam o corpo, e depois não têm mais o que possam fazer."}, {"numero": 5, "texto": "Mas eu vos mostrarei a quem deveis temer; temei a aquele, que depois de matar, [também] tem poder para lançar no inferno; sim, a este temei."}, {"numero": 6, "texto": "Não se vendem cinco passarinhos por duas pequenas moedas? E nem um deles está esquecido diante de Deus."}, {"numero": 7, "texto": "E até os cabelos de vossa cabeça estão todos contados; não temais, pois; mais valeis vós que muitos passarinhos."}, {"numero": 8, "texto": "E vos digo que todo aquele que me confessar diante dos seres humanos, também o Filho do homem o confessará diante dos anjos de Deus."}, {"numero": 9, "texto": "Mas quem me negar diante dos seres humanos será negado diante dos anjos de Deus."}, {"numero": 10, "texto": "E a todo aquele que disser [alguma] palavra contra o Filho do homem, lhe será perdoado, mas ao que blasfemar contra o Espírito Santo, não lhe será perdoado."}, {"numero": 11, "texto": "E quando vos trouxerem às sinagogas, aos magistrados e autoridades, não estejais ansiosos, como, ou que, em [vossa] defesa deveis dizer, ou que deveis falar."}, {"numero": 12, "texto": "Porque na mesma hora o Espírito Santo vos ensinará o que deveis falar."}, {"numero": 13, "texto": "E um da multidão lhe disse: Mestre, dize a meu irmão que reparta a herança comigo."}, {"numero": 14, "texto": "Mas ele lhe disse: Homem, quem me pôs por juiz, ou repartidor sobre vós?"}, {"numero": 15, "texto": "E disse-lhes: Olhai, e tomai cuidado com a ganância; porque a vida de alguém não consiste na abundância dos bens que possui."}, {"numero": 16, "texto": "E propôs-lhes uma parábola, dizendo: A terra de um homem rico tinha frutificado bem."}, {"numero": 17, "texto": "E ele questionava a si mesmo, dizendo: Que farei? Porque não tenho onde juntar meus frutos."}, {"numero": 18, "texto": "E disse: Farei isto: derrubarei meus celeiros, e construirei maiores, e ali juntarei toda esta minha colheita, e estes meus bens."}, {"numero": 19, "texto": "E direi à minha alma: Alma, muitos bens tens guardados, para muitos anos; descansa, come, bebe, alegra-te!"}, {"numero": 20, "texto": "Porém Deus lhe disse: Louco, esta noite te pedirão tua alma; e o que tens preparado, de quem será?"}, {"numero": 21, "texto": "Assim [é] o que junta tesouros para si, mas não é rico em Deus."}, {"numero": 22, "texto": "E disse a seus discípulos: Portanto vos digo, não estejais ansiosos por vossa vida, que comereis; nem pelo corpo, que vestireis."}, {"numero": 23, "texto": "Mais é a vida que o alimento, e [mais] o corpo que o vestido."}, {"numero": 24, "texto": "Considerai os corvos, que nem semeiam, nem ceifam; nem tem armazém, nem celeiro; e Deus os alimenta."}, {"numero": 25, "texto": "E quem de vós pode, com sua ansiedade, acrescentar um côvado à sua altura?"}, {"numero": 26, "texto": "Pois, se não podeis nem mesmo com algo pequeno, por que estais ansiosos com o resto?"}, {"numero": 27, "texto": "Considerai os lírios, como crescem; não trabalham, nem fiam; e digo-vos, que nem mesmo Salomão, em toda sua glória, [chegou] a se vestir como um deles."}, {"numero": 28, "texto": "E se assim Deus veste a erva, que hoje está no campo, e amanhá é lançada no forno, quanto mais [vestirá] a vós, homens de pouca fé?"}, {"numero": 29, "texto": "Vós, pois, não pergunteis que comereis, ou que bebereis; e não andeis preocupados."}, {"numero": 30, "texto": "Porque todas estas coisas, os gentios do mundo as buscam; mas vosso Pai sabe que necessitais destas coisas."}, {"numero": 31, "texto": "Mas buscai o Reino de Deus, e todas estas coisas vos serão acrescentadas."}, {"numero": 32, "texto": "Não temas, ó pequeno rebanho; porque vosso Pai se agradou de dar a vós o Reino."}, {"numero": 33, "texto": "Vendei o que tendes, e daí esmola. Fazei para vós bolsas que não se envelheçam; tesouro nos céus que nunca se deprecia; onde ladrão não chega, nem a traça destrói."}, {"numero": 34, "texto": "Porque aonde estiver vosso tesouro, ali estará também vosso coração."}, {"numero": 35, "texto": "Estejam devidamente vestidos vossos quadris, e acesas as lâmpadas."}, {"numero": 36, "texto": "E sede vós semelhantes às pessoas que esperam a seu senhor quando voltar do casamento; para que quando ele vier, e bater, logo possam lhe abrir."}, {"numero": 37, "texto": "Bem-aventurados aqueles servos, os quais, quando o Senhor vier, [os] achar vigiando; em verdade vos digo que ele se vestirá, e os fará se sentarem [à mesa] ,e chegando-se, os servirá."}, {"numero": 38, "texto": "E ainda que venha à segunda vigília; e [que] venha a terceira vigília, e assim [os] achar, bem-aventurados são tais servos."}, {"numero": 39, "texto": "Isto, porém, sabei: que se o chefe da casa soubesse à que hora o ladrão viria, ele vigiaria, e não deixaria sua casa sofrer dano."}, {"numero": 40, "texto": "Vós, pois, também estejais prontos; porque o Filho do homem virá à hora que não imaginais."}, {"numero": 41, "texto": "E Pedro lhe disse: Senhor, dizes tu esta parábola para nós, ou também para todos?"}, {"numero": 42, "texto": "E o Senhor disse: Qual é, pois, o mordomo fiel e prudente, a quem [seu] senhor puser sobre seus servos, para que [lhes] dê alimento no tempo certo?"}, {"numero": 43, "texto": "Bem-aventurado aquele servo ao qual, quando seu senhor vier, o achar fazendo assim."}, {"numero": 44, "texto": "Em verdade vos digo, que o porá sobre todos os seus bens."}, {"numero": 45, "texto": "Mas se aquele servo disser em seu coração: Meu senhor está demorando para vir; e começar a espancar aos servos e servas, e a comer, e a beber, e a se embebedar,"}, {"numero": 46, "texto": "Virá o senhor daquele servo, no dia em que ele não espera, e na hora que ele não sabe; e será partido em dois, e porá sua porção com os incrédulos."}, {"numero": 47, "texto": "E o servo que sabia a vontade de seu senhor, e não se preparou, nem fez conforme a sua vontade, será muito espancado."}, {"numero": 48, "texto": "Mas o que não sabia, e fez [coisas] dignas de pancadas, será pouco espancado. E a qualquer que muito for dado, muito se lhe pedirá, e ao que muito se confiou, muito mais lhe será exigido."}, {"numero": 49, "texto": "Eu vim para lançar fogo na terra; e o que mais posso querer, se já está aceso?"}, {"numero": 50, "texto": "Porém há um batismo que tenho que ser batizado; e como me angustio até que se venha a cumprir!"}, {"numero": 51, "texto": "Vós pensais que vim para dar paz à terra? Não, eu vos digo; mas antes [vim para trazer] divisão."}, {"numero": 52, "texto": "Porque daqui em diante cinco estarão divididos em uma casa; três contra dois, e dois contra três."}, {"numero": 53, "texto": "O pai estará dividido contra o filho, e o filho contra o pai; a mãe contra a filha, e a filha contra a mãe; a sogra contra sua nora, e a nora contra sua sogra."}, {"numero": 54, "texto": "E ele dizia também para as multidões: Quando vedes a nuvem que vem do ocidente, logo dizeis: Lá vem chuva; E assim acontece."}, {"numero": 55, "texto": "E quando venta do sul, dizeis: Haverá calor; E assim acontece."}, {"numero": 56, "texto": "Hipócritas! Sabeis entender a aparência da terra e do céu; e como não entendeis este tempo?"}, {"numero": 57, "texto": "E por que também não julgais por vós mesmos o que é justo?"}, {"numero": 58, "texto": "Pois quando fores com teu adversário à autoridade, procura te livrares dele no caminho, para que ele não venha a te levar ao juiz, e o juiz te entregue ao oficial de justiça, e o oficial de justiça te lance na prisão."}, {"numero": 59, "texto": "Eu te digo que não sairás dali enquanto não pagares até a última moeda."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 12, 'en', '[{"numero": 1, "texto": "In the mean time, when there were gathered together an innumerable multitude of people, insomuch that they trode one upon another, he began to say unto his disciples first of all, Beware ye of the leaven of the Pharisees, which is hypocrisy."}, {"numero": 2, "texto": "For there is nothing covered, that shall not be revealed; neither hid, that shall not be known."}, {"numero": 3, "texto": "Therefore whatsoever ye have spoken in darkness shall be heard in the light; and that which ye have spoken in the ear in closets shall be proclaimed upon the housetops."}, {"numero": 4, "texto": "And I say unto you my friends, Be not afraid of them that kill the body, and after that have no more that they can do."}, {"numero": 5, "texto": "But I will forewarn you whom ye shall fear: Fear him, which after he hath killed hath power to cast into hell; yea, I say unto you, Fear him."}, {"numero": 6, "texto": "Are not five sparrows sold for two farthings, and not one of them is forgotten before God?"}, {"numero": 7, "texto": "But even the very hairs of your head are all numbered. Fear not therefore: ye are of more value than many sparrows."}, {"numero": 8, "texto": "Also I say unto you, Whosoever shall confess me before men, him shall the Son of man also confess before the angels of God:"}, {"numero": 9, "texto": "But he that denieth me before men shall be denied before the angels of God."}, {"numero": 10, "texto": "And whosoever shall speak a word against the Son of man, it shall be forgiven him: but unto him that blasphemeth against the Holy Ghost it shall not be forgiven."}, {"numero": 11, "texto": "And when they bring you unto the synagogues, and unto magistrates, and powers, take ye no thought how or what thing ye shall answer, or what ye shall say:"}, {"numero": 12, "texto": "For the Holy Ghost shall teach you in the same hour what ye ought to say."}, {"numero": 13, "texto": "And one of the company said unto him, Master, speak to my brother, that he divide the inheritance with me."}, {"numero": 14, "texto": "And he said unto him, Man, who made me a judge or a divider over you?"}, {"numero": 15, "texto": "And he said unto them, Take heed, and beware of covetousness: for a man''s life consisteth not in the abundance of the things which he possesseth."}, {"numero": 16, "texto": "And he spake a parable unto them, saying, The ground of a certain rich man brought forth plentifully:"}, {"numero": 17, "texto": "And he thought within himself, saying, What shall I do, because I have no room where to bestow my fruits?"}, {"numero": 18, "texto": "And he said, This will I do: I will pull down my barns, and build greater; and there will I bestow all my fruits and my goods."}, {"numero": 19, "texto": "And I will say to my soul, Soul, thou hast much goods laid up for many years; take thine ease, eat, drink, and be merry."}, {"numero": 20, "texto": "But God said unto him, Thou fool, this night thy soul shall be required of thee: then whose shall those things be, which thou hast provided?"}, {"numero": 21, "texto": "So is he that layeth up treasure for himself, and is not rich toward God."}, {"numero": 22, "texto": "And he said unto his disciples, Therefore I say unto you, Take no thought for your life, what ye shall eat; neither for the body, what ye shall put on."}, {"numero": 23, "texto": "The life is more than meat, and the body is more than raiment."}, {"numero": 24, "texto": "Consider the ravens: for they neither sow nor reap; which neither have storehouse nor barn; and God feedeth them: how much more are ye better than the fowls?"}, {"numero": 25, "texto": "And which of you with taking thought can add to his stature one cubit?"}, {"numero": 26, "texto": "If ye then be not able to do that thing which is least, why take ye thought for the rest?"}, {"numero": 27, "texto": "Consider the lilies how they grow: they toil not, they spin not; and yet I say unto you, that Solomon in all his glory was not arrayed like one of these."}, {"numero": 28, "texto": "If then God so clothe the grass, which is to day in the field, and to morrow is cast into the oven; how much more will he clothe you, O ye of little faith?"}, {"numero": 29, "texto": "And seek not ye what ye shall eat, or what ye shall drink, neither be ye of doubtful mind."}, {"numero": 30, "texto": "For all these things do the nations of the world seek after: and your Father knoweth that ye have need of these things."}, {"numero": 31, "texto": "But rather seek ye the kingdom of God; and all these things shall be added unto you."}, {"numero": 32, "texto": "Fear not, little flock; for it is your Father''s good pleasure to give you the kingdom."}, {"numero": 33, "texto": "Sell that ye have, and give alms; provide yourselves bags which wax not old, a treasure in the heavens that faileth not, where no thief approacheth, neither moth corrupteth."}, {"numero": 34, "texto": "For where your treasure is, there will your heart be also."}, {"numero": 35, "texto": "Let your loins be girded about, and your lights burning;"}, {"numero": 36, "texto": "And ye yourselves like unto men that wait for their lord, when he will return from the wedding; that when he cometh and knocketh, they may open unto him immediately."}, {"numero": 37, "texto": "Blessed are those servants, whom the lord when he cometh shall find watching: verily I say unto you, that he shall gird himself, and make them to sit down to meat, and will come forth and serve them."}, {"numero": 38, "texto": "And if he shall come in the second watch, or come in the third watch, and find them so, blessed are those servants."}, {"numero": 39, "texto": "And this know, that if the goodman of the house had known what hour the thief would come, he would have watched, and not have suffered his house to be broken through."}, {"numero": 40, "texto": "Be ye therefore ready also: for the Son of man cometh at an hour when ye think not."}, {"numero": 41, "texto": "Then Peter said unto him, Lord, speakest thou this parable unto us, or even to all?"}, {"numero": 42, "texto": "And the Lord said, Who then is that faithful and wise steward, whom his lord shall make ruler over his household, to give them their portion of meat in due season?"}, {"numero": 43, "texto": "Blessed is that servant, whom his lord when he cometh shall find so doing."}, {"numero": 44, "texto": "Of a truth I say unto you, that he will make him ruler over all that he hath."}, {"numero": 45, "texto": "But and if that servant say in his heart, My lord delayeth his coming; and shall begin to beat the menservants and maidens, and to eat and drink, and to be drunken;"}, {"numero": 46, "texto": "The lord of that servant will come in a day when he looketh not for him, and at an hour when he is not aware, and will cut him in sunder, and will appoint him his portion with the unbelievers."}, {"numero": 47, "texto": "And that servant, which knew his lord''s will, and prepared not himself, neither did according to his will, shall be beaten with many stripes."}, {"numero": 48, "texto": "But he that knew not, and did commit things worthy of stripes, shall be beaten with few stripes. For unto whomsoever much is given, of him shall be much required: and to whom men have committed much, of him they will ask the more."}, {"numero": 49, "texto": "I am come to send fire on the earth; and what will I, if it be already kindled?"}, {"numero": 50, "texto": "But I have a baptism to be baptized with; and how am I straitened till it be accomplished!"}, {"numero": 51, "texto": "Suppose ye that I am come to give peace on earth? I tell you, Nay; but rather division:"}, {"numero": 52, "texto": "For from henceforth there shall be five in one house divided, three against two, and two against three."}, {"numero": 53, "texto": "The father shall be divided against the son, and the son against the father; the mother against the daughter, and the daughter against the mother; the mother in law against her daughter in law, and the daughter in law against her mother in law."}, {"numero": 54, "texto": "And he said also to the people, When ye see a cloud rise out of the west, straightway ye say, There cometh a shower; and so it is."}, {"numero": 55, "texto": "And when ye see the south wind blow, ye say, There will be heat; and it cometh to pass."}, {"numero": 56, "texto": "Ye hypocrites, ye can discern the face of the sky and of the earth; but how is it that ye do not discern this time?"}, {"numero": 57, "texto": "Yea, and why even of yourselves judge ye not what is right?"}, {"numero": 58, "texto": "When thou goest with thine adversary to the magistrate, as thou art in the way, give diligence that thou mayest be delivered from him; lest he hale thee to the judge, and the judge deliver thee to the officer, and the officer cast thee into prison."}, {"numero": 59, "texto": "I tell thee, thou shalt not depart thence, till thou hast paid the very last mite."}]'::jsonb, 'King James Version'),
  ('Lc', 12, 'fr', '[{"numero": 1, "texto": "Sur ces entrefaites, les gens s''''étant rassemblés par milliers, au point de se fouler les uns les autres, Jésus se mit à dire à ses disciples: Avant tout, gardez-vous du levain des pharisiens, qui est l''''hypocrisie."}, {"numero": 2, "texto": "Il n''''y a rien de caché qui ne doive être découvert, ni de secret qui ne doive être connu."}, {"numero": 3, "texto": "C''''est pourquoi tout ce que vous aurez dit dans les ténèbres sera entendu dans la lumière, et ce que vous aurez dit à l''''oreille dans les chambres sera prêché sur les toits."}, {"numero": 4, "texto": "Je vous dis, à vous qui êtes mes amis: Ne craignez pas ceux qui tuent le corps et qui, après cela, ne peuvent rien faire de plus."}, {"numero": 5, "texto": "Je vous montrerai qui vous devez craindre. Craignez celui qui, après avoir tué, a le pouvoir de jeter dans la géhenne; oui, je vous le dis, c''''est lui que vous devez craindre."}, {"numero": 6, "texto": "Ne vend-on pas cinq passereaux pour deux sous? Cependant, aucun d''''eux n''''est oublié devant Dieu."}, {"numero": 7, "texto": "Et même les cheveux de votre tête sont tous comptés. Ne craignez donc point: vous valez plus que beaucoup de passereaux."}, {"numero": 8, "texto": "Je vous le dis, quiconque me confessera devant les hommes, le Fils de l''''homme le confessera aussi devant les anges de Dieu;"}, {"numero": 9, "texto": "mais celui qui me reniera devant les hommes sera renié devant les anges de Dieu."}, {"numero": 10, "texto": "Et quiconque parlera contre le Fils de l''''homme, il lui sera pardonné; mais à celui qui blasphémera contre le Saint-Esprit il ne sera point pardonné."}, {"numero": 11, "texto": "Quand on vous mènera devant les synagogues, les magistrats et les autorités, ne vous inquiétez pas de la manière dont vous vous défendrez ni de ce que vous direz;"}, {"numero": 12, "texto": "car le Saint-Esprit vous enseignera à l''''heure même ce qu''''il faudra dire."}, {"numero": 13, "texto": "Quelqu''''un dit à Jésus, du milieu de la foule: Maître, dis à mon frère de partager avec moi notre héritage."}, {"numero": 14, "texto": "Jésus lui répondit: O homme, qui m''''a établi pour être votre juge, ou pour faire vos partages?"}, {"numero": 15, "texto": "Puis il leur dit: Gardez-vous avec soin de toute avarice; car la vie d''''un homme ne dépend pas de ses biens, fût-il dans l''''abondance."}, {"numero": 16, "texto": "Et il leur dit cette parabole: Les terres d''''un homme riche avaient beaucoup rapporté."}, {"numero": 17, "texto": "Et il raisonnait en lui-même, disant: Que ferai-je? car je n''''ai pas de place pour serrer ma récolte."}, {"numero": 18, "texto": "Voici, dit-il, ce que je ferai: j''''abattrai mes greniers, j''''en bâtirai de plus grands, j''''y amasserai toute ma récolte et tous mes biens;"}, {"numero": 19, "texto": "et je dirai à mon âme: Mon âme, tu as beaucoup de biens en réserve pour plusieurs années; repose-toi, mange, bois, et réjouis-toi."}, {"numero": 20, "texto": "Mais Dieu lui dit: Insensé! cette nuit même ton âme te sera redemandée; et ce que tu as préparé, pour qui cela sera-t-il?"}, {"numero": 21, "texto": "Il en est ainsi de celui qui amasse des trésors pour lui-même, et qui n''''est pas riche pour Dieu."}, {"numero": 22, "texto": "Jésus dit ensuite à ses disciples: C''''est pourquoi je vous dis: Ne vous inquiétez pas pour votre vie de ce que vous mangerez, ni pour votre corps de quoi vous serez vêtus."}, {"numero": 23, "texto": "La vie est plus que la nourriture, et le corps plus que le vêtement."}, {"numero": 24, "texto": "Considérez les corbeaux: ils ne sèment ni ne moissonnent, ils n''''ont ni cellier ni grenier; et Dieu les nourrit. Combien ne valez-vous pas plus que les oiseaux!"}, {"numero": 25, "texto": "Qui de vous, par ses inquiétudes, peut ajouter une coudée à la durée de sa vie?"}, {"numero": 26, "texto": "Si donc vous ne pouvez pas même la moindre chose, pourquoi vous inquiétez-vous du reste?"}, {"numero": 27, "texto": "Considérez comment croissent les lis: ils ne travaillent ni ne filent; cependant je vous dis que Salomon même, dans toute sa gloire, n''''a pas été vêtu comme l''''un d''''eux."}, {"numero": 28, "texto": "Si Dieu revêt ainsi l''''herbe qui est aujourd''''hui dans les champs et qui demain sera jetée au four, à combien plus forte raison ne vous vêtira-t-il pas, gens de peu de foi?"}, {"numero": 29, "texto": "Et vous, ne cherchez pas ce que vous mangerez et ce que vous boirez, et ne soyez pas inquiets."}, {"numero": 30, "texto": "Car toutes ces choses, ce sont les païens du monde qui les recherchent. Votre Père sait que vous en avez besoin."}, {"numero": 31, "texto": "Cherchez plutôt le royaume de Dieu; et toutes ces choses vous seront données par-dessus."}, {"numero": 32, "texto": "Ne crains point, petit troupeau; car votre Père a trouvé bon de vous donner le royaume."}, {"numero": 33, "texto": "Vendez ce que vous possédez, et donnez-le en aumônes. Faites-vous des bourses qui ne s''''usent point, un trésor inépuisable dans les cieux, où le voleur n''''approche point, et où la teigne ne détruit point."}, {"numero": 34, "texto": "Car là où est votre trésor, là aussi sera votre coeur."}, {"numero": 35, "texto": "Que vos reins soient ceints, et vos lampes allumées."}, {"numero": 36, "texto": "Et vous, soyez semblables à des hommes qui attendent que leur maître revienne des noces, afin de lui ouvrir dès qu''''il arrivera et frappera."}, {"numero": 37, "texto": "Heureux ces serviteurs que le maître, à son arrivée, trouvera veillant! Je vous le dis en vérité, il se ceindra, les fera mettre à table, et s''''approchera pour les servir."}, {"numero": 38, "texto": "Qu''''il arrive à la deuxième ou à la troisième veille, heureux ces serviteurs, s''''il les trouve veillant!"}, {"numero": 39, "texto": "Sachez-le bien, si le maître de la maison savait à quelle heure le voleur doit venir, il veillerait et ne laisserait pas percer sa maison."}, {"numero": 40, "texto": "Vous aussi, tenez-vous prêts, car le Fils de l''''homme viendra à l''''heure où vous n''''y penserez pas."}, {"numero": 41, "texto": "Pierre lui dit: Seigneur, est-ce à nous, ou à tous, que tu adresses cette parabole?"}, {"numero": 42, "texto": "Et le Seigneur dit: Quel est donc l''''économe fidèle et prudent que le maître établira sur ses gens, pour leur donner la nourriture au temps convenable?"}, {"numero": 43, "texto": "Heureux ce serviteur, que son maître, à son arrivée, trouvera faisant ainsi!"}, {"numero": 44, "texto": "Je vous le dis en vérité, il l''''établira sur tous ses biens."}, {"numero": 45, "texto": "Mais, si ce serviteur dit en lui-même: Mon maître tarde à venir; s''''il se met à battre les serviteurs et les servantes, à manger, à boire et à s''''enivrer,"}, {"numero": 46, "texto": "le maître de ce serviteur viendra le jour où il ne s''''y attend pas et à l''''heure qu''''il ne connaît pas, il le mettra en pièces, et lui donnera sa part avec les infidèles."}, {"numero": 47, "texto": "Le serviteur qui, ayant connu la volonté de son maître, n''''a rien préparé et n''''a pas agi selon sa volonté, sera battu d''''un grand nombre de coups."}, {"numero": 48, "texto": "Mais celui qui, ne l''''ayant pas connue, a fait des choses dignes de châtiment, sera battu de peu de coups. On demandera beaucoup à qui l''''on a beaucoup donné, et on exigera davantage de celui à qui l''''on a beaucoup confié."}, {"numero": 49, "texto": "Je suis venu jeter un feu sur la terre, et qu''''ai-je à désirer, s''''il est déjà allumé?"}, {"numero": 50, "texto": "Il est un baptême dont je dois être baptisé, et combien il me tarde qu''''il soit accompli!"}, {"numero": 51, "texto": "Pensez-vous que je sois venu apporter la paix sur la terre? Non, vous dis-je, mais la division."}, {"numero": 52, "texto": "Car désormais cinq dans une maison seront divisés, trois contre deux, et deux contre trois;"}, {"numero": 53, "texto": "le père contre le fils et le fils contre le père, la mère contre la fille et la fille contre la mère, la belle-mère contre la belle-fille et la belle-fille contre la belle-mère."}, {"numero": 54, "texto": "Il dit encore aux foules: Quand vous voyez un nuage se lever à l''''occident, vous dites aussitôt: La pluie vient. Et il arrive ainsi."}, {"numero": 55, "texto": "Et quand vous voyez souffler le vent du midi, vous dites: Il fera chaud. Et cela arrive."}, {"numero": 56, "texto": "Hypocrites! vous savez discerner l''''aspect de la terre et du ciel; comment ne discernez-vous pas ce temps-ci?"}, {"numero": 57, "texto": "Et pourquoi ne discernez-vous pas de vous-mêmes ce qui est juste?"}, {"numero": 58, "texto": "Lorsque tu vas avec ton adversaire devant le magistrat, tâche en chemin de te dégager de lui, de peur qu''''il ne te traîne devant le juge, que le juge ne te livre à l''''officier de justice, et que celui-ci ne te mette en prison."}, {"numero": 59, "texto": "Je te le dis, tu ne sortiras pas de là que tu n''''aies payé jusqu''''à la dernière pite."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 12, 'es', '[{"numero": 1, "texto": "EN esto, juntándose muchas gentes, tanto que unos á otros se hollaban, comenzó á decir á sus discípulos, primeramente: Guardaos de la levadura de los Fariseos, que es hipocresía."}, {"numero": 2, "texto": "Porque nada hay encubierto, que no haya de ser descubierto; ni oculto, que no haya de ser sabido."}, {"numero": 3, "texto": "Por tanto, las cosas que dijisteis en tinieblas, á la luz serán oídas; y lo que hablasteis al oído en las cámaras, será pregonado en los terrados."}, {"numero": 4, "texto": "Mas os digo, amigos míos: No temáis de los que matan el cuerpo, y después no tienen más que hacer."}, {"numero": 5, "texto": "Mas os enseñaré á quién temáis: temed á aquel que después de haber quitado la vida, tiene poder de echar en la Gehenna: así os digo: á éste temed."}, {"numero": 6, "texto": "¿No se venden cinco pajarillos por dos blancas? pues ni uno de ellos está olvidado delante de Dios."}, {"numero": 7, "texto": "Y aun los cabellos de vuestra cabeza están todos contados. No temáis pues: de más estima sois que muchos pajarillos."}, {"numero": 8, "texto": "Y os digo que todo aquel que me confesare delante de los hombres, también el Hijo del hombre le confesará delante de los ángeles de Dios;"}, {"numero": 9, "texto": "Mas el que me negare delante de los hombres, será negado delante de los ángeles de Dios."}, {"numero": 10, "texto": "Y todo aquel que dice palabra contra el Hijo del hombre, le será perdonado; mas al que blasfemare contra el Espíritu Santo, no le será perdonado."}, {"numero": 11, "texto": "Y cuando os trajeren á las sinagogas, y á los magistrados y potestades, no estéis solícitos cómo ó qué hayáis de responder, ó qué hayáis de decir;"}, {"numero": 12, "texto": "Porque el Espíritu Santo os enseñará en la misma hora lo que será necesario decir."}, {"numero": 13, "texto": "Y díjole uno de la compañía: Maestro, di á mi hermano que parta conmigo la herencia."}, {"numero": 14, "texto": "Mas él le dijo: Hombre, ¿quién me puso por juez ó partidor sobre vosotros?"}, {"numero": 15, "texto": "Y díjoles: Mirad, y guardaos de toda avaricia; porque la vida del hombre no consiste en la abundancia de los bienes que posee."}, {"numero": 16, "texto": "Y refirióles una parábola, diciendo: La heredad de un hombre rico había llevado mucho;"}, {"numero": 17, "texto": "Y él pensaba dentro de sí, diciendo: ¿Qué haré, porque no tengo donde juntar mis frutos?"}, {"numero": 18, "texto": "Y dijo: Esto haré: derribaré mis alfolíes, y los edificaré mayores, y allí juntaré todos mis frutos y mis bienes;"}, {"numero": 19, "texto": "Y diré á mi alma: Alma, muchos bienes tienes almacenados para muchos años; repósate, come, bebe, huélgate."}, {"numero": 20, "texto": "Y díjole Dios: Necio, esta noche vuelven á pedir tu alma; y lo que has prevenido, ¿de quién será?"}, {"numero": 21, "texto": "Así es el que hace para sí tesoro, y no es rico en Dios."}, {"numero": 22, "texto": "Y dijo á sus discípulos: Por tanto os digo: No estéis afanosos de vuestra vida, qué comeréis; ni del cuerpo, qué vestiréis."}, {"numero": 23, "texto": "La vida más es que la comida, y el cuerpo que el vestido."}, {"numero": 24, "texto": "Considerad los cuervos, que ni siembran, ni siegan; que ni tienen cillero, ni alfolí; y Dios los alimenta. ¿Cuánto de más estima sois vosotros que las aves?"}, {"numero": 25, "texto": "¿Y quién de vosotros podrá con afán añadir á su estatura un codo?"}, {"numero": 26, "texto": "Pues si no podéis aun lo que es menos, ¿para qué estaréis afanosos de lo demás?"}, {"numero": 27, "texto": "Considerad los lirios, cómo crecen: no labran, ni hilan; y os digo, que ni Salomón con toda su gloria se vistió como uno de ellos."}, {"numero": 28, "texto": "Y si así viste Dios á la hierba, que hoy está en el campo, y mañana es echada en el horno; ¿cuánto más á vosotros, hombres de poca fe?"}, {"numero": 29, "texto": "Vosotros, pues, no procuréis qué hayáis de comer, ó qué hayáis de beber; ni estéis en ansiosa perplejidad."}, {"numero": 30, "texto": "Porque todas estas cosas buscan las gentes del mundo; que vuestro Padre sabe que necesitáis estas cosas."}, {"numero": 31, "texto": "Mas procurad el reino de Dios, y todas estas cosas os serán añadidas."}, {"numero": 32, "texto": "No temáis, manada pequeña; porque al Padre ha placido daros el reino."}, {"numero": 33, "texto": "Vended lo que poseéis, y dad limosna; haceos bolsas que no se envejecen, tesoro en los cielos que nunca falta; donde ladrón no llega, ni polilla corrompe."}, {"numero": 34, "texto": "Porque donde está vuestro tesoro, allí también estará vuestro corazón."}, {"numero": 35, "texto": "Estén ceñidos vuestros lomos, y vuestras antorchas encendidas;"}, {"numero": 36, "texto": "Y vosotros semejantes á hombres que esperan cuando su señor ha de volver de las bodas; para que cuando viniere y llamare, luego le abran."}, {"numero": 37, "texto": "Bienaventurados aquellos siervos, á los cuales cuando el Señor viniere, hallare velando: de cierto os digo, que se ceñirá, y hará que se sienten á la mesa, y pasando les servirá."}, {"numero": 38, "texto": "Y aunque venga á la segunda vigilia, y aunque venga á la tercera vigilia, y los hallare así, bienaventurados son los tales siervos."}, {"numero": 39, "texto": "Esto empero sabed, que si supiese el padre de familia á qué hora había de venir el ladrón, velaría ciertamente, y no dejaría minar su casa."}, {"numero": 40, "texto": "Vosotros pues también, estad apercibidos; porque á la hora que no pensáis, el Hijo del hombre vendrá."}, {"numero": 41, "texto": "Entonces Pedro le dijo: Señor, ¿dices esta parábola á nosotros, ó también á todos?"}, {"numero": 42, "texto": "Y dijo el Señor: ¿Quién es el mayordomo fiel y prudente, al cual el señor pondrá sobre su familia, para que á tiempo les dé su ración?"}, {"numero": 43, "texto": "Bienaventurado aquel siervo, al cual, cuando el señor viniere, hallare haciendo así."}, {"numero": 44, "texto": "En verdad os digo, que él le pondrá sobre todos sus bienes."}, {"numero": 45, "texto": "Mas si el tal siervo dijere en su corazón: Mi señor tarda en venir: y comenzare á herir á los siervos y á las criadas, y á comer y á beber y á embriagarse;"}, {"numero": 46, "texto": "Vendrá el señor de aquel siervo el día que no espera, y á la hora que no sabe, y le apartará, y pondrá su parte con los infieles."}, {"numero": 47, "texto": "Porque el siervo que entendió la voluntad de su señor, y no se apercibió, ni hizo conforme á su voluntad, será azotado mucho."}, {"numero": 48, "texto": "Mas el que no entendió, é hizo cosas dignas de azotes, será azotado poco: porque á cualquiera que fué dado mucho, mucho será vuelto á demandar de él; y al que encomendaron mucho, más le será pedido."}, {"numero": 49, "texto": "Fuego vine á meter en la tierra: ¿y qué quiero, si ya está encendido?"}, {"numero": 50, "texto": "Empero de bautismo me es necesario ser bautizado: y ¡cómo me angustio hasta que sea cumplido!"}, {"numero": 51, "texto": "¿Pensáis que he venido á la tierra á dar paz? No, os digo; mas disensión."}, {"numero": 52, "texto": "Porque estarán de aquí adelante cinco en una casa divididos; tres contra dos, y dos contra tres."}, {"numero": 53, "texto": "El padre estará dividido contra el hijo, y el hijo contra el padre; la madre contra la hija, y la hija contra la madre; la suegra contra su nuera, y la nuera contra su suegra."}, {"numero": 54, "texto": "Y decía también á las gentes: Cuando veis la nube que sale del poniente, luego decís: Agua viene; y es así."}, {"numero": 55, "texto": "Y cuando sopla el austro, decís: Habrá calor; y lo hay."}, {"numero": 56, "texto": "¡Hipócritas! Sabéis examinar la faz del cielo y de la tierra; ¿y cómo no reconocéis este tiempo?"}, {"numero": 57, "texto": "¿Y por qué aun de vosotros mismos no juzgáis lo que es justo?"}, {"numero": 58, "texto": "Pues cuando vas al magistrado con tu adversario, procura en el camino librarte de él; porque no te arrastre al juez, y el juez te entregue al alguacil, y el alguacil te meta en la cárcel."}, {"numero": 59, "texto": "Te digo que no saldrás de allá, hasta que hayas pagado hasta el último maravedí."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 13, 'pt', '[{"numero": 1, "texto": "E naquele mesmo tempo estavam ali presentes alguns, que lhe contavam dos galileus cujo sangue Pilatos tinha misturado com seus sacrifícios."}, {"numero": 2, "texto": "E respondendo Jesus, disse-lhes: Vós pensais que estes galileus foram mais pecadores, por terem sofrido estas coisas?"}, {"numero": 3, "texto": "Não, eu vos digo; antes, se vós não vos arrependerdes, todos de modo semelhante perecereis."}, {"numero": 4, "texto": "Ou aqueles dezoito, sobre os quais a torre em Siloé caiu, matando-os; pensais que eram mais culpados dos que todos as pessoas que moravam em Jerusalém?"}, {"numero": 5, "texto": "Não, eu vos digo; antes, se vós não vos arrependerdes, todos de modo semelhante perecereis."}, {"numero": 6, "texto": "E dizia esta parábola: Um certo [homem] tinha uma figueira plantada em sua vinha, e veio até ela para buscar fruto, e não achou."}, {"numero": 7, "texto": "E disse ao que cuidava da vinha: Eis que há três anos, que venho para buscar fruto nesta figueira, e não [o] acho; corta-a; por que ainda ocupa inutilmente a terra?"}, {"numero": 8, "texto": "E respondendo ele, disse-lhe: Senhor, deixa-a [ainda] este ano, até que eu a escave ao redor, e a adube;"}, {"numero": 9, "texto": "E se der fruto, [deixa-a ficar] ; se não, tu a cortarás depois."}, {"numero": 10, "texto": "E ensinava em uma das sinagogas num sábado."}, {"numero": 11, "texto": "E eis que estava ali uma mulher, que havia dezoito anos que tinha um espírito de enfermidade; e andava encurvada, e de maneira nenhuma ela podia se endireitar."}, {"numero": 12, "texto": "E Jesus vendo-a, chamou-a para si, e disse-lhe: Mulher, livre estás de tua enfermidade."}, {"numero": 13, "texto": "E pôs as mãos sobre ela, e logo ela se endireitou, e glorificava a Deus."}, {"numero": 14, "texto": "E o chefe da sinagoga, irritado por Jesus ter curado no sábado, respondendo, disse à multidão: Há seis dias em que se deve trabalhar; nestes dias, pois, vinde para ser curados, e não no dia de sábado."}, {"numero": 15, "texto": "Porém o Senhor lhe respondeu, e disse: Hipócrita, no sábado cada um de vós não desata seu boi ou jumento da manjedoura, e o leva para dar de beber?"}, {"numero": 16, "texto": "E não convinha soltar desta ligadura no dia de sábado a esta [mulher] ,que é filha de Abraão, a qual, eis que Satanás já a havia ligado há dezoito anos?"}, {"numero": 17, "texto": "E ele, dizendo estas coisas, todos seus adversários ficaram envergonhados; e todo o povo se alegrava de todas as coisas gloriosas que eram feitas por ele."}, {"numero": 18, "texto": "E dizia: A que o Reino de Deus é semelhante? E a que eu o compararei?"}, {"numero": 19, "texto": "Semelhante é ao grão da mostarda, que um homem, tomando-o, lançou-o em sua horta; e cresceu, e fez-se uma grande árvore, e as aves dos céus fizeram ninhos em seus ramos."}, {"numero": 20, "texto": "E disse outra vez: A que compararei o Reino de Deus?"}, {"numero": 21, "texto": "Semelhante é ao fermento, que a mulher, tomando-o, o escondeu em três medidas de farinha, até tudo ficar levedado."}, {"numero": 22, "texto": "E andava de cidade em cidade, e de aldeia em aldeia ensinando, e caminhando para Jerusalém."}, {"numero": 23, "texto": "E disse-lhe um: Senhor, são também poucos os que se salvam? E ele lhes disse:"}, {"numero": 24, "texto": "Trabalhai para entrar pela porta estreita; porque eu vos digo, [que] muitos procuraram entrar, e não puderam."}, {"numero": 25, "texto": "Porque quando o chefe da casa se levantar, e fechar a porta, e se estiverdes de fora, e começardes a bater à porta, dizendo: Senhor, senhor, abre-nos! E respondendo ele, vos disser: Não vos conheço, [nem sei] de onde vós sois."}, {"numero": 26, "texto": "Então começareis a dizer: Em tua presença temos comido e bebido, e tens ensinado em nossas ruas."}, {"numero": 27, "texto": "E ele dirá: Digo-vos que não vos conheço, [nem sei] de onde vós sois; afastai-vos de mim, vós todos praticantes de injustiça."}, {"numero": 28, "texto": "Ali haverá choro e ranger de dentes, quando virdes a Abraão, a Isaque, a Jacó, e a todos os profetas no Reino de Deus; mas vós [sendo] lançados fora."}, {"numero": 29, "texto": "E virão [pessoas] do oriente, e do ocidente, e do norte, e do sul, e se sentarão [à mesa] no Reino de Deus."}, {"numero": 30, "texto": "E eis que há [alguns] dos últimos que serão primeiros, e há [alguns] dos primeiros que serão últimos."}, {"numero": 31, "texto": "Naquele mesmo dia, chegaram uns fariseus, dizendo-lhe: Sai, e vai-te daqui, porque Herodes quer te matar."}, {"numero": 32, "texto": "E disse-lhes: Ide, e dizei a aquela raposa: eis que expulso demônios, e faço curas hoje e amanhã, e ao terceiro dia eu terei completado."}, {"numero": 33, "texto": "Porém é necessário que hoje, e amanhã, e no [dia] seguinte eu caminhe; porque um profeta não pode morrer fora de Jerusalém."}, {"numero": 34, "texto": "Jerusalém, Jerusalém, que matas aos profetas, e apedrejas aos que te são enviados: quantas vezes eu quis juntar teus filhos, como a galinha junta seus pintos debaixo de suas asas, e não quisestes?"}, {"numero": 35, "texto": "Eis que vossa casa é deixada deserta para vós. E em verdade vos digo, que não me vereis até que venha [o tempo] em que digais: Bendito aquele que vem no nome do Senhor."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 13, 'en', '[{"numero": 1, "texto": "There were present at that season some that told him of the Galilaeans, whose blood Pilate had mingled with their sacrifices."}, {"numero": 2, "texto": "And Jesus answering said unto them, Suppose ye that these Galilaeans were sinners above all the Galilaeans, because they suffered such things?"}, {"numero": 3, "texto": "I tell you, Nay: but, except ye repent, ye shall all likewise perish."}, {"numero": 4, "texto": "Or those eighteen, upon whom the tower in Siloam fell, and slew them, think ye that they were sinners above all men that dwelt in Jerusalem?"}, {"numero": 5, "texto": "I tell you, Nay: but, except ye repent, ye shall all likewise perish."}, {"numero": 6, "texto": "He spake also this parable; A certain man had a fig tree planted in his vineyard; and he came and sought fruit thereon, and found none."}, {"numero": 7, "texto": "Then said he unto the dresser of his vineyard, Behold, these three years I come seeking fruit on this fig tree, and find none: cut it down; why cumbereth it the ground?"}, {"numero": 8, "texto": "And he answering said unto him, Lord, let it alone this year also, till I shall dig about it, and dung it:"}, {"numero": 9, "texto": "And if it bear fruit, well: and if not, then after that thou shalt cut it down."}, {"numero": 10, "texto": "And he was teaching in one of the synagogues on the sabbath."}, {"numero": 11, "texto": "And, behold, there was a woman which had a spirit of infirmity eighteen years, and was bowed together, and could in no wise lift up herself."}, {"numero": 12, "texto": "And when Jesus saw her, he called her to him, and said unto her, Woman, thou art loosed from thine infirmity."}, {"numero": 13, "texto": "And he laid his hands on her: and immediately she was made straight, and glorified God."}, {"numero": 14, "texto": "And the ruler of the synagogue answered with indignation, because that Jesus had healed on the sabbath day, and said unto the people, There are six days in which men ought to work: in them therefore come and be healed, and not on the sabbath day."}, {"numero": 15, "texto": "The Lord then answered him, and said, Thou hypocrite, doth not each one of you on the sabbath loose his ox or his ass from the stall, and lead him away to watering?"}, {"numero": 16, "texto": "And ought not this woman, being a daughter of Abraham, whom Satan hath bound, lo, these eighteen years, be loosed from this bond on the sabbath day?"}, {"numero": 17, "texto": "And when he had said these things, all his adversaries were ashamed: and all the people rejoiced for all the glorious things that were done by him."}, {"numero": 18, "texto": "Then said he, Unto what is the kingdom of God like? and whereunto shall I resemble it?"}, {"numero": 19, "texto": "It is like a grain of mustard seed, which a man took, and cast into his garden; and it grew, and waxed a great tree; and the fowls of the air lodged in the branches of it."}, {"numero": 20, "texto": "And again he said, Whereunto shall I liken the kingdom of God?"}, {"numero": 21, "texto": "It is like leaven, which a woman took and hid in three measures of meal, till the whole was leavened."}, {"numero": 22, "texto": "And he went through the cities and villages, teaching, and journeying toward Jerusalem."}, {"numero": 23, "texto": "Then said one unto him, Lord, are there few that be saved? And he said unto them,"}, {"numero": 24, "texto": "Strive to enter in at the strait gate: for many, I say unto you, will seek to enter in, and shall not be able."}, {"numero": 25, "texto": "When once the master of the house is risen up, and hath shut to the door, and ye begin to stand without, and to knock at the door, saying, Lord, Lord, open unto us; and he shall answer and say unto you, I know you not whence ye are:"}, {"numero": 26, "texto": "Then shall ye begin to say, We have eaten and drunk in thy presence, and thou hast taught in our streets."}, {"numero": 27, "texto": "But he shall say, I tell you, I know you not whence ye are; depart from me, all ye workers of iniquity."}, {"numero": 28, "texto": "There shall be weeping and gnashing of teeth, when ye shall see Abraham, and Isaac, and Jacob, and all the prophets, in the kingdom of God, and you yourselves thrust out."}, {"numero": 29, "texto": "And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of God."}, {"numero": 30, "texto": "And, behold, there are last which shall be first, and there are first which shall be last."}, {"numero": 31, "texto": "The same day there came certain of the Pharisees, saying unto him, Get thee out, and depart hence: for Herod will kill thee."}, {"numero": 32, "texto": "And he said unto them, Go ye, and tell that fox, Behold, I cast out devils, and I do cures to day and to morrow, and the third day I shall be perfected."}, {"numero": 33, "texto": "Nevertheless I must walk to day, and to morrow, and the day following: for it cannot be that a prophet perish out of Jerusalem."}, {"numero": 34, "texto": "O Jerusalem, Jerusalem, which killest the prophets, and stonest them that are sent unto thee; how often would I have gathered thy children together, as a hen doth gather her brood under her wings, and ye would not!"}, {"numero": 35, "texto": "Behold, your house is left unto you desolate: and verily I say unto you, Ye shall not see me, until the time come when ye shall say, Blessed is he that cometh in the name of the Lord."}]'::jsonb, 'King James Version'),
  ('Lc', 13, 'fr', '[{"numero": 1, "texto": "En ce même temps, quelques personnes qui se trouvaient là racontaient à Jésus ce qui était arrivé à des Galiléens dont Pilate avait mêlé le sang avec celui de leurs sacrifices."}, {"numero": 2, "texto": "Il leur répondit: Croyez-vous que ces Galiléens fussent de plus grands pécheurs que tous les autres Galiléens, parce qu''''ils ont souffert de la sorte?"}, {"numero": 3, "texto": "Non, je vous le dis. Mais si vous ne vous repentez, vous périrez tous également."}, {"numero": 4, "texto": "Ou bien, ces dix-huit personnes sur qui est tombée la tour de Siloé et qu''''elle a tuées, croyez-vous qu''''elles fussent plus coupables que tous les autres habitants de Jérusalem?"}, {"numero": 5, "texto": "Non, je vous le dis. Mais si vous ne vous repentez, vous périrez tous également."}, {"numero": 6, "texto": "Il dit aussi cette parabole: Un homme avait un figuier planté dans sa vigne. Il vint pour y chercher du fruit, et il n''''en trouva point."}, {"numero": 7, "texto": "Alors il dit au vigneron: Voilà trois ans que je viens chercher du fruit à ce figuier, et je n''''en trouve point. Coupe-le: pourquoi occupe-t-il la terre inutilement?"}, {"numero": 8, "texto": "Le vigneron lui répondit: Seigneur, laisse-le encore cette année; je creuserai tout autour, et j''''y mettrai du fumier."}, {"numero": 9, "texto": "Peut-être à l''''avenir donnera-t-il du fruit; sinon, tu le couperas."}, {"numero": 10, "texto": "Jésus enseignait dans une des synagogues, le jour du sabbat."}, {"numero": 11, "texto": "Et voici, il y avait là une femme possédée d''''un esprit qui la rendait infirme depuis dix-huit ans; elle était courbée, et ne pouvait pas du tout se redresser."}, {"numero": 12, "texto": "Lorsqu''''il la vit, Jésus lui adressa la parole, et lui dit: Femme, tu es délivrée de ton infirmité."}, {"numero": 13, "texto": "Et il lui imposa les mains. A l''''instant elle se redressa, et glorifia Dieu."}, {"numero": 14, "texto": "Mais le chef de la synagogue, indigné de ce que Jésus avait opéré cette guérison un jour de sabbat, dit à la foule: Il y a six jours pour travailler; venez donc vous faire guérir ces jours-là, et non pas le jour du sabbat."}, {"numero": 15, "texto": "Hypocrites! lui répondit le Seigneur, est-ce que chacun de vous, le jour du sabbat, ne détache pas de la crèche son boeuf ou son âne, pour le mener boire?"}, {"numero": 16, "texto": "Et cette femme, qui est une fille d''''Abraham, et que Satan tenait liée depuis dix-huit ans, ne fallait-il pas la délivrer de cette chaîne le jour du sabbat?"}, {"numero": 17, "texto": "Tandis qu''''il parlait ainsi, tous ses adversaires étaient confus, et la foule se réjouissait de toutes les choses glorieuses qu''''il faisait."}, {"numero": 18, "texto": "Il dit encore: A quoi le royaume de Dieu est-il semblable, et à quoi le comparerai-je?"}, {"numero": 19, "texto": "Il est semblable à un grain de sénevé qu''''un homme a pris et jeté dans son jardin; il pousse, devient un arbre, et les oiseaux du ciel habitent dans ses branches."}, {"numero": 20, "texto": "Il dit encore: A quoi comparerai-je le royaume de Dieu?"}, {"numero": 21, "texto": "Il est semblable à du levain qu''''une femme a pris et mis dans trois mesures de farine, pour faire lever toute la pâte."}, {"numero": 22, "texto": "Jésus traversait les villes et les villages, enseignant, et faisant route vers Jérusalem."}, {"numero": 23, "texto": "Quelqu''''un lui dit: Seigneur, n''''y a-t-il que peu de gens qui soient sauvés? Il leur répondit:"}, {"numero": 24, "texto": "Efforcez-vous d''''entrer par la porte étroite. Car, je vous le dis, beaucoup chercheront à entrer, et ne le pourront pas."}, {"numero": 25, "texto": "Quand le maître de la maison se sera levé et aura fermé la porte, et que vous, étant dehors, vous commencerez à frapper à la porte, en disant: Seigneur, Seigneur, ouvre-nous! il vous répondra: Je ne sais d''''où vous êtes."}, {"numero": 26, "texto": "Alors vous vous mettrez à dire: Nous avons mangé et bu devant toi, et tu as enseigné dans nos rues."}, {"numero": 27, "texto": "Et il répondra: Je vous le dis, je ne sais d''''où vous êtes; retirez-vous de moi, vous tous, ouvriers d''''iniquité."}, {"numero": 28, "texto": "C''''est là qu''''il y aura des pleurs et des grincements de dents, quand vous verrez Abraham, Isaac et Jacob, et tous les prophètes, dans le royaume de Dieu, et que vous serez jetés dehors."}, {"numero": 29, "texto": "Il en viendra de l''''orient et de l''''occident, du nord et du midi; et ils se mettront à table dans le royaume de Dieu."}, {"numero": 30, "texto": "Et voici, il y en a des derniers qui seront les premiers, et des premiers qui seront les derniers."}, {"numero": 31, "texto": "Ce même jour, quelques pharisiens vinrent lui dire: Va-t''''en, pars d''''ici, car Hérode veut te tuer."}, {"numero": 32, "texto": "Il leur répondit: Allez, et dites à ce renard: Voici, je chasse les démons et je fais des guérisons aujourd''''hui et demain, et le troisième jour j''''aurai fini."}, {"numero": 33, "texto": "Mais il faut que je marche aujourd''''hui, demain, et le jour suivant; car il ne convient pas qu''''un prophète périsse hors de Jérusalem."}, {"numero": 34, "texto": "Jérusalem, Jérusalem, qui tues les prophètes et qui lapides ceux qui te sont envoyés, combien de fois ai-je voulu rassembler tes enfants, comme une poule rassemble sa couvée sous ses ailes, et vous ne l''''avez pas voulu!"}, {"numero": 35, "texto": "Voici, votre maison vous sera laissée; mais, je vous le dis, vous ne me verrez plus, jusqu''''à ce que vous disiez: Béni soit celui qui vient au nom du Seigneur!"}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 13, 'es', '[{"numero": 1, "texto": "Y EN este mismo tiempo estaban allí unos que le contaban acerca de los Galileos, cuya sangre Pilato había mezclado con sus sacrificios."}, {"numero": 2, "texto": "Y respondiendo Jesús, les dijo: ¿Pensáis que estos Galileos, porque han padecido tales cosas, hayan sido más pecadores que todos los Galileos?"}, {"numero": 3, "texto": "No, os digo; antes si no os arrepintiereis, todos pereceréis igualmente."}, {"numero": 4, "texto": "O aquellos dieciocho, sobre los cuales cayó la torre en Siloé, y los mató, ¿pensáis que ellos fueron más deudores que todos los hombres que habitan en Jerusalem?"}, {"numero": 5, "texto": "No, os digo; antes si no os arrepintiereis, todos pereceréis asimismo."}, {"numero": 6, "texto": "Y dijo esta parábola: Tenía uno una higuera plantada en su viña, y vino á buscar fruto en ella, y no lo halló."}, {"numero": 7, "texto": "Y dijo al viñero: He aquí tres años ha que vengo á buscar fruto en esta higuera, y no lo hallo; córtala, ¿por qué ocupará aún la tierra?"}, {"numero": 8, "texto": "El entonces respondiendo, le dijo: Señor, déjala aún este año, hasta que la excave, y estercole."}, {"numero": 9, "texto": "Y si hiciere fruto, bien; y si no, la cortarás después."}, {"numero": 10, "texto": "Y enseñaba en una sinagoga en sábado."}, {"numero": 11, "texto": "Y he aquí una mujer que tenía espíritu de enfermedad dieciocho años, y andaba agobiada, que en ninguna manera se podía enhestar."}, {"numero": 12, "texto": "Y como Jesús la vió, llamóla, y díjole: Mujer, libre eres de tu enfermedad."}, {"numero": 13, "texto": "Y puso las manos sobre ella; y luego se enderezó, y glorificaba á Dios."}, {"numero": 14, "texto": "Y respondiendo el príncipe de la sinagoga, enojado de que Jesús hubiese curado en sábado, dijo á la compañía: Seis días hay en que es necesario obrar: en estos, pues, venid y sed curados, y no en día de sábado."}, {"numero": 15, "texto": "Entonces el Señor le respondió, y dijo: Hipócrita, cada uno de vosotros ¿no desata en sábado su buey ó su asno del pesebre, y lo lleva á beber?"}, {"numero": 16, "texto": "Y á esta hija de Abraham, que he aquí Satanás la había ligado dieciocho años, ¿no convino desatarla de esta ligadura en día de sábado?"}, {"numero": 17, "texto": "Y diciendo estas cosas, se avergonzaban todos sus adversarios: mas todo el pueblo se gozaba de todas las cosas gloriosas que eran por él hechas."}, {"numero": 18, "texto": "Y dijo: ¿A qué es semejante el reino de Dios, y á qué le compararé?"}, {"numero": 19, "texto": "Semejante es al grano de la mostaza, que tomándolo un hombre lo metió en su huerto; y creció, y fué hecho árbol grande, y las aves del cielo hicieron nidos en sus ramas."}, {"numero": 20, "texto": "Y otra vez dijo: ¿A qué compararé el reino de Dios?"}, {"numero": 21, "texto": "Semejante es á la levadura, que tomó una mujer, y la escondió en tres medidas de harina, hasta que todo hubo fermentado."}, {"numero": 22, "texto": "Y pasaba por todas las ciudades y aldeas, enseñando, y caminando á Jerusalem."}, {"numero": 23, "texto": "Y díjole uno: Señor, ¿son pocos los que se salvan? Y él les dijo:"}, {"numero": 24, "texto": "Porfiad á entrar por la puerta angosta; porque os digo que muchos procurarán entrar, y no podrán."}, {"numero": 25, "texto": "Después que el padre de familia se levantare, y cerrare la puerta, y comenzareis á estar fuera, y llamar á la puerta, diciendo: Señor, Señor, ábrenos; y respondiendo os dirá: No os conozco de dónde seáis."}, {"numero": 26, "texto": "Entonces comenzaréis á decir: Delante de ti hemos comido y bebido, y en nuestras plazas enseñaste;"}, {"numero": 27, "texto": "Y os dirá: Dígoos que no os conozco de dónde seáis; apartaos de mí todos los obreros de iniquidad."}, {"numero": 28, "texto": "Allí será el llanto y el crujir de dientes, cuando viereis á Abraham, y á Isaac, y á Jacob, y á todos los profetas en el reino de Dios, y vosotros excluídos."}, {"numero": 29, "texto": "Y vendrán del Oriente y del Occidente, del Norte y del Mediodía, y se sentarán á la mesa en el reino de Dios."}, {"numero": 30, "texto": "Y he aquí, son postreros los que eran los primeros; y son primeros los que eran los postreros."}, {"numero": 31, "texto": "Aquel mismo día llegaron unos de los Fariseos, diciéndole: Sal, y vete de aquí, porque Herodes te quiere matar."}, {"numero": 32, "texto": "Y les dijo: Id, y decid á aquella zorra: He aquí, echo fuera demonios y acabo sanidades hoy y mañana, y al tercer día soy consumado."}, {"numero": 33, "texto": "Empero es menester que hoy, y mañana, y pasado mañana camine; porque no es posible que profeta muera fuera de Jerusalem."}, {"numero": 34, "texto": "¡Jerusalem, Jerusalem! que matas á los profetas, y apedreas á los que son enviados á ti: ¡cuántas veces quise juntar tus hijos, como la gallina sus pollos debajo de sus alas, y no quisiste!"}, {"numero": 35, "texto": "He aquí, os es dejada vuestra casa desierta: y os digo que no me veréis, hasta que venga tiempo cuando digáis: Bendito el que viene en nombre del Señor."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 14, 'pt', '[{"numero": 1, "texto": "E aconteceu que, entrando ele num sábado para comer pão na casa de um dos chefes dos fariseus, eles estavam o observando."}, {"numero": 2, "texto": "E eis que um certo homem com o corpo inchado estava ali diante dele."}, {"numero": 3, "texto": "E respondendo Jesus, falou aos estudiosos da Lei, e aos fariseus, dizendo: É lícito curar no sábado?"}, {"numero": 4, "texto": "Porém eles ficaram calados; e ele, tomando [-o] ,o curou, e [o] despediu."}, {"numero": 5, "texto": "E ele, respondendo-lhes, disse: De qual que vós cairá o jumento, ou o boi em algum poço que, [mesmo] no sábado, não o tire logo?"}, {"numero": 6, "texto": "E nada podiam lhe responder a estas coisas."}, {"numero": 7, "texto": "E vendo como os convidados escolhiam os primeiros assentos, disse-lhes uma parábola:"}, {"numero": 8, "texto": "Quando fores convidados para o casamento de alguém, não te sentes no primeiro assento, para que não [aconteça de] se outro convidado mais digno que tu estiver,"}, {"numero": 9, "texto": "E venha o que convidou a ti e a ele, e te diga: Dá lugar a este; E então, com vergonha, tenhas que tomar o último lugar."}, {"numero": 10, "texto": "Mas quando fores convidado, vai, e senta-te no último lugar; para que quando vier o que te convidou, te diga: Amigo, sobe para [este assento] melhor. Então terás honra diante dos que estiverem sentados contigo [à mesa] ."}, {"numero": 11, "texto": "Porque qualquer que exaltar a si mesmo, e aquele que humilhar a si mesmo, será exaltado."}, {"numero": 12, "texto": "E dizia também ao que tinha lhe convidado: Quando fizeres um jantar, ou uma ceia, não chames a teus amigos, nem a teus irmãos, nem a teus parentes, nem a [teus] vizinhos ricos, para que eles também em algum tempo não te convidem de volta, e tu sejas recompensado."}, {"numero": 13, "texto": "Mas quando fizeres convite, chama aos pobres, aleijados, mancos [e] cegos."}, {"numero": 14, "texto": "E serás bem-aventurado, porque não eles não têm como te recompensar; pois tu serás recompensado na ressurreição dos justos."}, {"numero": 15, "texto": "E um dos que juntamente estavam sentados [à mesa] , ouvindo isto, disse-lhe: Bem-aventurado aquele que comer pão no Reino de Deus."}, {"numero": 16, "texto": "Porém ele lhe disse: Um certo homem fez um grande jantar, e convidou a muitos."}, {"numero": 17, "texto": "E na hora do jantar, mandou seu servo para dizer aos convidados: Vinde, que tudo já está preparado."}, {"numero": 18, "texto": "E cada um deles todos começou a dar desculpas. O primeiro lhe disse: Comprei um campo, e tenho que ir vê-lo; peço-te desculpas."}, {"numero": 19, "texto": "E outro disse: Comprei cinco pares de bois, e vou testá-los; peço-te desculpas."}, {"numero": 20, "texto": "E outro disse: Casei-me [com] uma mulher, e portanto não posso vir."}, {"numero": 21, "texto": "E aquele servo, ao voltar, anunciou estas coisas a seu senhor. Então o chefe da casa, irritado, disse a seu servo: Sai depressa pelas ruas e praças da cidade, e traze aqui aos pobres, e aleijados, e mancos e cegos."}, {"numero": 22, "texto": "E o servo disse: Senhor, está feito como mandaste, e ainda há lugar."}, {"numero": 23, "texto": "E o senhor disse ao servo: Sai pelos caminhos, e trilhas, e força-os a entrar, para que minha casa se encha."}, {"numero": 24, "texto": "Porque eu vos digo, que nenhum daqueles homens que foram convidados experimentará da minha ceia."}, {"numero": 25, "texto": "E muitas multidões iam com ele; e virando-se, disse-lhes:"}, {"numero": 26, "texto": "Se alguém vier a mim, e não odiar a seu pai, e mãe, e mulher, e filhos, e irmãos, e irmãs, e ainda também sua própria vida, não pode ser meu discípulo."}, {"numero": 27, "texto": "E qualquer que não levar sua cruz, e vier após mim, não pode ser meu discípulo."}, {"numero": 28, "texto": "Porque qual de vós, querendo edificar uma torre, não se senta primeiro para fazer as contas dos gastos, [para ver] se tem o [suficiente] para a completar?"}, {"numero": 29, "texto": "Para que não aconteça que, depois de ter posto seu fundamento, e não podendo a completar, comecem a escarnecer dele todos os que [o] virem,"}, {"numero": 30, "texto": "Dizendo: Este homem começou a construir, e não pôde terminar."}, {"numero": 31, "texto": "Ou qual rei, indo a guerra para lutar contra outro rei, não se senta primeiro para consultar, se pode ir ao encontro com dez mil [soldados] , vindo contra ele vinte mil?"}, {"numero": 32, "texto": "Se não [puder] , estando o outro ainda longe, manda [-lhe] representantes diplomáticos, e roga pela paz."}, {"numero": 33, "texto": "Assim, portanto, qualquer de vós que não renuncia a tudo, não pode ser meu discípulo."}, {"numero": 34, "texto": "Bom é o sal; porém se o sal perder o sabor, com o que ele será temperado?"}, {"numero": 35, "texto": "Nem para a terra, nem para adubo serve; lançam-no fora. Quem tem ouvidos para ouvir, ouça."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 14, 'en', '[{"numero": 1, "texto": "And it came to pass, as he went into the house of one of the chief Pharisees to eat bread on the sabbath day, that they watched him."}, {"numero": 2, "texto": "And, behold, there was a certain man before him which had the dropsy."}, {"numero": 3, "texto": "And Jesus answering spake unto the lawyers and Pharisees, saying, Is it lawful to heal on the sabbath day?"}, {"numero": 4, "texto": "And they held their peace. And he took him, and healed him, and let him go;"}, {"numero": 5, "texto": "And answered them, saying, Which of you shall have an ass or an ox fallen into a pit, and will not straightway pull him out on the sabbath day?"}, {"numero": 6, "texto": "And they could not answer him again to these things."}, {"numero": 7, "texto": "And he put forth a parable to those which were bidden, when he marked how they chose out the chief rooms; saying unto them."}, {"numero": 8, "texto": "When thou art bidden of any man to a wedding, sit not down in the highest room; lest a more honourable man than thou be bidden of him;"}, {"numero": 9, "texto": "And he that bade thee and him come and say to thee, Give this man place; and thou begin with shame to take the lowest room."}, {"numero": 10, "texto": "But when thou art bidden, go and sit down in the lowest room; that when he that bade thee cometh, he may say unto thee, Friend, go up higher: then shalt thou have worship in the presence of them that sit at meat with thee."}, {"numero": 11, "texto": "For whosoever exalteth himself shall be abased; and he that humbleth himself shall be exalted."}, {"numero": 12, "texto": "Then said he also to him that bade him, When thou makest a dinner or a supper, call not thy friends, nor thy brethren, neither thy kinsmen, nor thy rich neighbours; lest they also bid thee again, and a recompence be made thee."}, {"numero": 13, "texto": "But when thou makest a feast, call the poor, the maimed, the lame, the blind:"}, {"numero": 14, "texto": "And thou shalt be blessed; for they cannot recompense thee: for thou shalt be recompensed at the resurrection of the just."}, {"numero": 15, "texto": "And when one of them that sat at meat with him heard these things, he said unto him, Blessed is he that shall eat bread in the kingdom of God."}, {"numero": 16, "texto": "Then said he unto him, A certain man made a great supper, and bade many:"}, {"numero": 17, "texto": "And sent his servant at supper time to say to them that were bidden, Come; for all things are now ready."}, {"numero": 18, "texto": "And they all with one consent began to make excuse. The first said unto him, I have bought a piece of ground, and I must needs go and see it: I pray thee have me excused."}, {"numero": 19, "texto": "And another said, I have bought five yoke of oxen, and I go to prove them: I pray thee have me excused."}, {"numero": 20, "texto": "And another said, I have married a wife, and therefore I cannot come."}, {"numero": 21, "texto": "So that servant came, and shewed his lord these things. Then the master of the house being angry said to his servant, Go out quickly into the streets and lanes of the city, and bring in hither the poor, and the maimed, and the halt, and the blind."}, {"numero": 22, "texto": "And the servant said, Lord, it is done as thou hast commanded, and yet there is room."}, {"numero": 23, "texto": "And the lord said unto the servant, Go out into the highways and hedges, and compel them to come in, that my house may be filled."}, {"numero": 24, "texto": "For I say unto you, That none of those men which were bidden shall taste of my supper."}, {"numero": 25, "texto": "And there went great multitudes with him: and he turned, and said unto them,"}, {"numero": 26, "texto": "If any man come to me, and hate not his father, and mother, and wife, and children, and brethren, and sisters, yea, and his own life also, he cannot be my disciple."}, {"numero": 27, "texto": "And whosoever doth not bear his cross, and come after me, cannot be my disciple."}, {"numero": 28, "texto": "For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?"}, {"numero": 29, "texto": "Lest haply, after he hath laid the foundation, and is not able to finish it, all that behold it begin to mock him,"}, {"numero": 30, "texto": "Saying, This man began to build, and was not able to finish."}, {"numero": 31, "texto": "Or what king, going to make war against another king, sitteth not down first, and consulteth whether he be able with ten thousand to meet him that cometh against him with twenty thousand?"}, {"numero": 32, "texto": "Or else, while the other is yet a great way off, he sendeth an ambassage, and desireth conditions of peace."}, {"numero": 33, "texto": "So likewise, whosoever he be of you that forsaketh not all that he hath, he cannot be my disciple."}, {"numero": 34, "texto": "Salt is good: but if the salt have lost his savour, wherewith shall it be seasoned?"}, {"numero": 35, "texto": "It is neither fit for the land, nor yet for the dunghill; but men cast it out. He that hath ears to hear, let him hear."}]'::jsonb, 'King James Version'),
  ('Lc', 14, 'fr', '[{"numero": 1, "texto": "Jésus étant entré, un jour de sabbat, dans la maison de l''''un des chefs des pharisiens, pour prendre un repas, les pharisiens l''''observaient."}, {"numero": 2, "texto": "Et voici, un homme hydropique était devant lui."}, {"numero": 3, "texto": "Jésus prit la parole, et dit aux docteurs de la loi et aux pharisiens: Est-il permis, ou non, de faire une guérison le jour du sabbat?"}, {"numero": 4, "texto": "Ils gardèrent le silence. Alors Jésus avança la main sur cet homme, le guérit, et le renvoya."}, {"numero": 5, "texto": "Puis il leur dit: Lequel de vous, si son fils ou son boeuf tombe dans un puits, ne l''''en retirera pas aussitôt, le jour du sabbat?"}, {"numero": 6, "texto": "Et ils ne purent rien répondre à cela."}, {"numero": 7, "texto": "Il adressa ensuite une parabole aux conviés, en voyant qu''''ils choisissaient les premières places; et il leur dit:"}, {"numero": 8, "texto": "Lorsque tu seras invité par quelqu''''un à des noces, ne te mets pas à la première place, de peur qu''''il n''''y ait parmi les invités une personne plus considérable que toi,"}, {"numero": 9, "texto": "et que celui qui vous a invités l''''un et l''''autre ne vienne te dire: Cède la place à cette personne-là. Tu aurais alors la honte d''''aller occuper la dernière place."}, {"numero": 10, "texto": "Mais, lorsque tu seras invité, va te mettre à la dernière place, afin que, quand celui qui t''''a invité viendra, il te dise: Mon ami, monte plus haut. Alors cela te fera honneur devant tous ceux qui seront à table avec toi."}, {"numero": 11, "texto": "Car quiconque s''''élève sera abaissé, et quiconque s''''abaisse sera élevé."}, {"numero": 12, "texto": "Il dit aussi à celui qui l''''avait invité: Lorsque tu donnes à dîner ou à souper, n''''invite pas tes amis, ni tes frères, ni tes parents, ni des voisins riches, de peur qu''''ils ne t''''invitent à leur tour et qu''''on ne te rende la pareille."}, {"numero": 13, "texto": "Mais, lorsque tu donnes un festin, invite des pauvres, des estropiés, des boiteux, des aveugles."}, {"numero": 14, "texto": "Et tu seras heureux de ce qu''''ils ne peuvent pas te rendre la pareille; car elle te sera rendue à la résurrection des justes."}, {"numero": 15, "texto": "Un de ceux qui étaient à table, après avoir entendu ces paroles, dit à Jésus: Heureux celui qui prendra son repas dans le royaume de Dieu!"}, {"numero": 16, "texto": "Et Jésus lui répondit: Un homme donna un grand souper, et il invita beaucoup de gens."}, {"numero": 17, "texto": "A l''''heure du souper, il envoya son serviteur dire aux conviés: Venez, car tout est déjà prêt."}, {"numero": 18, "texto": "Mais tous unanimement se mirent à s''''excuser. Le premier lui dit: J''''ai acheté un champ, et je suis obligé d''''aller le voir; excuse-moi, je te prie."}, {"numero": 19, "texto": "Un autre dit: J''''ai acheté cinq paires de boeufs, et je vais les essayer; excuse-moi, je te prie."}, {"numero": 20, "texto": "Un autre dit: Je viens de me marier, et c''''est pourquoi je ne puis aller."}, {"numero": 21, "texto": "Le serviteur, de retour, rapporta ces choses à son maître. Alors le maître de la maison irrité dit à son serviteur: Va promptement dans les places et dans les rues de la ville, et amène ici les pauvres, les estropiés, les aveugles et les boiteux."}, {"numero": 22, "texto": "Le serviteur dit: Maître, ce que tu as ordonné a été fait, et il y a encore de la place."}, {"numero": 23, "texto": "Et le maître dit au serviteur: Va dans les chemins et le long des haies, et ceux que tu trouveras, contrains-les d''''entrer, afin que ma maison soit remplie."}, {"numero": 24, "texto": "Car, je vous le dis, aucun de ces hommes qui avaient été invités ne goûtera de mon souper."}, {"numero": 25, "texto": "De grandes foules faisaient route avec Jésus. Il se retourna, et leur dit:"}, {"numero": 26, "texto": "Si quelqu''''un vient à moi, et s''''il ne hait pas son père, sa mère, sa femme, ses enfants, ses frères, et ses soeurs, et même sa propre vie, il ne peut être mon disciple."}, {"numero": 27, "texto": "Et quiconque ne porte pas sa croix, et ne me suit pas, ne peut être mon disciple."}, {"numero": 28, "texto": "Car, lequel de vous, s''''il veut bâtir une tour, ne s''''assied d''''abord pour calculer la dépense et voir s''''il a de quoi la terminer,"}, {"numero": 29, "texto": "de peur qu''''après avoir posé les fondements, il ne puisse l''''achever, et que tous ceux qui le verront ne se mettent à le railler,"}, {"numero": 30, "texto": "en disant: Cet homme a commencé à bâtir, et il n''''a pu achever?"}, {"numero": 31, "texto": "Ou quel roi, s''''il va faire la guerre à un autre roi, ne s''''assied d''''abord pour examiner s''''il peut, avec dix mille hommes, marcher à la rencontre de celui qui vient l''''attaquer avec vingt mille?"}, {"numero": 32, "texto": "S''''il ne le peut, tandis que cet autre roi est encore loin, il lui envoie une ambassade pour demander la paix."}, {"numero": 33, "texto": "Ainsi donc, quiconque d''''entre vous ne renonce pas à tout ce qu''''il possède ne peut être mon disciple."}, {"numero": 34, "texto": "Le sel est une bonne chose; mais si le sel perd sa saveur, avec quoi l''''assaisonnera-t-on?"}, {"numero": 35, "texto": "Il n''''est bon ni pour la terre, ni pour le fumier; on le jette dehors. Que celui qui a des oreilles pour entendre entende."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 14, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que entrando en casa de un príncipe de los Fariseos un sábado á comer pan, ellos le acechaban."}, {"numero": 2, "texto": "Y he aquí un hombre hidrópico estaba delante de él."}, {"numero": 3, "texto": "Y respondiendo Jesús, habló á los doctores de la ley y á los Fariseos, diciendo: ¿Es lícito sanar en sábado?"}, {"numero": 4, "texto": "Y ellos callaron. Entonces él tomándole, le sanó, y despidióle."}, {"numero": 5, "texto": "Y respondiendo á ellos dijo: ¿El asno ó el buey de cuál de vosotros caerá en algún pozo, y no lo sacará luego en día de sábado?"}, {"numero": 6, "texto": "Y no le podían replicar á estas cosas."}, {"numero": 7, "texto": "Y observando cómo escogían los primeros asientos á la mesa, propuso una parábola á los convidados, diciéndoles:"}, {"numero": 8, "texto": "Cuando fueres convidado de alguno á bodas, no te sientes en el primer lugar, no sea que otro más honrado que tú esté por él convidado,"}, {"numero": 9, "texto": "Y viniendo el que te llamó á ti y á él, te diga: Da lugar á éste: y entonces comiences con vergüenza á tener el lugar último."}, {"numero": 10, "texto": "Mas cuando fueres convidado, ve, y siéntate en el postrer lugar; porque cuando viniere el que te llamó, te diga: Amigo, sube arriba: entonces tendrás gloria delante de los que juntamente se asientan á la mesa."}, {"numero": 11, "texto": "Porque cualquiera que se ensalza, será humillado; y el que se humilla, será ensalzado."}, {"numero": 12, "texto": "Y dijo también al que le había convidado: Cuando haces comida ó cena, no llames á tus amigos, ni á tus hermanos, ni á tus parientes, ni á vecinos ricos; porque también ellos no te vuelvan á convidar, y te sea hecha compensación."}, {"numero": 13, "texto": "Mas cuando haces banquete, llama á los pobres, los mancos, los cojos, los ciegos;"}, {"numero": 14, "texto": "Y serás bienaventurado; porque no te pueden retribuir; mas te será recompensado en la resurrección de los justos."}, {"numero": 15, "texto": "Y oyendo esto uno de los que juntamente estaban sentados á la mesa, le dijo: Bienaventurado el que comerá pan en el reino de los cielos."}, {"numero": 16, "texto": "El entonces le dijo: Un hombre hizo una grande cena, y convidó á muchos."}, {"numero": 17, "texto": "Y á la hora de la cena envió á su siervo á decir á los convidados: Venid, que ya está todo aparejado."}, {"numero": 18, "texto": "Y comenzaron todos á una á excusarse. El primero le dijo: He comprado una hacienda, y necesito salir y verla; te ruego que me des por excusado."}, {"numero": 19, "texto": "Y el otro dijo: He comprado cinco yuntas de bueyes, y voy á probarlos; ruégote que me des por excusado."}, {"numero": 20, "texto": "Y el otro dijo: Acabo de casarme, y por tanto no puedo ir."}, {"numero": 21, "texto": "Y vuelto el siervo, hizo saber estas cosas á su señor. Entonces enojado el padre de la familia, dijo á su siervo: Ve presto por las plazas y por las calles de la ciudad, y mete acá los pobres, los mancos, y cojos, y ciegos."}, {"numero": 22, "texto": "Y dijo el siervo: Señor, hecho es como mandaste, y aun hay lugar."}, {"numero": 23, "texto": "Y dijo el señor al siervo: Ve por los caminos y por los vallados, y fuérzalos á entrar, para que se llene mi casa."}, {"numero": 24, "texto": "Porque os digo que ninguno de aquellos hombres que fueron llamados, gustará mi cena."}, {"numero": 25, "texto": "Y muchas gentes iban con él; y volviéndose les dijo:"}, {"numero": 26, "texto": "Si alguno viene á mí, y no aborrece á su padre, y madre, y mujer, é hijos, y hermanos, y hermanas, y aun también su vida, no puede ser mi discípulo."}, {"numero": 27, "texto": "Y cualquiera que no trae su cruz, y viene en pos de mí, no puede ser mi discípulo."}, {"numero": 28, "texto": "Porque ¿cuál de vosotros, queriendo edificar una torre, no cuenta primero sentado los gastos, si tiene lo que necesita para acabarla?"}, {"numero": 29, "texto": "Porque después que haya puesto el fundamento, y no pueda acabarla, todos los que lo vieren, no comiencen á hacer burla de él,"}, {"numero": 30, "texto": "Diciendo: Este hombre comenzó á edificar, y no pudo acabar."}, {"numero": 31, "texto": "¿O cuál rey, habiendo de ir á hacer guerra contra otro rey, sentándose primero no consulta si puede salir al encuentro con diez mil al que viene contra él con veinte mil?"}, {"numero": 32, "texto": "De otra manera, cuando aun el otro está lejos, le ruega por la paz, enviándole embajada."}, {"numero": 33, "texto": "Así pues, cualquiera de vosotros que no renuncia á todas las cosas que posee, no puede ser mi discípulo."}, {"numero": 34, "texto": "Buena es la sal; mas si aun la sal fuere desvanecida, ¿con qué se adobará?"}, {"numero": 35, "texto": "Ni para la tierra, ni para el muladar es buena; fuera la arrojan. Quien tiene oídos para oir, oiga."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 15, 'pt', '[{"numero": 1, "texto": "E chegavam-se a ele todos os publicanos e pecadores para o ouvirem."}, {"numero": 2, "texto": "E os fariseus e escribas murmuravam, dizendo: Este recebe aos pecadores, e come com eles."}, {"numero": 3, "texto": "E ele lhes propôs esta parábola, dizendo:"}, {"numero": 4, "texto": "Quem de vós, tendo cem ovelhas, e perdendo uma delas, não deixa no deserto as noventa e nove, e vai em [busca] da perdida, até que a encontre?"}, {"numero": 5, "texto": "E encontrando-a, [não] a ponha sobre seus ombros, com alegria?"}, {"numero": 6, "texto": "E vindo para casa, [não] convoque aos amigos, e vizinhos, dizendo-lhes: Alegrai-vos comigo, porque já achei minha ovelha perdida?"}, {"numero": 7, "texto": "Digo-vos, que assim haverá mais alegria no céu por um pecador que se arrepende, do que por noventa e nove justos que não precisam de arrependimento."}, {"numero": 8, "texto": "Ou que mulher, tendo dez moedas de prata, se perder a uma moeda, não acende a lâmpada, e varre a casa, e busca cuidadosamente até [a] achar?"}, {"numero": 9, "texto": "E achando [-a] , [não] chame as amigas e as vizinhas, dizendo: Alegrai-vos comigo, porque já achei a moeda perdida!"}, {"numero": 10, "texto": "Assim vos digo, que há alegria diante dos anjos de Deus por um pecador que se arrepende."}, {"numero": 11, "texto": "E disse: Um certo homem tinha dois filhos."}, {"numero": 12, "texto": "E disse o mais jovem deles ao pai: Pai, dá-me a parte dos bens que [me] pertencem. E ele lhe repartiu os bens."}, {"numero": 13, "texto": "E depois de não muitos dias, o filho mais jovem, juntando tudo, partiu-se para uma terra distante, e ali desperdiçou seus bens, vivendo de forma irresponsável."}, {"numero": 14, "texto": "E ele, tendo já gastado tudo, houve uma grande fome naquela terra, e ele começou a sofrer necessidade."}, {"numero": 15, "texto": "E foi, se chegou a um dos cidadãos daquela terra; e [este] o mandou a seus campos para alimentar porcos."}, {"numero": 16, "texto": "E ele ficava com vontade de encher seu estômago com os grãos que os porcos comiam, mas ninguém [as] dava para ele."}, {"numero": 17, "texto": "E ele, pensando consigo mesmo, disse: Quantos empregados de meu pai tem pão em abundância, e eu [aqui] morro de fome!"}, {"numero": 18, "texto": "Eu levantarei, e irei a meu pai, e lhe direi: Pai, pequei contra o céu, e diante de ti."}, {"numero": 19, "texto": "E já não sou digno de ser chamado teu filho; faze-me como a um de teus empregados."}, {"numero": 20, "texto": "E levantando-se, foi a seu pai. E quando ainda estava longe, o seu pai o viu, e teve compaixão dele; e correndo, caiu ao seu pescoço, e o beijou."}, {"numero": 21, "texto": "E o filho lhe disse: Pai, pequei contra o céu, e diante de ti; e já não sou digno de ser chamado teu filho."}, {"numero": 22, "texto": "Mas o pai disse a seus servos: Trazei a melhor roupa, e o vesti; e ponde um anel em sua mão, e sandálias nos [seus] pés."}, {"numero": 23, "texto": "E trazei o bezerro engordado, e o matai; e comamos, e nos alegremos."}, {"numero": 24, "texto": "Porque este meu filho estava morto, e reviveu; tinha se perdido, e foi achado. E começaram a se alegrar."}, {"numero": 25, "texto": "E seu filho mais velho estava no campo; e quando veio, chegou perto da casa, ouviu a música, e as danças."}, {"numero": 26, "texto": "E chamando para si um dos servos, perguntou-lhe: O que era aquilo?"}, {"numero": 27, "texto": "E ele lhe disse: Teu irmão chegou; e teu pai matou o bezerro engordado, porque ele voltou são."}, {"numero": 28, "texto": "Porém ele se irritou, e não queria entrar. Então o seu pai, saindo, rogava-lhe [que entrasse] ."}, {"numero": 29, "texto": "Mas [o filho] respondendo, disse ao pai: Eis que eu te sirvo há tantos anos, e nunca desobedeci tua ordem, e nunca me deste um cabrito, para que eu me alegrasse com meus amigos."}, {"numero": 30, "texto": "Porém, vindo este teu filho, que gastou teus bens com prostitutas, tu lhe mataste o bezerro engordado."}, {"numero": 31, "texto": "E ele lhe disse: Filho, tu sempre estás comigo, e todas as minhas coisas são tuas."}, {"numero": 32, "texto": "Mas era necessário se alegrar e animar; porque este teu irmão estava morto, e reviveu; e tinha se perdido, e foi encontrado."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 15, 'en', '[{"numero": 1, "texto": "Then drew near unto him all the publicans and sinners for to hear him."}, {"numero": 2, "texto": "And the Pharisees and scribes murmured, saying, This man receiveth sinners, and eateth with them."}, {"numero": 3, "texto": "And he spake this parable unto them, saying,"}, {"numero": 4, "texto": "What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?"}, {"numero": 5, "texto": "And when he hath found it, he layeth it on his shoulders, rejoicing."}, {"numero": 6, "texto": "And when he cometh home, he calleth together his friends and neighbours, saying unto them, Rejoice with me; for I have found my sheep which was lost."}, {"numero": 7, "texto": "I say unto you, that likewise joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance."}, {"numero": 8, "texto": "Either what woman having ten pieces of silver, if she lose one piece, doth not light a candle, and sweep the house, and seek diligently till she find it?"}, {"numero": 9, "texto": "And when she hath found it, she calleth her friends and her neighbours together, saying, Rejoice with me; for I have found the piece which I had lost."}, {"numero": 10, "texto": "Likewise, I say unto you, there is joy in the presence of the angels of God over one sinner that repenteth."}, {"numero": 11, "texto": "And he said, A certain man had two sons:"}, {"numero": 12, "texto": "And the younger of them said to his father, Father, give me the portion of goods that falleth to me. And he divided unto them his living."}, {"numero": 13, "texto": "And not many days after the younger son gathered all together, and took his journey into a far country, and there wasted his substance with riotous living."}, {"numero": 14, "texto": "And when he had spent all, there arose a mighty famine in that land; and he began to be in want."}, {"numero": 15, "texto": "And he went and joined himself to a citizen of that country; and he sent him into his fields to feed swine."}, {"numero": 16, "texto": "And he would fain have filled his belly with the husks that the swine did eat: and no man gave unto him."}, {"numero": 17, "texto": "And when he came to himself, he said, How many hired servants of my father''s have bread enough and to spare, and I perish with hunger!"}, {"numero": 18, "texto": "I will arise and go to my father, and will say unto him, Father, I have sinned against heaven, and before thee,"}, {"numero": 19, "texto": "And am no more worthy to be called thy son: make me as one of thy hired servants."}, {"numero": 20, "texto": "And he arose, and came to his father. But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him."}, {"numero": 21, "texto": "And the son said unto him, Father, I have sinned against heaven, and in thy sight, and am no more worthy to be called thy son."}, {"numero": 22, "texto": "But the father said to his servants, Bring forth the best robe, and put it on him; and put a ring on his hand, and shoes on his feet:"}, {"numero": 23, "texto": "And bring hither the fatted calf, and kill it; and let us eat, and be merry:"}, {"numero": 24, "texto": "For this my son was dead, and is alive again; he was lost, and is found. And they began to be merry."}, {"numero": 25, "texto": "Now his elder son was in the field: and as he came and drew nigh to the house, he heard musick and dancing."}, {"numero": 26, "texto": "And he called one of the servants, and asked what these things meant."}, {"numero": 27, "texto": "And he said unto him, Thy brother is come; and thy father hath killed the fatted calf, because he hath received him safe and sound."}, {"numero": 28, "texto": "And he was angry, and would not go in: therefore came his father out, and intreated him."}, {"numero": 29, "texto": "And he answering said to his father, Lo, these many years do I serve thee, neither transgressed I at any time thy commandment: and yet thou never gavest me a kid, that I might make merry with my friends:"}, {"numero": 30, "texto": "But as soon as this thy son was come, which hath devoured thy living with harlots, thou hast killed for him the fatted calf."}, {"numero": 31, "texto": "And he said unto him, Son, thou art ever with me, and all that I have is thine."}, {"numero": 32, "texto": "It was meet that we should make merry, and be glad: for this thy brother was dead, and is alive again; and was lost, and is found."}]'::jsonb, 'King James Version'),
  ('Lc', 15, 'fr', '[{"numero": 1, "texto": "Tous les publicains et les gens de mauvaise vie s''''approchaient de Jésus pour l''''entendre."}, {"numero": 2, "texto": "Et les pharisiens et les scribes murmuraient, disant: Cet homme accueille des gens de mauvaise vie, et mange avec eux."}, {"numero": 3, "texto": "Mais il leur dit cette parabole:"}, {"numero": 4, "texto": "Quel homme d''''entre vous, s''''il a cent brebis, et qu''''il en perde une, ne laisse les quatre-vingt-dix-neuf autres dans le désert pour aller après celle qui est perdue, jusqu''''à ce qu''''il la retrouve?"}, {"numero": 5, "texto": "Lorsqu''''il l''''a retrouvée, il la met avec joie sur ses épaules,"}, {"numero": 6, "texto": "et, de retour à la maison, il appelle ses amis et ses voisins, et leur dit: Réjouissez-vous avec moi, car j''''ai retrouvé ma brebis qui était perdue."}, {"numero": 7, "texto": "De même, je vous le dis, il y aura plus de joie dans le ciel pour un seul pécheur qui se repent, que pour quatre-vingt-dix-neuf justes qui n''''ont pas besoin de repentance."}, {"numero": 8, "texto": "Ou quelle femme, si elle a dix drachmes, et qu''''elle en perde une, n''''allume une lampe, ne balaie la maison, et ne cherche avec soin, jusqu''''à ce qu''''elle la retrouve?"}, {"numero": 9, "texto": "Lorsqu''''elle l''''a retrouvée, elle appelle ses amies et ses voisines, et dit: Réjouissez-vous avec moi, car j''''ai retrouvé la drachme que j''''avais perdue."}, {"numero": 10, "texto": "De même, je vous le dis, il y a de la joie devant les anges de Dieu pour un seul pécheur qui se repent."}, {"numero": 11, "texto": "Il dit encore: Un homme avait deux fils."}, {"numero": 12, "texto": "Le plus jeune dit à son père: Mon père, donne-moi la part de bien qui doit me revenir. Et le père leur partagea son bien."}, {"numero": 13, "texto": "Peu de jours après, le plus jeune fils, ayant tout ramassé, partit pour un pays éloigné, où il dissipa son bien en vivant dans la débauche."}, {"numero": 14, "texto": "Lorsqu''''il eut tout dépensé, une grande famine survint dans ce pays, et il commença à se trouver dans le besoin."}, {"numero": 15, "texto": "Il alla se mettre au service d''''un des habitants du pays, qui l''''envoya dans ses champs garder les pourceaux."}, {"numero": 16, "texto": "Il aurait bien voulu se rassasier des carouges que mangeaient les pourceaux, mais personne ne lui en donnait."}, {"numero": 17, "texto": "Etant rentré en lui-même, il se dit: Combien de mercenaires chez mon père ont du pain en abondance, et moi, ici, je meurs de faim!"}, {"numero": 18, "texto": "Je me lèverai, j''''irai vers mon père, et je lui dirai: Mon père, j''''ai péché contre le ciel et contre toi,"}, {"numero": 19, "texto": "je ne suis plus digne d''''être appelé ton fils; traite-moi comme l''''un de tes mercenaires."}, {"numero": 20, "texto": "Et il se leva, et alla vers son père. Comme il était encore loin, son père le vit et fut ému de compassion, il courut se jeter à son cou et le baisa."}, {"numero": 21, "texto": "Le fils lui dit: Mon père, j''''ai péché contre le ciel et contre toi, je ne suis plus digne d''''être appelé ton fils."}, {"numero": 22, "texto": "Mais le père dit à ses serviteurs: Apportez vite la plus belle robe, et l''''en revêtez; mettez-lui un anneau au doigt, et des souliers aux pieds."}, {"numero": 23, "texto": "Amenez le veau gras, et tuez-le. Mangeons et réjouissons-nous;"}, {"numero": 24, "texto": "car mon fils que voici était mort, et il est revenu à la vie; il était perdu, et il est retrouvé. Et ils commencèrent à se réjouir."}, {"numero": 25, "texto": "Or, le fils aîné était dans les champs. Lorsqu''''il revint et approcha de la maison, il entendit la musique et les danses."}, {"numero": 26, "texto": "Il appela un des serviteurs, et lui demanda ce que c''''était."}, {"numero": 27, "texto": "Ce serviteur lui dit: Ton frère est de retour, et, parce qu''''il l''''a retrouvé en bonne santé, ton père a tué le veau gras."}, {"numero": 28, "texto": "Il se mit en colère, et ne voulut pas entrer. Son père sortit, et le pria d''''entrer."}, {"numero": 29, "texto": "Mais il répondit à son père: Voici, il y a tant d''''années que je te sers, sans avoir jamais transgressé tes ordres, et jamais tu ne m''''as donné un chevreau pour que je me réjouisse avec mes amis."}, {"numero": 30, "texto": "Et quand ton fils est arrivé, celui qui a mangé ton bien avec des prostituées, c''''est pour lui que tu as tué le veau gras!"}, {"numero": 31, "texto": "Mon enfant, lui dit le père, tu es toujours avec moi, et tout ce que j''''ai est à toi;"}, {"numero": 32, "texto": "mais il fallait bien s''''égayer et se réjouir, parce que ton frère que voici était mort et qu''''il est revenu à la vie, parce qu''''il était perdu et qu''''il est retrouvé."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 15, 'es', '[{"numero": 1, "texto": "Y SE llegaban á él todos los publicanos y pecadores á oirle."}, {"numero": 2, "texto": "Y murmuraban los Fariseos y los escribas, diciendo: Este á los pecadores recibe, y con ellos come."}, {"numero": 3, "texto": "Y él les propuso esta parábola, diciendo:"}, {"numero": 4, "texto": "¿Qué hombre de vosotros, teniendo cien ovejas, si perdiere una de ellas, no deja las noventa y nueve en el desierto, y va á la que se perdió, hasta que la halle?"}, {"numero": 5, "texto": "Y hallada, la pone sobre sus hombros gozoso;"}, {"numero": 6, "texto": "Y viniendo á casa, junta á los amigos y á los vecinos, diciéndoles: Dadme el parabién, porque he hallado mi oveja que se había perdido."}, {"numero": 7, "texto": "Os digo, que así habrá más gozo en el cielo de un pecador que se arrepiente, que de noventa y nueve justos, que no necesitan arrepentimiento."}, {"numero": 8, "texto": "¿O qué mujer que tiene diez dracmas, si perdiere una dracma, no enciende el candil, y barre la casa, y busca con diligencia hasta hallarla?"}, {"numero": 9, "texto": "Y cuando la hubiere hallado, junta las amigas y las vecinas, diciendo: Dadme el parabién, porque he hallado la dracma que había perdido."}, {"numero": 10, "texto": "Así os digo que hay gozo delante de los ángeles de Dios por un pecador que se arrepiente."}, {"numero": 11, "texto": "Y dijo: Un hombre tenía dos hijos;"}, {"numero": 12, "texto": "Y el menor de ellos dijo á su padre: Padre, dame la parte de la hacienda que me pertenece: y les repartió la hacienda."}, {"numero": 13, "texto": "Y no muchos días después, juntándolo todo el hijo menor, partió lejos á una provincia apartada; y allí desperdició su hacienda viviendo perdidamente."}, {"numero": 14, "texto": "Y cuando todo lo hubo malgastado, vino una grande hambre en aquella provincia, y comenzóle á faltar."}, {"numero": 15, "texto": "Y fué y se llegó á uno de los ciudadanos de aquella tierra, el cual le envió á su hacienda para que apacentase los puercos."}, {"numero": 16, "texto": "Y deseaba henchir su vientre de las algarrobas que comían los puercos; mas nadie se las daba."}, {"numero": 17, "texto": "Y volviendo en sí, dijo: ¡Cuántos jornaleros en casa de mi padre tienen abundancia de pan, y yo aquí perezco de hambre!"}, {"numero": 18, "texto": "Me levantaré, é iré á mi padre, y le diré: Padre, he pecado contra el cielo, y contra ti;"}, {"numero": 19, "texto": "Ya no soy digno de ser llamado tu hijo; hazme como á uno de tus jornaleros."}, {"numero": 20, "texto": "Y levantándose, vino á su padre. Y como aun estuviese lejos, viólo su padre, y fué movido á misericordia, y corrió, y echóse sobre su cuello, y besóle."}, {"numero": 21, "texto": "Y el hijo le dijo: Padre, he pecado contra el cielo, y contra ti, y ya no soy digno de ser llamado tu hijo."}, {"numero": 22, "texto": "Mas el padre dijo á sus siervos: Sacad el principal vestido, y vestidle; y poned un anillo en su mano, y zapatos en sus pies."}, {"numero": 23, "texto": "Y traed el becerro grueso, y matadlo, y comamos, y hagamos fiesta:"}, {"numero": 24, "texto": "Porque este mi hijo muerto era, y ha revivido; habíase perdido, y es hallado. Y comenzaron á regocijarse."}, {"numero": 25, "texto": "Y su hijo el mayor estaba en el campo; el cual como vino, y llegó cerca de casa, oyó la sinfonía y las danzas;"}, {"numero": 26, "texto": "Y llamando á uno de los criados, preguntóle qué era aquello."}, {"numero": 27, "texto": "Y él le dijo: Tu hermano ha venido; y tu padre ha muerto el becerro grueso, por haberle recibido salvo."}, {"numero": 28, "texto": "Entonces se enojó, y no quería entrar. Salió por tanto su padre, y le rogaba que entrase."}, {"numero": 29, "texto": "Mas él respondiendo, dijo al padre: He aquí tantos años te sirvo, no habiendo traspasado jamás tu mandamiento, y nunca me has dado un cabrito para gozarme con mis amigos:"}, {"numero": 30, "texto": "Mas cuando vino éste tu hijo, que ha consumido tu hacienda con rameras, has matado para él el becerro grueso."}, {"numero": 31, "texto": "El entonces le dijo: Hijo, tú siempre estás conmigo, y todas mis cosas son tuyas."}, {"numero": 32, "texto": "Mas era menester hacer fiesta y holgarnos, porque este tu hermano muerto era, y ha revivido; habíase perdido, y es hallado."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 16, 'pt', '[{"numero": 1, "texto": "E dizia também a seus discípulos: Havia um certo homem rico, o qual tinha um mordomo; e este lhe foi acusado de fazer perder seus bens."}, {"numero": 2, "texto": "E ele, chamando-o, disse-lhe: Como ouço isto sobre ti? Presta contas de teu trabalho, porque não poderás mais ser [meu] mordomo."}, {"numero": 3, "texto": "E disse o mordomo para si mesmo: O que farei, agora que meu senhor está me tirando o trabalho de mordomo? Cavar eu não posso; mendigar eu tenho vergonha."}, {"numero": 4, "texto": "Eu sei o que farei, para que, quando eu for expulso do meu trabalho de mordomo, me recebam em suas casas."}, {"numero": 5, "texto": "E chamando a si a cada um dos devedores de seu senhor, disse ao primeiro: Quanto deves a meu senhor?"}, {"numero": 6, "texto": "E ele disse: Cem medidas de azeite. E disse-lhe: Pega a tua conta, senta, e escreve logo cinquenta."}, {"numero": 7, "texto": "Depois disse a outro: E tu, quanto deves? E ele disse: Cem volumes de trigo. E disse-lhe: Toma tua conta, e escreve oitenta."}, {"numero": 8, "texto": "E aquele senhor elogiou o injusto mordomo, por ter feito prudentemente; porque os filhos deste mundo são mais prudentes do que os filhos da luz com esta geração."}, {"numero": 9, "texto": "E eu vos digo: fazei amigos para vós com as riquezas da injustiça, para que quando vos faltar, vos recebam nos tabernáculos eternos."}, {"numero": 10, "texto": "Quem é fiel no mínimo, também é fiel no muito; e quem é injusto no mínimo, também é injusto no muito."}, {"numero": 11, "texto": "Pois se nas riquezas da injustiça não fostes fiéis, quem vos confiará as verdadeiras [riquezas] ?"}, {"numero": 12, "texto": "E se nas [coisas] dos outros não fostes fiéis, quem vos dará o que é vosso?"}, {"numero": 13, "texto": "Nenhum servo pode servir a dois senhores; porque ou irá odiar a um, e a amar ao outro; ou irá se achegar a um, e desprezar ao outro. Não podeis servir a Deus e às riquezas."}, {"numero": 14, "texto": "E os fariseus também ouviram todas estas coisas, eles que eram avarentos. E zombaram dele."}, {"numero": 15, "texto": "E disse-lhes: Vós sois os que justificais a vós mesmos diante dos seres humanos; mas Deus conhece vossos corações. Porque o que é excelente para os seres humanos é odiável diante de Deus."}, {"numero": 16, "texto": "A Lei e os profetas [foram] até João; desde então, o Reino de Deus é anunciado, todo homem [tenta entrar] nele pela força."}, {"numero": 17, "texto": "E é mais fácil passar o céu e a terra do que cair um traço de alguma letra da Lei."}, {"numero": 18, "texto": "Qualquer que deixa sua mulher, e casa com outra, adultera; e qualquer que se casa com a deixada pelo marido, [também] adultera."}, {"numero": 19, "texto": "Havia porém um certo homem rico, e vestia-se de púrpura, e de linho finíssimo, e festejava todo dia com luxo."}, {"numero": 20, "texto": "Havia também um certo mendigo, de nome Lázaro, o qual ficava deitado à sua porta cheio de feridas."}, {"numero": 21, "texto": "E desejava se satisfazer com as migalhas que caíam da mesa do rico; porém vinham também os cães, e lambiam suas feridas."}, {"numero": 22, "texto": "E aconteceu que o mendigo morreu, e foi levado pelos anjos para o colo de Abraão. E o rico também morreu, e foi sepultado."}, {"numero": 23, "texto": "E estando no Xeol em tormentos, ele levantou seus olhos, e viu a Abraão de longe, e a Lázaro junto dele."}, {"numero": 24, "texto": "E ele, chamando, disse: Pai Abraão, tem misericórdia de mim, e manda a Lázaro que molhe a ponta de seu dedo na água, e refresque a minha língua; porque estou sofrendo neste fogo."}, {"numero": 25, "texto": "Porém Abraão disse: Filho, lembra-te que em tua vida recebeste teus bens, e Lázaro do mesmo jeito [recebeu] males. E agora este é consolado, e tu [és] atormentado."}, {"numero": 26, "texto": "E, além de tudo isto, um grande abismo está posto entre nós e vós, para os que quisessem passar daqui para vós não possam; nem também os daí passarem para cá."}, {"numero": 27, "texto": "E disse ele: Rogo-te, pois, ó pai, que o mandes à casa de meu pai."}, {"numero": 28, "texto": "Porque tenho cinco irmãos, para que lhes dê testemunho; para que também não venham para este lugar de tormento."}, {"numero": 29, "texto": "Disse-lhe Abraão: Eles têm a Moisés e aos profetas, ouçam-lhes."}, {"numero": 30, "texto": "E ele disse: Não, pai Abraão; mas se alguém dos mortos fosse até eles, eles se arrependeriam."}, {"numero": 31, "texto": "Porém [Abraão] lhe disse: Se não ouvem a Moisés e aos profetas, também não se deixariam convencer, ainda que alguém ressuscite dos mortos."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 16, 'en', '[{"numero": 1, "texto": "And he said also unto his disciples, There was a certain rich man, which had a steward; and the same was accused unto him that he had wasted his goods."}, {"numero": 2, "texto": "And he called him, and said unto him, How is it that I hear this of thee? give an account of thy stewardship; for thou mayest be no longer steward."}, {"numero": 3, "texto": "Then the steward said within himself, What shall I do? for my lord taketh away from me the stewardship: I cannot dig; to beg I am ashamed."}, {"numero": 4, "texto": "I am resolved what to do, that, when I am put out of the stewardship, they may receive me into their houses."}, {"numero": 5, "texto": "So he called every one of his lord''s debtors unto him, and said unto the first, How much owest thou unto my lord?"}, {"numero": 6, "texto": "And he said, An hundred measures of oil. And he said unto him, Take thy bill, and sit down quickly, and write fifty."}, {"numero": 7, "texto": "Then said he to another, And how much owest thou? And he said, An hundred measures of wheat. And he said unto him, Take thy bill, and write fourscore."}, {"numero": 8, "texto": "And the lord commended the unjust steward, because he had done wisely: for the children of this world are in their generation wiser than the children of light."}, {"numero": 9, "texto": "And I say unto you, Make to yourselves friends of the mammon of unrighteousness; that, when ye fail, they may receive you into everlasting habitations."}, {"numero": 10, "texto": "He that is faithful in that which is least is faithful also in much: and he that is unjust in the least is unjust also in much."}, {"numero": 11, "texto": "If therefore ye have not been faithful in the unrighteous mammon, who will commit to your trust the true riches?"}, {"numero": 12, "texto": "And if ye have not been faithful in that which is another man''s, who shall give you that which is your own?"}, {"numero": 13, "texto": "No servant can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon."}, {"numero": 14, "texto": "And the Pharisees also, who were covetous, heard all these things: and they derided him."}, {"numero": 15, "texto": "And he said unto them, Ye are they which justify yourselves before men; but God knoweth your hearts: for that which is highly esteemed among men is abomination in the sight of God."}, {"numero": 16, "texto": "The law and the prophets were until John: since that time the kingdom of God is preached, and every man presseth into it."}, {"numero": 17, "texto": "And it is easier for heaven and earth to pass, than one tittle of the law to fail."}, {"numero": 18, "texto": "Whosoever putteth away his wife, and marrieth another, committeth adultery: and whosoever marrieth her that is put away from her husband committeth adultery."}, {"numero": 19, "texto": "There was a certain rich man, which was clothed in purple and fine linen, and fared sumptuously every day:"}, {"numero": 20, "texto": "And there was a certain beggar named Lazarus, which was laid at his gate, full of sores,"}, {"numero": 21, "texto": "And desiring to be fed with the crumbs which fell from the rich man''s table: moreover the dogs came and licked his sores."}, {"numero": 22, "texto": "And it came to pass, that the beggar died, and was carried by the angels into Abraham''s bosom: the rich man also died, and was buried;"}, {"numero": 23, "texto": "And in hell he lift up his eyes, being in torments, and seeth Abraham afar off, and Lazarus in his bosom."}, {"numero": 24, "texto": "And he cried and said, Father Abraham, have mercy on me, and send Lazarus, that he may dip the tip of his finger in water, and cool my tongue; for I am tormented in this flame."}, {"numero": 25, "texto": "But Abraham said, Son, remember that thou in thy lifetime receivedst thy good things, and likewise Lazarus evil things: but now he is comforted, and thou art tormented."}, {"numero": 26, "texto": "And beside all this, between us and you there is a great gulf fixed: so that they which would pass from hence to you cannot; neither can they pass to us, that would come from thence."}, {"numero": 27, "texto": "Then he said, I pray thee therefore, father, that thou wouldest send him to my father''s house:"}, {"numero": 28, "texto": "For I have five brethren; that he may testify unto them, lest they also come into this place of torment."}, {"numero": 29, "texto": "Abraham saith unto him, They have Moses and the prophets; let them hear them."}, {"numero": 30, "texto": "And he said, Nay, father Abraham: but if one went unto them from the dead, they will repent."}, {"numero": 31, "texto": "And he said unto him, If they hear not Moses and the prophets, neither will they be persuaded, though one rose from the dead."}]'::jsonb, 'King James Version'),
  ('Lc', 16, 'fr', '[{"numero": 1, "texto": "Jésus dit aussi à ses disciples: Un homme riche avait un économe, qui lui fut dénoncé comme dissipant ses biens."}, {"numero": 2, "texto": "Il l''''appela, et lui dit: Qu''''est-ce que j''''entends dire de toi? Rends compte de ton administration, car tu ne pourras plus administrer mes biens."}, {"numero": 3, "texto": "L''''économe dit en lui-même: Que ferai-je, puisque mon maître m''''ôte l''''administration de ses biens? Travailler à la terre? je ne le puis. Mendier? j''''en ai honte."}, {"numero": 4, "texto": "Je sais ce que je ferai, pour qu''''il y ait des gens qui me reçoivent dans leurs maisons quand je serai destitué de mon emploi."}, {"numero": 5, "texto": "Et, faisant venir chacun des débiteurs de son maître, il dit au premier: Combien dois-tu à mon maître?"}, {"numero": 6, "texto": "Cent mesures d''''huile, répondit-il. Et il lui dit: Prends ton billet, assieds-toi vite, et écris cinquante."}, {"numero": 7, "texto": "Il dit ensuite à un autre: Et toi, combien dois-tu? Cent mesures de blé, répondit-il. Et il lui dit: Prends ton billet, et écris quatre-vingts."}, {"numero": 8, "texto": "Le maître loua l''''économe infidèle de ce qu''''il avait agi prudemment. Car les enfants de ce siècle sont plus prudents à l''''égard de leurs semblables que ne le sont les enfants de lumière."}, {"numero": 9, "texto": "Et moi, je vous dis: Faites-vous des amis avec les richesses injustes, pour qu''''ils vous reçoivent dans les tabernacles éternels, quand elles viendront à vous manquer."}, {"numero": 10, "texto": "Celui qui est fidèle dans les moindres choses l''''est aussi dans les grandes, et celui qui est injuste dans les moindres choses l''''est aussi dans les grandes."}, {"numero": 11, "texto": "Si donc vous n''''avez pas été fidèles dans les richesses injustes, qui vous confiera les véritables?"}, {"numero": 12, "texto": "Et si vous n''''avez pas été fidèles dans ce qui est à autrui, qui vous donnera ce qui est à vous?"}, {"numero": 13, "texto": "Nul serviteur ne peut servir deux maîtres. Car, ou il haïra l''''un et aimera l''''autre; ou il s''''attachera à l''''un et méprisera l''''autre. Vous ne pouvez servir Dieu et Mamon."}, {"numero": 14, "texto": "Les pharisiens, qui étaient avares, écoutaient aussi tout cela, et ils se moquaient de lui."}, {"numero": 15, "texto": "Jésus leur dit: Vous, vous cherchez à paraître justes devant les hommes, mais Dieu connaît vos coeurs; car ce qui est élevé parmi les hommes est une abomination devant Dieu."}, {"numero": 16, "texto": "La loi et les prophètes ont subsisté jusqu''''à Jean; depuis lors, le royaume de Dieu est annoncé, et chacun use de violence pour y entrer."}, {"numero": 17, "texto": "Il est plus facile que le ciel et la terre passent, qu''''il ne l''''est qu''''un seul trait de lettre de la loi vienne à tomber."}, {"numero": 18, "texto": "Quiconque répudie sa femme et en épouse une autre commet un adultère, et quiconque épouse une femme répudiée par son mari commet un adultère."}, {"numero": 19, "texto": "Il y avait un homme riche, qui était vêtu de pourpre et de fin lin, et qui chaque jour menait joyeuse et brillante vie."}, {"numero": 20, "texto": "Un pauvre, nommé Lazare, était couché à sa porte, couvert d''''ulcères,"}, {"numero": 21, "texto": "et désireux de se rassasier des miettes qui tombaient de la table du riche; et même les chiens venaient encore lécher ses ulcères."}, {"numero": 22, "texto": "Le pauvre mourut, et il fut porté par les anges dans le sein d''''Abraham. Le riche mourut aussi, et il fut enseveli."}, {"numero": 23, "texto": "Dans le séjour des morts, il leva les yeux; et, tandis qu''''il était en proie aux tourments, il vit de loin Abraham, et Lazare dans son sein."}, {"numero": 24, "texto": "Il s''''écria: Père Abraham, aie pitié de moi, et envoie Lazare, pour qu''''il trempe le bout de son doigt dans l''''eau et me rafraîchisse la langue; car je souffre cruellement dans cette flamme."}, {"numero": 25, "texto": "Abraham répondit: Mon enfant, souviens-toi que tu as reçu tes biens pendant ta vie, et que Lazare a eu les maux pendant la sienne; maintenant il est ici consolé, et toi, tu souffres."}, {"numero": 26, "texto": "D''''ailleurs, il y a entre nous et vous un grand abîme, afin que ceux qui voudraient passer d''''ici vers vous, ou de là vers nous, ne puissent le faire."}, {"numero": 27, "texto": "Le riche dit: Je te prie donc, père Abraham, d''''envoyer Lazare dans la maison de mon père;"}, {"numero": 28, "texto": "car j''''ai cinq frères. C''''est pour qu''''il leur atteste ces choses, afin qu''''ils ne viennent pas aussi dans ce lieu de tourments."}, {"numero": 29, "texto": "Abraham répondit: Ils ont Moïse et les prophètes; qu''''ils les écoutent."}, {"numero": 30, "texto": "Et il dit: Non, père Abraham, mais si quelqu''''un des morts va vers eux, ils se repentiront."}, {"numero": 31, "texto": "Et Abraham lui dit: S''''ils n''''écoutent pas Moïse et les prophètes, ils ne se laisseront pas persuader quand même quelqu''''un des morts ressusciterait."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 16, 'es', '[{"numero": 1, "texto": "Y DIJO también á sus discípulos: Había un hombre rico, el cual tenía un mayordomo, y éste fué acusado delante de él como disipador de sus bienes."}, {"numero": 2, "texto": "Y le llamó, y le dijo: ¿Qué es esto que oigo de ti? Da cuenta de tu mayordomía, porque ya no podrás más ser mayordomo."}, {"numero": 3, "texto": "Entonces el mayordomo dijo dentro de sí: ¿Qué haré? que mi señor me quita la mayordomía. Cavar, no puedo; mendigar, tengo vergüenza."}, {"numero": 4, "texto": "Yo sé lo que haré para que cuando fuere quitado de la mayordomía, me reciban en sus casas."}, {"numero": 5, "texto": "Y llamando á cada uno de los deudores de su señor, dijo al primero: ¿Cuánto debes á mi señor?"}, {"numero": 6, "texto": "Y él dijo: Cien barriles de aceite. Y le dijo: Toma tu obligación, y siéntate presto, y escribe cincuenta."}, {"numero": 7, "texto": "Después dijo á otro: ¿Y tú, cuánto debes? Y él dijo: Cien coros de trigo. Y él le dijo: Toma tu obligación, y escribe ochenta."}, {"numero": 8, "texto": "Y alabó el señor al mayordomo malo por haber hecho discretamente; porque los hijos de este siglo son en su generación más sagaces que los hijos de luz."}, {"numero": 9, "texto": "Y yo os digo: Haceos amigos de las riquezas de maldad, para que cuando faltareis, os reciban en las moradas eternas."}, {"numero": 10, "texto": "El que es fiel en lo muy poco, también en lo más es fiel: y el que en lo muy poco es injusto, también en lo más es injusto."}, {"numero": 11, "texto": "Pues si en las malas riquezas no fuisteis fieles, ¿quién os confiará lo verdadero?"}, {"numero": 12, "texto": "Y si en lo ajeno no fuisteis fieles, ¿quién os dará lo que es vuestro?"}, {"numero": 13, "texto": "Ningún siervo puede servir á dos señores; porque ó aborrecerá al uno y amará al otro, ó se allegará al uno y menospreciará al otro. No podéis servir á Dios y á las riquezas."}, {"numero": 14, "texto": "Y oían también todas estas cosas los Fariseos, los cuales eran avaros, y se burlaban de él."}, {"numero": 15, "texto": "Y díjoles: Vosotros sois los que os justificáis á vosotros mismos delante de los hombres; mas Dios conoce vuestros corazones; porque lo que los hombres tienen por sublime, delante de Dios es abominación."}, {"numero": 16, "texto": "La ley y los profetas hasta Juan: desde entonces el reino de Dios es anunciado, y quienquiera se esfuerza á entrar en él."}, {"numero": 17, "texto": "Empero más fácil cosa es pasar el cielo y la tierra, que frustrarse un tilde de la ley."}, {"numero": 18, "texto": "Cualquiera que repudia á su mujer, y se casa con otra, adultera: y el que se casa con la repudiada del marido, adultera."}, {"numero": 19, "texto": "Había un hombre rico, que se vestía de púrpura y de lino fino, y hacía cada día banquete con esplendidez."}, {"numero": 20, "texto": "Había también un mendigo llamado Lázaro, el cual estaba echado á la puerta de él, lleno de llagas,"}, {"numero": 21, "texto": "Y deseando hartarse de las migajas que caían de la mesa del rico; y aun los perros venían y le lamían las llagas."}, {"numero": 22, "texto": "Y aconteció que murió el mendigo, y fué llevado por los ángeles al seno de Abraham: y murió también el rico, y fué sepultado."}, {"numero": 23, "texto": "Y en el infierno alzó sus ojos, estando en los tormentos, y vió á Abraham de lejos, y á Lázaro en su seno."}, {"numero": 24, "texto": "Entonces él, dando voces, dijo: Padre Abraham, ten misericordia de mí, y envía á Lázaro que moje la punta de su dedo en agua, y refresque mi lengua; porque soy atormentado en esta llama."}, {"numero": 25, "texto": "Y díjole Abraham: Hijo, acuérdate que recibiste tus bienes en tu vida, y Lázaro también males; mas ahora éste es consolado aquí, y tú atormentado."}, {"numero": 26, "texto": "Y además de todo esto, una grande sima está constituída entre nosotros y vosotros, que los que quisieren pasar de aquí á vosotros, no pueden, ni de allá pasar acá."}, {"numero": 27, "texto": "Y dijo: Ruégote pues, padre, que le envíes á la casa de mi padre;"}, {"numero": 28, "texto": "Porque tengo cinco hermanos; para que les testifique, porque no vengan ellos también á este lugar de tormento."}, {"numero": 29, "texto": "Y Abraham le dice: A Moisés y á los profetas tienen: óiganlos."}, {"numero": 30, "texto": "El entonces dijo: No, padre Abraham: mas si alguno fuere á ellos de los muertos, se arrepentirán."}, {"numero": 31, "texto": "Mas Abraham le dijo: Si no oyen á Moisés y á los profetas, tampoco se persuadirán, si alguno se levantare de los muertos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 17, 'pt', '[{"numero": 1, "texto": "E disse aos discípulos: É impossível que não venham tentações para o pecado, mas ai [daquele] por quem [essas tentações] vierem!"}, {"numero": 2, "texto": "Melhor lhe seria que lhe atasse ao pescoço uma grande pedra de moinho, e fosse lançado no mar, do que conduzir ao pecado um destes pequenos."}, {"numero": 3, "texto": "Olhai por vós. E se teu irmão pecar contra ti, repreende-o; e se ele se arrepender, perdoa-lhe."}, {"numero": 4, "texto": "E se pecar contra ti sete vezes ao dia, e se sete vezes ao dia voltar a ti, dizendo: Estou arrependido. Perdoa-lhe."}, {"numero": 5, "texto": "E os apóstolos disseram ao Senhor: Acrescenta-nos fé."}, {"numero": 6, "texto": "E o Senhor disse: Se tivésseis fé como um grão de mostarda, diríeis a esta árvore de amoras: Arranca-te daqui pelas tuas raízes, e planta-te no mar, ela vos obedeceria."}, {"numero": 7, "texto": "E qual de vós terá um servo, lavrando ou apascentando [gado] que, voltando do campo, logo lhe diga: Chega, e senta [à mesa] ."}, {"numero": 8, "texto": "E não lhe diga antes: Prepara-me o jantar, e apronta-te, e serve-me, até que eu tenha comido e bebido; e depois, que tu comas e bebas."}, {"numero": 9, "texto": "Por acaso [o senhor] agradece a tal servo, porque fez o que lhe foi mandado? Acho que não."}, {"numero": 10, "texto": "Assim também vós, quando fizerdes tudo o que vos for mandado, dizei: Somos servos inúteis, porque fizemos [somente] o que devíamos fazer."}, {"numero": 11, "texto": "E aconteceu que, indo ele para Jerusalém, passou por meio da Samaria e da Galileia."}, {"numero": 12, "texto": "E entrando em uma certa aldeia, saíram-lhe ao encontro dez homens leprosos, os quais pararam de longe."}, {"numero": 13, "texto": "E levantaram a voz, dizendo: Jesus, Mestre, tem misericórdia de nós!"}, {"numero": 14, "texto": "E ele, vendo-os, disse-lhes: Ide, e mostrai-vos aos sacerdotes.E aconteceu que, enquanto eles iam, ficaram limpos."}, {"numero": 15, "texto": "E vendo um deles que estava são, voltou, glorificando a Deus a alta voz."}, {"numero": 16, "texto": "E caiu com o rosto a seus pés, agradecendo-lhe; e este era samaritano."}, {"numero": 17, "texto": "E respondendo Jesus, disse: Não foram os dez limpos? E onde estão os nove?"}, {"numero": 18, "texto": "Não houve quem voltasse para dar glória a Deus, a não ser este estrangeiro?"}, {"numero": 19, "texto": "E disse-lhe: Levanta-te, e vai; tua fé te salvou."}, {"numero": 20, "texto": "E perguntado pelos fariseus [sobre] quando o Reino de Deus viria, respondeu-lhes, e disse: O Reino de Deus não vem com aparência visível."}, {"numero": 21, "texto": "Nem dirão: Eis aqui, ou Eis ali, porque eis que o Reino de Deus está entre vós."}, {"numero": 22, "texto": "E disse aos discípulos: Dias virão, quando desejareis ver um dos dias do Filho do homem, e não [o] vereis."}, {"numero": 23, "texto": "E vos dirão: Eis que [ele está] aqui, ou Eis que [ele está] ali, não vades, nem sigais."}, {"numero": 24, "texto": "Porque como o relâmpago, que relampeja desde o começo do céu, e brilha até ao fim do céu, assim será também o Filho do homem em seu dia."}, {"numero": 25, "texto": "Mas é necessário primeiro sofrer muito, e ser rejeitado por esta geração."}, {"numero": 26, "texto": "E como aconteceu nos dias de Noé, assim será também nos dias do Filho do homem."}, {"numero": 27, "texto": "Comiam, bebiam, se casavam, e se davam em casamento, até o dia em que Noé entrou na arca; e veio o dilúvio, e destruiu a todos."}, {"numero": 28, "texto": "Como também da mesma maneira aconteceu nos dias de Ló, comiam, bebiam, compravam, vendiam, plantavam, [e] construíam."}, {"numero": 29, "texto": "Mas o dia em que Ló saiu de Sodoma, choveu fogo e enxofre do céu, e destruiu a todos."}, {"numero": 30, "texto": "Assim será [também] no dia em que o Filho do homem se manifestar."}, {"numero": 31, "texto": "Naquele dia, o que estiver no telhado, e suas ferramentas em casa, não desça para pegá-las; e o que [estiver] no campo, não volte para trás."}, {"numero": 32, "texto": "Lembrai-vos da mulher de Ló."}, {"numero": 33, "texto": "Qualquer que procurar salvar sua vida a perderá; e qualquer que a perder, irá salvá-la."}, {"numero": 34, "texto": "Digo-vos que naquela noite, dois estarão em uma cama; um será tomado, e o outro será deixado."}, {"numero": 35, "texto": "Duas estarão juntas moendo; uma será tomada, e a outra será deixada."}, {"numero": 36, "texto": "Dois estarão no campo; um será tomado, e o outro será deixado."}, {"numero": 37, "texto": "E respondendo, disseram-lhe: Onde, Senhor?E ele lhes disse: Onde estiver o corpo, ali os abutres se juntarão."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 17, 'en', '[{"numero": 1, "texto": "Then said he unto the disciples, It is impossible but that offences will come: but woe unto him, through whom they come!"}, {"numero": 2, "texto": "It were better for him that a millstone were hanged about his neck, and he cast into the sea, than that he should offend one of these little ones."}, {"numero": 3, "texto": "Take heed to yourselves: If thy brother trespass against thee, rebuke him; and if he repent, forgive him."}, {"numero": 4, "texto": "And if he trespass against thee seven times in a day, and seven times in a day turn again to thee, saying, I repent; thou shalt forgive him."}, {"numero": 5, "texto": "And the apostles said unto the Lord, Increase our faith."}, {"numero": 6, "texto": "And the Lord said, If ye had faith as a grain of mustard seed, ye might say unto this sycamine tree, Be thou plucked up by the root, and be thou planted in the sea; and it should obey you."}, {"numero": 7, "texto": "But which of you, having a servant plowing or feeding cattle, will say unto him by and by, when he is come from the field, Go and sit down to meat?"}, {"numero": 8, "texto": "And will not rather say unto him, Make ready wherewith I may sup, and gird thyself, and serve me, till I have eaten and drunken; and afterward thou shalt eat and drink?"}, {"numero": 9, "texto": "Doth he thank that servant because he did the things that were commanded him? I trow not."}, {"numero": 10, "texto": "So likewise ye, when ye shall have done all those things which are commanded you, say, We are unprofitable servants: we have done that which was our duty to do."}, {"numero": 11, "texto": "And it came to pass, as he went to Jerusalem, that he passed through the midst of Samaria and Galilee."}, {"numero": 12, "texto": "And as he entered into a certain village, there met him ten men that were lepers, which stood afar off:"}, {"numero": 13, "texto": "And they lifted up their voices, and said, Jesus, Master, have mercy on us."}, {"numero": 14, "texto": "And when he saw them, he said unto them, Go shew yourselves unto the priests. And it came to pass, that, as they went, they were cleansed."}, {"numero": 15, "texto": "And one of them, when he saw that he was healed, turned back, and with a loud voice glorified God,"}, {"numero": 16, "texto": "And fell down on his face at his feet, giving him thanks: and he was a Samaritan."}, {"numero": 17, "texto": "And Jesus answering said, Were there not ten cleansed? but where are the nine?"}, {"numero": 18, "texto": "There are not found that returned to give glory to God, save this stranger."}, {"numero": 19, "texto": "And he said unto him, Arise, go thy way: thy faith hath made thee whole."}, {"numero": 20, "texto": "And when he was demanded of the Pharisees, when the kingdom of God should come, he answered them and said, The kingdom of God cometh not with observation:"}, {"numero": 21, "texto": "Neither shall they say, Lo here! or, lo there! for, behold, the kingdom of God is within you."}, {"numero": 22, "texto": "And he said unto the disciples, The days will come, when ye shall desire to see one of the days of the Son of man, and ye shall not see it."}, {"numero": 23, "texto": "And they shall say to you, See here; or, see there: go not after them, nor follow them."}, {"numero": 24, "texto": "For as the lightning, that lighteneth out of the one part under heaven, shineth unto the other part under heaven; so shall also the Son of man be in his day."}, {"numero": 25, "texto": "But first must he suffer many things, and be rejected of this generation."}, {"numero": 26, "texto": "And as it was in the days of Noe, so shall it be also in the days of the Son of man."}, {"numero": 27, "texto": "They did eat, they drank, they married wives, they were given in marriage, until the day that Noah entered into the ark, and the flood came, and destroyed them all."}, {"numero": 28, "texto": "Likewise also as it was in the days of Lot; they did eat, they drank, they bought, they sold, they planted, they builded;"}, {"numero": 29, "texto": "But the same day that Lot went out of Sodom it rained fire and brimstone from heaven, and destroyed them all."}, {"numero": 30, "texto": "Even thus shall it be in the day when the Son of man is revealed."}, {"numero": 31, "texto": "In that day, he which shall be upon the housetop, and his stuff in the house, let him not come down to take it away: and he that is in the field, let him likewise not return back."}, {"numero": 32, "texto": "Remember Lot''s wife."}, {"numero": 33, "texto": "Whosoever shall seek to save his life shall lose it; and whosoever shall lose his life shall preserve it."}, {"numero": 34, "texto": "I tell you, in that night there shall be two men in one bed; the one shall be taken, and the other shall be left."}, {"numero": 35, "texto": "Two women shall be grinding together; the one shall be taken, and the other left."}, {"numero": 36, "texto": "Two men shall be in the field; the one shall be taken, and the other left."}, {"numero": 37, "texto": "And they answered and said unto him, Where, Lord? And he said unto them, Wheresoever the body is, thither will the eagles be gathered together."}]'::jsonb, 'King James Version'),
  ('Lc', 17, 'fr', '[{"numero": 1, "texto": "Jésus dit à ses disciples: Il est impossible qu''''il n''''arrive pas des scandales; mais malheur à celui par qui ils arrivent!"}, {"numero": 2, "texto": "Il vaudrait mieux pour lui qu''''on mît à son cou une pierre de moulin et qu''''on le jetât dans la mer, que s''''il scandalisait un de ces petits."}, {"numero": 3, "texto": "Prenez garde à vous-mêmes. Si ton frère a péché, reprends-le; et, s''''il se repent, pardonne-lui."}, {"numero": 4, "texto": "Et s''''il a péché contre toi sept fois dans un jour et que sept fois il revienne à toi, disant: Je me repens, -tu lui pardonneras."}, {"numero": 5, "texto": "Les apôtres dirent au Seigneur: Augmente-nous la foi."}, {"numero": 6, "texto": "Et le Seigneur dit: Si vous aviez de la foi comme un grain de sénevé, vous diriez à ce sycomore: Déracine-toi, et plante-toi dans la mer; et il vous obéirait."}, {"numero": 7, "texto": "Qui de vous, ayant un serviteur qui laboure ou paît les troupeaux, lui dira, quand il revient des champs: Approche vite, et mets-toi à table?"}, {"numero": 8, "texto": "Ne lui dira-t-il pas au contraire: Prépare-moi à souper, ceins-toi, et sers-moi, jusqu''''à ce que j''''aie mangé et bu; après cela, toi, tu mangeras et boiras?"}, {"numero": 9, "texto": "Doit-il de la reconnaissance à ce serviteur parce qu''''il a fait ce qui lui était ordonné?"}, {"numero": 10, "texto": "Vous de même, quand vous avez fait tout ce qui vous a été ordonné, dites: Nous sommes des serviteurs inutiles, nous avons fait ce que nous devions faire."}, {"numero": 11, "texto": "Jésus, se rendant à Jérusalem, passait entre la Samarie et la Galilée."}, {"numero": 12, "texto": "Comme il entrait dans un village, dix lépreux vinrent à sa rencontre. Se tenant à distance,"}, {"numero": 13, "texto": "ils élevèrent la voix, et dirent: Jésus, maître, aie pitié de nous!"}, {"numero": 14, "texto": "Dès qu''''il les eut vus, il leur dit: Allez vous montrer aux sacrificateurs. Et, pendant qu''''ils y allaient, il arriva qu''''ils furent guéris."}, {"numero": 15, "texto": "L''''un d''''eux, se voyant guéri, revint sur ses pas, glorifiant Dieu à haute voix."}, {"numero": 16, "texto": "Il tomba sur sa face aux pieds de Jésus, et lui rendit grâces. C''''était un Samaritain."}, {"numero": 17, "texto": "Jésus, prenant la parole, dit: Les dix n''''ont-ils pas été guéris? Et les neuf autres, où sont-ils?"}, {"numero": 18, "texto": "Ne s''''est-il trouvé que cet étranger pour revenir et donner gloire à Dieu?"}, {"numero": 19, "texto": "Puis il lui dit: Lève-toi, va; ta foi t''''a sauvé."}, {"numero": 20, "texto": "Les pharisiens demandèrent à Jésus quand viendrait le royaume de Dieu. Il leur répondit: Le royaume de Dieu ne vient pas de manière à frapper les regards."}, {"numero": 21, "texto": "On ne dira point: Il est ici, ou: Il est là. Car voici, le royaume de Dieu est au milieu de vous."}, {"numero": 22, "texto": "Et il dit aux disciples: Des jours viendront où vous désirerez voir l''''un des jours du Fils de l''''homme, et vous ne le verrez point."}, {"numero": 23, "texto": "On vous dira: Il est ici, il est là. N''''y allez pas, ne courez pas après."}, {"numero": 24, "texto": "Car, comme l''''éclair resplendit et brille d''''une extrémité du ciel à l''''autre, ainsi sera le Fils de l''''homme en son jour."}, {"numero": 25, "texto": "Mais il faut auparavant qu''''il souffre beaucoup, et qu''''il soit rejeté par cette génération."}, {"numero": 26, "texto": "Ce qui arriva du temps de Noé arrivera de même aux jours du Fils de l''''homme."}, {"numero": 27, "texto": "Les hommes mangeaient, buvaient, se mariaient et mariaient leurs enfants, jusqu''''au jour où Noé entra dans l''''arche; le déluge vint, et les fit tous périr."}, {"numero": 28, "texto": "Ce qui arriva du temps de Lot arrivera pareillement. Les hommes mangeaient, buvaient, achetaient, vendaient, plantaient, bâtissaient;"}, {"numero": 29, "texto": "mais le jour où Lot sortit de Sodome, une pluie de feu et de soufre tomba du ciel, et les fit tous périr."}, {"numero": 30, "texto": "Il en sera de même le jour où le Fils de l''''homme paraîtra."}, {"numero": 31, "texto": "En ce jour-là, que celui qui sera sur le toit, et qui aura ses effets dans la maison, ne descende pas pour les prendre; et que celui qui sera dans les champs ne retourne pas non plus en arrière."}, {"numero": 32, "texto": "Souvenez-vous de la femme de Lot."}, {"numero": 33, "texto": "Celui qui cherchera à sauver sa vie la perdra, et celui qui la perdra la retrouvera."}, {"numero": 34, "texto": "Je vous le dis, en cette nuit-là, de deux personnes qui seront dans un même lit, l''''une sera prise et l''''autre laissée;"}, {"numero": 35, "texto": "de deux femmes qui moudront ensemble, l''''une sera prise et l''''autre laissée."}, {"numero": 36, "texto": "De deux hommes qui seront dans un champ, l''''un sera pris et l''''autre laissé."}, {"numero": 37, "texto": "Les disciples lui dirent: Où sera-ce, Seigneur? Et il répondit: Où sera le corps, là s''''assembleront les aigles."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 17, 'es', '[{"numero": 1, "texto": "Y Á SUS discípulos dice: Imposible es que no vengan escándalos; mas ¡ay de aquél por quien vienen!"}, {"numero": 2, "texto": "Mejor le fuera, si le pusiesen al cuello una piedra de molino, y le lanzasen en el mar, que escandalizar á uno de estos pequeñitos."}, {"numero": 3, "texto": "Mirad por vosotros: si pecare contra ti tu hermano, repréndele; y si se arrepintiere, perdónale."}, {"numero": 4, "texto": "Y si siete veces al día pecare contra ti, y siete veces al día se volviere á ti, diciendo, pésame, perdónale."}, {"numero": 5, "texto": "Y dijeron los apóstoles al Señor: Auméntanos la fe."}, {"numero": 6, "texto": "Entonces el Señor dijo: Si tuvieseis fe como un grano de mostaza, diréis á este sicómoro: Desarráigate, y plántate en el mar; y os obedecerá."}, {"numero": 7, "texto": "¿Y quién de vosotros tiene un siervo que ara ó apacienta, que vuelto del campo le diga luego: Pasa, siéntate á la mesa?"}, {"numero": 8, "texto": "¿No le dice antes: Adereza qué cene, y arremángate, y sírveme hasta que haya comido y bebido; y después de esto, come tú y bebe?"}, {"numero": 9, "texto": "¿Da gracias al siervo porque hizo lo que le había sido mandado? Pienso que no."}, {"numero": 10, "texto": "Así también vosotros, cuando hubiereis hecho todo lo que os es mandado, decid: Siervos inútiles somos, porque lo que debíamos hacer, hicimos."}, {"numero": 11, "texto": "Y aconteció que yendo él á Jerusalem, pasaba por medio de Samaria y de Galilea."}, {"numero": 12, "texto": "Y entrando en una aldea, viniéronle al encuentro diez hombres leprosos, los cuales se pararon de lejos,"}, {"numero": 13, "texto": "Y alzaron la voz, diciendo: Jesús, Maestro, ten misericordia de nosotros."}, {"numero": 14, "texto": "Y como él los vió, les dijo: Id, mostraos á los sacerdotes. Y aconteció, que yendo ellos, fueron limpios."}, {"numero": 15, "texto": "Entonces uno de ellos, como se vió que estaba limpio, volvió, glorificando á Dios á gran voz;"}, {"numero": 16, "texto": "Y derribóse sobre el rostro á sus pies, dándole gracias: y éste era Samaritano."}, {"numero": 17, "texto": "Y respondiendo Jesús, dijo: ¿No son diez los que fueron limpios? ¿Y los nueve dónde están?"}, {"numero": 18, "texto": "¿No hubo quien volviese y diese gloria á Dios sino este extranjero?"}, {"numero": 19, "texto": "Y díjole: Levántate, vete; tu fe te ha salvado."}, {"numero": 20, "texto": "Y preguntado por los Fariseos, cuándo había de venir el reino de Dios, les respondió y dijo: El reino de Dios no vendrá con advertencia;"}, {"numero": 21, "texto": "Ni dirán: Helo aquí, ó helo allí: porque he aquí el reino de Dios entre vosotros está."}, {"numero": 22, "texto": "Y dijo á sus discípulos: Tiempo vendrá, cuando desearéis ver uno de los días del Hijo del hombre, y no lo veréis."}, {"numero": 23, "texto": "Y os dirán: Helo aquí, ó helo allí. No vayáis, ni sigáis."}, {"numero": 24, "texto": "Porque como el relámpago, relampagueando desde una parte de debajo del cielo, resplandece hasta la otra debajo del cielo, así también será el Hijo del hombre en su día."}, {"numero": 25, "texto": "Mas primero es necesario que padezca mucho, y sea reprobado de esta generación."}, {"numero": 26, "texto": "Y como fué en los días de Noé, así también será en los días del Hijo del hombre."}, {"numero": 27, "texto": "Comían, bebían, los hombres tomaban mujeres, y las mujeres maridos, hasta el día que entró Noé en el arca; y vino el diluvio, y destruyó á todos."}, {"numero": 28, "texto": "Asimismo también como fué en los días de Lot; comían, bebían, compraban, vendían, plantaban, edificaban;"}, {"numero": 29, "texto": "Mas el día que Lot salió de Sodoma, llovió del cielo fuego y azufre, y destruyó á todos:"}, {"numero": 30, "texto": "Como esto será el día en que el Hijo del hombre se manifestará."}, {"numero": 31, "texto": "En aquel día, el que estuviere en el terrado, y sus alhajas en casa, no descienda á tomarlas: y el que en el campo, asimismo no vuelva atrás."}, {"numero": 32, "texto": "Acordaos de la mujer de Lot."}, {"numero": 33, "texto": "Cualquiera que procurare salvar su vida, la perderá; y cualquiera que la perdiere, la salvará."}, {"numero": 34, "texto": "Os digo que en aquella noche estarán dos en una cama; el uno será tomado, y el otro será dejado."}, {"numero": 35, "texto": "Dos mujeres estarán moliendo juntas: la una será tomada, y la otra dejada."}, {"numero": 36, "texto": "Dos estarán en el campo; el uno será tomado, y el otro dejado."}, {"numero": 37, "texto": "Y respondiendo, le dicen: ¿Dónde, Señor? Y él les dijo: Donde estuviere el cuerpo, allá se juntarán también las águilas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 18, 'pt', '[{"numero": 1, "texto": "E [Jesus] lhes disse também uma parábola [sobre] o dever de sempre orar, e nunca se cansar."}, {"numero": 2, "texto": "Dizendo: Havia um certo juiz em uma cidade, que não temia a Deus, nem respeitava pessoa alguma."}, {"numero": 3, "texto": "Havia também naquela mesma cidade uma certa viúva, e vinha até ele, dizendo: Faze-me justiça com meu adversário."}, {"numero": 4, "texto": "E por um [certo] tempo ele não quis; mas depois disto, disse para si: Ainda que eu não tema a Deus, nem respeite pessoa alguma,"}, {"numero": 5, "texto": "Porém, porque esta viúva me incomoda, eu lhe farei justiça, para que ela pare de vir me chatear."}, {"numero": 6, "texto": "E disse o Senhor: Ouvi o que diz o juiz injusto."}, {"numero": 7, "texto": "E Deus não fará justiça para seus escolhidos, que clamam a ele de dia e de noite? Demorará com eles?"}, {"numero": 8, "texto": "Digo-vos que depressa lhes fará justiça. Porém, quando o Filho do homem vier, por acaso ele achará fé na terra?"}, {"numero": 9, "texto": "E disse também a uns, que tinham confiança de si mesmos que eram justos, e desprezavam aos outros, esta parábola:"}, {"numero": 10, "texto": "Dois homens subiram ao Templo para orar, um fariseu, e o outro publicano."}, {"numero": 11, "texto": "O fariseu, estando de pé, orava consigo desta maneira: Ó Deus, eu te agradeço, porque não sou como os outros homens, ladrões, injustos e adúlteros; nem [sou] como este publicano."}, {"numero": 12, "texto": "Jejuo duas vezes por semana, [e] dou dízimo de tudo quanto possuo."}, {"numero": 13, "texto": "E o publicano, estando em pé de longe, nem mesmo queria levantar os olhos ao céu, mas batia em seu peito, dizendo: Ó Deus, tem misericórdia de mim, [que sou] pecador."}, {"numero": 14, "texto": "Digo-vos que este desceu mais justificado à sua casa do que aquele outro; porque qualquer que a si mesmo se exalta, será humilhado; e qualquer que a si mesmo se humilha, será exaltado."}, {"numero": 15, "texto": "E traziam-lhe também crianças pequenas, para que as tocasse; e os discípulos, vendo, os repreendiam."}, {"numero": 16, "texto": "Mas Jesus, chamando-lhes para si, disse: Deixai as crianças virem a mim, e não as impeçais; porque das tais é o Reino de Deus."}, {"numero": 17, "texto": "Em verdade vos digo, que qualquer que não receber o Reino de Deus como criança, não entrará nele."}, {"numero": 18, "texto": "E um certo líder lhe perguntou, dizendo: Bom mestre, o que tenho que fazer para herdar a vida eterna?"}, {"numero": 19, "texto": "E Jesus lhe disse: Por que me chamas de bom? Ninguém [é] bom, a não ser um: Deus."}, {"numero": 20, "texto": "Tu sabes os mandamentos: não adulterarás, não matarás, não furtarás, não darás falso testemunho, honra a teu pai e a tua mãe."}, {"numero": 21, "texto": "E ele disse: Todas estas coisas tenho guardado desde minha juventude."}, {"numero": 22, "texto": "Porém Jesus, ouvindo isto, disse-lhe: Ainda uma coisa te falta: vende tudo quanto tens, e reparte-o entre os pobres, e terás um tesouro no céu; e vem, segue-me."}, {"numero": 23, "texto": "Mas ele, ouvindo isto, ficou muito triste, porque era muito rico."}, {"numero": 24, "texto": "E vendo Jesus que ele tinha ficado muito triste, disse: Como é difícil os que têm [muitos] bens entrarem no Reino de Deus!"}, {"numero": 25, "texto": "Porque é mais fácil um camelo entrar pelo olho de uma agulha do que um rico entrar no Reino de Deus."}, {"numero": 26, "texto": "E os que ouviram [isto] ,disseram: Quem então pode se salvar?"}, {"numero": 27, "texto": "E ele disse: As coisas que são impossíveis para os seres humanos são possíveis para Deus."}, {"numero": 28, "texto": "E Pedro disse: Eis que deixamos tudo, e temos te seguido."}, {"numero": 29, "texto": "E ele lhes disse: Em verdade vos digo, que há ninguém que, tenha deixado casa, ou pais, ou irmãos, ou mulher, ou filhos,"}, {"numero": 30, "texto": "Que não venha a receber de volta muito mais nestes tempos, e nos tempos vindouros [receba] a vida eterna."}, {"numero": 31, "texto": "E tomando consigo aos doze, disse-lhes: Eis que estamos subindo a Jerusalém, e se cumprirá no Filho do homem tudo o que [está] escrito pelos profetas."}, {"numero": 32, "texto": "Porque ele será entregue aos gentios, e escarnecido, injuriado e cuspido."}, {"numero": 33, "texto": "E [depois de] açoitá-lo, o matarão; e ao terceiro dia ressuscitará."}, {"numero": 34, "texto": "E eles nada entendiam destas coisas; e esta palavra lhes era oculta; e não entendiam o que estava sendo lhes dito."}, {"numero": 35, "texto": "E aconteceu que ele, chegando perto de Jericó, estava um cego sentado junto ao caminho, mendigando."}, {"numero": 36, "texto": "E este, ouvindo a multidão passar, perguntou: O que era aquilo?"}, {"numero": 37, "texto": "E disseram-lhe que Jesus Nazareno estava passando."}, {"numero": 38, "texto": "Então clamou, dizendo: Jesus, Filho de Davi, tem misericórdia de mim!"}, {"numero": 39, "texto": "E os que estavam mais a frente o repreendiam, para que calasse; porém ele clamava ainda mais: Filho de Davi, tem misericórdia de mim!"}, {"numero": 40, "texto": "Então Jesus, parando, mandou que o trouxessem para si; e chegando ele, perguntou-lhe,"}, {"numero": 41, "texto": "Dizendo: Que queres que eu te faça?E ele disse: Senhor, que eu veja."}, {"numero": 42, "texto": "E Jesus lhe disse: Vê, tua fé te salvou."}, {"numero": 43, "texto": "E logo ele viu, e o seguia, glorificando a Deus. E o todo o povo, vendo [isto] , dava louvores a Deus."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 18, 'en', '[{"numero": 1, "texto": "And he spake a parable unto them to this end, that men ought always to pray, and not to faint;"}, {"numero": 2, "texto": "Saying, There was in a city a judge, which feared not God, neither regarded man:"}, {"numero": 3, "texto": "And there was a widow in that city; and she came unto him, saying, Avenge me of mine adversary."}, {"numero": 4, "texto": "And he would not for a while: but afterward he said within himself, Though I fear not God, nor regard man;"}, {"numero": 5, "texto": "Yet because this widow troubleth me, I will avenge her, lest by her continual coming she weary me."}, {"numero": 6, "texto": "And the Lord said, Hear what the unjust judge saith."}, {"numero": 7, "texto": "And shall not God avenge his own elect, which cry day and night unto him, though he bear long with them?"}, {"numero": 8, "texto": "I tell you that he will avenge them speedily. Nevertheless when the Son of man cometh, shall he find faith on the earth?"}, {"numero": 9, "texto": "And he spake this parable unto certain which trusted in themselves that they were righteous, and despised others:"}, {"numero": 10, "texto": "Two men went up into the temple to pray; the one a Pharisee, and the other a publican."}, {"numero": 11, "texto": "The Pharisee stood and prayed thus with himself, God, I thank thee, that I am not as other men are, extortioners, unjust, adulterers, or even as this publican."}, {"numero": 12, "texto": "I fast twice in the week, I give tithes of all that I possess."}, {"numero": 13, "texto": "And the publican, standing afar off, would not lift up so much as his eyes unto heaven, but smote upon his breast, saying, God be merciful to me a sinner."}, {"numero": 14, "texto": "I tell you, this man went down to his house justified rather than the other: for every one that exalteth himself shall be abased; and he that humbleth himself shall be exalted."}, {"numero": 15, "texto": "And they brought unto him also infants, that he would touch them: but when his disciples saw it, they rebuked them."}, {"numero": 16, "texto": "But Jesus called them unto him, and said, Suffer little children to come unto me, and forbid them not: for of such is the kingdom of God."}, {"numero": 17, "texto": "Verily I say unto you, Whosoever shall not receive the kingdom of God as a little child shall in no wise enter therein."}, {"numero": 18, "texto": "And a certain ruler asked him, saying, Good Master, what shall I do to inherit eternal life?"}, {"numero": 19, "texto": "And Jesus said unto him, Why callest thou me good? none is good, save one, that is, God."}, {"numero": 20, "texto": "Thou knowest the commandments, Do not commit adultery, Do not kill, Do not steal, Do not bear false witness, Honour thy father and thy mother."}, {"numero": 21, "texto": "And he said, All these have I kept from my youth up."}, {"numero": 22, "texto": "Now when Jesus heard these things, he said unto him, Yet lackest thou one thing: sell all that thou hast, and distribute unto the poor, and thou shalt have treasure in heaven: and come, follow me."}, {"numero": 23, "texto": "And when he heard this, he was very sorrowful: for he was very rich."}, {"numero": 24, "texto": "And when Jesus saw that he was very sorrowful, he said, How hardly shall they that have riches enter into the kingdom of God!"}, {"numero": 25, "texto": "For it is easier for a camel to go through a needle''s eye, than for a rich man to enter into the kingdom of God."}, {"numero": 26, "texto": "And they that heard it said, Who then can be saved?"}, {"numero": 27, "texto": "And he said, The things which are impossible with men are possible with God."}, {"numero": 28, "texto": "Then Peter said, Lo, we have left all, and followed thee."}, {"numero": 29, "texto": "And he said unto them, Verily I say unto you, There is no man that hath left house, or parents, or brethren, or wife, or children, for the kingdom of God''s sake,"}, {"numero": 30, "texto": "Who shall not receive manifold more in this present time, and in the world to come life everlasting."}, {"numero": 31, "texto": "Then he took unto him the twelve, and said unto them, Behold, we go up to Jerusalem, and all things that are written by the prophets concerning the Son of man shall be accomplished."}, {"numero": 32, "texto": "For he shall be delivered unto the Gentiles, and shall be mocked, and spitefully entreated, and spitted on:"}, {"numero": 33, "texto": "And they shall scourge him, and put him to death: and the third day he shall rise again."}, {"numero": 34, "texto": "And they understood none of these things: and this saying was hid from them, neither knew they the things which were spoken."}, {"numero": 35, "texto": "And it came to pass, that as he was come nigh unto Jericho, a certain blind man sat by the way side begging:"}, {"numero": 36, "texto": "And hearing the multitude pass by, he asked what it meant."}, {"numero": 37, "texto": "And they told him, that Jesus of Nazareth passeth by."}, {"numero": 38, "texto": "And he cried, saying, Jesus, thou son of David, have mercy on me."}, {"numero": 39, "texto": "And they which went before rebuked him, that he should hold his peace: but he cried so much the more, Thou son of David, have mercy on me."}, {"numero": 40, "texto": "And Jesus stood, and commanded him to be brought unto him: and when he was come near, he asked him,"}, {"numero": 41, "texto": "Saying, What wilt thou that I shall do unto thee? And he said, Lord, that I may receive my sight."}, {"numero": 42, "texto": "And Jesus said unto him, Receive thy sight: thy faith hath saved thee."}, {"numero": 43, "texto": "And immediately he received his sight, and followed him, glorifying God: and all the people, when they saw it, gave praise unto God."}]'::jsonb, 'King James Version'),
  ('Lc', 18, 'fr', '[{"numero": 1, "texto": "Jésus leur adressa une parabole, pour montrer qu''''il faut toujours prier, et ne point se relâcher."}, {"numero": 2, "texto": "Il dit: Il y avait dans une ville un juge qui ne craignait point Dieu et qui n''''avait d''''égard pour personne."}, {"numero": 3, "texto": "Il y avait aussi dans cette ville une veuve qui venait lui dire: Fais-moi justice de ma partie adverse."}, {"numero": 4, "texto": "Pendant longtemps il refusa. Mais ensuite il dit en lui-même: Quoique je ne craigne point Dieu et que je n''''aie d''''égard pour personne,"}, {"numero": 5, "texto": "néanmoins, parce que cette veuve m''''importune, je lui ferai justice, afin qu''''elle ne vienne pas sans cesse me rompre la tête."}, {"numero": 6, "texto": "Le Seigneur ajouta: Entendez ce que dit le juge inique."}, {"numero": 7, "texto": "Et Dieu ne fera-t-il pas justice à ses élus, qui crient à lui jour et nuit, et tardera-t-il à leur égard?"}, {"numero": 8, "texto": "Je vous le dis, il leur fera promptement justice. Mais, quand le Fils de l''''homme viendra, trouvera-t-il la foi sur la terre?"}, {"numero": 9, "texto": "Il dit encore cette parabole, en vue de certaines personnes se persuadant qu''''elles étaient justes, et ne faisant aucun cas des autres:"}, {"numero": 10, "texto": "Deux hommes montèrent au temple pour prier; l''''un était pharisien, et l''''autre publicain."}, {"numero": 11, "texto": "Le pharisien, debout, priait ainsi en lui-même: O Dieu, je te rends grâces de ce que je ne suis pas comme le reste des hommes, qui sont ravisseurs, injustes, adultères, ou même comme ce publicain;"}, {"numero": 12, "texto": "je jeûne deux fois la semaine, je donne la dîme de tous mes revenus."}, {"numero": 13, "texto": "Le publicain, se tenant à distance, n''''osait même pas lever les yeux au ciel; mais il se frappait la poitrine, en disant: O Dieu, sois apaisé envers moi, qui suis un pécheur."}, {"numero": 14, "texto": "Je vous le dis, celui-ci descendit dans sa maison justifié, plutôt que l''''autre. Car quiconque s''''élève sera abaissé, et celui qui s''''abaisse sera élevé."}, {"numero": 15, "texto": "On lui amena aussi les petits enfants, afin qu''''il les touchât. Mais les disciples, voyant cela, reprenaient ceux qui les amenaient."}, {"numero": 16, "texto": "Et Jésus les appela, et dit: Laissez venir à moi les petits enfants, et ne les en empêchez pas; car le royaume de Dieu est pour ceux qui leur ressemblent."}, {"numero": 17, "texto": "Je vous le dis en vérité, quiconque ne recevra pas le royaume de Dieu comme un petit enfant n''''y entrera point."}, {"numero": 18, "texto": "Un chef interrogea Jésus, et dit: Bon maître, que dois-je faire pour hériter la vie éternelle?"}, {"numero": 19, "texto": "Jésus lui répondit: Pourquoi m''''appelles-tu bon? Il n''''y a de bon que Dieu seul."}, {"numero": 20, "texto": "Tu connais les commandements: Tu ne commettras point d''''adultère; tu ne tueras point; tu ne déroberas point; tu ne diras point de faux témoignage; honore ton père et ta mère."}, {"numero": 21, "texto": "J''''ai, dit-il, observé toutes ces choses dès ma jeunesse."}, {"numero": 22, "texto": "Jésus, ayant entendu cela, lui dit: Il te manque encore une chose: vends tout ce que tu as, distribue- le aux pauvres, et tu auras un trésor dans les cieux. Puis, viens, et suis-moi."}, {"numero": 23, "texto": "Lorsqu''''il entendit ces paroles, il devint tout triste; car il était très riche."}, {"numero": 24, "texto": "Jésus, voyant qu''''il était devenu tout triste, dit: Qu''''il est difficile à ceux qui ont des richesses d''''entrer dans le royaume de Dieu!"}, {"numero": 25, "texto": "Car il est plus facile à un chameau de passer par le trou d''''une aiguille qu''''à un riche d''''entrer dans le royaume de Dieu."}, {"numero": 26, "texto": "Ceux qui l''''écoutaient dirent: Et qui peut être sauvé?"}, {"numero": 27, "texto": "Jésus répondit: Ce qui est impossible aux hommes est possible à Dieu."}, {"numero": 28, "texto": "Pierre dit alors: Voici, nous avons tout quitté, et nous t''''avons suivi."}, {"numero": 29, "texto": "Et Jésus leur dit: Je vous le dis en vérité, il n''''est personne qui, ayant quitté, à cause du royaume de Dieu, sa maison, ou sa femme, ou ses frères, ou ses parents, ou ses enfants,"}, {"numero": 30, "texto": "ne reçoive beaucoup plus dans ce siècle-ci, et, dans le siècle à venir, la vie éternelle."}, {"numero": 31, "texto": "Jésus prit les douze auprès de lui, et leur dit: Voici, nous montons à Jérusalem, et tout ce qui a été écrit par les prophètes au sujet du Fils de l''''homme s''''accomplira."}, {"numero": 32, "texto": "Car il sera livré aux païens; on se moquera de lui, on l''''outragera, on crachera sur lui,"}, {"numero": 33, "texto": "et, après l''''avoir battu de verges, on le fera mourir; et le troisième jour il ressuscitera."}, {"numero": 34, "texto": "Mais ils ne comprirent rien à cela; c''''était pour eux un langage caché, des paroles dont ils ne saisissaient pas le sens."}, {"numero": 35, "texto": "Comme Jésus approchait de Jéricho, un aveugle était assis au bord du chemin, et mendiait."}, {"numero": 36, "texto": "Entendant la foule passer, il demanda ce que c''''était."}, {"numero": 37, "texto": "On lui dit: C''''est Jésus de Nazareth qui passe."}, {"numero": 38, "texto": "Et il cria: Jésus, Fils de David, aie pitié de moi!"}, {"numero": 39, "texto": "Ceux qui marchaient devant le reprenaient, pour le faire taire; mais il criait beaucoup plus fort: Fils de David, aie pitié de moi!"}, {"numero": 40, "texto": "Jésus, s''''étant arrêté, ordonna qu''''on le lui amène; et, quand il se fut approché, il lui demanda:"}, {"numero": 41, "texto": "Que veux-tu que je te fasse? Il répondit: Seigneur, que je recouvre la vue."}, {"numero": 42, "texto": "Et Jésus lui dit: Recouvre la vue; ta foi t''''a sauvé."}, {"numero": 43, "texto": "A l''''instant il recouvra la vue, et suivit Jésus, en glorifiant Dieu. Tout le peuple, voyant cela, loua Dieu."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 18, 'es', '[{"numero": 1, "texto": "Y PROPÚSOLES también una parábola sobre que es necesario orar siempre, y no desmayar,"}, {"numero": 2, "texto": "Diciendo: Había un juez en una ciudad, el cual ni temía á Dios, ni respetaba á hombre."}, {"numero": 3, "texto": "Había también en aquella ciudad una viuda, la cual venía á él diciendo: Hazme justicia de mi adversario."}, {"numero": 4, "texto": "Pero él no quiso por algún tiempo; mas después de esto dijo dentro de sí: Aunque ni temo á Dios, ni tengo respeto á hombre,"}, {"numero": 5, "texto": "Todavía, porque esta viuda me es molesta, le haré justicia, porque al fin no venga y me muela."}, {"numero": 6, "texto": "Y dijo el Señor: Oid lo que dice el juez injusto."}, {"numero": 7, "texto": "¿Y Dios no hará justicia á sus escogidos, que claman á él día y noche, aunque sea longánime acerca de ellos?"}, {"numero": 8, "texto": "Os digo que los defenderá presto. Empero cuando el Hijo del hombre viniere, ¿hallará fe en la tierra?"}, {"numero": 9, "texto": "Y dijo también á unos que confiaban de sí como justos, y menospreciaban á los otros, esta parábola:"}, {"numero": 10, "texto": "Dos hombres subieron al templo á orar: el uno Fariseo, el otro publicano."}, {"numero": 11, "texto": "El Fariseo, en pie, oraba consigo de esta manera: Dios, te doy gracias, que no soy como los otros hombres, ladrones, injustos, adúlteros, ni aun como este publicano;"}, {"numero": 12, "texto": "Ayuno dos veces á la semana, doy diezmos de todo lo que poseo."}, {"numero": 13, "texto": "Mas el publicano estando lejos no quería ni aun alzar los ojos al cielo, sino que hería su pecho, diciendo: Dios, sé propicio á mí pecador."}, {"numero": 14, "texto": "Os digo que éste descendió á su casa justificado antes que el otro; porque cualquiera que se ensalza, será humillado; y el que se humilla, será ensalzado."}, {"numero": 15, "texto": "Y traían á él los niños para que los tocase; lo cual viendo los discípulos les reñían."}, {"numero": 16, "texto": "Mas Jesús llamándolos, dijo: Dejad los niños venir á mí, y no los impidáis; porque de tales es el reino de Dios."}, {"numero": 17, "texto": "De cierto os digo, que cualquiera que no recibiere el reino de Dios como un niño, no entrará en él."}, {"numero": 18, "texto": "Y preguntóle un príncipe, diciendo: Maestro bueno, ¿qué haré para poseer la vida eterna?"}, {"numero": 19, "texto": "Y Jesús le dijo: ¿Por qué me llamas bueno? ninguno hay bueno sino sólo Dios."}, {"numero": 20, "texto": "Los mandamientos sabes: No matarás: No adulterarás: No hurtarás: No dirás falso testimonio: Honra á tu padre y á tu madre."}, {"numero": 21, "texto": "Y él dijo: Todas estas cosas he guardado desde mi juventud."}, {"numero": 22, "texto": "Y Jesús, oído esto, le dijo: Aun te falta una cosa: vende todo lo que tienes, y da á los pobres, y tendrás tesoro en el cielo; y ven, sígueme."}, {"numero": 23, "texto": "Entonces él, oídas estas cosas, se puso muy triste, porque era muy rico."}, {"numero": 24, "texto": "Y viendo Jesús que se había entristecido mucho, dijo: ¡Cuán dificultosamente entrarán en el reino de Dios los que tienen riquezas!"}, {"numero": 25, "texto": "Porque más fácil cosa es entrar un camello por el ojo de una aguja, que un rico entrar en el reino de Dios."}, {"numero": 26, "texto": "Y los que lo oían, dijeron: ¿Y quién podrá ser salvo?"}, {"numero": 27, "texto": "Y él les dijo: Lo que es imposible para con los hombres, posible es para Dios."}, {"numero": 28, "texto": "Entonces Pedro dijo: He aquí, nosotros hemos dejado las posesiones nuestras, y te hemos seguido."}, {"numero": 29, "texto": "Y él les dijo: De cierto os digo, que nadie hay que haya dejado casa, padres, ó hermanos, ó mujer, ó hijos, por el reino de Dios,"}, {"numero": 30, "texto": "Que no haya de recibir mucho más en este tiempo, y en el siglo venidero la vida eterna."}, {"numero": 31, "texto": "Y Jesús, tomando á los doce, les dijo: He aquí subimos á Jerusalem, y serán cumplidas todas las cosas que fueron escritas por los profetas, del Hijo del hombre."}, {"numero": 32, "texto": "Porque será entregado á las gentes, y será escarnecido, é injuriado, y escupido."}, {"numero": 33, "texto": "Y después que le hubieren azotado, le matarán: mas al tercer día resucitará."}, {"numero": 34, "texto": "Pero ellos nada de estas cosas entendían, y esta palabra les era encubierta, y no entendían lo que se decía."}, {"numero": 35, "texto": "Y aconteció que acercándose él á Jericó, un ciego estaba sentado junto al camino mendigando;"}, {"numero": 36, "texto": "El cual como oyó la gente que pasaba, preguntó qué era aquello."}, {"numero": 37, "texto": "Y dijéronle que pasaba Jesús Nazareno."}, {"numero": 38, "texto": "Entonces dió voces, diciendo: Jesús, Hijo de David, ten misericordia de mí."}, {"numero": 39, "texto": "Y los que iban delante, le reñían que callase; mas él clamaba mucho más: Hijo de David, ten misericordia de mí."}, {"numero": 40, "texto": "Jesús entonces parándose, mandó traerle á sí: y como él llegó, le preguntó,"}, {"numero": 41, "texto": "Diciendo: ¿Qué quieres que te haga? Y él dijo: Señor, que vea."}, {"numero": 42, "texto": "Y Jesús le dijo: Ve, tu fe te ha hecho salvo."}, {"numero": 43, "texto": "Y luego vió, y le seguía, glorificando á Dios: y todo el pueblo como lo vió, dió á Dios alabanza."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 19, 'pt', '[{"numero": 1, "texto": "E [Jesus] entrou e foi passando por Jericó."}, {"numero": 2, "texto": "E eis que havia ali um homem, chamado pelo nome de Zaqueu, e este era chefe dos publicanos, e era rico."}, {"numero": 3, "texto": "E procurava ver quem era Jesus, e não podia, por causa da multidão, pois era pequeno de altura."}, {"numero": 4, "texto": "E correndo com antecedência, subiu em uma árvore de frutos que parecem figos, para o ver; porque ele passaria por ali."}, {"numero": 5, "texto": "E quando Jesus chegou a aquele lugar, olhando para cima, o viu, e disse-lhe: Zaqueu, apressa-te, e desce; porque hoje é necessário que eu fique em tua casa."}, {"numero": 6, "texto": "E apressando-se, desceu, e o recebeu com alegria."}, {"numero": 7, "texto": "E todos, vendo [isto] , murmuravam, dizendo: Ele entrou para se hospedar com um homem pecador."}, {"numero": 8, "texto": "E Zaqueu, levantando-se, disse ao Senhor: Senhor, eis que dou a metade de meus bens aos pobres; e se eu consegui algo enganando a alguém, eu [o] devolvo quatro vezes mais."}, {"numero": 9, "texto": "E Jesus lhe disse: Hoje houve salvação nesta casa, porque ele também é filho de Abraão."}, {"numero": 10, "texto": "Porque o Filho do homem veio para buscar, e para salvar o que tinha se perdido."}, {"numero": 11, "texto": "E ouvindo eles estas coisas, [Jesus] prosseguiu, e disse uma parábola, porque estava perto de Jerusalém, e pensavam que logo o Reino seria manifesto."}, {"numero": 12, "texto": "Disse, pois: Um certo homem nobre partiu para uma terra distante."}, {"numero": 13, "texto": "E chamando dez servos seus, deu-lhes dez minas, e disse-lhes: Investi até que eu venha;"}, {"numero": 14, "texto": "E seus cidadãos o odiavam; e mandaram representantes depois dele, dizendo: Não queremos que este reine sobre nós."}, {"numero": 15, "texto": "E aconteceu que, quando ele voltou, tendo tomado o reino, disse que lhe chamassem a aqueles servos, a quem tinha dado o dinheiro, para saber o que cada um tinha ganho fazendo investimentos."}, {"numero": 16, "texto": "E veio o primeiro, dizendo: Senhor, tua mina rendeu outras dez minas."}, {"numero": 17, "texto": "E ele lhe disse: Ótimo, bom servo! Por teres sido fiel no pouco, terás autoridade sobre dez cidades."}, {"numero": 18, "texto": "E veio o segundo, dizendo: Senhor, tua mina rendeu cinco minas."}, {"numero": 19, "texto": "E disse também a este: E tu [governarás] cinco cidades."}, {"numero": 20, "texto": "E veio outro, dizendo: Eis aqui tua mina, que guardei em um lenço."}, {"numero": 21, "texto": "Porque tive medo de ti, que és um homem rigoroso, que tomas o que não puseste, e colhes o que não semeaste."}, {"numero": 22, "texto": "Porém ele lhe disse: Servo mau, por tua boca eu te julgarei; tu sabias que eu era um homem rigoroso, que tomo o que não pus, e que colho o que não semeei;"}, {"numero": 23, "texto": "Por que, então, não puseste meu dinheiro no banco; e quando eu viesse, o receberia de volta com juros?"}, {"numero": 24, "texto": "E disse aos que estavam com ele: Tirai-lhe a mina, e dai-a ao que tem as dez minas."}, {"numero": 25, "texto": "E eles lhe disseram: Senhor, ele [já] tem dez minas."}, {"numero": 26, "texto": "[O senhor respondeu:] Porque eu vos digo, que todo aquele que tiver, lhe será dado; mas ao que não tiver, até o que tem, lhe será tirado."}, {"numero": 27, "texto": "Porém a aqueles meus inimigos, que não quiseram que eu reinasse sobre eles, trazei [- os] aqui, e matai [-os] diante de mim."}, {"numero": 28, "texto": "E dito isto, ele foi caminhando adiante, subindo para Jerusalém."}, {"numero": 29, "texto": "E aconteceu que, chegando perto de Betfagé, e de Betânia, ao monte chamado das Oliveiras, mandou a dois de seus discípulos,"}, {"numero": 30, "texto": "Dizendo: Ide à aldeia que está em frente; onde, ao entrardes, achareis um potro atado, em que ninguém jamais se sentou; soltai-o, e trazei [-o] ."}, {"numero": 31, "texto": "E se alguém vos perguntar: Por que [o] soltais? Direis assim a ele: Porque o Senhor precisa dele."}, {"numero": 32, "texto": "E indo os que tinham sido mandados, acharam como lhes disse:"}, {"numero": 33, "texto": "E soltando o potro, seus donos lhe disseram: Por que soltais o potro?"}, {"numero": 34, "texto": "E eles disseram: O Senhor precisa dele."}, {"numero": 35, "texto": "E o trouxeram a Jesus; e lançando suas roupas sobre o potro, puseram Jesus montado nele."}, {"numero": 36, "texto": "E indo ele andando, estendiam suas roupas pelo caminho."}, {"numero": 37, "texto": "E quando já chegava perto da descida do monte das Oliveiras, toda a multidão de discípulos, com alegria começou a louvar a Deus em alta voz, por todas as maravilhas que tinham visto,"}, {"numero": 38, "texto": "Dizendo: Bendito o Rei que vem em nome do Senhor; paz no céu, e glória nas alturas."}, {"numero": 39, "texto": "E alguns dos fariseus da multidão lhe disseram: Mestre, repreende a teus discípulos."}, {"numero": 40, "texto": "E respondendo ele, disse-lhes: Digo-vos, que se estes se calarem, as pedras clamariam."}, {"numero": 41, "texto": "E quando já estava chegando, viu a cidade, e chorou por causa dela,"}, {"numero": 42, "texto": "Dizendo: Ah, se tu também conhecesses, pelo menos neste teu dia, aquilo que lhe traria paz! Mas agora [isto] está escondido de teus olhos."}, {"numero": 43, "texto": "Porque dias virão sobre ti, em que teus inimigos lhe cercarão com barricadas, e ao redor te sitiarão, e lhe pressionarão por todos os lados."}, {"numero": 44, "texto": "E derrubarão a ti, e a teus filhos; e não deixarão em ti pedra sobre pedra, porque não conheceste o tempo em que foste visitada."}, {"numero": 45, "texto": "E entrando no Templo, começou a expulsar a todos os que vendiam e compravam ali,"}, {"numero": 46, "texto": "Dizendo-lhes: Está escrito: Minha casa é casa de oração; Mas vós a tendes feito um esconderijo de ladrões."}, {"numero": 47, "texto": "E ensinava diariamente no Templo; e os chefes dos sacerdotes, e os escribas, e os chefes do povo, procuravam matá-lo."}, {"numero": 48, "texto": "E não achavam como fazer, porque todo o povo o ouvia com muita atenção."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 19, 'en', '[{"numero": 1, "texto": "And Jesus entered and passed through Jericho."}, {"numero": 2, "texto": "And, behold, there was a man named Zacchaeus, which was the chief among the publicans, and he was rich."}, {"numero": 3, "texto": "And he sought to see Jesus who he was; and could not for the press, because he was little of stature."}, {"numero": 4, "texto": "And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way."}, {"numero": 5, "texto": "And when Jesus came to the place, he looked up, and saw him, and said unto him, Zacchaeus, make haste, and come down; for to day I must abide at thy house."}, {"numero": 6, "texto": "And he made haste, and came down, and received him joyfully."}, {"numero": 7, "texto": "And when they saw it, they all murmured, saying, That he was gone to be guest with a man that is a sinner."}, {"numero": 8, "texto": "And Zacchaeus stood, and said unto the Lord: Behold, Lord, the half of my goods I give to the poor; and if I have taken any thing from any man by false accusation, I restore him fourfold."}, {"numero": 9, "texto": "And Jesus said unto him, This day is salvation come to this house, forsomuch as he also is a son of Abraham."}, {"numero": 10, "texto": "For the Son of man is come to seek and to save that which was lost."}, {"numero": 11, "texto": "And as they heard these things, he added and spake a parable, because he was nigh to Jerusalem, and because they thought that the kingdom of God should immediately appear."}, {"numero": 12, "texto": "He said therefore, A certain nobleman went into a far country to receive for himself a kingdom, and to return."}, {"numero": 13, "texto": "And he called his ten servants, and delivered them ten pounds, and said unto them, Occupy till I come."}, {"numero": 14, "texto": "But his citizens hated him, and sent a message after him, saying, We will not have this man to reign over us."}, {"numero": 15, "texto": "And it came to pass, that when he was returned, having received the kingdom, then he commanded these servants to be called unto him, to whom he had given the money, that he might know how much every man had gained by trading."}, {"numero": 16, "texto": "Then came the first, saying, Lord, thy pound hath gained ten pounds."}, {"numero": 17, "texto": "And he said unto him, Well, thou good servant: because thou hast been faithful in a very little, have thou authority over ten cities."}, {"numero": 18, "texto": "And the second came, saying, Lord, thy pound hath gained five pounds."}, {"numero": 19, "texto": "And he said likewise to him, Be thou also over five cities."}, {"numero": 20, "texto": "And another came, saying, Lord, behold, here is thy pound, which I have kept laid up in a napkin:"}, {"numero": 21, "texto": "For I feared thee, because thou art an austere man: thou takest up that thou layedst not down, and reapest that thou didst not sow."}, {"numero": 22, "texto": "And he saith unto him, Out of thine own mouth will I judge thee, thou wicked servant. Thou knewest that I was an austere man, taking up that I laid not down, and reaping that I did not sow:"}, {"numero": 23, "texto": "Wherefore then gavest not thou my money into the bank, that at my coming I might have required mine own with usury?"}, {"numero": 24, "texto": "And he said unto them that stood by, Take from him the pound, and give it to him that hath ten pounds."}, {"numero": 25, "texto": "(And they said unto him, Lord, he hath ten pounds.)"}, {"numero": 26, "texto": "For I say unto you, That unto every one which hath shall be given; and from him that hath not, even that he hath shall be taken away from him."}, {"numero": 27, "texto": "But those mine enemies, which would not that I should reign over them, bring hither, and slay them before me."}, {"numero": 28, "texto": "And when he had thus spoken, he went before, ascending up to Jerusalem."}, {"numero": 29, "texto": "And it came to pass, when he was come nigh to Bethphage and Bethany, at the mount called the mount of Olives, he sent two of his disciples,"}, {"numero": 30, "texto": "Saying, Go ye into the village over against you; in the which at your entering ye shall find a colt tied, whereon yet never man sat: loose him, and bring him hither."}, {"numero": 31, "texto": "And if any man ask you, Why do ye loose him? thus shall ye say unto him, Because the Lord hath need of him."}, {"numero": 32, "texto": "And they that were sent went their way, and found even as he had said unto them."}, {"numero": 33, "texto": "And as they were loosing the colt, the owners thereof said unto them, Why loose ye the colt?"}, {"numero": 34, "texto": "And they said, The Lord hath need of him."}, {"numero": 35, "texto": "And they brought him to Jesus: and they cast their garments upon the colt, and they set Jesus thereon."}, {"numero": 36, "texto": "And as he went, they spread their clothes in the way."}, {"numero": 37, "texto": "And when he was come nigh, even now at the descent of the mount of Olives, the whole multitude of the disciples began to rejoice and praise God with a loud voice for all the mighty works that they had seen;"}, {"numero": 38, "texto": "Saying, Blessed be the King that cometh in the name of the Lord: peace in heaven, and glory in the highest."}, {"numero": 39, "texto": "And some of the Pharisees from among the multitude said unto him, Master, rebuke thy disciples."}, {"numero": 40, "texto": "And he answered and said unto them, I tell you that, if these should hold their peace, the stones would immediately cry out."}, {"numero": 41, "texto": "And when he was come near, he beheld the city, and wept over it,"}, {"numero": 42, "texto": "Saying, If thou hadst known, even thou, at least in this thy day, the things which belong unto thy peace! but now they are hid from thine eyes."}, {"numero": 43, "texto": "For the days shall come upon thee, that thine enemies shall cast a trench about thee, and compass thee round, and keep thee in on every side,"}, {"numero": 44, "texto": "And shall lay thee even with the ground, and thy children within thee; and they shall not leave in thee one stone upon another; because thou knewest not the time of thy visitation."}, {"numero": 45, "texto": "And he went into the temple, and began to cast out them that sold therein, and them that bought;"}, {"numero": 46, "texto": "Saying unto them, It is written, My house is the house of prayer: but ye have made it a den of thieves."}, {"numero": 47, "texto": "And he taught daily in the temple. But the chief priests and the scribes and the chief of the people sought to destroy him,"}, {"numero": 48, "texto": "And could not find what they might do: for all the people were very attentive to hear him."}]'::jsonb, 'King James Version'),
  ('Lc', 19, 'fr', '[{"numero": 1, "texto": "Jésus, étant entré dans Jéricho, traversait la ville."}, {"numero": 2, "texto": "Et voici, un homme riche, appelé Zachée, chef des publicains,"}, {"numero": 3, "texto": "cherchait à voir qui était Jésus; mais il ne pouvait y parvenir, à cause de la foule, car il était de petite taille."}, {"numero": 4, "texto": "Il courut en avant, et monta sur un sycomore pour le voir, parce qu''''il devait passer par là."}, {"numero": 5, "texto": "Lorsque Jésus fut arrivé à cet endroit, il leva les yeux et lui dit: Zachée, hâte-toi de descendre; car il faut que je demeure aujourd''''hui dans ta maison."}, {"numero": 6, "texto": "Zachée se hâta de descendre, et le reçut avec joie."}, {"numero": 7, "texto": "Voyant cela, tous murmuraient, et disaient: Il est allé loger chez un homme pécheur."}, {"numero": 8, "texto": "Mais Zachée, se tenant devant le Seigneur, lui dit: Voici, Seigneur, je donne aux pauvres la moitié de mes biens, et, si j''''ai fait tort de quelque chose à quelqu''''un, je lui rends le quadruple."}, {"numero": 9, "texto": "Jésus lui dit: Le salut est entré aujourd''''hui dans cette maison, parce que celui-ci est aussi un fils d''''Abraham."}, {"numero": 10, "texto": "Car le Fils de l''''homme est venu chercher et sauver ce qui était perdu."}, {"numero": 11, "texto": "Ils écoutaient ces choses, et Jésus ajouta une parabole, parce qu''''il était près de Jérusalem, et qu''''on croyait qu''''à l''''instant le royaume de Dieu allait paraître."}, {"numero": 12, "texto": "Il dit donc: Un homme de haute naissance s''''en alla dans un pays lointain, pour se faire investir de l''''autorité royale, et revenir ensuite."}, {"numero": 13, "texto": "Il appela dix de ses serviteurs, leur donna dix mines, et leur dit: Faites-les valoir jusqu''''à ce que je revienne."}, {"numero": 14, "texto": "Mais ses concitoyens le haïssaient, et ils envoyèrent une ambassade après lui, pour dire: Nous ne voulons pas que cet homme règne sur nous."}, {"numero": 15, "texto": "Lorsqu''''il fut de retour, après avoir été investi de l''''autorité royale, il fit appeler auprès de lui les serviteurs auxquels il avait donné l''''argent, afin de connaître comment chacun l''''avait fait valoir."}, {"numero": 16, "texto": "Le premier vint, et dit: Seigneur, ta mine a rapporté dix mines."}, {"numero": 17, "texto": "Il lui dit: C''''est bien, bon serviteur; parce que tu as été fidèle en peu de chose, reçois le gouvernement de dix villes."}, {"numero": 18, "texto": "Le second vint, et dit: Seigneur, ta mine a produit cinq mines."}, {"numero": 19, "texto": "Il lui dit: Toi aussi, sois établi sur cinq villes."}, {"numero": 20, "texto": "Un autre vint, et dit: Seigneur, voici ta mine, que j''''ai gardée dans un linge;"}, {"numero": 21, "texto": "car j''''avais peur de toi, parce que tu es un homme sévère; tu prends ce que tu n''''as pas déposé, et tu moissonnes ce que tu n''''as pas semé."}, {"numero": 22, "texto": "Il lui dit: Je te juge sur tes paroles, méchant serviteur; tu savais que je suis un homme sévère, prenant ce que je n''''ai pas déposé, et moissonnant ce que je n''''ai pas semé;"}, {"numero": 23, "texto": "pourquoi donc n''''as-tu pas mis mon argent dans une banque, afin qu''''à mon retour je le retirasse avec un intérêt?"}, {"numero": 24, "texto": "Puis il dit à ceux qui étaient là: Otez-lui la mine, et donnez-la à celui qui a les dix mines."}, {"numero": 25, "texto": "Ils lui dirent: Seigneur, il a dix mines. -"}, {"numero": 26, "texto": "Je vous le dis, on donnera à celui qui a, mais à celui qui n''''a pas on ôtera même ce qu''''il a."}, {"numero": 27, "texto": "Au reste, amenez ici mes ennemis, qui n''''ont pas voulu que je régnasse sur eux, et tuez-les en ma présence."}, {"numero": 28, "texto": "Après avoir ainsi parlé, Jésus marcha devant la foule, pour monter à Jérusalem."}, {"numero": 29, "texto": "Lorsqu''''il approcha de Bethphagé et de Béthanie, vers la montagne appelée montagne des oliviers, Jésus envoya deux de ses disciples,"}, {"numero": 30, "texto": "en disant: Allez au village qui est en face; quand vous y serez entrés, vous trouverez un ânon attaché, sur lequel aucun homme ne s''''est jamais assis; détachez-le, et amenez-le."}, {"numero": 31, "texto": "Si quelqu''''un vous demande: Pourquoi le détachez-vous? vous lui répondrez: Le Seigneur en a besoin."}, {"numero": 32, "texto": "Ceux qui étaient envoyés allèrent, et trouvèrent les choses comme Jésus leur avait dit."}, {"numero": 33, "texto": "Comme ils détachaient l''''ânon, ses maîtres leur dirent: Pourquoi détachez-vous l''''ânon?"}, {"numero": 34, "texto": "Ils répondirent: Le Seigneur en a besoin."}, {"numero": 35, "texto": "Et ils amenèrent à Jésus l''''ânon, sur lequel ils jetèrent leurs vêtements, et firent monter Jésus."}, {"numero": 36, "texto": "Quand il fut en marche, les gens étendirent leurs vêtements sur le chemin."}, {"numero": 37, "texto": "Et lorsque déjà il approchait de Jérusalem, vers la descente de la montagne des oliviers, toute la multitude des disciples, saisie de joie, se mit à louer Dieu à haute voix pour tous les miracles qu''''ils avaient vus."}, {"numero": 38, "texto": "Ils disaient: Béni soit le roi qui vient au nom du Seigneur! Paix dans le ciel, et gloire dans les lieux très hauts!"}, {"numero": 39, "texto": "Quelques pharisiens, du milieu de la foule, dirent à Jésus: Maître, reprends tes disciples."}, {"numero": 40, "texto": "Et il répondit: Je vous le dis, s''''ils se taisent, les pierres crieront!"}, {"numero": 41, "texto": "Comme il approchait de la ville, Jésus, en la voyant, pleura sur elle,"}, {"numero": 42, "texto": "et dit: Si toi aussi, au moins en ce jour qui t''''est donné, tu connaissais les choses qui appartiennent à ta paix! Mais maintenant elles sont cachées à tes yeux."}, {"numero": 43, "texto": "Il viendra sur toi des jours où tes ennemis t''''environneront de tranchées, t''''enfermeront, et te serreront de toutes parts;"}, {"numero": 44, "texto": "ils te détruiront, toi et tes enfants au milieu de toi, et ils ne laisseront pas en toi pierre sur pierre, parce que tu n''''as pas connu le temps où tu as été visitée."}, {"numero": 45, "texto": "Il entra dans le temple, et il se mit à chasser ceux qui vendaient,"}, {"numero": 46, "texto": "leur disant: Il est écrit: Ma maison sera une maison de prière. Mais vous, vous en avez fait une caverne de voleurs."}, {"numero": 47, "texto": "Il enseignait tous les jours dans le temple. Et les principaux sacrificateurs, les scribes, et les principaux du peuple cherchaient à le faire périr;"}, {"numero": 48, "texto": "mais ils ne savaient comment s''''y prendre, car tout le peuple l''''écoutait avec admiration."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 19, 'es', '[{"numero": 1, "texto": "Y HABIENDO entrado Jesús, iba pasando por Jericó;"}, {"numero": 2, "texto": "Y he aquí un varón llamado Zaqueo, el cual era el principal de los publicanos, y era rico;"}, {"numero": 3, "texto": "Y procuraba ver á Jesús quién fuese; mas no podía á causa de la multitud, porque era pequeño de estatura."}, {"numero": 4, "texto": "Y corriendo delante, subióse á un árbol sicómoro para verle; porque había de pasar por allí."}, {"numero": 5, "texto": "Y como vino á aquel lugar Jesús, mirando, le vió, y díjole: Zaqueo, date priesa, desciende, porque hoy es necesario que pose en tu casa."}, {"numero": 6, "texto": "Entonces él descendió apriesa, y le recibió gozoso."}, {"numero": 7, "texto": "Y viendo esto, todos murmuraban, diciendo que había entrado á posar con un hombre pecador."}, {"numero": 8, "texto": "Entonces Zaqueo, puesto en pie, dijo al Señor: He aquí, Señor, la mitad de mis bienes doy á los pobres; y si en algo he defraudado á alguno, lo vuelvo con el cuatro tanto."}, {"numero": 9, "texto": "Y Jesús le dijo: Hoy ha venido la salvación á esta casa; por cuanto él también es hijo de Abraham."}, {"numero": 10, "texto": "Porque el Hijo del hombre vino á buscar y á salvar lo que se había perdido."}, {"numero": 11, "texto": "Y oyendo ellos estas cosas, prosiguió Jesús y dijo una parábola, por cuanto estaba cerca de Jerusalem, y porque pensaban que luego había de ser manifestado el reino de Dios."}, {"numero": 12, "texto": "Dijo pues: Un hombre noble partió á una provincia lejos, para tomar para sí un reino, y volver."}, {"numero": 13, "texto": "Mas llamados diez siervos suyos, les dió diez minas, y díjoles: Negociad entre tanto que vengo."}, {"numero": 14, "texto": "Empero sus ciudadanos le aborrecían, y enviaron tras de él una embajada, diciendo: No queremos que éste reine sobre nosotros."}, {"numero": 15, "texto": "Y aconteció, que vuelto él, habiendo tomado el reino, mandó llamar á sí á aquellos siervos á los cuales había dado el dinero, para saber lo que había negociado cada uno."}, {"numero": 16, "texto": "Y vino el primero, diciendo: Señor, tu mina ha ganado diez minas."}, {"numero": 17, "texto": "Y él le dice: Está bien, buen siervo; pues que en lo poco has sido fiel, tendrás potestad sobre diez ciudades."}, {"numero": 18, "texto": "Y vino otro, diciendo: Señor, tu mina ha hecho cinco minas."}, {"numero": 19, "texto": "Y también á éste dijo: Tú también sé sobre cinco ciudades."}, {"numero": 20, "texto": "Y vino otro, diciendo: Señor, he aquí tu mina, la cual he tenido guardada en un pañizuelo:"}, {"numero": 21, "texto": "Porque tuve miedo de ti, que eres hombre recio; tomas lo que no pusiste, y siegas lo que no sembraste."}, {"numero": 22, "texto": "Entonces él le dijo: Mal siervo, de tu boca te juzgo. Sabías que yo era hombre recio, que tomo lo que no puse, y que siego lo que no sembré;"}, {"numero": 23, "texto": "¿Por qué, pues, no diste mi dinero al banco, y yo viniendo lo demandara con el logro?"}, {"numero": 24, "texto": "Y dijo á los que estaban presentes: Quitadle la mina, y dadla al que tiene las diez minas."}, {"numero": 25, "texto": "Y ellos le dijeron: Señor, tiene diez minas."}, {"numero": 26, "texto": "Pues yo os digo que á cualquiera que tuviere, le será dado; mas al que no tuviere, aun lo que tiene le será quitado."}, {"numero": 27, "texto": "Y también á aquellos mis enemigos que no querían que yo reinase sobre ellos, traedlos acá, y degolladlos delante de mí."}, {"numero": 28, "texto": "Y dicho esto, iba delante subiendo á Jerusalem."}, {"numero": 29, "texto": "Y aconteció, que llegando cerca de Bethfagé, y de Bethania, al monte que se llama de las Olivas, envió dos de sus discípulos,"}, {"numero": 30, "texto": "Diciendo: Id á la aldea de enfrente; en la cual como entrareis, hallaréis un pollino atado, en el que ningún hombre se ha sentado jamás; desatadlo, y traedlo."}, {"numero": 31, "texto": "Y si alguien os preguntare, ¿por qué lo desatáis? le responderéis así: Porque el Señor lo ha menester."}, {"numero": 32, "texto": "Y fueron los que habían sido enviados, y hallaron como les dijo."}, {"numero": 33, "texto": "Y desatando ellos el pollino, sus dueños les dijeron: ¿Por qué desatáis el pollino?"}, {"numero": 34, "texto": "Y ellos dijeron: Porque el Señor lo ha menester."}, {"numero": 35, "texto": "Y trajéronlo á Jesús; y habiendo echado sus vestidos sobre el pollino, pusieron á Jesús encima."}, {"numero": 36, "texto": "Y yendo él tendían sus capas por el camino."}, {"numero": 37, "texto": "Y como llegasen ya cerca de la bajada del monte de las Olivas, toda la multitud de los discípulos, gozándose, comenzaron á alabar á Dios á gran voz por todas las maravillas que habían visto,"}, {"numero": 38, "texto": "Diciendo: ¡Bendito el rey que viene en el nombre del Señor: paz en el cielo, y gloria en lo altísimo!"}, {"numero": 39, "texto": "Entonces algunos de los Fariseos de la compañía, le dijeron: Maestro, reprende á tus discípulos."}, {"numero": 40, "texto": "Y él respondiendo, les dijo: Os digo que si éstos callaren, las piedras clamarán."}, {"numero": 41, "texto": "Y como llegó cerca, viendo la ciudad, lloró sobre ella,"}, {"numero": 42, "texto": "Diciendo: ¡Oh si también tú conocieses, á lo menos en este tu día, lo que toca á tu paz! mas ahora está encubierto de tus ojos."}, {"numero": 43, "texto": "Porque vendrán días sobre ti, que tus enemigos te cercarán con baluarte, y te pondrán cerco, y de todas partes te pondrán en estrecho,"}, {"numero": 44, "texto": "Y te derribarán á tierra, y á tus hijos dentro de ti; y no dejarán sobre ti piedra sobre piedra; por cuanto no conociste el tiempo de tu visitación."}, {"numero": 45, "texto": "Y entrando en el templo, comenzó á echar fuera á todos los que vendían y compraban en él."}, {"numero": 46, "texto": "Diciéndoles: Escrito está: Mi casa, casa de oración es; mas vosotros la habéis hecho cueva de ladrones."}, {"numero": 47, "texto": "Y enseñaba cada día en el templo; mas los príncipes de los sacerdotes, y los escribas, y los principales del pueblo procuraban matarle."}, {"numero": 48, "texto": "Y no hallaban qué hacerle, porque todo el pueblo estaba suspenso oyéndole."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 20, 'pt', '[{"numero": 1, "texto": "E aconteceu, num daqueles dias que, enquanto ele estava ensinando ao povo no Templo, e anunciando o Evangelho, vieram até ele os chefes dos sacerdotes, e os escribas com os anciãos."}, {"numero": 2, "texto": "E falaram-lhe, dizendo: Dize-nos, com que autoridade fazes estas coisas? Ou quem é o que te deu esta autoridade?"}, {"numero": 3, "texto": "E respondendo ele, disse-lhes: Também eu vos perguntarei algo, e dizei-me:"}, {"numero": 4, "texto": "O batismo de João era do céu, ou dos homens?"}, {"numero": 5, "texto": "E eles discutiam entre si, dizendo: Se dissermos: Do céu, ele nos dirá: Por que, então, vós não [o] crestes?"}, {"numero": 6, "texto": "E se dissermos: Dos homens, todo o povo nos apedrejará; pois estão convencidos de que João era profeta."}, {"numero": 7, "texto": "E responderam que não sabiam de onde [era] ."}, {"numero": 8, "texto": "E Jesus lhes disse: Nem eu vos direi com que autoridade eu faço estas coisas."}, {"numero": 9, "texto": "E começou a dizer ao povo esta parábola: Um certo homem plantou uma vinha, e a arrendou a [uns] lavradores, e viajou para outro país por muito tempo."}, {"numero": 10, "texto": "E certo tempo [depois] mandou um servo aos lavradores, para que lhe dessem do fruto da vinha; mas os lavradores, espancando-o, mandaram [-no] sem coisa alguma."}, {"numero": 11, "texto": "E voltou a mandar outro servo; mas eles, espancando e humilhando também [a ele] ,o mandaram sem nada."}, {"numero": 12, "texto": "E voltou a mandar ao terceiro; mas eles, ferindo também a este, [o] expulsaram."}, {"numero": 13, "texto": "E o senhor da vinha disse: Que farei? Mandarei a meu filho amado; talvez quando o verem, [o] respeitarão."}, {"numero": 14, "texto": "Mas os lavradores, vendo-o, discutiram entre si, dizendo: Este é o herdeiro; vamos matá-lo, para que a herança venha a ser nossa."}, {"numero": 15, "texto": "E expulsando-o da vinha, [o] mataram. O que, então, lhes fará o senhor da vinha?"}, {"numero": 16, "texto": "Virá, e destruirá a estes lavradores, e dará a vinha a outros.E eles, ouvindo isto, disseram: Que [isto] nunca aconteça!"}, {"numero": 17, "texto": "Mas [Jesus] ,olhando para eles, disse: Por que, então, isto está escrito: A pedra que os construtores rejeitaram, essa foi posta como a principal da esquina?"}, {"numero": 18, "texto": "Todo aquele que cair sobre aquela pedra, se quebrará em pedaços; e aquele sobre quem ela cair, se fará pó."}, {"numero": 19, "texto": "E os chefes dos sacerdotes e os escribas queriam detê-lo naquela mesma hora, mas temiam ao povo; porque entenderam que foi contra eles que ele tinha dito a parábola."}, {"numero": 20, "texto": "E, observando-o, mandaram espiões, que fingissem ser justos, para o pegarem por meio de algo que ele dissesse, e o entregarem ao poder e autoridade do governador."}, {"numero": 21, "texto": "E perguntaram-lhe, dizendo: Mestre, nós sabemos que falas e ensinas corretamente, e que não te importas com as aparências, mas na verdade tu ensinas o caminho de Deus."}, {"numero": 22, "texto": "É lícito para nós dar tributo a César, ou não?"}, {"numero": 23, "texto": "E ele, entendendo a astúcia deles, disse-lhes: Por que me tentais?"}, {"numero": 24, "texto": "Mostrai-me uma moeda; ela tem a imagem e a inscrição de quem?E eles, respondendo, disseram: De César."}, {"numero": 25, "texto": "Então lhes disse: Dai pois a César o que [é] de César, e a Deus o que [é] de Deus."}, {"numero": 26, "texto": "E não puderam lhe pegar em algo que ele tenha dito diante do povo; e maravilhados de sua resposta, calaram-se."}, {"numero": 27, "texto": "E chegando-se alguns dos saduceus, que negam haver a ressurreição, perguntaram-lhe,"}, {"numero": 28, "texto": "Dizendo: Mestre, Moisés nos escreveu, que se o irmão de alguém morrer, tendo mulher, e morrer sem filhos, o irmão deve tomar a mulher, e gerar descendência a seu irmão."}, {"numero": 29, "texto": "Houve, pois, sete irmãos, e o primeiro tomou mulher, e morreu sem filhos."}, {"numero": 30, "texto": "E o segundo a tomou; e [também] este morreu sem filhos."}, {"numero": 31, "texto": "E o terceiro a tomou, e assim também os sete, e não deixaram filhos, e morreram."}, {"numero": 32, "texto": "E por fim, depois de todos, morreu também a mulher."}, {"numero": 33, "texto": "Na ressurreição, pois, ela será mulher de qual deles? Pois os sete a tiveram por mulher."}, {"numero": 34, "texto": "E respondendo Jesus, disse-lhes: Os filhos destes tempos se casam, e se dão em casamento."}, {"numero": 35, "texto": "Mas os que forem considerados dignos de alcançarem aqueles tempos futuros, e da ressurreição dos mortos, nem se casarão, nem se darão em casamento."}, {"numero": 36, "texto": "Porque já não podem mais morrer; pois são iguais aos anjos; e são filhos de Deus, pois são filhos da ressurreição."}, {"numero": 37, "texto": "E até Moisés mostrou, junto à sarça, que os mortos ressuscitam, quando ele chama ao Senhor de Deus de Abraão, e Deus de Isaque, e Deus de Jacó."}, {"numero": 38, "texto": "Ora, ele não é Deus de mortos, mas de vivos; pois todos vivem por causa dele."}, {"numero": 39, "texto": "E alguns dos escribas, respondendo, disseram: Mestre, bem disseste."}, {"numero": 40, "texto": "E não ousavam lhe perguntar mais nada."}, {"numero": 41, "texto": "E ele lhes disse: Como dizem que o Cristo é filho de Davi?"}, {"numero": 42, "texto": "Pois o próprio Davi diz no livro dos Salmos: Disse o Senhor a meu Senhor: Senta-te à minha direita,"}, {"numero": 43, "texto": "Até que eu ponha teus inimigos por escabelo de teus pés."}, {"numero": 44, "texto": "Se Davi o chama de Senhor, como, então, é seu filho?"}, {"numero": 45, "texto": "Enquanto todo o povo estava ouvindo, ele disse a seus discípulos:"}, {"numero": 46, "texto": "Tomai cuidado com os escribas, que querem andar roupas compridas, e amam as saudações nas praças, e as primeiras cadeiras nas sinagogas, e os primeiros assentos nos jantares."}, {"numero": 47, "texto": "Que devoram as casas das viúvas, e fingem fazer longas orações. Estes receberão mais grave condenação."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 20, 'en', '[{"numero": 1, "texto": "And it came to pass, that on one of those days, as he taught the people in the temple, and preached the gospel, the chief priests and the scribes came upon him with the elders,"}, {"numero": 2, "texto": "And spake unto him, saying, Tell us, by what authority doest thou these things? or who is he that gave thee this authority?"}, {"numero": 3, "texto": "And he answered and said unto them, I will also ask you one thing; and answer me:"}, {"numero": 4, "texto": "The baptism of John, was it from heaven, or of men?"}, {"numero": 5, "texto": "And they reasoned with themselves, saying, If we shall say, From heaven; he will say, Why then believed ye him not?"}, {"numero": 6, "texto": "But and if we say, Of men; all the people will stone us: for they be persuaded that John was a prophet."}, {"numero": 7, "texto": "And they answered, that they could not tell whence it was."}, {"numero": 8, "texto": "And Jesus said unto them, Neither tell I you by what authority I do these things."}, {"numero": 9, "texto": "Then began he to speak to the people this parable; A certain man planted a vineyard, and let it forth to husbandmen, and went into a far country for a long time."}, {"numero": 10, "texto": "And at the season he sent a servant to the husbandmen, that they should give him of the fruit of the vineyard: but the husbandmen beat him, and sent him away empty."}, {"numero": 11, "texto": "And again he sent another servant: and they beat him also, and entreated him shamefully, and sent him away empty."}, {"numero": 12, "texto": "And again he sent a third: and they wounded him also, and cast him out."}, {"numero": 13, "texto": "Then said the lord of the vineyard, What shall I do? I will send my beloved son: it may be they will reverence him when they see him."}, {"numero": 14, "texto": "But when the husbandmen saw him, they reasoned among themselves, saying, This is the heir: come, let us kill him, that the inheritance may be ours."}, {"numero": 15, "texto": "So they cast him out of the vineyard, and killed him. What therefore shall the lord of the vineyard do unto them?"}, {"numero": 16, "texto": "He shall come and destroy these husbandmen, and shall give the vineyard to others. And when they heard it, they said, God forbid."}, {"numero": 17, "texto": "And he beheld them, and said, What is this then that is written, The stone which the builders rejected, the same is become the head of the corner?"}, {"numero": 18, "texto": "Whosoever shall fall upon that stone shall be broken; but on whomsoever it shall fall, it will grind him to powder."}, {"numero": 19, "texto": "And the chief priests and the scribes the same hour sought to lay hands on him; and they feared the people: for they perceived that he had spoken this parable against them."}, {"numero": 20, "texto": "And they watched him, and sent forth spies, which should feign themselves just men, that they might take hold of his words, that so they might deliver him unto the power and authority of the governor."}, {"numero": 21, "texto": "And they asked him, saying, Master, we know that thou sayest and teachest rightly, neither acceptest thou the person of any, but teachest the way of God truly:"}, {"numero": 22, "texto": "Is it lawful for us to give tribute unto Caesar, or no?"}, {"numero": 23, "texto": "But he perceived their craftiness, and said unto them, Why tempt ye me?"}, {"numero": 24, "texto": "Shew me a penny. Whose image and superscription hath it? They answered and said, Caesar''s."}, {"numero": 25, "texto": "And he said unto them, Render therefore unto Caesar the things which be Caesar''s, and unto God the things which be God''s."}, {"numero": 26, "texto": "And they could not take hold of his words before the people: and they marvelled at his answer, and held their peace."}, {"numero": 27, "texto": "Then came to him certain of the Sadducees, which deny that there is any resurrection; and they asked him,"}, {"numero": 28, "texto": "Saying, Master, Moses wrote unto us, If any man''s brother die, having a wife, and he die without children, that his brother should take his wife, and raise up seed unto his brother."}, {"numero": 29, "texto": "There were therefore seven brethren: and the first took a wife, and died without children."}, {"numero": 30, "texto": "And the second took her to wife, and he died childless."}, {"numero": 31, "texto": "And the third took her; and in like manner the seven also: and they left no children, and died."}, {"numero": 32, "texto": "Last of all the woman died also."}, {"numero": 33, "texto": "Therefore in the resurrection whose wife of them is she? for seven had her to wife."}, {"numero": 34, "texto": "And Jesus answering said unto them, The children of this world marry, and are given in marriage:"}, {"numero": 35, "texto": "But they which shall be accounted worthy to obtain that world, and the resurrection from the dead, neither marry, nor are given in marriage:"}, {"numero": 36, "texto": "Neither can they die any more: for they are equal unto the angels; and are the children of God, being the children of the resurrection."}, {"numero": 37, "texto": "Now that the dead are raised, even Moses shewed at the bush, when he calleth the Lord the God of Abraham, and the God of Isaac, and the God of Jacob."}, {"numero": 38, "texto": "For he is not a God of the dead, but of the living: for all live unto him."}, {"numero": 39, "texto": "Then certain of the scribes answering said, Master, thou hast well said."}, {"numero": 40, "texto": "And after that they durst not ask him any question at all."}, {"numero": 41, "texto": "And he said unto them, How say they that Christ is David''s son?"}, {"numero": 42, "texto": "And David himself saith in the book of Psalms, The Lord said unto my Lord, Sit thou on my right hand,"}, {"numero": 43, "texto": "Till I make thine enemies thy footstool."}, {"numero": 44, "texto": "David therefore calleth him Lord, how is he then his son?"}, {"numero": 45, "texto": "Then in the audience of all the people he said unto his disciples,"}, {"numero": 46, "texto": "Beware of the scribes, which desire to walk in long robes, and love greetings in the markets, and the highest seats in the synagogues, and the chief rooms at feasts;"}, {"numero": 47, "texto": "Which devour widows'' houses, and for a shew make long prayers: the same shall receive greater damnation."}]'::jsonb, 'King James Version'),
  ('Lc', 20, 'fr', '[{"numero": 1, "texto": "Un de ces jours-là, comme Jésus enseignait le peuple dans le temple et qu''''il annonçait la bonne nouvelle, les principaux sacrificateurs et les scribes, avec les anciens, survinrent,"}, {"numero": 2, "texto": "et lui dirent: Dis-nous, par quelle autorité fais-tu ces choses, ou qui est celui qui t''''a donné cette autorité?"}, {"numero": 3, "texto": "Il leur répondit: Je vous adresserai aussi une question. Dites-moi,"}, {"numero": 4, "texto": "le baptême de Jean venait-il du ciel, ou des hommes?"}, {"numero": 5, "texto": "Mais ils raisonnèrent ainsi entre eux: Si nous répondons: Du ciel, il dira: Pourquoi n''''avez-vous pas cru en lui?"}, {"numero": 6, "texto": "Et si nous répondons: Des hommes, tout le peuple nous lapidera, car il est persuadé que Jean était un prophète."}, {"numero": 7, "texto": "Alors ils répondirent qu''''ils ne savaient d''''où il venait."}, {"numero": 8, "texto": "Et Jésus leur dit: Moi non plus, je ne vous dirai pas par quelle autorité je fais ces choses."}, {"numero": 9, "texto": "Il se mit ensuite à dire au peuple cette parabole: Un homme planta une vigne, l''''afferma à des vignerons, et quitta pour longtemps le pays."}, {"numero": 10, "texto": "Au temps de la récolte, il envoya un serviteur vers les vignerons, pour qu''''ils lui donnent une part du produit de la vigne. Les vignerons le battirent, et le renvoyèrent à vide."}, {"numero": 11, "texto": "Il envoya encore un autre serviteur; ils le battirent, l''''outragèrent, et le renvoyèrent à vide."}, {"numero": 12, "texto": "Il en envoya encore un troisième; ils le blessèrent, et le chassèrent."}, {"numero": 13, "texto": "Le maître de la vigne dit: Que ferai-je? J''''enverrai mon fils bien-aimé; peut-être auront-ils pour lui du respect."}, {"numero": 14, "texto": "Mais, quand les vignerons le virent, ils raisonnèrent entre eux, et dirent: Voici l''''héritier; tuons-le, afin que l''''héritage soit à nous."}, {"numero": 15, "texto": "Et ils le jetèrent hors de la vigne, et le tuèrent. Maintenant, que leur fera le maître de la vigne?"}, {"numero": 16, "texto": "Il viendra, fera périr ces vignerons, et il donnera la vigne à d''''autres. Lorsqu''''ils eurent entendu cela, ils dirent: A Dieu ne plaise!"}, {"numero": 17, "texto": "Mais, jetant les regards sur eux, Jésus dit: Que signifie donc ce qui est écrit: La pierre qu''''ont rejetée ceux qui bâtissaient Est devenue la principale de l''''angle?"}, {"numero": 18, "texto": "Quiconque tombera sur cette pierre s''''y brisera, et celui sur qui elle tombera sera écrasé."}, {"numero": 19, "texto": "Les principaux sacrificateurs et les scribes cherchèrent à mettre la main sur lui à l''''heure même, mais ils craignirent le peuple. Ils avaient compris que c''''était pour eux que Jésus avait dit cette parabole."}, {"numero": 20, "texto": "Ils se mirent à observer Jésus; et ils envoyèrent des gens qui feignaient d''''être justes, pour lui tendre des pièges et saisir de lui quelque parole, afin de le livrer au magistrat et à l''''autorité du gouverneur."}, {"numero": 21, "texto": "Ces gens lui posèrent cette question: Maître, nous savons que tu parles et enseignes droitement, et que tu ne regardes pas à l''''apparence, mais que tu enseignes la voie de Dieu selon la vérité."}, {"numero": 22, "texto": "Nous est-il permis, ou non, de payer le tribut à César?"}, {"numero": 23, "texto": "Jésus, apercevant leur ruse, leur répondit:"}, {"numero": 24, "texto": "Montrez-moi un denier. De qui porte-t-il l''''effigie et l''''inscription? De César, répondirent-ils."}, {"numero": 25, "texto": "Alors il leur dit: Rendez donc à César ce qui est à César, et à Dieu ce qui est à Dieu."}, {"numero": 26, "texto": "Ils ne purent rien reprendre dans ses paroles devant le peuple; mais, étonnés de sa réponse, ils gardèrent le silence."}, {"numero": 27, "texto": "Quelques-uns des sadducéens, qui disent qu''''il n''''y a point de résurrection, s''''approchèrent, et posèrent à Jésus cette question:"}, {"numero": 28, "texto": "Maître, voici ce que Moïse nous a prescrit: Si le frère de quelqu''''un meurt, ayant une femme sans avoir d''''enfants, son frère épousera la femme, et suscitera une postérité à son frère."}, {"numero": 29, "texto": "Or, il y avait sept frères. Le premier se maria, et mourut sans enfants."}, {"numero": 30, "texto": "Le second et le troisième épousèrent la veuve;"}, {"numero": 31, "texto": "il en fut de même des sept, qui moururent sans laisser d''''enfants."}, {"numero": 32, "texto": "Enfin, la femme mourut aussi."}, {"numero": 33, "texto": "A la résurrection, duquel d''''entre eux sera-t-elle donc la femme? Car les sept l''''ont eue pour femme."}, {"numero": 34, "texto": "Jésus leur répondit: Les enfants de ce siècle prennent des femmes et des maris;"}, {"numero": 35, "texto": "mais ceux qui seront trouvés dignes d''''avoir part au siècle à venir et à la résurrection des morts ne prendront ni femmes ni maris."}, {"numero": 36, "texto": "Car ils ne pourront plus mourir, parce qu''''ils seront semblables aux anges, et qu''''ils seront fils de Dieu, étant fils de la résurrection."}, {"numero": 37, "texto": "Que les morts ressuscitent, c''''est ce que Moïse a fait connaître quand, à propos du buisson, il appelle le Seigneur le Dieu d''''Abraham, le Dieu d''''Isaac, et le Dieu de Jacob."}, {"numero": 38, "texto": "Or, Dieu n''''est pas Dieu des morts, mais des vivants; car pour lui tous sont vivants."}, {"numero": 39, "texto": "Quelques-uns des scribes, prenant la parole, dirent: Maître, tu as bien parlé."}, {"numero": 40, "texto": "Et ils n''''osaient plus lui faire aucune question."}, {"numero": 41, "texto": "Jésus leur dit: Comment dit-on que le Christ est fils de David?"}, {"numero": 42, "texto": "David lui-même dit dans le livre des Psaumes: Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite,"}, {"numero": 43, "texto": "Jusqu''''à ce que je fasse de tes ennemis ton marchepied."}, {"numero": 44, "texto": "David donc l''''appelle Seigneur; comment est-il son fils?"}, {"numero": 45, "texto": "Tandis que tout le peuple l''''écoutait, il dit à ses disciples:"}, {"numero": 46, "texto": "Gardez-vous des scribes, qui aiment à se promener en robes longues, et à être salués dans les places publiques; qui recherchent les premiers sièges dans les synagogues, et les premières places dans les festins;"}, {"numero": 47, "texto": "qui dévorent les maisons des veuves, et qui font pour l''''apparence de longues prières. Ils seront jugés plus sévèrement."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 20, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ un día, que enseñando él al pueblo en el templo, y anunciando el evangelio, llegáronse los príncipes de los sacerdotes y los escribas, con los ancianos;"}, {"numero": 2, "texto": "Y le hablaron, diciendo: Dinos: ¿con qué potestad haces estas cosas? ¿ó quién es el que te ha dado esta potestad?"}, {"numero": 3, "texto": "Respondiendo entonces Jesús, les dijo: Os preguntaré yo también una palabra; respondedme:"}, {"numero": 4, "texto": "El bautismo de Juan, ¿era del cielo, ó de los hombres?"}, {"numero": 5, "texto": "Mas ellos pensaban dentro de sí, diciendo: Si dijéremos, del cielo, dirá: ¿Por qué, pues, no le creísteis?"}, {"numero": 6, "texto": "Y si dijéremos, de los hombres, todo el pueblo nos apedreará: porque están ciertos que Juan era profeta."}, {"numero": 7, "texto": "Y respondieron que no sabían de dónde."}, {"numero": 8, "texto": "Entonces Jesús les dijo: Ni yo os digo con qué potestad hago estas cosas."}, {"numero": 9, "texto": "Y comenzó á decir al pueblo esta parábola: Un hombre plantó una viña, y arrendóla á labradores, y se ausentó por mucho tiempo."}, {"numero": 10, "texto": "Y al tiempo, envió un siervo á los labradores, para que le diesen del fruto de la viña; mas los labradores le hirieron, y enviaron vacío."}, {"numero": 11, "texto": "Y volvió á enviar otro siervo; mas ellos á éste también, herido y afrentado, le enviaron vacío."}, {"numero": 12, "texto": "Y volvió á enviar al tercer siervo; mas ellos también á éste echaron herido."}, {"numero": 13, "texto": "Entonces el señor de la viña dijo: ¿Qué haré? Enviaré mi hijo amado: quizás cuando á éste vieren, tendrán respeto."}, {"numero": 14, "texto": "Mas los labradores, viéndole, pensaron entre sí, diciendo: Este es el heredero; venid, matémosle para que la heredad sea nuestra."}, {"numero": 15, "texto": "Y echáronle fuera de la viña, y le mataron. ¿Qué pues, les hará el señor de la viña?"}, {"numero": 16, "texto": "Vendrá, y destruirá á estos labradores, y dará su viña á otros. Y como ellos lo oyeron, dijeron: ¡Dios nos libre!"}, {"numero": 17, "texto": "Mas él mirándolos, dice: ¿Qué pues es lo que está escrito: La piedra que condenaron los edificadores, ésta fué por cabeza de esquina?"}, {"numero": 18, "texto": "Cualquiera que cayere sobre aquella piedra, será quebrantado; mas sobre el que la piedra cayere, le desmenuzará."}, {"numero": 19, "texto": "Y procuraban los príncipes de los sacerdotes y los escribas echarle mano en aquella hora, porque entendieron que contra ellos había dicho esta parábola: mas temieron al pueblo."}, {"numero": 20, "texto": "Y acechándole enviaron espías que se simulasen justos, para sorprenderle en palabras, para que le entregasen al principado y á la potestad del presidente."}, {"numero": 21, "texto": "Los cuales le preguntaron, diciendo: Maestro, sabemos que dices y enseñas bien, y que no tienes respeto á persona; antes enseñas el camino de Dios con verdad."}, {"numero": 22, "texto": "¿Nos es lícito dar tributo á César, ó no?"}, {"numero": 23, "texto": "Mas él, entendiendo la astucia de ellos, les dijo: ¿Por qué me tentáis?"}, {"numero": 24, "texto": "Mostradme la moneda. ¿De quién tiene la imagen y la inscripción? Y respondiendo dijeron: De César."}, {"numero": 25, "texto": "Entonces les dijo: Pues dad á César lo que es de César; y lo que es de Dios, á Dios."}, {"numero": 26, "texto": "Y no pudieron reprender sus palabras delante del pueblo: antes maravillados de su respuesta, callaron."}, {"numero": 27, "texto": "Y llegándose unos de los Saduceos, los cuales niegan haber resurrección, le preguntaron,"}, {"numero": 28, "texto": "Diciendo: Maestro, Moisés nos escribió: Si el hermano de alguno muriere teniendo mujer, y muriere sin hijos, que su hermano tome la mujer, y levante simiente á su hermano."}, {"numero": 29, "texto": "Fueron, pues, siete hermanos: y el primero tomó mujer, y murió sin hijos."}, {"numero": 30, "texto": "Y la tomó el segundo, el cual también murió sin hijos."}, {"numero": 31, "texto": "Y la tomó el tercero: asimismo también todos siete: y murieron sin dejar prole."}, {"numero": 32, "texto": "Y á la postre de todos murió también la mujer."}, {"numero": 33, "texto": "En la resurrección, pues, ¿mujer de cuál de ellos será? porque los siete la tuvieron por mujer."}, {"numero": 34, "texto": "Entonces respondiendo Jesús, les dijo: Los hijos de este siglo se casan, y son dados en casamiento:"}, {"numero": 35, "texto": "Mas los que fueren tenidos por dignos de aquel siglo y de la resurrección de los muertos, ni se casan, ni son dados en casamiento:"}, {"numero": 36, "texto": "Porque no pueden ya más morir: porque son iguales á los ángeles, y son hijos de Dios, cuando son hijos de la resurrección."}, {"numero": 37, "texto": "Y que los muertos hayan de resucitar, aun Moisés lo enseñó en el pasaje de la zarza, cuando llama al Señor: Dios de Abraham, y Dios de Isaac, y Dios de Jacob."}, {"numero": 38, "texto": "Porque Dios no es Dios de muertos, mas de vivos: porque todos viven á él."}, {"numero": 39, "texto": "Y respondiéndole unos de los escribas, dijeron: Maestro, bien has dicho."}, {"numero": 40, "texto": "Y no osaron más preguntarle algo."}, {"numero": 41, "texto": "Y él les dijo: ¿Cómo dicen que el Cristo es hijo de David?"}, {"numero": 42, "texto": "Y el mismo David dice en el libro de los Salmos: Dijo el Señor á mi Señor: Siéntate á mi diestra,"}, {"numero": 43, "texto": "Entre tanto que pongo tus enemigos por estrado de tus pies."}, {"numero": 44, "texto": "Así que David le llama Señor: ¿cómo pues es su hijo?"}, {"numero": 45, "texto": "Y oyéndole todo el pueblo, dijo á sus discípulos:"}, {"numero": 46, "texto": "Guardaos de los escribas, que quieren andar con ropas largas, y aman las salutaciones en las plazas, y las primeras sillas en las sinagogas, y los primeros asientos en las cenas;"}, {"numero": 47, "texto": "Que devoran las casas de las viudas, poniendo por pretexto la larga oración: éstos recibirán mayor condenación."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 21, 'pt', '[{"numero": 1, "texto": "E ele, olhando, viu os ricos lançarem suas ofertas na arca do tesouro [do templo] ."}, {"numero": 2, "texto": "E viu também uma pobre viúva lançar ali duas pequenas moedas."}, {"numero": 3, "texto": "E disse: Em verdade vos digo que esta pobre viúva lançou mais do que todos,"}, {"numero": 4, "texto": "Porque todos aqueles lançaram para as ofertas de Deus daquilo que lhes sobrava; mas esta [viúva] , de sua pobreza, lançou todo o sustento que tinha."}, {"numero": 5, "texto": "E alguns estavam falando do templo, que era adornado com formosas pedras e ofertas. Então [Jesus] disse:"}, {"numero": 6, "texto": "Destas coisas que vedes, dias virão, em que não se deixará pedra sobre pedra, que não seja derrubada."}, {"numero": 7, "texto": "E perguntaram-lhe, dizendo: Mestre, quando, pois, serão essas coisas? E que sinal haverá, quando essas coisas vierem a acontecer?"}, {"numero": 8, "texto": "Então ele disse: Olhai para que não vos enganem, porque muitos virão em meu nome, dizendo: Eu sou [o Cristo] . E o tempo já está perto; portanto não os sigais."}, {"numero": 9, "texto": "E quando ouvirdes de guerras, e de rebeliões, não vos espanteis. Porque é necessário que estas coisas aconteçam primeiro; mas ainda não é o fim."}, {"numero": 10, "texto": "Então lhe disse: Então se levantará nação contra nação, e reino contra reino."}, {"numero": 11, "texto": "E haverá em vários lugares grandes terremotos e fomes, e pragas; haverá também coisas espantosas, e grandes sinais do céu."}, {"numero": 12, "texto": "Mas antes de tudo isto, eles vos impedirão e vos perseguirão, [vos] entregando em sinagogas e prisões, [e] vos trazendo diante de reis, e governadores, por causa do meu nome."}, {"numero": 13, "texto": "E isto vos acontecerá para haver testemunho."}, {"numero": 14, "texto": "Portanto, que vós decidais nos vossos corações não planejar como direis em vossa defesa,"}, {"numero": 15, "texto": "porque eu vos darei boca e sabedoria, para que todos os que forem contra vós não posam [vos] contradizer ou resistir."}, {"numero": 16, "texto": "E vós sereis entregues até pelos pais, e irmãos, e parentes, e amigos; e [alguns] de vós serão mortos."}, {"numero": 17, "texto": "E vós sereis odiados por todos por causa do meu nome."}, {"numero": 18, "texto": "Mas nem um cabelo de vossa cabeça parecerá."}, {"numero": 19, "texto": "Por vossa paciência ganhareis vossas almas."}, {"numero": 20, "texto": "Porém quando virdes a Jerusalém cercada de exércitos, sabei então, que próxima está sua desolação."}, {"numero": 21, "texto": "Então, os que estiverem na Judeia, fujam para os montes; e os que estiverem no meio dela, saiam, e os que estiverem nos campos, não entrem nela."}, {"numero": 22, "texto": "Porque estes são dias de vingança, para que todas as coisas que estão escritas se cumpram."}, {"numero": 23, "texto": "Mas ai das grávidas, e das que amamentarem naqueles dias; porque grande calamidade haverá na terra, e ira contra este povo."}, {"numero": 24, "texto": "E cairão pela lâmina de espada, e serão levados cativos para todas as nações; e Jerusalém será pisada pelos gentios, até que os tempos dos gentios se cumpram."}, {"numero": 25, "texto": "E haverá sinais no Sol, [na] Lua, e [nas] estrelas; e na terra sofrimento entre as nações, como o rugir e agitar do mar."}, {"numero": 26, "texto": "As pessoas desmaiarão de medo e da expectativa das coisas que vão acontecer ao mundo, porque os poderes dos céus serão abalados."}, {"numero": 27, "texto": "E então verão o Filho do homem vir em uma nuvem com grande poder e glória."}, {"numero": 28, "texto": "Ora, quando estas coisas começarem a acontecer, olhai para cima, e levantai vossas cabeças, porque vosso resgate está perto."}, {"numero": 29, "texto": "E disse-lhes uma parábola: Olhai a figueira, e todas as árvores;"}, {"numero": 30, "texto": "Quando vós vedes elas já brotando, sabeis por vós mesmos que o verão já está perto."}, {"numero": 31, "texto": "Assim também vós, quando virdes acontecer estas coisas, sabei que o Reino de Deus já está perto."}, {"numero": 32, "texto": "Em verdade vos digo, que esta geração não passará, até que tudo aconteça."}, {"numero": 33, "texto": "O céu e a terra passarão, mas minhas palavras de maneira nenhuma passarão."}, {"numero": 34, "texto": "E olhai por vós, para que vossos corações não venham a se encher de ressaca e embriaguez, e das preocupações d [esta] vida; e vos venha aquele dia de surpresa."}, {"numero": 35, "texto": "Porque virá como uma armadilha sobre todos os que habitam sobre a face de toda a terra."}, {"numero": 36, "texto": "Então vigiai sempre, orando para que sejais considerados dignos de escaparem de todas as coisas que irão acontecer, e de ficarem de pé diante do Filho do homem."}, {"numero": 37, "texto": "E ensinava durante os dias no Templo, porém, às noites saía e as passava no monte, chamado as Oliveiras."}, {"numero": 38, "texto": "E todo o povo vinha até ele de manhã cedo ao templo, para o ouvir."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 21, 'en', '[{"numero": 1, "texto": "And he looked up, and saw the rich men casting their gifts into the treasury."}, {"numero": 2, "texto": "And he saw also a certain poor widow casting in thither two mites."}, {"numero": 3, "texto": "And he said, Of a truth I say unto you, that this poor widow hath cast in more than they all:"}, {"numero": 4, "texto": "For all these have of their abundance cast in unto the offerings of God: but she of her penury hath cast in all the living that she had."}, {"numero": 5, "texto": "And as some spake of the temple, how it was adorned with goodly stones and gifts, he said,"}, {"numero": 6, "texto": "As for these things which ye behold, the days will come, in the which there shall not be left one stone upon another, that shall not be thrown down."}, {"numero": 7, "texto": "And they asked him, saying, Master, but when shall these things be? and what sign will there be when these things shall come to pass?"}, {"numero": 8, "texto": "And he said, Take heed that ye be not deceived: for many shall come in my name, saying, I am Christ; and the time draweth near: go ye not therefore after them."}, {"numero": 9, "texto": "But when ye shall hear of wars and commotions, be not terrified: for these things must first come to pass; but the end is not by and by."}, {"numero": 10, "texto": "Then said he unto them, Nation shall rise against nation, and kingdom against kingdom:"}, {"numero": 11, "texto": "And great earthquakes shall be in divers places, and famines, and pestilences; and fearful sights and great signs shall there be from heaven."}, {"numero": 12, "texto": "But before all these, they shall lay their hands on you, and persecute you, delivering you up to the synagogues, and into prisons, being brought before kings and rulers for my name''s sake."}, {"numero": 13, "texto": "And it shall turn to you for a testimony."}, {"numero": 14, "texto": "Settle it therefore in your hearts, not to meditate before what ye shall answer:"}, {"numero": 15, "texto": "For I will give you a mouth and wisdom, which all your adversaries shall not be able to gainsay nor resist."}, {"numero": 16, "texto": "And ye shall be betrayed both by parents, and brethren, and kinsfolks, and friends; and some of you shall they cause to be put to death."}, {"numero": 17, "texto": "And ye shall be hated of all men for my name''s sake."}, {"numero": 18, "texto": "But there shall not an hair of your head perish."}, {"numero": 19, "texto": "In your patience possess ye your souls."}, {"numero": 20, "texto": "And when ye shall see Jerusalem compassed with armies, then know that the desolation thereof is nigh."}, {"numero": 21, "texto": "Then let them which are in Judaea flee to the mountains; and let them which are in the midst of it depart out; and let not them that are in the countries enter thereinto."}, {"numero": 22, "texto": "For these be the days of vengeance, that all things which are written may be fulfilled."}, {"numero": 23, "texto": "But woe unto them that are with child, and to them that give suck, in those days! for there shall be great distress in the land, and wrath upon this people."}, {"numero": 24, "texto": "And they shall fall by the edge of the sword, and shall be led away captive into all nations: and Jerusalem shall be trodden down of the Gentiles, until the times of the Gentiles be fulfilled."}, {"numero": 25, "texto": "And there shall be signs in the sun, and in the moon, and in the stars; and upon the earth distress of nations, with perplexity; the sea and the waves roaring;"}, {"numero": 26, "texto": "Men''s hearts failing them for fear, and for looking after those things which are coming on the earth: for the powers of heaven shall be shaken."}, {"numero": 27, "texto": "And then shall they see the Son of man coming in a cloud with power and great glory."}, {"numero": 28, "texto": "And when these things begin to come to pass, then look up, and lift up your heads; for your redemption draweth nigh."}, {"numero": 29, "texto": "And he spake to them a parable; Behold the fig tree, and all the trees;"}, {"numero": 30, "texto": "When they now shoot forth, ye see and know of your own selves that summer is now nigh at hand."}, {"numero": 31, "texto": "So likewise ye, when ye see these things come to pass, know ye that the kingdom of God is nigh at hand."}, {"numero": 32, "texto": "Verily I say unto you, This generation shall not pass away, till all be fulfilled."}, {"numero": 33, "texto": "Heaven and earth shall pass away: but my words shall not pass away."}, {"numero": 34, "texto": "And take heed to yourselves, lest at any time your hearts be overcharged with surfeiting, and drunkenness, and cares of this life, and so that day come upon you unawares."}, {"numero": 35, "texto": "For as a snare shall it come on all them that dwell on the face of the whole earth."}, {"numero": 36, "texto": "Watch ye therefore, and pray always, that ye may be accounted worthy to escape all these things that shall come to pass, and to stand before the Son of man."}, {"numero": 37, "texto": "And in the day time he was teaching in the temple; and at night he went out, and abode in the mount that is called the mount of Olives."}, {"numero": 38, "texto": "And all the people came early in the morning to him in the temple, for to hear him."}]'::jsonb, 'King James Version'),
  ('Lc', 21, 'fr', '[{"numero": 1, "texto": "Jésus, ayant levé les yeux, vit les riches qui mettaient leurs offrandes dans le tronc."}, {"numero": 2, "texto": "Il vit aussi une pauvre veuve, qui y mettait deux petites pièces."}, {"numero": 3, "texto": "Et il dit: Je vous le dis en vérité, cette pauvre veuve a mis plus que tous les autres;"}, {"numero": 4, "texto": "car c''''est de leur superflu que tous ceux-là ont mis des offrandes dans le tronc, mais elle a mis de son nécessaire, tout ce qu''''elle avait pour vivre."}, {"numero": 5, "texto": "Comme quelques-uns parlaient des belles pierres et des offrandes qui faisaient l''''ornement du temple, Jésus dit:"}, {"numero": 6, "texto": "Les jours viendront où, de ce que vous voyez, il ne restera pas pierre sur pierre qui ne soit renversée."}, {"numero": 7, "texto": "Ils lui demandèrent: Maître, quand donc cela arrivera-t-il, et à quel signe connaîtra-t-on que ces choses vont arriver?"}, {"numero": 8, "texto": "Jésus répondit: Prenez garde que vous ne soyez séduits. Car plusieurs viendront en mon nom, disant: C''''est moi, et le temps approche. Ne les suivez pas."}, {"numero": 9, "texto": "Quand vous entendrez parler de guerres et de soulèvements, ne soyez pas effrayés, car il faut que ces choses arrivent premièrement. Mais ce ne sera pas encore la fin."}, {"numero": 10, "texto": "Alors il leur dit: Une nation s''''élèvera contre une nation, et un royaume contre un royaume;"}, {"numero": 11, "texto": "il y aura de grands tremblements de terre, et, en divers lieux, des pestes et des famines; il y aura des phénomènes terribles, et de grands signes dans le ciel."}, {"numero": 12, "texto": "Mais, avant tout cela, on mettra la main sur vous, et l''''on vous persécutera; on vous livrera aux synagogues, on vous jettera en prison, on vous mènera devant des rois et devant des gouverneurs, à cause de mon nom."}, {"numero": 13, "texto": "Cela vous arrivera pour que vous serviez de témoignage."}, {"numero": 14, "texto": "Mettez-vous donc dans l''''esprit de ne pas préméditer votre défense;"}, {"numero": 15, "texto": "car je vous donnerai une bouche et une sagesse à laquelle tous vos adversaires ne pourront résister ou contredire."}, {"numero": 16, "texto": "Vous serez livrés même par vos parents, par vos frères, par vos proches et par vos amis, et ils feront mourir plusieurs d''''entre vous."}, {"numero": 17, "texto": "Vous serez haïs de tous, à cause de mon nom."}, {"numero": 18, "texto": "Mais il ne se perdra pas un cheveu de votre tête;"}, {"numero": 19, "texto": "par votre persévérance vous sauverez vos âmes."}, {"numero": 20, "texto": "Lorsque vous verrez Jérusalem investie par des armées, sachez alors que sa désolation est proche."}, {"numero": 21, "texto": "Alors, que ceux qui seront en Judée fuient dans les montagnes, que ceux qui seront au milieu de Jérusalem en sortent, et que ceux qui seront dans les champs n''''entrent pas dans la ville."}, {"numero": 22, "texto": "Car ce seront des jours de vengeance, pour l''''accomplissement de tout ce qui est écrit."}, {"numero": 23, "texto": "Malheur aux femmes qui seront enceintes et à celles qui allaiteront en ces jours-là! Car il y aura une grande détresse dans le pays, et de la colère contre ce peuple."}, {"numero": 24, "texto": "Ils tomberont sous le tranchant de l''''épée, ils seront emmenés captifs parmi toutes les nations, et Jérusalem sera foulée aux pieds par les nations, jusqu''''à ce que les temps des nations soient accomplis."}, {"numero": 25, "texto": "Il y aura des signes dans le soleil, dans la lune et dans les étoiles. Et sur la terre, il y aura de l''''angoisse chez les nations qui ne sauront que faire, au bruit de la mer et des flots,"}, {"numero": 26, "texto": "les hommes rendant l''''âme de terreur dans l''''attente de ce qui surviendra pour la terre; car les puissances des cieux seront ébranlées."}, {"numero": 27, "texto": "Alors on verra le Fils de l''''homme venant sur une nuée avec puissance et une grande gloire."}, {"numero": 28, "texto": "Quand ces choses commenceront à arriver, redressez-vous et levez vos têtes, parce que votre délivrance approche."}, {"numero": 29, "texto": "Et il leur dit une comparaison: Voyez le figuier, et tous les arbres."}, {"numero": 30, "texto": "Dès qu''''ils ont poussé, vous connaissez de vous-mêmes, en regardant, que déjà l''''été est proche."}, {"numero": 31, "texto": "De même, quand vous verrez ces choses arriver, sachez que le royaume de Dieu est proche."}, {"numero": 32, "texto": "Je vous le dis en vérité, cette génération ne passera point, que tout cela n''''arrive."}, {"numero": 33, "texto": "Le ciel et la terre passeront, mais mes paroles ne passeront point."}, {"numero": 34, "texto": "Prenez garde à vous-mêmes, de crainte que vos coeurs ne s''''appesantissent par les excès du manger et du boire, et par les soucis de la vie, et que ce jour ne vienne sur vous à l''''improviste;"}, {"numero": 35, "texto": "car il viendra comme un filet sur tous ceux qui habitent sur la face de toute la terre."}, {"numero": 36, "texto": "Veillez donc et priez en tout temps, afin que vous ayez la force d''''échapper à toutes ces choses qui arriveront, et de paraître debout devant le Fils de l''''homme."}, {"numero": 37, "texto": "Pendant le jour, Jésus enseignait dans le temple, et il allait passer la nuit à la montagne appelée montagne des oliviers."}, {"numero": 38, "texto": "Et tout le peuple, dès le matin, se rendait vers lui dans le temple pour l''''écouter."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 21, 'es', '[{"numero": 1, "texto": "Y MIRANDO, vió á los ricos que echaban sus ofrendas en el gazofilacio."}, {"numero": 2, "texto": "Y vió también una viuda pobrecilla, que echaba allí dos blancas."}, {"numero": 3, "texto": "Y dijo: De verdad os digo, que esta pobre viuda echó más que todos:"}, {"numero": 4, "texto": "Porque todos estos, de lo que les sobra echaron para las ofrendas de Dios; mas ésta de su pobreza echó todo el sustento que tenía."}, {"numero": 5, "texto": "Y á unos que decían del templo, que estaba adornado de hermosas piedras y dones, dijo:"}, {"numero": 6, "texto": "Estas cosas que veis, días vendrán que no quedará piedra sobre piedra que no sea destruída."}, {"numero": 7, "texto": "Y le preguntaron, diciendo: Maestro, ¿cuándo será esto? ¿y qué señal habrá cuando estas cosas hayan de comenzar á ser hechas?"}, {"numero": 8, "texto": "El entonces dijo: Mirad, no seáis engañados; porque vendrán muchos en mi nombre, diciendo: Yo soy; y, El tiempo está cerca: por tanto, no vayáis en pos de ellos."}, {"numero": 9, "texto": "Empero cuando oyereis guerras y sediciones, no os espantéis; porque es necesario que estas cosas acontezcan primero: mas no luego será el fin."}, {"numero": 10, "texto": "Entonces les dijo: Se levantará gente contra gente, y reino contra reino;"}, {"numero": 11, "texto": "Y habrá grandes terremotos, y en varios lugares hambres y pestilencias: y habrá espantos y grandes señales del cielo."}, {"numero": 12, "texto": "Mas antes de todas estas cosas os echarán mano, y perseguirán, entregándoos á las sinagogas y á las cárceles, siendo llevados á los reyes y á los gobernadores por causa de mi nombre."}, {"numero": 13, "texto": "Y os será para testimonio."}, {"numero": 14, "texto": "Poned pues en vuestros corazones no pensar antes cómo habéis de responder:"}, {"numero": 15, "texto": "Porque yo os daré boca y sabiduría, á la cual no podrán resistir ni contradecir todos los que se os opondrán."}, {"numero": 16, "texto": "Mas seréis entregados aun de vuestros padres, y hermanos, y parientes, y amigos; y matarán á algunos de vosotros."}, {"numero": 17, "texto": "Y seréis aborrecidos de todos por causa de mi nombre."}, {"numero": 18, "texto": "Mas un pelo de vuestra cabeza no perecerá."}, {"numero": 19, "texto": "En vuestra paciencia poseeréis vuestras almas."}, {"numero": 20, "texto": "Y cuando viereis á Jerusalem cercada de ejércitos, sabed entonces que su destrucción ha llegado."}, {"numero": 21, "texto": "Entonces los que estuvieren en Judea, huyan á los montes; y los que en medio de ella, váyanse; y los que estén en los campos, no entren en ella."}, {"numero": 22, "texto": "Porque estos son días de venganza: para que se cumplan todas las cosas que están escritas."}, {"numero": 23, "texto": "Mas ¡ay de las preñadas, y de las que crían en aquellos días! porque habrá apuro grande sobre la tierra é ira en este pueblo."}, {"numero": 24, "texto": "Y caerán á filo de espada, y serán llevados cautivos á todas las naciones: y Jerusalem será hollada de las gentes, hasta que los tiempos de las gentes sean cumplidos."}, {"numero": 25, "texto": "Entonces habrá señales en el sol, y en la luna, y en las estrellas; y en la tierra angustia de gentes por la confusión del sonido de la mar y de las ondas:"}, {"numero": 26, "texto": "Secándose los hombres á causa del temor y expectación de las cosas que sobrevendrán á la redondez de la tierra: porque las virtudes de los cielos serán conmovidas."}, {"numero": 27, "texto": "Y entonces verán al Hijo del hombre, que vendrá en una nube con potestad y majestad grande."}, {"numero": 28, "texto": "Y cuando estas cosas comenzaren á hacerse, mirad, y levantad vuestras cabezas, porque vuestra redención está cerca."}, {"numero": 29, "texto": "Y díjoles una parábola: Mirad la higuera y todos los árboles:"}, {"numero": 30, "texto": "Cuando ya brotan, viéndolo, de vosotros mismos entendéis que el verano está ya cerca."}, {"numero": 31, "texto": "Así también vosotros, cuando viereis hacerse estas cosas, entended que está cerca el reino de Dios."}, {"numero": 32, "texto": "De cierto os digo, que no pasará esta generación hasta que todo sea hecho."}, {"numero": 33, "texto": "El cielo y la tierra pasarán; mas mis palabras no pasarán."}, {"numero": 34, "texto": "Y mirad por vosotros, que vuestros corazones no sean cargados de glotonería y embriaguez, y de los cuidados de esta vida, y venga de repente sobre vosotros aquel día."}, {"numero": 35, "texto": "Porque como un lazo vendrá sobre todos los que habitan sobre la faz de toda la tierra."}, {"numero": 36, "texto": "Velad pues, orando en todo tiempo, que seáis tenidos por dignos de evitar todas estas cosas que han de venir, y de estar en pie delante del Hijo del hombre."}, {"numero": 37, "texto": "Y enseñaba de día en el templo; y de noche saliendo, estábase en el monte que se llama de las Olivas."}, {"numero": 38, "texto": "Y todo el pueblo venía á él por la mañana, para oirle en el templo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 22, 'pt', '[{"numero": 1, "texto": "Estava perto a festa dos pães sem fermento, chamada de páscoa."}, {"numero": 2, "texto": "E os chefes dos sacerdotes, e os escribas procuravam um meio de o matar, pois eles temiam ao povo."}, {"numero": 3, "texto": "E Satanás entrou no Judas que era chamado Iscariotes, que era um dos doze."}, {"numero": 4, "texto": "E foi, e falou com os chefes dos sacerdotes e os oficiais, sobre como [o] entregaria para eles."}, {"numero": 5, "texto": "E [estes] se alegraram, e concordaram em lhe dar dinheiro."}, {"numero": 6, "texto": "E [lhes] prometeu, e buscava oportunidade para o entregar quando não houvesse uma multidão."}, {"numero": 7, "texto": "E veio o dia dos [pães] sem fermento, em que se devia fazer o sacrifício da páscoa."}, {"numero": 8, "texto": "E [Jesus] mandou a Pedro, e a João, dizendo: Ide, preparai-nos a páscoa, para que [a] comamos."}, {"numero": 9, "texto": "E eles lhe disseram: Onde queres que [a] preparemos?"}, {"numero": 10, "texto": "E ele lhes disse: Eis que, quando entrardes na cidade, um homem com um vaso de água vos encontrará; segui-o até a casa onde ele entrar."}, {"numero": 11, "texto": "E direis ao dono da casa: O Mestre te diz: Onde está o salão onde comerei a páscoa com meus discípulos?"}, {"numero": 12, "texto": "Então ele vos mostrará um grande salão já arrumado; preparai-a ali."}, {"numero": 13, "texto": "E indo eles, acharam como lhes tinha dito; e prepararam a páscoa."}, {"numero": 14, "texto": "E vinda a hora, sentou-se [à mesa] ,e com ele os doze apóstolos."}, {"numero": 15, "texto": "E disse-lhes: Muito desejei comer convosco esta páscoa, antes que eu sofra."}, {"numero": 16, "texto": "Porque eu vos digo, que dela não mais comerei, até que [isto] se cumpra no Reino de Deus."}, {"numero": 17, "texto": "E tomando o copo, e tendo agradecido [a Deus] ,disse: Tomai-o, e reparti [-o] entre vós."}, {"numero": 18, "texto": "Porque vos digo, que do fruto da videira eu não beberei, até que o Reino de Deus venha."}, {"numero": 19, "texto": "E tomando o pão, e tendo agradecido [a Deus] ,partiu-o, e o deu a eles, dizendo: Isto é o meu corpo, que é dado por vós; fazei isto em memória de mim."}, {"numero": 20, "texto": "De modo semelhante também com o copo, depois da ceia, disse: Este copo [é] o Novo Testamento em meu sangue, que é derramado por vós."}, {"numero": 21, "texto": "Porém eis que a mão do que me trai [está] comigo à mesa."}, {"numero": 22, "texto": "E realmente o Filho do homem vai conforme o que está determinado; mas ai daquele homem por quem é traído!"}, {"numero": 23, "texto": "E começaram a perguntar entre si, qual deles seria o que faria isto."}, {"numero": 24, "texto": "E houve também uma briga entre eles, sobre qual deles era considerado o maior."}, {"numero": 25, "texto": "E [Jesus] lhes disse: Os reis dos gentios os dominam, e os que exercem autoridade sobre eles são chamados de benfeitores;"}, {"numero": 26, "texto": "Mas não [seja] assim entre vós; antes o maior de vós seja como o menor; e o que lidera, como o que serve."}, {"numero": 27, "texto": "Porque qual é maior? O que se senta [à mesa] ,ou o que serve? Por acaso não é o que se senta [à mesa] ? Porém eu estou entre vós como aquele que serve."}, {"numero": 28, "texto": "E vós sois os que tendes permanecido comigo em minhas tentações."}, {"numero": 29, "texto": "E eu vos determino um Reino, assim como meu pai o determinou a mim."}, {"numero": 30, "texto": "Para que em meu Reino, comais e bebais à minha mesa; e vos senteis sobre tronos, julgando as doze tribos de Israel."}, {"numero": 31, "texto": "Disse também o Senhor: Simão, Simão; eis que Satanás vos pediu, para [vos] peneirar como trigo;"}, {"numero": 32, "texto": "Mas eu roguei por ti, que tua fé não se acabe; e quando tu te converteres, fortaleça teus irmãos."}, {"numero": 33, "texto": "E ele lhe disse: Senhor, estou preparado para ir contigo até à prisão, e à morte."}, {"numero": 34, "texto": "Mas ele disse: Pedro, eu te digo que hoje o galo não cantará, antes que me negues três vezes que me conheces."}, {"numero": 35, "texto": "E disse a eles: Quando vos mandei sem bolsa, e sem sacola, e sem sandálias, por acaso algo vos faltou?E disseram: Nada."}, {"numero": 36, "texto": "Então, ele lhes disse: Mas agora, quem tem bolsa, tome-a, como também a sacola; e o que não tem espada, venda sua roupa, e compre uma."}, {"numero": 37, "texto": "Porque eu vos digo, que ainda é necessário que se cumpra em mim aquilo que está escrito: E ele foi contado com os malfeitores. Porque aquilo que é sobre mim tem que se cumprir."}, {"numero": 38, "texto": "E eles disseram: Senhor, eis aqui duas espadas.E ele lhes disse: É o suficiente."}, {"numero": 39, "texto": "E saindo, foi, como de costume, para o monte das Oliveiras; e os seus discípulos também o seguiram."}, {"numero": 40, "texto": "E quando chegou a aquele lugar, disse-lhes: Orai para que não entreis em tentação."}, {"numero": 41, "texto": "E se afastou deles, [à distância] de um tiro de pedra. E pondo-se de joelhos, orava,"}, {"numero": 42, "texto": "Dizendo: Pai, se tu quiseres, passa este copo de mim; porém não se faça minha vontade, mas a tua."}, {"numero": 43, "texto": "E apareceu-lhe um anjo do céu, que o fortalecia."}, {"numero": 44, "texto": "E estando em angústia, orava mais intensamente. E seu suor se fez como gotas de sangue, que desciam até o chão."}, {"numero": 45, "texto": "E ele, levantando-se da oração, veio a seus discípulos, e os achou dormindo por causa da tristeza."}, {"numero": 46, "texto": "E disse-lhes: Por que estais dormindo? Levantai-vos, e orai, para que não entreis em tentação."}, {"numero": 47, "texto": "E enquanto ele ainda estava falando, eis que uma multidão [chegou] ; e um dos doze, o que se chamava Judas, ia adiante deles, e se aproximou de Jesus, para o beijar."}, {"numero": 48, "texto": "E Jesus lhe disse: Judas, com um beijo trais ao Filho do homem?"}, {"numero": 49, "texto": "E os que estavam com ele, vendo o que iria acontecer, disseram-lhe: Senhor, feriremos com a espada?"}, {"numero": 50, "texto": "E um deles feriu a um servo do chefe dos sacerdotes, e cortou-lhe a orelha direita."}, {"numero": 51, "texto": "E respondendo Jesus, disse: Para com isto! E tocando-lhe a orelha, o curou."}, {"numero": 52, "texto": "E disse Jesus aos chefes dos sacerdotes, e aos oficiais do Templo, e aos anciãos, que tinham vindo contra ele: Como [se eu fosse] ladrão, saístes com espadas e bastões?"}, {"numero": 53, "texto": "Estando eu convosco todo dia no Templo, contra mim não me prendestes; mas esta é a vossa hora, e [sob] a autoridade das trevas."}, {"numero": 54, "texto": "E prendendo-o, [o] trouxeram e o puseram na casa do sumo sacerdote. E Pedro [o] seguia de longe."}, {"numero": 55, "texto": "E acenderam fogo no meio do pátio, e sentaram-se juntos, e Pedro se sentou entre eles."}, {"numero": 56, "texto": "E uma serva, vendo-o sentado junto ao fogo, fixando o olhos nele, disse: Este também estava com ele."}, {"numero": 57, "texto": "Porém ele o negou, dizendo: Mulher, eu não o conheço."}, {"numero": 58, "texto": "E pouco depois, outro o viu, e disse: Também tu és um deles."}, {"numero": 59, "texto": "E quando já tinha passado quase uma hora, outro afirmava, dizendo: Verdadeiramente também este estava com ele, porque também é galileu."}, {"numero": 60, "texto": "E Pedro disse: Homem, não sei o que dizes.E logo, estando ele ainda falando, cantou o galo."}, {"numero": 61, "texto": "E o Senhor, virando-se, olhou para Pedro; e Pedro se lembrou da palavra do Senhor, como lhe tinha dito: Antes que o galo cante, tu me negarás três vezes."}, {"numero": 62, "texto": "E Pedro, saindo, chorou amargamente."}, {"numero": 63, "texto": "E os homens que tinham prendido a Jesus zombavam dele, ferindo-o;"}, {"numero": 64, "texto": "E cobrindo-o, feriam-no no rosto; e perguntavam-lhe, dizendo: Profetiza, quem é o que te feriu?"}, {"numero": 65, "texto": "E diziam muitas outras coisas contra ele, insultando-o."}, {"numero": 66, "texto": "E quando já era de dia, juntaram-se os anciãos do povo, e os chefes dos sacerdotes, e os escribas, e o trouxeram ao supremo conselho,"}, {"numero": 67, "texto": "dizendo, Tu és o Cristo? Dize-nos. E ele lhes disse: Se eu vos disser, não o crereis."}, {"numero": 68, "texto": "E também se eu perguntar, não me respondereis, nem [me] soltareis."}, {"numero": 69, "texto": "A partir de agora o Filho do homem se sentará à direita do poder de Deus."}, {"numero": 70, "texto": "E todos disseram: Então tu és o Filho de Deus?E ele lhes disse: Vós dizeis que eu sou."}, {"numero": 71, "texto": "E eles disseram: Para que precisamos de mais testemunho? Pois nós mesmos o ouvimos de sua boca."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 22, 'en', '[{"numero": 1, "texto": "Now the feast of unleavened bread drew nigh, which is called the Passover."}, {"numero": 2, "texto": "And the chief priests and scribes sought how they might kill him; for they feared the people."}, {"numero": 3, "texto": "Then entered Satan into Judas surnamed Iscariot, being of the number of the twelve."}, {"numero": 4, "texto": "And he went his way, and communed with the chief priests and captains, how he might betray him unto them."}, {"numero": 5, "texto": "And they were glad, and covenanted to give him money."}, {"numero": 6, "texto": "And he promised, and sought opportunity to betray him unto them in the absence of the multitude."}, {"numero": 7, "texto": "Then came the day of unleavened bread, when the passover must be killed."}, {"numero": 8, "texto": "And he sent Peter and John, saying, Go and prepare us the passover, that we may eat."}, {"numero": 9, "texto": "And they said unto him, Where wilt thou that we prepare?"}, {"numero": 10, "texto": "And he said unto them, Behold, when ye are entered into the city, there shall a man meet you, bearing a pitcher of water; follow him into the house where he entereth in."}, {"numero": 11, "texto": "And ye shall say unto the goodman of the house, The Master saith unto thee, Where is the guestchamber, where I shall eat the passover with my disciples?"}, {"numero": 12, "texto": "And he shall shew you a large upper room furnished: there make ready."}, {"numero": 13, "texto": "And they went, and found as he had said unto them: and they made ready the passover."}, {"numero": 14, "texto": "And when the hour was come, he sat down, and the twelve apostles with him."}, {"numero": 15, "texto": "And he said unto them, With desire I have desired to eat this passover with you before I suffer:"}, {"numero": 16, "texto": "For I say unto you, I will not any more eat thereof, until it be fulfilled in the kingdom of God."}, {"numero": 17, "texto": "And he took the cup, and gave thanks, and said, Take this, and divide it among yourselves:"}, {"numero": 18, "texto": "For I say unto you, I will not drink of the fruit of the vine, until the kingdom of God shall come."}, {"numero": 19, "texto": "And he took bread, and gave thanks, and brake it, and gave unto them, saying, This is my body which is given for you: this do in remembrance of me."}, {"numero": 20, "texto": "Likewise also the cup after supper, saying, This cup is the new testament in my blood, which is shed for you."}, {"numero": 21, "texto": "But, behold, the hand of him that betrayeth me is with me on the table."}, {"numero": 22, "texto": "And truly the Son of man goeth, as it was determined: but woe unto that man by whom he is betrayed!"}, {"numero": 23, "texto": "And they began to enquire among themselves, which of them it was that should do this thing."}, {"numero": 24, "texto": "And there was also a strife among them, which of them should be accounted the greatest."}, {"numero": 25, "texto": "And he said unto them, The kings of the Gentiles exercise lordship over them; and they that exercise authority upon them are called benefactors."}, {"numero": 26, "texto": "But ye shall not be so: but he that is greatest among you, let him be as the younger; and he that is chief, as he that doth serve."}, {"numero": 27, "texto": "For whether is greater, he that sitteth at meat, or he that serveth? is not he that sitteth at meat? but I am among you as he that serveth."}, {"numero": 28, "texto": "Ye are they which have continued with me in my temptations."}, {"numero": 29, "texto": "And I appoint unto you a kingdom, as my Father hath appointed unto me;"}, {"numero": 30, "texto": "That ye may eat and drink at my table in my kingdom, and sit on thrones judging the twelve tribes of Israel."}, {"numero": 31, "texto": "And the Lord said, Simon, Simon, behold, Satan hath desired to have you, that he may sift you as wheat:"}, {"numero": 32, "texto": "But I have prayed for thee, that thy faith fail not: and when thou art converted, strengthen thy brethren."}, {"numero": 33, "texto": "And he said unto him, Lord, I am ready to go with thee, both into prison, and to death."}, {"numero": 34, "texto": "And he said, I tell thee, Peter, the cock shall not crow this day, before that thou shalt thrice deny that thou knowest me."}, {"numero": 35, "texto": "And he said unto them, When I sent you without purse, and scrip, and shoes, lacked ye any thing? And they said, Nothing."}, {"numero": 36, "texto": "Then said he unto them, But now, he that hath a purse, let him take it, and likewise his scrip: and he that hath no sword, let him sell his garment, and buy one."}, {"numero": 37, "texto": "For I say unto you, that this that is written must yet be accomplished in me, And he was reckoned among the transgressors: for the things concerning me have an end."}, {"numero": 38, "texto": "And they said, Lord, behold, here are two swords. And he said unto them, It is enough."}, {"numero": 39, "texto": "And he came out, and went, as he was wont, to the mount of Olives; and his disciples also followed him."}, {"numero": 40, "texto": "And when he was at the place, he said unto them, Pray that ye enter not into temptation."}, {"numero": 41, "texto": "And he was withdrawn from them about a stone''s cast, and kneeled down, and prayed,"}, {"numero": 42, "texto": "Saying, Father, if thou be willing, remove this cup from me: nevertheless not my will, but thine, be done."}, {"numero": 43, "texto": "And there appeared an angel unto him from heaven, strengthening him."}, {"numero": 44, "texto": "And being in an agony he prayed more earnestly: and his sweat was as it were great drops of blood falling down to the ground."}, {"numero": 45, "texto": "And when he rose up from prayer, and was come to his disciples, he found them sleeping for sorrow,"}, {"numero": 46, "texto": "And said unto them, Why sleep ye? rise and pray, lest ye enter into temptation."}, {"numero": 47, "texto": "And while he yet spake, behold a multitude, and he that was called Judas, one of the twelve, went before them, and drew near unto Jesus to kiss him."}, {"numero": 48, "texto": "But Jesus said unto him, Judas, betrayest thou the Son of man with a kiss?"}, {"numero": 49, "texto": "When they which were about him saw what would follow, they said unto him, Lord, shall we smite with the sword?"}, {"numero": 50, "texto": "And one of them smote the servant of the high priest, and cut off his right ear."}, {"numero": 51, "texto": "And Jesus answered and said, Suffer ye thus far. And he touched his ear, and healed him."}, {"numero": 52, "texto": "Then Jesus said unto the chief priests, and captains of the temple, and the elders, which were come to him, Be ye come out, as against a thief, with swords and staves?"}, {"numero": 53, "texto": "When I was daily with you in the temple, ye stretched forth no hands against me: but this is your hour, and the power of darkness."}, {"numero": 54, "texto": "Then took they him, and led him, and brought him into the high priest''s house. And Peter followed afar off."}, {"numero": 55, "texto": "And when they had kindled a fire in the midst of the hall, and were set down together, Peter sat down among them."}, {"numero": 56, "texto": "But a certain maid beheld him as he sat by the fire, and earnestly looked upon him, and said, This man was also with him."}, {"numero": 57, "texto": "And he denied him, saying, Woman, I know him not."}, {"numero": 58, "texto": "And after a little while another saw him, and said, Thou art also of them. And Peter said, Man, I am not."}, {"numero": 59, "texto": "And about the space of one hour after another confidently affirmed, saying, Of a truth this fellow also was with him: for he is a Galilaean."}, {"numero": 60, "texto": "And Peter said, Man, I know not what thou sayest. And immediately, while he yet spake, the cock crew."}, {"numero": 61, "texto": "And the Lord turned, and looked upon Peter. And Peter remembered the word of the Lord, how he had said unto him, Before the cock crow, thou shalt deny me thrice."}, {"numero": 62, "texto": "And Peter went out, and wept bitterly."}, {"numero": 63, "texto": "And the men that held Jesus mocked him, and smote him."}, {"numero": 64, "texto": "And when they had blindfolded him, they struck him on the face, and asked him, saying, Prophesy, who is it that smote thee?"}, {"numero": 65, "texto": "And many other things blasphemously spake they against him."}, {"numero": 66, "texto": "And as soon as it was day, the elders of the people and the chief priests and the scribes came together, and led him into their council, saying,"}, {"numero": 67, "texto": "Art thou the Christ? tell us. And he said unto them, If I tell you, ye will not believe:"}, {"numero": 68, "texto": "And if I also ask you, ye will not answer me, nor let me go."}, {"numero": 69, "texto": "Hereafter shall the Son of man sit on the right hand of the power of God."}, {"numero": 70, "texto": "Then said they all, Art thou then the Son of God? And he said unto them, Ye say that I am."}, {"numero": 71, "texto": "And they said, What need we any further witness? for we ourselves have heard of his own mouth."}]'::jsonb, 'King James Version'),
  ('Lc', 22, 'fr', '[{"numero": 1, "texto": "La fête des pains sans levain, appelée la Pâque, approchait."}, {"numero": 2, "texto": "Les principaux sacrificateurs et les scribes cherchaient les moyens de faire mourir Jésus; car ils craignaient le peuple."}, {"numero": 3, "texto": "Or, Satan entra dans Judas, surnommé Iscariot, qui était du nombre des douze."}, {"numero": 4, "texto": "Et Judas alla s''''entendre avec les principaux sacrificateurs et les chefs des gardes, sur la manière de le leur livrer."}, {"numero": 5, "texto": "Ils furent dans la joie, et ils convinrent de lui donner de l''''argent."}, {"numero": 6, "texto": "Après s''''être engagé, il cherchait une occasion favorable pour leur livrer Jésus à l''''insu de la foule."}, {"numero": 7, "texto": "Le jour des pains sans levain, où l''''on devait immoler la Pâque, arriva,"}, {"numero": 8, "texto": "et Jésus envoya Pierre et Jean, en disant: Allez nous préparer la Pâque, afin que nous la mangions."}, {"numero": 9, "texto": "Ils lui dirent: Où veux-tu que nous la préparions?"}, {"numero": 10, "texto": "Il leur répondit: Voici, quand vous serez entrés dans la ville, vous rencontrerez un homme portant une cruche d''''eau; suivez-le dans la maison où il entrera,"}, {"numero": 11, "texto": "et vous direz au maître de la maison: Le maître te dit: Où est le lieu où je mangerai la Pâque avec mes disciples?"}, {"numero": 12, "texto": "Et il vous montrera une grande chambre haute, meublée: c''''est là que vous préparerez la Pâque."}, {"numero": 13, "texto": "Ils partirent, et trouvèrent les choses comme il le leur avait dit; et ils préparèrent la Pâque."}, {"numero": 14, "texto": "L''''heure étant venue, il se mit à table, et les apôtres avec lui."}, {"numero": 15, "texto": "Il leur dit: J''''ai désiré vivement manger cette Pâque avec vous, avant de souffrir;"}, {"numero": 16, "texto": "car, je vous le dis, je ne la mangerai plus, jusqu''''à ce qu''''elle soit accomplie dans le royaume de Dieu."}, {"numero": 17, "texto": "Et, ayant pris une coupe et rendu grâces, il dit: Prenez cette coupe, et distribuez-la entre vous;"}, {"numero": 18, "texto": "car, je vous le dis, je ne boirai plus désormais du fruit de la vigne, jusqu''''à ce que le royaume de Dieu soit venu."}, {"numero": 19, "texto": "Ensuite il prit du pain; et, après avoir rendu grâces, il le rompit, et le leur donna, en disant: Ceci est mon corps, qui est donné pour vous; faites ceci en mémoire de moi."}, {"numero": 20, "texto": "Il prit de même la coupe, après le souper, et la leur donna, en disant: Cette coupe est la nouvelle alliance en mon sang, qui est répandu pour vous."}, {"numero": 21, "texto": "Cependant voici, la main de celui qui me livre est avec moi à cette table."}, {"numero": 22, "texto": "Le Fils de l''''homme s''''en va selon ce qui est déterminé. Mais malheur à l''''homme par qui il est livré!"}, {"numero": 23, "texto": "Et ils commencèrent à se demander les uns aux autres qui était celui d''''entre eux qui ferait cela."}, {"numero": 24, "texto": "Il s''''éleva aussi parmi les apôtres une contestation: lequel d''''entre eux devait être estimé le plus grand?"}, {"numero": 25, "texto": "Jésus leur dit: Les rois des nations les maîtrisent, et ceux qui les dominent sont appelés bienfaiteurs."}, {"numero": 26, "texto": "Qu''''il n''''en soit pas de même pour vous. Mais que le plus grand parmi vous soit comme le plus petit, et celui qui gouverne comme celui qui sert."}, {"numero": 27, "texto": "Car quel est le plus grand, celui qui est à table, ou celui qui sert? N''''est-ce pas celui qui est à table? Et moi, cependant, je suis au milieu de vous comme celui qui sert."}, {"numero": 28, "texto": "Vous, vous êtes ceux qui avez persévéré avec moi dans mes épreuves;"}, {"numero": 29, "texto": "c''''est pourquoi je dispose du royaume en votre faveur, comme mon Père en a disposé en ma faveur,"}, {"numero": 30, "texto": "afin que vous mangiez et buviez à ma table dans mon royaume, et que vous soyez assis sur des trônes, pour juger les douze tribus d''''Israël."}, {"numero": 31, "texto": "Le Seigneur dit: Simon, Simon, Satan vous a réclamés, pour vous cribler comme le froment."}, {"numero": 32, "texto": "Mais j''''ai prié pour toi, afin que ta foi ne défaille point; et toi, quand tu seras converti, affermis tes frères."}, {"numero": 33, "texto": "Seigneur, lui dit Pierre, je suis prêt à aller avec toi et en prison et à la mort."}, {"numero": 34, "texto": "Et Jésus dit: Pierre, je te le dis, le coq ne chantera pas aujourd''''hui que tu n''''aies nié trois fois de me connaître."}, {"numero": 35, "texto": "Il leur dit encore: Quand je vous ai envoyés sans bourse, sans sac, et sans souliers, avez-vous manqué de quelque chose? Ils répondirent: De rien."}, {"numero": 36, "texto": "Et il leur dit: Maintenant, au contraire, que celui qui a une bourse la prenne et que celui qui a un sac le prenne également, que celui qui n''''a point d''''épée vende son vêtement et achète une épée."}, {"numero": 37, "texto": "Car, je vous le dis, il faut que cette parole qui est écrite s''''accomplisse en moi: Il a été mis au nombre des malfaiteurs. Et ce qui me concerne est sur le point d''''arriver."}, {"numero": 38, "texto": "Ils dirent: Seigneur, voici deux épées. Et il leur dit: Cela suffit."}, {"numero": 39, "texto": "Après être sorti, il alla, selon sa coutume, à la montagne des oliviers. Ses disciples le suivirent."}, {"numero": 40, "texto": "Lorsqu''''il fut arrivé dans ce lieu, il leur dit: Priez, afin que vous ne tombiez pas en tentation."}, {"numero": 41, "texto": "Puis il s''''éloigna d''''eux à la distance d''''environ un jet de pierre, et, s''''étant mis à genoux, il pria,"}, {"numero": 42, "texto": "disant: Père, si tu voulais éloigner de moi cette coupe! Toutefois, que ma volonté ne se fasse pas, mais la tienne."}, {"numero": 43, "texto": "Alors un ange lui apparut du ciel, pour le fortifier."}, {"numero": 44, "texto": "Etant en agonie, il priait plus instamment, et sa sueur devint comme des grumeaux de sang, qui tombaient à terre."}, {"numero": 45, "texto": "Après avoir prié, il se leva, et vint vers les disciples, qu''''il trouva endormis de tristesse,"}, {"numero": 46, "texto": "et il leur dit: Pourquoi dormez-vous? Levez-vous et priez, afin que vous ne tombiez pas en tentation."}, {"numero": 47, "texto": "Comme il parlait encore, voici, une foule arriva; et celui qui s''''appelait Judas, l''''un des douze, marchait devant elle. Il s''''approcha de Jésus, pour le baiser."}, {"numero": 48, "texto": "Et Jésus lui dit: Judas, c''''est par un baiser que tu livres le Fils de l''''homme!"}, {"numero": 49, "texto": "Ceux qui étaient avec Jésus, voyant ce qui allait arriver, dirent: Seigneur, frapperons-nous de l''''épée?"}, {"numero": 50, "texto": "Et l''''un d''''eux frappa le serviteur du souverain sacrificateur, et lui emporta l''''oreille droite."}, {"numero": 51, "texto": "Mais Jésus, prenant la parole, dit: Laissez, arrêtez! Et, ayant touché l''''oreille de cet homme, il le guérit."}, {"numero": 52, "texto": "Jésus dit ensuite aux principaux sacrificateurs, aux chefs des gardes du temple, et aux anciens, qui étaient venus contre lui: Vous êtes venus, comme après un brigand, avec des épées et des bâtons."}, {"numero": 53, "texto": "J''''étais tous les jours avec vous dans le temple, et vous n''''avez pas mis la main sur moi. Mais c''''est ici votre heure, et la puissance des ténèbres."}, {"numero": 54, "texto": "Après avoir saisi Jésus, ils l''''emmenèrent, et le conduisirent dans la maison du souverain sacrificateur. Pierre suivait de loin."}, {"numero": 55, "texto": "Ils allumèrent du feu au milieu de la cour, et ils s''''assirent. Pierre s''''assit parmi eux."}, {"numero": 56, "texto": "Une servante, qui le vit assis devant le feu, fixa sur lui les regards, et dit: Cet homme était aussi avec lui."}, {"numero": 57, "texto": "Mais il le nia disant: Femme, je ne le connais pas."}, {"numero": 58, "texto": "Peu après, un autre, l''''ayant vu, dit: Tu es aussi de ces gens-là. Et Pierre dit: Homme, je n''''en suis pas."}, {"numero": 59, "texto": "Environ une heure plus tard, un autre insistait, disant: Certainement cet homme était aussi avec lui, car il est Galiléen."}, {"numero": 60, "texto": "Pierre répondit: Homme, je ne sais ce que tu dis. Au même instant, comme il parlait encore, le coq chanta."}, {"numero": 61, "texto": "Le Seigneur, s''''étant retourné, regarda Pierre. Et Pierre se souvint de la parole que le Seigneur lui avait dite: Avant que le coq chante aujourd''''hui, tu me renieras trois fois."}, {"numero": 62, "texto": "Et étant sorti, il pleura amèrement."}, {"numero": 63, "texto": "Les hommes qui tenaient Jésus se moquaient de lui, et le frappaient."}, {"numero": 64, "texto": "Ils lui voilèrent le visage, et ils l''''interrogeaient, en disant: Devine qui t''''a frappé."}, {"numero": 65, "texto": "Et ils proféraient contre lui beaucoup d''''autres injures."}, {"numero": 66, "texto": "Quand le jour fut venu, le collège des anciens du peuple, les principaux sacrificateurs et les scribes, s''''assemblèrent, et firent amener Jésus dans leur sanhédrin. Ils dirent:"}, {"numero": 67, "texto": "Si tu es le Christ, dis-le nous. Jésus leur répondit: Si je vous le dis, vous ne le croirez pas;"}, {"numero": 68, "texto": "et, si je vous interroge, vous ne répondrez pas."}, {"numero": 69, "texto": "Désormais le Fils de l''''homme sera assis à la droite de la puissance de Dieu."}, {"numero": 70, "texto": "Tous dirent: Tu es donc le Fils de Dieu? Et il leur répondit: Vous le dites, je le suis."}, {"numero": 71, "texto": "Alors ils dirent: Qu''''avons-nous encore besoin de témoignage? Nous l''''avons entendu nous-mêmes de sa bouche."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 22, 'es', '[{"numero": 1, "texto": "Y ESTABA cerca el día de la fiesta de los ázimos, que se llama la Pascua."}, {"numero": 2, "texto": "Y los príncipes de los sacerdotes y los escribas buscaban cómo le matarían; mas tenían miedo del pueblo."}, {"numero": 3, "texto": "Y entró Satanás en Judas, por sobrenombre Iscariote, el cual era uno del número de los doce;"}, {"numero": 4, "texto": "Y fué, y habló con los príncipes de los sacerdotes, y con los magistrados, de cómo se lo entregaría."}, {"numero": 5, "texto": "Los cuales se holgaron, y concertaron de darle dinero."}, {"numero": 6, "texto": "Y prometió, y buscaba oportunidad para entregarle á ellos sin bulla."}, {"numero": 7, "texto": "Y vino el día de los ázimos, en el cual era necesario matar la pascua."}, {"numero": 8, "texto": "Y envió á Pedro y á Juan, diciendo: Id, aparejadnos la pascua para que comamos."}, {"numero": 9, "texto": "Y ellos le dijeron: ¿Dónde quieres que aparejemos?"}, {"numero": 10, "texto": "Y él les dijo: He aquí cuando entrareis en la ciudad, os encontrará un hombre que lleva un cántaro de agua: seguidle hasta la casa donde entrare,"}, {"numero": 11, "texto": "Y decid al padre de la familia de la casa: El Maestro te dice: ¿Dónde está el aposento donde tengo de comer la pascua con mis discípulos?"}, {"numero": 12, "texto": "Entonces él os mostrará un gran cenáculo aderezado; aparejad allí."}, {"numero": 13, "texto": "Fueron pues, y hallaron como les había dicho; y aparejaron la pascua."}, {"numero": 14, "texto": "Y como fué hora, sentóse á la mesa, y con él los apóstoles."}, {"numero": 15, "texto": "Y les dijo: En gran manera he deseado comer con vosotros esta pascua antes que padezca;"}, {"numero": 16, "texto": "Porque os digo que no comeré más de ella, hasta que se cumpla en el reino de Dios."}, {"numero": 17, "texto": "Y tomando el vaso, habiendo dado gracias, dijo: Tomad esto, y partidlo entre vosotros;"}, {"numero": 18, "texto": "Porque os digo, que no beberé más del fruto de la vid, hasta que el reino de Dios venga."}, {"numero": 19, "texto": "Y tomando el pan, habiendo dado gracias, partió, y les dió, diciendo: Esto es mi cuerpo, que por vosotros es dado: haced esto en memoria de mí."}, {"numero": 20, "texto": "Asimismo también el vaso, después que hubo cenado, diciendo: Este vaso es el nuevo pacto en mi sangre, que por vosotros se derrama."}, {"numero": 21, "texto": "Con todo eso, he aquí la mano del que me entrega, conmigo en la mesa."}, {"numero": 22, "texto": "Y á la verdad el Hijo del hombre va, según lo que está determinado; empero ¡ay de aquel hombre por el cual es entregado!"}, {"numero": 23, "texto": "Ellos entonces comenzaron á preguntar entre sí, cuál de ellos sería el que había de hacer esto."}, {"numero": 24, "texto": "Y hubo entre ellos una contienda, quién de ellos parecía ser el mayor."}, {"numero": 25, "texto": "Entonces él les dijo: Los reyes de las gentes se enseñorean de ellas; y los que sobre ellas tienen potestad, son llamados bienhechores:"}, {"numero": 26, "texto": "Mas vosotros, no así: antes el que es mayor entre vosotros, sea como el más mozo; y el que es príncipe, como el que sirve."}, {"numero": 27, "texto": "Porque, ¿cuál es mayor, el que se sienta á la mesa, ó el que sirve? ¿No es el que se sienta á la mesa? Y yo soy entre vosotros como el que sirve."}, {"numero": 28, "texto": "Empero vosotros sois los que habéis permanecido conmigo en mis tentaciones:"}, {"numero": 29, "texto": "Yo pues os ordeno un reino, como mi Padre me lo ordenó á mí,"}, {"numero": 30, "texto": "Para que comáis y bebáis en mi mesa en mi reino, y os sentéis sobre tronos juzgando á las doce tribus de Israel."}, {"numero": 31, "texto": "Dijo también el Señor: Simón, Simón, he aquí Satanás os ha pedido para zarandaros como á trigo;"}, {"numero": 32, "texto": "Mas yo he rogado por ti que tu fe no falte: y tú, una vez vuelto, confirma á tus hermanos."}, {"numero": 33, "texto": "Y él le dijo: Señor, pronto estoy á ir contigo aun á cárcel y á muerte."}, {"numero": 34, "texto": "Y él dijo: Pedro, te digo que el gallo no cantará hoy antes que tú niegues tres veces que me conoces."}, {"numero": 35, "texto": "Y á ellos dijo: Cuando os envié sin bolsa, y sin alforja, y sin zapatos, ¿os faltó algo? Y ellos dijeron: Nada."}, {"numero": 36, "texto": "Y les dijo: Pues ahora, el que tiene bolsa, tómela, y también la alforja, y el que no tiene, venda su capa y compre espada."}, {"numero": 37, "texto": "Porque os digo, que es necesario que se cumpla todavía en mí aquello que está escrito: Y con los malos fué contado: porque lo que está escrito de mí, cumplimiento tiene."}, {"numero": 38, "texto": "Entonces ellos dijeron: Señor, he aquí dos espadas. Y él les dijo: Basta."}, {"numero": 39, "texto": "Y saliendo, se fué, como solía, al monte de las Olivas; y sus discípulos también le siguieron."}, {"numero": 40, "texto": "Y como llegó á aquel lugar, les dijo: Orad que no entréis en tentación."}, {"numero": 41, "texto": "Y él se apartó de ellos como un tiro de piedra; y puesto de rodillas oró,"}, {"numero": 42, "texto": "Diciendo: Padre, si quieres, pasa este vaso de mí; empero no se haga mi voluntad, sino la tuya."}, {"numero": 43, "texto": "Y le apareció un ángel del cielo confortándole."}, {"numero": 44, "texto": "Y estando en agonía, oraba más intensamente: y fué su sudor como grandes gotas de sangre que caían hasta la tierra."}, {"numero": 45, "texto": "Y como se levantó de la oración, y vino á sus discípulos, hallólos durmiendo de tristeza;"}, {"numero": 46, "texto": "Y les dijo: ¿Por qué dormís? Levantaos, y orad que no entréis en tentación."}, {"numero": 47, "texto": "Estando él aún hablando, he aquí una turba; y el que se llamaba Judas, uno de los doce, iba delante de ellos; y llegóse á Jesús para besarlo."}, {"numero": 48, "texto": "Entonces Jesús le dijo: Judas, ¿con beso entregas al Hijo del hombre?"}, {"numero": 49, "texto": "Y viendo los que estaban con él lo que había de ser, le dijeron: Señor, ¿heriremos á cuchillo?"}, {"numero": 50, "texto": "Y uno de ellos hirió á un siervo del príncipe de los sacerdotes, y le quitó la oreja derecha."}, {"numero": 51, "texto": "Entonces respondiendo Jesús, dijo: Dejad hasta aquí. Y tocando su oreja, le sanó."}, {"numero": 52, "texto": "Y Jesús dijo á los que habían venido á él, los príncipes de los sacerdotes, y los magistrados del templo, y los ancianos: ¿Como á ladrón habéis salido con espadas y con palos?"}, {"numero": 53, "texto": "Habiendo estado con vosotros cada día en el templo, no extendisteis las manos contra mí; mas ésta es vuestra hora, y la potestad de las tinieblas."}, {"numero": 54, "texto": "Y prendiéndole trajéronle, y metiéronle en casa del príncipe de los sacerdotes. Y Pedro le seguía de lejos."}, {"numero": 55, "texto": "Y habiendo encendido fuego en medio de la sala, y sentándose todos alrededor, se sentó también Pedro entre ellos."}, {"numero": 56, "texto": "Y como una criada le vió que estaba sentado al fuego, fijóse en él, y dijo: Y éste con él estaba."}, {"numero": 57, "texto": "Entonces él lo negó, diciendo: Mujer, no le conozco."}, {"numero": 58, "texto": "Y un poco después, viéndole otro, dijo: Y tú de ellos eras. Y Pedro dijo: Hombre, no soy."}, {"numero": 59, "texto": "Y como una hora pasada otro afirmaba, diciendo: Verdaderamente también éste estaba con él, porque es Galileo."}, {"numero": 60, "texto": "Y Pedro dijo: Hombre, no sé qué dices. Y luego, estando él aún hablando, el gallo cantó."}, {"numero": 61, "texto": "Entonces, vuelto el Señor, miró á Pedro: y Pedro se acordó de la palabra del Señor como le había dicho: Antes que el gallo cante, me negarás tres veces."}, {"numero": 62, "texto": "Y saliendo fuera Pedro, lloró amargamente."}, {"numero": 63, "texto": "Y los hombres que tenían á Jesús, se burlaban de él hiriéndole;"}, {"numero": 64, "texto": "Y cubriéndole, herían su rostro, y preguntábanle, diciendo: Profetiza quién es el que te hirió."}, {"numero": 65, "texto": "Y decían otras muchas cosas injuriándole."}, {"numero": 66, "texto": "Y cuando fué de día, se juntaron los ancianos del pueblo, y los príncipes de los sacerdotes, y los escribas, y le trajeron á su concilio,"}, {"numero": 67, "texto": "Diciendo: ¿Eres tú el Cristo? dínoslo. Y les dijo: Si os lo dijere, no creeréis;"}, {"numero": 68, "texto": "Y también si os preguntare, no me responderéis, ni me soltaréis:"}, {"numero": 69, "texto": "Mas después de ahora el Hijo del hombre se asentará á la diestra de la potencia de Dios."}, {"numero": 70, "texto": "Y dijeron todos: ¿Luego tú eres Hijo de Dios? Y él les dijo: Vosotros decís que yo soy."}, {"numero": 71, "texto": "Entonces ellos dijeron: ¿Qué más testimonio deseamos? porque nosotros lo hemos oído de su boca."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 23, 'pt', '[{"numero": 1, "texto": "E levantando-se toda a multidão deles, o levaram a Pilatos."}, {"numero": 2, "texto": "E começaram a acusá-lo, dizendo: Encontramos este [homem] ,que perverte a nação, e proíbe dar tributo a César, dizendo que ele mesmo é Cristo, o Rei."}, {"numero": 3, "texto": "E Pilatos lhe perguntou, dizendo: Tu és o Rei dos judeus?E respondendo, ele lhe disse: Tu o dizes."}, {"numero": 4, "texto": "E Pilatos disse aos chefes dos sacerdotes, e às multidões: Não acho culpa nenhuma neste homem."}, {"numero": 5, "texto": "Mas eles insistiam, dizendo: Ele incita ao povo, ensinando por toda a Judeia, começando desde a Galileia até aqui."}, {"numero": 6, "texto": "Então Pilatos, ouvindo [falar] da Galileia, perguntou se aquele homem era galileu."}, {"numero": 7, "texto": "E quando soube que era da jurisdição de Herodes, ele o entregou a Herodes, que naqueles dias também estava em Jerusalém."}, {"numero": 8, "texto": "E Herodes, ao ver Jesus, alegrou-se muito, porque havia muito tempo que desejava o ver, pois ouvia muitas coisas sobre ele; e esperava ver algum sinal feito por ele."}, {"numero": 9, "texto": "E perguntava-lhe com muitas palavras, mas ele nada lhe respondia;"}, {"numero": 10, "texto": "E estavam [lá] os chefes dos sacerdotes, e os escribas, acusando-o com veemência."}, {"numero": 11, "texto": "E Herodes, com seus soldados, desprezando-o, e escarnecendo dele, o vestiu com uma roupa luxuosa, e o enviou de volta a Pilatos."}, {"numero": 12, "texto": "E no mesmo dia Pilatos e Herodes se fizeram amigos; porque antes tinham inimizade um contra o outro."}, {"numero": 13, "texto": "E Pilatos, convocando aos chefes dos sacerdotes, aos líderes, e ao povo, disse-lhes:"}, {"numero": 14, "texto": "Vós me trouxestes a este homem, como que perverte o povo; e eis que eu, examinando-o em vossa presença, nenhuma culpa eu acho neste homem, das de que o acusais."}, {"numero": 15, "texto": "E nem também Herodes; porque a ele eu vos remeti; e eis que ele nada fez para que seja digno de morte."}, {"numero": 16, "texto": "Então eu o castigarei, e [depois] o soltarei."}, {"numero": 17, "texto": "E ele tinha de soltar-lhes alguém durante a festa."}, {"numero": 18, "texto": "Porém todos clamavam juntos, dizendo: Tirai-o daqui! E soltai Barrabás para nós!"}, {"numero": 19, "texto": "(O qual por uma rebelião feita na cidade, e [por] uma morte, tinha sido lançado na prisão)."}, {"numero": 20, "texto": "Pilatos falou-lhes então outra vez, querendo soltar Jesus."}, {"numero": 21, "texto": "Mas eles clamavam, dizendo: Crucifica [-o] ! crucifica-o!"}, {"numero": 22, "texto": "E ele lhes disse a terceira vez: Pois que mal este fez? Nenhuma culpa de morte nele eu achei. Então eu o castigarei, e [depois] o soltarei."}, {"numero": 23, "texto": "Mas eles continuavam, com grandes gritos, pedindo que fosse crucificado. E seus gritos, e [os] dos chefes dos sacerdotes, prevaleceram."}, {"numero": 24, "texto": "Então Pilatos julgou que se fizesse o que pediam."}, {"numero": 25, "texto": "E soltou-lhes ao que fora lançado na prisão por uma rebelião e [uma] morte, que [era] o que pediam; porém a Jesus [lhes] entregou à sua vontade."}, {"numero": 26, "texto": "E enquanto o levavam, tomaram a um Simão Cireneu, que vinha do campo, e puseram-lhe a cruz às costas, para que a levasse atrás de Jesus."}, {"numero": 27, "texto": "E seguia-o uma grande multidão do povo, e de mulheres, as quais também ficavam desconsoladas, e lamentavam por ele."}, {"numero": 28, "texto": "E Jesus, virando-se para elas, disse: Filhas de Jerusalém, não choreis por mim, mas chorai por vós mesmas, e por vossos filhos."}, {"numero": 29, "texto": "Porque eis que vêm dias em que dirão: Bem-aventuradas as estéreis, e os ventres que não deram a luz, e os peitos que não amamentaram."}, {"numero": 30, "texto": "Então começarão a dizer aos montes: Cai sobre nós; E aos morros: Cobri-nos!"}, {"numero": 31, "texto": "Porque, se fazem isto à árvore verde, o que se fará com a [árvore] seca?"}, {"numero": 32, "texto": "E também levaram outros dois, que eram malfeitores, para matar com ele."}, {"numero": 33, "texto": "E quando chegaram ao lugar, chamado a Caveira, o crucificaram ali, e aos malfeitores, um à direita, e outro à esquerda."}, {"numero": 34, "texto": "E Jesus dizia: Pai, perdoa-lhes, porque não sabem o que fazem. E, repartindo suas roupas, lançaram sortes."}, {"numero": 35, "texto": "E o povo estava olhando; e os líderes também zombavam com eles, dizendo: Salvou a outros, salve agora a si mesmo, se é o Cristo, o escolhido de Deus."}, {"numero": 36, "texto": "E os soldados também escarneciam dele, aproximando-se dele, e mostrando-lhe vinagre;"}, {"numero": 37, "texto": "E dizendo: Se tu és o Rei dos judeus, salva a ti mesmo."}, {"numero": 38, "texto": "E também estava acima dele um título escrito com letras gregas, romanas e hebraicas: ESTE É O REI DOS JUDEUS."}, {"numero": 39, "texto": "E um dos malfeitores que estavam pendurados o insultava, dizendo: Se tu és o Cristo, salva a ti mesmo, e a nós."}, {"numero": 40, "texto": "Porém o outro, respondendo, repreendia-o, dizendo: Tu ainda não temes a Deus, [mesmo] estando na mesma condenação?"}, {"numero": 41, "texto": "E nós realmente [estamos sendo punidos] justamente, porque estamos recebendo de volta merecidamente por aquilo que praticamos; mas este nada fez de errado."}, {"numero": 42, "texto": "E disse a Jesus: Senhor, lembra-te de mim, quando chegares em teu Reino."}, {"numero": 43, "texto": "E Jesus lhe disse: Em verdade te digo, hoje estarás comigo no paraíso."}, {"numero": 44, "texto": "E era já quase a hora sexta, e houve trevas em toda a terra, até a hora nona."}, {"numero": 45, "texto": "E o sol se escureceu, e o véu do templo se rasgou ao meio."}, {"numero": 46, "texto": "E Jesus, clamando em alta voz, disse: Pai, em tuas mãos eu entrego meu espírito.E tendo dito isto, parou de respirar."}, {"numero": 47, "texto": "E o centurião, vendo o o que tinha acontecido, deu glória a Deus, dizendo: Verdadeiramente este homem era justo."}, {"numero": 48, "texto": "E todas as multidões que se juntavam para observar, vendo o que tinha acontecido, voltaram, batendo nos peitos."}, {"numero": 49, "texto": "E todos os seus conhecidos, e as mulheres que acompanhando [-o] desde a Galileia, tinham o seguido, estavam longe, vendo estas coisas."}, {"numero": 50, "texto": "E eis que um homem, de nome José, membro do conselho [de justiça] ,sendo homem bom e justo."}, {"numero": 51, "texto": "(Que não tinha concordado, nem com o conselho, nem em atos que fizeram), da cidade de Arimateia, [da terra] dos judeus, e que também esperava pelo Reino de Deus."}, {"numero": 52, "texto": "Este, chegando a Pilatos, pediu o corpo de Jesus."}, {"numero": 53, "texto": "E tendo o tirado, o envolveu em um tecido de linho, e o pôs em um sepulcro, escavado em uma rocha, onde nunca ainda tinha sido posto."}, {"numero": 54, "texto": "E era o dia da preparação, e o sábado estava começando."}, {"numero": 55, "texto": "E as mulheres que vieram com ele da Galileia também [o] seguiram, e viram o sepulcro, e como seu corpo foi posto."}, {"numero": 56, "texto": "E elas, ao voltarem, prepararam materiais aromáticos e óleos perfumados. E descansaram o sábado, conforme o mandamento."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 23, 'en', '[{"numero": 1, "texto": "And the whole multitude of them arose, and led him unto Pilate."}, {"numero": 2, "texto": "And they began to accuse him, saying, We found this fellow perverting the nation, and forbidding to give tribute to Caesar, saying that he himself is Christ a King."}, {"numero": 3, "texto": "And Pilate asked him, saying, Art thou the King of the Jews? And he answered him and said, Thou sayest it."}, {"numero": 4, "texto": "Then said Pilate to the chief priests and to the people, I find no fault in this man."}, {"numero": 5, "texto": "And they were the more fierce, saying, He stirreth up the people, teaching throughout all Jewry, beginning from Galilee to this place."}, {"numero": 6, "texto": "When Pilate heard of Galilee, he asked whether the man were a Galilaean."}, {"numero": 7, "texto": "And as soon as he knew that he belonged unto Herod''s jurisdiction, he sent him to Herod, who himself also was at Jerusalem at that time."}, {"numero": 8, "texto": "And when Herod saw Jesus, he was exceeding glad: for he was desirous to see him of a long season, because he had heard many things of him; and he hoped to have seen some miracle done by him."}, {"numero": 9, "texto": "Then he questioned with him in many words; but he answered him nothing."}, {"numero": 10, "texto": "And the chief priests and scribes stood and vehemently accused him."}, {"numero": 11, "texto": "And Herod with his men of war set him at nought, and mocked him, and arrayed him in a gorgeous robe, and sent him again to Pilate."}, {"numero": 12, "texto": "And the same day Pilate and Herod were made friends together: for before they were at enmity between themselves."}, {"numero": 13, "texto": "And Pilate, when he had called together the chief priests and the rulers and the people,"}, {"numero": 14, "texto": "Said unto them, Ye have brought this man unto me, as one that perverteth the people: and, behold, I, having examined him before you, have found no fault in this man touching those things whereof ye accuse him:"}, {"numero": 15, "texto": "No, nor yet Herod: for I sent you to him; and, lo, nothing worthy of death is done unto him."}, {"numero": 16, "texto": "I will therefore chastise him, and release him."}, {"numero": 17, "texto": "(For of necessity he must release one unto them at the feast.)"}, {"numero": 18, "texto": "And they cried out all at once, saying, Away with this man, and release unto us Barabbas:"}, {"numero": 19, "texto": "(Who for a certain sedition made in the city, and for murder, was cast into prison.)"}, {"numero": 20, "texto": "Pilate therefore, willing to release Jesus, spake again to them."}, {"numero": 21, "texto": "But they cried, saying, Crucify him, crucify him."}, {"numero": 22, "texto": "And he said unto them the third time, Why, what evil hath he done? I have found no cause of death in him: I will therefore chastise him, and let him go."}, {"numero": 23, "texto": "And they were instant with loud voices, requiring that he might be crucified. And the voices of them and of the chief priests prevailed."}, {"numero": 24, "texto": "And Pilate gave sentence that it should be as they required."}, {"numero": 25, "texto": "And he released unto them him that for sedition and murder was cast into prison, whom they had desired; but he delivered Jesus to their will."}, {"numero": 26, "texto": "And as they led him away, they laid hold upon one Simon, a Cyrenian, coming out of the country, and on him they laid the cross, that he might bear it after Jesus."}, {"numero": 27, "texto": "And there followed him a great company of people, and of women, which also bewailed and lamented him."}, {"numero": 28, "texto": "But Jesus turning unto them said, Daughters of Jerusalem, weep not for me, but weep for yourselves, and for your children."}, {"numero": 29, "texto": "For, behold, the days are coming, in the which they shall say, Blessed are the barren, and the wombs that never bare, and the paps which never gave suck."}, {"numero": 30, "texto": "Then shall they begin to say to the mountains, Fall on us; and to the hills, Cover us."}, {"numero": 31, "texto": "For if they do these things in a green tree, what shall be done in the dry?"}, {"numero": 32, "texto": "And there were also two other, malefactors, led with him to be put to death."}, {"numero": 33, "texto": "And when they were come to the place, which is called Calvary, there they crucified him, and the malefactors, one on the right hand, and the other on the left."}, {"numero": 34, "texto": "Then said Jesus, Father, forgive them; for they know not what they do. And they parted his raiment, and cast lots."}, {"numero": 35, "texto": "And the people stood beholding. And the rulers also with them derided him, saying, He saved others; let him save himself, if he be Christ, the chosen of God."}, {"numero": 36, "texto": "And the soldiers also mocked him, coming to him, and offering him vinegar,"}, {"numero": 37, "texto": "And saying, If thou be the king of the Jews, save thyself."}, {"numero": 38, "texto": "And a superscription also was written over him in letters of Greek, and Latin, and Hebrew, This Is The King Of The Jews."}, {"numero": 39, "texto": "And one of the malefactors which were hanged railed on him, saying, If thou be Christ, save thyself and us."}, {"numero": 40, "texto": "But the other answering rebuked him, saying, Dost not thou fear God, seeing thou art in the same condemnation?"}, {"numero": 41, "texto": "And we indeed justly; for we receive the due reward of our deeds: but this man hath done nothing amiss."}, {"numero": 42, "texto": "And he said unto Jesus, Lord, remember me when thou comest into thy kingdom."}, {"numero": 43, "texto": "And Jesus said unto him, Verily I say unto thee, Today shalt thou be with me in paradise."}, {"numero": 44, "texto": "And it was about the sixth hour, and there was a darkness over all the earth until the ninth hour."}, {"numero": 45, "texto": "And the sun was darkened, and the veil of the temple was rent in the midst."}, {"numero": 46, "texto": "And when Jesus had cried with a loud voice, he said, Father, into thy hands I commend my spirit: and having said thus, he gave up the ghost."}, {"numero": 47, "texto": "Now when the centurion saw what was done, he glorified God, saying, Certainly this was a righteous man."}, {"numero": 48, "texto": "And all the people that came together to that sight, beholding the things which were done, smote their breasts, and returned."}, {"numero": 49, "texto": "And all his acquaintance, and the women that followed him from Galilee, stood afar off, beholding these things."}, {"numero": 50, "texto": "And, behold, there was a man named Joseph, a counsellor; and he was a good man, and a just:"}, {"numero": 51, "texto": "(The same had not consented to the counsel and deed of them;) he was of Arimathaea, a city of the Jews: who also himself waited for the kingdom of God."}, {"numero": 52, "texto": "This man went unto Pilate, and begged the body of Jesus."}, {"numero": 53, "texto": "And he took it down, and wrapped it in linen, and laid it in a sepulchre that was hewn in stone, wherein never man before was laid."}, {"numero": 54, "texto": "And that day was the preparation, and the sabbath drew on."}, {"numero": 55, "texto": "And the women also, which came with him from Galilee, followed after, and beheld the sepulchre, and how his body was laid."}, {"numero": 56, "texto": "And they returned, and prepared spices and ointments; and rested the sabbath day according to the commandment."}]'::jsonb, 'King James Version'),
  ('Lc', 23, 'fr', '[{"numero": 1, "texto": "Ils se levèrent tous, et ils conduisirent Jésus devant Pilate."}, {"numero": 2, "texto": "Ils se mirent à l''''accuser, disant: Nous avons trouvé cet homme excitant notre nation à la révolte, empêchant de payer le tribut à César, et se disant lui-même Christ, roi."}, {"numero": 3, "texto": "Pilate l''''interrogea, en ces termes: Es-tu le roi des Juifs? Jésus lui répondit: Tu le dis."}, {"numero": 4, "texto": "Pilate dit aux principaux sacrificateurs et à la foule: Je ne trouve rien de coupable en cet homme."}, {"numero": 5, "texto": "Mais ils insistèrent, et dirent: Il soulève le peuple, en enseignant par toute la Judée, depuis la Galilée, où il a commencé, jusqu''''ici."}, {"numero": 6, "texto": "Quand Pilate entendit parler de la Galilée, il demanda si cet homme était Galiléen;"}, {"numero": 7, "texto": "et, ayant appris qu''''il était de la juridiction d''''Hérode, il le renvoya à Hérode, qui se trouvait aussi à Jérusalem en ces jours-là."}, {"numero": 8, "texto": "Lorsque Hérode vit Jésus, il en eut une grande joie; car depuis longtemps, il désirait le voir, à cause de ce qu''''il avait entendu dire de lui, et il espérait qu''''il le verrait faire quelque miracle."}, {"numero": 9, "texto": "Il lui adressa beaucoup de questions; mais Jésus ne lui répondit rien."}, {"numero": 10, "texto": "Les principaux sacrificateurs et les scribes étaient là, et l''''accusaient avec violence."}, {"numero": 11, "texto": "Hérode, avec ses gardes, le traita avec mépris; et, après s''''être moqué de lui et l''''avoir revêtu d''''un habit éclatant, il le renvoya à Pilate."}, {"numero": 12, "texto": "Ce jour même, Pilate et Hérode devinrent amis, d''''ennemis qu''''ils étaient auparavant."}, {"numero": 13, "texto": "Pilate, ayant assemblé les principaux sacrificateurs, les magistrats, et le peuple,"}, {"numero": 14, "texto": "leur dit: Vous m''''avez amené cet homme comme excitant le peuple à la révolte. Et voici, je l''''ai interrogé devant vous, et je ne l''''ai trouvé coupable d''''aucune des choses dont vous l''''accusez;"}, {"numero": 15, "texto": "Hérode non plus, car il nous l''''a renvoyé, et voici, cet homme n''''a rien fait qui soit digne de mort."}, {"numero": 16, "texto": "Je le relâcherai donc, après l''''avoir fait battre de verges."}, {"numero": 17, "texto": "A chaque fête, il était obligé de leur relâcher un prisonnier."}, {"numero": 18, "texto": "Ils s''''écrièrent tous ensemble: Fais mourir celui-ci, et relâche-nous Barabbas."}, {"numero": 19, "texto": "Cet homme avait été mis en prison pour une sédition qui avait eu lieu dans la ville, et pour un meurtre."}, {"numero": 20, "texto": "Pilate leur parla de nouveau, dans l''''intention de relâcher Jésus."}, {"numero": 21, "texto": "Et ils crièrent: Crucifie, crucifie-le!"}, {"numero": 22, "texto": "Pilate leur dit pour la troisième fois: Quel mal a-t-il fait? Je n''''ai rien trouvé en lui qui mérite la mort. Je le relâcherai donc, après l''''avoir fait battre de verges."}, {"numero": 23, "texto": "Mais ils insistèrent à grands cris, demandant qu''''il fût crucifié. Et leurs cris l''''emportèrent:"}, {"numero": 24, "texto": "Pilate prononça que ce qu''''ils demandaient serait fait."}, {"numero": 25, "texto": "Il relâcha celui qui avait été mis en prison pour sédition et pour meurtre, et qu''''ils réclamaient; et il livra Jésus à leur volonté."}, {"numero": 26, "texto": "Comme ils l''''emmenaient, ils prirent un certain Simon de Cyrène, qui revenait des champs, et ils le chargèrent de la croix, pour qu''''il la porte derrière Jésus."}, {"numero": 27, "texto": "Il était suivi d''''une grande multitude des gens du peuple, et de femmes qui se frappaient la poitrine et se lamentaient sur lui."}, {"numero": 28, "texto": "Jésus se tourna vers elles, et dit: Filles de Jérusalem, ne pleurez pas sur moi; mais pleurez sur vous et sur vos enfants."}, {"numero": 29, "texto": "Car voici, des jours viendront où l''''on dira: Heureuses les stériles, heureuses les entrailles qui n''''ont point enfanté, et les mamelles qui n''''ont point allaité!"}, {"numero": 30, "texto": "Alors ils se mettront à dire aux montagnes: Tombez sur nous! Et aux collines: Couvrez-nous!"}, {"numero": 31, "texto": "Car, si l''''on fait ces choses au bois vert, qu''''arrivera-t-il au bois sec?"}, {"numero": 32, "texto": "On conduisait en même temps deux malfaiteurs, qui devaient être mis à mort avec Jésus."}, {"numero": 33, "texto": "Lorsqu''''ils furent arrivés au lieu appelé Crâne, ils le crucifièrent là, ainsi que les deux malfaiteurs, l''''un à droite, l''''autre à gauche."}, {"numero": 34, "texto": "Jésus dit: Père, pardonne-leur, car ils ne savent ce qu''''ils font. Ils se partagèrent ses vêtements, en tirant au sort."}, {"numero": 35, "texto": "Le peuple se tenait là, et regardait. Les magistrats se moquaient de Jésus, disant: Il a sauvé les autres; qu''''il se sauve lui-même, s''''il est le Christ, l''''élu de Dieu!"}, {"numero": 36, "texto": "Les soldats aussi se moquaient de lui; s''''approchant et lui présentant du vinaigre,"}, {"numero": 37, "texto": "ils disaient: Si tu es le roi des Juifs, sauve-toi toi-même!"}, {"numero": 38, "texto": "Il y avait au-dessus de lui cette inscription: Celui-ci est le roi des Juifs."}, {"numero": 39, "texto": "L''''un des malfaiteurs crucifiés l''''injuriait, disant: N''''es-tu pas le Christ? Sauve-toi toi-même, et sauve-nous!"}, {"numero": 40, "texto": "Mais l''''autre le reprenait, et disait: Ne crains-tu pas Dieu, toi qui subis la même condamnation?"}, {"numero": 41, "texto": "Pour nous, c''''est justice, car nous recevons ce qu''''ont mérité nos crimes; mais celui-ci n''''a rien fait de mal."}, {"numero": 42, "texto": "Et il dit à Jésus: Souviens-toi de moi, quand tu viendras dans ton règne."}, {"numero": 43, "texto": "Jésus lui répondit: Je te le dis en vérité, aujourd''''hui tu seras avec moi dans le paradis."}, {"numero": 44, "texto": "Il était déjà environ la sixième heure, et il y eut des ténèbres sur toute la terre, jusqu''''à la neuvième heure."}, {"numero": 45, "texto": "Le soleil s''''obscurcit, et le voile du temple se déchira par le milieu."}, {"numero": 46, "texto": "Jésus s''''écria d''''une voix forte: Père, je remets mon esprit entre tes mains. Et, en disant ces paroles, il expira."}, {"numero": 47, "texto": "Le centenier, voyant ce qui était arrivé, glorifia Dieu, et dit: Certainement, cet homme était juste."}, {"numero": 48, "texto": "Et tous ceux qui assistaient en foule à ce spectacle, après avoir vu ce qui était arrivé, s''''en retournèrent, se frappant la poitrine."}, {"numero": 49, "texto": "Tous ceux de la connaissance de Jésus, et les femmes qui l''''avaient accompagné depuis la Galilée, se tenaient dans l''''éloignement et regardaient ce qui se passait."}, {"numero": 50, "texto": "Il y avait un conseiller, nommé Joseph, homme bon et juste,"}, {"numero": 51, "texto": "qui n''''avait point participé à la décision et aux actes des autres; il était d''''Arimathée, ville des Juifs, et il attendait le royaume de Dieu."}, {"numero": 52, "texto": "Cet homme se rendit vers Pilate, et demanda le corps de Jésus."}, {"numero": 53, "texto": "Il le descendit de la croix, l''''enveloppa d''''un linceul, et le déposa dans un sépulcre taillé dans le roc, où personne n''''avait encore été mis."}, {"numero": 54, "texto": "C''''était le jour de la préparation, et le sabbat allait commencer."}, {"numero": 55, "texto": "Les femmes qui étaient venues de la Galilée avec Jésus accompagnèrent Joseph, virent le sépulcre et la manière dont le corps de Jésus y fut déposé,"}, {"numero": 56, "texto": "et, s''''en étant retournées, elles préparèrent des aromates et des parfums. Puis elles se reposèrent le jour du sabbat, selon la loi."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 23, 'es', '[{"numero": 1, "texto": "LEVANTÁNDOSE entonces toda la multitud de ellos, lleváronle á Pilato."}, {"numero": 2, "texto": "Y comenzaron á acusarle, diciendo: A éste hemos hallado que pervierte la nación, y que veda dar tributo á César, diciendo que él es el Cristo, el rey."}, {"numero": 3, "texto": "Entonces Pilato le preguntó, diciendo: ¿Eres tú el Rey de los Judíos? Y respondiéndole él, dijo: Tú lo dices."}, {"numero": 4, "texto": "Y Pilato dijo á los príncipes de los sacerdotes, y á las gentes: Ninguna culpa hallo en este hombre."}, {"numero": 5, "texto": "Mas ellos porfiaban, diciendo: Alborota al pueblo, enseñando por toda Judea, comenzando desde Galilea hasta aquí."}, {"numero": 6, "texto": "Entonces Pilato, oyendo de Galilea, preguntó si el hombre era Galileo."}, {"numero": 7, "texto": "Y como entendió que era de la jurisdicción de Herodes, le remitió á Herodes, el cual también estaba en Jerusalem en aquellos días."}, {"numero": 8, "texto": "Y Herodes, viendo á Jesús, holgóse mucho, porque hacía mucho que deseaba verle; porque había oído de él muchas cosas, y tenía esperanza que le vería hacer alguna señal."}, {"numero": 9, "texto": "Y le preguntaba con muchas palabras; mas él nada le respondió:"}, {"numero": 10, "texto": "Y estaban los príncipes de los sacerdotes y los escribas acusándole con gran porfía."}, {"numero": 11, "texto": "Mas Herodes con su corte le menospreció, y escarneció, vistiéndole de una ropa rica; y volvióle á enviar á Pilato."}, {"numero": 12, "texto": "Y fueron hechos amigos entre sí Pilato y Herodes en el mismo día; porque antes eran enemigos entre sí."}, {"numero": 13, "texto": "Entonces Pilato, convocando los príncipes de los sacerdotes, y los magistrados, y el pueblo,"}, {"numero": 14, "texto": "Les dijo: Me habéis presentado á éste por hombre que desvía al pueblo: y he aquí, preguntando yo delante de vosotros, no he hallado culpa alguna en este hombre de aquéllas de que le acusáis."}, {"numero": 15, "texto": "Y ni aun Herodes; porque os remití á él, y he aquí, ninguna cosa digna de muerte ha hecho."}, {"numero": 16, "texto": "Le soltaré, pues, castigado."}, {"numero": 17, "texto": "Y tenía necesidad de soltarles uno en cada fiesta."}, {"numero": 18, "texto": "Mas toda la multitud dió voces á una, diciendo: Quita á éste, y suéltanos á Barrabás:"}, {"numero": 19, "texto": "(El cual había sido echado en la cárcel por una sedición hecha en la ciudad, y una muerte.)"}, {"numero": 20, "texto": "Y hablóles otra vez Pilato, queriendo soltar á Jesús."}, {"numero": 21, "texto": "Pero ellos volvieron á dar voces, diciendo: Crucifícale, crucifícale."}, {"numero": 22, "texto": "Y él les dijo la tercera vez: ¿Pues qué mal ha hecho éste? Ninguna culpa de muerte he hallado en él: le castigaré, pues, y le soltaré."}, {"numero": 23, "texto": "Mas ellos instaban á grandes voces, pidiendo que fuese crucificado. Y las voces de ellos y de los príncipes de los sacerdotes crecían."}, {"numero": 24, "texto": "Entonces Pilato juzgó que se hiciese lo que ellos pedían;"}, {"numero": 25, "texto": "Y les soltó á aquél que había sido echado en la cárcel por sedición y una muerte, al cual habían pedido; y entregó á Jesús á la voluntad de ellos."}, {"numero": 26, "texto": "Y llevándole, tomaron á un Simón Cireneo, que venía del campo, y le pusieron encima la cruz para que la llevase tras Jesús."}, {"numero": 27, "texto": "Y le seguía una grande multitud de pueblo, y de mujeres, las cuales le lloraban y lamentaban."}, {"numero": 28, "texto": "Mas Jesús, vuelto á ellas, les dice: Hijas de Jerusalem, no me lloréis á mí, mas llorad por vosotras mismas, y por vuestros hijos."}, {"numero": 29, "texto": "Porque he aquí vendrán días en que dirán: Bienaventuradas las estériles, y los vientres que no engendraron, y los pechos que no criaron."}, {"numero": 30, "texto": "Entonces comenzarán á decir á los montes: Caed sobre nosotros: y á los collados: Cubridnos."}, {"numero": 31, "texto": "Porque si en el árbol verde hacen estas cosas, ¿en el seco, qué se hará?"}, {"numero": 32, "texto": "Y llevaban también con él otros dos, malhechores, á ser muertos."}, {"numero": 33, "texto": "Y como vinieron al lugar que se llama de la Calavera, le crucificaron allí, y á los malhechores, uno á la derecha, y otro á la izquierda."}, {"numero": 34, "texto": "Y Jesús decía: Padre, perdónalos, porque no saben lo que hacen. Y partiendo sus vestidos, echaron suertes."}, {"numero": 35, "texto": "Y el pueblo estaba mirando; y se burlaban de él los príncipes con ellos, diciendo: A otros hizo salvos: sálvese á sí, si éste es el Mesías, el escogido de Dios."}, {"numero": 36, "texto": "Escarnecían de él también los soldados, llegándose y presentándole vinagre,"}, {"numero": 37, "texto": "Y diciendo: Si tú eres el Rey de los Judíos, sálvate á ti mismo."}, {"numero": 38, "texto": "Y había también sobre él un título escrito con letras griegas, y latinas, y hebraicas: ESTE ES EL REY DE LOS JUDIOS."}, {"numero": 39, "texto": "Y uno de los malhechores que estaban colgados, le injuriaba, diciendo: Si tú eres el Cristo, sálvate á ti mismo y á nosotros."}, {"numero": 40, "texto": "Y respondiendo el otro, reprendióle, diciendo: ¿Ni aun tú temes á Dios, estando en la misma condenación?"}, {"numero": 41, "texto": "Y nosotros, á la verdad, justamente padecemos; porque recibimos lo que merecieron nuestros hechos: mas éste ningún mal hizo."}, {"numero": 42, "texto": "Y dijo á Jesús: Acuérdate de mí cuando vinieres á tu reino."}, {"numero": 43, "texto": "Entonces Jesús le dijo: De cierto te digo, que hoy estarás conmigo en el paraíso."}, {"numero": 44, "texto": "Y cuando era como la hora de sexta, fueron hechas tinieblas sobre toda la tierra hasta la hora de nona."}, {"numero": 45, "texto": "Y el sol se obscureció: y el velo del templo se rompió por medio."}, {"numero": 46, "texto": "Entonces Jesús, clamando á gran voz, dijo: Padre, en tus manos encomiendo mi espíritu. Y habiendo dicho esto, espiró."}, {"numero": 47, "texto": "Y como el centurión vió lo que había acontecido, dió gloria á Dios, diciendo: Verdaderamente este hombre era justo."}, {"numero": 48, "texto": "Y toda la multitud de los que estaban presentes á este espectáculo, viendo lo que había acontecido, se volvían hiriendo sus pechos."}, {"numero": 49, "texto": "Mas todos sus conocidos, y las mujeres que le habían seguido desde Galilea, estaban lejos mirando estas cosas."}, {"numero": 50, "texto": "Y he aquí un varón llamado José, el cual era senador, varón bueno y justo,"}, {"numero": 51, "texto": "(El cual no había consentido en el consejo ni en los hechos de ellos), de Arimatea, ciudad de la Judea, el cual también esperaba el reino de Dios;"}, {"numero": 52, "texto": "Este llegó á Pilato, y pidió el cuerpo de Jesús."}, {"numero": 53, "texto": "Y quitado, lo envolvió en una sábana, y le puso en un sepulcro abierto en una peña, en el cual ninguno había aún sido puesto."}, {"numero": 54, "texto": "Y era día de la víspera de la Pascua; y estaba para rayar el sábado."}, {"numero": 55, "texto": "Y las mujeres que con él habían venido de Galilea, siguieron también y vieron el sepulcro, y cómo fué puesto su cuerpo."}, {"numero": 56, "texto": "Y vueltas, aparejaron drogas aromáticas y ungüentos; y reposaron el sábado, conforme al mandamiento."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 24, 'pt', '[{"numero": 1, "texto": "E no primeiro [dia] da semana, de madrugada bem cedo, foram ao sepulcro, levando [consigo] os materiais aromáticos que tinham preparado; e algumas [outras] junto delas."}, {"numero": 2, "texto": "E acharam a pedra já revolvida do sepulcro."}, {"numero": 3, "texto": "E entrando, não acharam o corpo do Senhor Jesus."}, {"numero": 4, "texto": "E aconteceu, que estando elas perplexas, eis que dois homens apareceram junto a elas, com roupas luminosas."}, {"numero": 5, "texto": "E estando elas com muito medo, e abaixando o rosto para o chão, eles lhes disseram: Por que buscam entre os mortos aquele que vive?"}, {"numero": 6, "texto": "Ele não está aqui, mas já ressuscitou. Lembrai-vos de como ele vos falou, quando ainda estava na Galileia,"}, {"numero": 7, "texto": "Dizendo: É necessário que o Filho do homem seja entregue nas mãos de homens pecadores, e [que] seja crucificado, e ressuscite ao terceiro dia."}, {"numero": 8, "texto": "E se lembraram das palavras dele."}, {"numero": 9, "texto": "E, voltando do sepulcro, anunciaram todas estas coisas aos onze, e a todos os outros."}, {"numero": 10, "texto": "E eram Maria Madalena, e Joana, e Maria [mãe] de Tiago, e as outras [que estavam] com elas, que diziam estas coisas aos apóstolos."}, {"numero": 11, "texto": "E para eles, as palavras delas pareciam não ter sentido; e não creram nelas."}, {"numero": 12, "texto": "Porém Pedro, levantando-se, correu ao sepulcro; e abaixando-se, viu os tecidos postos separadamente; e saiu maravilhado com o que tinha acontecido."}, {"numero": 13, "texto": "E eis que dois deles iam naquele mesmo dia a uma aldeia, cujo nome era Emaús, que estava a sessenta estádios [de distância] de Jerusalém."}, {"numero": 14, "texto": "E iam falando entre si de todas aquelas coisas que tinham acontecido."}, {"numero": 15, "texto": "E aconteceu que, enquanto eles estavam conversando entre si, e perguntando um ao outro, Jesus se aproximou, e foi junto deles."}, {"numero": 16, "texto": "Mas seus olhos foram retidos, para que não o reconhecessem."}, {"numero": 17, "texto": "E disse-lhes: Que conversas são essas, que vós discutis enquanto andam, e ficais tristes?"}, {"numero": 18, "texto": "E um [deles] ,cujo nome era Cleofas, respondendo-o, disse-lhe: És tu o único viajante em Jerusalém que não sabe as coisas que nela tem acontecido nestes dias?"}, {"numero": 19, "texto": "E ele lhes disse: Quais?E eles lhe disseram: As sobre Jesus de Nazaré, a qual foi um homem profeta, poderoso em obras e em palavras, diante de Deus, e de todo o povo."}, {"numero": 20, "texto": "E como os chefes dos sacerdotes, e nossos líderes o entregaram à condenação de morte, e o crucificaram."}, {"numero": 21, "texto": "E nós esperávamos que ele fosse aquele que libertar a Israel; porém além de tudo isto, hoje é o terceiro dia desde que estas coisas aconteceram."}, {"numero": 22, "texto": "Ainda que também algumas mulheres dentre nós nos deixaram surpresos, as quais de madrugada foram ao sepulcro;"}, {"numero": 23, "texto": "E não achando seu corpo, vieram, dizendo que também tinham visto uma aparição de anjos, que disseram que ele vive."}, {"numero": 24, "texto": "E alguns do que estão conosco foram ao sepulcro, e [o] acharam assim como as mulheres tinham dito; porém não o viram."}, {"numero": 25, "texto": "E ele lhes disse: Ó tolos, e que demoram no coração para crerem em tudo o que os profetas falaram!"}, {"numero": 26, "texto": "Por acaso não era necessário que o Cristo sofresse estas coisas, e [então] entrar em sua glória?"}, {"numero": 27, "texto": "E começando de Moisés, e por todos os profetas, lhes declarava em todas as Escrituras o que estava [escrito] sobre ele."}, {"numero": 28, "texto": "E chegaram à aldeia para onde estavam indo; e ele agiu como se fosse para [um lugar] mais distante."}, {"numero": 29, "texto": "E eles lhe rogaram, dizendo: Fica conosco, porque já é tarde, e o dia está entardecendo;E ele entrou para ficar com eles."}, {"numero": 30, "texto": "E aconteceu que, estando sentado com eles [à mesa] ,tomou o pão, o benzeu, [o] partiu, e o deu a eles."}, {"numero": 31, "texto": "E os olhos deles se abriram, e o reconheceram, e ele lhes desapareceu."}, {"numero": 32, "texto": "E diziam um ao outro: Por acaso não estava nosso coração ardendo em nós, quando ele falava conosco pelo caminho, e quando nos desvendava as Escrituras?"}, {"numero": 33, "texto": "E levantando-se na mesma hora, voltaram para Jerusalém, e acharam reunidos aos onze, e aos que estavam com eles,"}, {"numero": 34, "texto": "Que diziam: Verdadeiramente o Senhor ressuscitou, e já apareceu a Simão."}, {"numero": 35, "texto": "E eles contaram as coisas que [lhes aconteceram] no caminho; e como foi reconhecido por eles quando partiu o pão."}, {"numero": 36, "texto": "E enquanto eles falavam disto, o próprio Jesus se pôs no meio deles, e lhes disse: Paz [seja] convosco."}, {"numero": 37, "texto": "E eles, espantados, e muito atemorizados, pensavam que viam algum espírito."}, {"numero": 38, "texto": "E ele lhes disse: Por que estais perturbados, e por que sobem dúvidas em vossos corações?"}, {"numero": 39, "texto": "Vede minhas mãos, e os meus pés, que sou em mesmo. Tocai-me, e vede, porque um espírito não tem carne nem ossos, como vós vedes que eu tenho."}, {"numero": 40, "texto": "E dizendo isto, lhes mostrou as mãos e os pés."}, {"numero": 41, "texto": "E eles, não crendo ainda, por causa da alegria, e maravilhados, [Jesus] disse-lhes: Tendes aqui alguma coisa para comer?"}, {"numero": 42, "texto": "Então eles lhe apresentaram parte de um peixe assado e de um favo de mel."}, {"numero": 43, "texto": "Ele pegou, e comeu diante deles."}, {"numero": 44, "texto": "E disse-lhes: Estas são as palavras que eu vos disse, enquanto ainda estava convosco, que era necessário que se cumprissem todas as coisas que estão escritas sobre mim na Lei de Moisés, [nos] profetas, e [nos] Salmos."}, {"numero": 45, "texto": "Então ele lhes abriu o entendimento, para que entendessem as Escrituras."}, {"numero": 46, "texto": "E disse-lhes: Assim está escrito, e assim era necessário que o Cristo sofresse, e que ao terceiro dia ressuscitasse dos mortos;"}, {"numero": 47, "texto": "E que em seu nome fosse pregado arrependimento e perdão de pecados em todas as nações, começando de Jerusalém."}, {"numero": 48, "texto": "E destas coisas vós sois testemunhas."}, {"numero": 49, "texto": "E eis que eu envio a promessa de meu Pai sobre vós; porém ficai vós na cidade de Jerusalém, até que vos seja dado poder do alto."}, {"numero": 50, "texto": "E os levou para fora até Betânia, e levantando suas mãos, os abençoou."}, {"numero": 51, "texto": "E aconteceu que, enquanto os abençoava, ele se afastou deles, e foi conduzido para cima ao céu."}, {"numero": 52, "texto": "E eles, adorando-o, voltaram para Jerusalém com grande alegria;"}, {"numero": 53, "texto": "E estavam sempre no Templo, louvando e bendizendo a Deus. Amém."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 24, 'en', '[{"numero": 1, "texto": "Now upon the first day of the week, very early in the morning, they came unto the sepulchre, bringing the spices which they had prepared, and certain others with them."}, {"numero": 2, "texto": "And they found the stone rolled away from the sepulchre."}, {"numero": 3, "texto": "And they entered in, and found not the body of the Lord Jesus."}, {"numero": 4, "texto": "And it came to pass, as they were much perplexed thereabout, behold, two men stood by them in shining garments:"}, {"numero": 5, "texto": "And as they were afraid, and bowed down their faces to the earth, they said unto them, Why seek ye the living among the dead?"}, {"numero": 6, "texto": "He is not here, but is risen: remember how he spake unto you when he was yet in Galilee,"}, {"numero": 7, "texto": "Saying, The Son of man must be delivered into the hands of sinful men, and be crucified, and the third day rise again."}, {"numero": 8, "texto": "And they remembered his words,"}, {"numero": 9, "texto": "And returned from the sepulchre, and told all these things unto the eleven, and to all the rest."}, {"numero": 10, "texto": "It was Mary Magdalene and Joanna, and Mary the mother of James, and other women that were with them, which told these things unto the apostles."}, {"numero": 11, "texto": "And their words seemed to them as idle tales, and they believed them not."}, {"numero": 12, "texto": "Then arose Peter, and ran unto the sepulchre; and stooping down, he beheld the linen clothes laid by themselves, and departed, wondering in himself at that which was come to pass."}, {"numero": 13, "texto": "And, behold, two of them went that same day to a village called Emmaus, which was from Jerusalem about threescore furlongs."}, {"numero": 14, "texto": "And they talked together of all these things which had happened."}, {"numero": 15, "texto": "And it came to pass, that, while they communed together and reasoned, Jesus himself drew near, and went with them."}, {"numero": 16, "texto": "But their eyes were holden that they should not know him."}, {"numero": 17, "texto": "And he said unto them, What manner of communications are these that ye have one to another, as ye walk, and are sad?"}, {"numero": 18, "texto": "And the one of them, whose name was Cleopas, answering said unto him, Art thou only a stranger in Jerusalem, and hast not known the things which are come to pass there in these days?"}, {"numero": 19, "texto": "And he said unto them, What things? And they said unto him, Concerning Jesus of Nazareth, which was a prophet mighty in deed and word before God and all the people:"}, {"numero": 20, "texto": "And how the chief priests and our rulers delivered him to be condemned to death, and have crucified him."}, {"numero": 21, "texto": "But we trusted that it had been he which should have redeemed Israel: and beside all this, to day is the third day since these things were done."}, {"numero": 22, "texto": "Yea, and certain women also of our company made us astonished, which were early at the sepulchre;"}, {"numero": 23, "texto": "And when they found not his body, they came, saying, that they had also seen a vision of angels, which said that he was alive."}, {"numero": 24, "texto": "And certain of them which were with us went to the sepulchre, and found it even so as the women had said: but him they saw not."}, {"numero": 25, "texto": "Then he said unto them, O fools, and slow of heart to believe all that the prophets have spoken:"}, {"numero": 26, "texto": "Ought not Christ to have suffered these things, and to enter into his glory?"}, {"numero": 27, "texto": "And beginning at Moses and all the prophets, he expounded unto them in all the scriptures the things concerning himself."}, {"numero": 28, "texto": "And they drew nigh unto the village, whither they went: and he made as though he would have gone further."}, {"numero": 29, "texto": "But they constrained him, saying, Abide with us: for it is toward evening, and the day is far spent. And he went in to tarry with them."}, {"numero": 30, "texto": "And it came to pass, as he sat at meat with them, he took bread, and blessed it, and brake, and gave to them."}, {"numero": 31, "texto": "And their eyes were opened, and they knew him; and he vanished out of their sight."}, {"numero": 32, "texto": "And they said one to another, Did not our heart burn within us, while he talked with us by the way, and while he opened to us the scriptures?"}, {"numero": 33, "texto": "And they rose up the same hour, and returned to Jerusalem, and found the eleven gathered together, and them that were with them,"}, {"numero": 34, "texto": "Saying, The Lord is risen indeed, and hath appeared to Simon."}, {"numero": 35, "texto": "And they told what things were done in the way, and how he was known of them in breaking of bread."}, {"numero": 36, "texto": "And as they thus spake, Jesus himself stood in the midst of them, and saith unto them, Peace be unto you."}, {"numero": 37, "texto": "But they were terrified and affrighted, and supposed that they had seen a spirit."}, {"numero": 38, "texto": "And he said unto them, Why are ye troubled? and why do thoughts arise in your hearts?"}, {"numero": 39, "texto": "Behold my hands and my feet, that it is I myself: handle me, and see; for a spirit hath not flesh and bones, as ye see me have."}, {"numero": 40, "texto": "And when he had thus spoken, he shewed them his hands and his feet."}, {"numero": 41, "texto": "And while they yet believed not for joy, and wondered, he said unto them, Have ye here any meat?"}, {"numero": 42, "texto": "And they gave him a piece of a broiled fish, and of an honeycomb."}, {"numero": 43, "texto": "And he took it, and did eat before them."}, {"numero": 44, "texto": "And he said unto them, These are the words which I spake unto you, while I was yet with you, that all things must be fulfilled, which were written in the law of Moses, and in the prophets, and in the psalms, concerning me."}, {"numero": 45, "texto": "Then opened he their understanding, that they might understand the scriptures,"}, {"numero": 46, "texto": "And said unto them, Thus it is written, and thus it behooved Christ to suffer, and to rise from the dead the third day:"}, {"numero": 47, "texto": "And that repentance and remission of sins should be preached in his name among all nations, beginning at Jerusalem."}, {"numero": 48, "texto": "And ye are witnesses of these things."}, {"numero": 49, "texto": "And, behold, I send the promise of my Father upon you: but tarry ye in the city of Jerusalem, until ye be endued with power from on high."}, {"numero": 50, "texto": "And he led them out as far as to Bethany, and he lifted up his hands, and blessed them."}, {"numero": 51, "texto": "And it came to pass, while he blessed them, he was parted from them, and carried up into heaven."}, {"numero": 52, "texto": "And they worshipped him, and returned to Jerusalem with great joy:"}, {"numero": 53, "texto": "And were continually in the temple, praising and blessing God. Amen."}]'::jsonb, 'King James Version'),
  ('Lc', 24, 'fr', '[{"numero": 1, "texto": "Le premier jour de la semaine, elles se rendirent au sépulcre de grand matin, portant les aromates qu''''elles avaient préparés."}, {"numero": 2, "texto": "Elles trouvèrent que la pierre avait été roulée de devant le sépulcre;"}, {"numero": 3, "texto": "et, étant entrées, elles ne trouvèrent pas le corps du Seigneur Jésus."}, {"numero": 4, "texto": "Comme elles ne savaient que penser de cela, voici, deux hommes leur apparurent, en habits resplendissants."}, {"numero": 5, "texto": "Saisies de frayeur, elles baissèrent le visage contre terre; mais ils leur dirent: Pourquoi cherchez-vous parmi les morts celui qui est vivant?"}, {"numero": 6, "texto": "Il n''''est point ici, mais il est ressuscité. Souvenez-vous de quelle manière il vous a parlé, lorsqu''''il était encore en Galilée,"}, {"numero": 7, "texto": "et qu''''il disait: Il faut que le Fils de l''''homme soit livré entre les mains des pécheurs, qu''''il soit crucifié, et qu''''il ressuscite le troisième jour."}, {"numero": 8, "texto": "Et elles se ressouvinrent des paroles de Jésus."}, {"numero": 9, "texto": "A leur retour du sépulcre, elles annoncèrent toutes ces choses aux onze, et à tous les autres."}, {"numero": 10, "texto": "Celles qui dirent ces choses aux apôtres étaient Marie de Magdala, Jeanne, Marie, mère de Jacques, et les autres qui étaient avec elles."}, {"numero": 11, "texto": "Ils tinrent ces discours pour des rêveries, et ils ne crurent pas ces femmes."}, {"numero": 12, "texto": "Mais Pierre se leva, et courut au sépulcre. S''''étant baissé, il ne vit que les linges qui étaient à terre; puis il s''''en alla chez lui, dans l''''étonnement de ce qui était arrivé."}, {"numero": 13, "texto": "Et voici, ce même jour, deux disciples allaient à un village nommé Emmaüs, éloigné de Jérusalem de soixante stades;"}, {"numero": 14, "texto": "et ils s''''entretenaient de tout ce qui s''''était passé."}, {"numero": 15, "texto": "Pendant qu''''ils parlaient et discutaient, Jésus s''''approcha, et fit route avec eux."}, {"numero": 16, "texto": "Mais leurs yeux étaient empêchés de le reconnaître."}, {"numero": 17, "texto": "Il leur dit: De quoi vous entretenez-vous en marchant, pour que vous soyez tout tristes?"}, {"numero": 18, "texto": "L''''un d''''eux, nommé Cléopas, lui répondit: Es-tu le seul qui, séjournant à Jérusalem ne sache pas ce qui y est arrivé ces jours-ci? -"}, {"numero": 19, "texto": "Quoi? leur dit-il. Et ils lui répondirent: Ce qui est arrivé au sujet de Jésus de Nazareth, qui était un prophète puissant en oeuvres et en paroles devant Dieu et devant tout le peuple,"}, {"numero": 20, "texto": "et comment les principaux sacrificateurs et nos magistrats l''''ont livré pour le faire condamner à mort et l''''ont crucifié."}, {"numero": 21, "texto": "Nous espérions que ce serait lui qui délivrerait Israël; mais avec tout cela, voici le troisième jour que ces choses se sont passées."}, {"numero": 22, "texto": "Il est vrai que quelques femmes d''''entre nous nous ont fort étonnés; s''''étant rendues de grand matin au sépulcre"}, {"numero": 23, "texto": "et n''''ayant pas trouvé son corps, elles sont venues dire que des anges leur sont apparus et ont annoncé qu''''il est vivant."}, {"numero": 24, "texto": "Quelques-uns de ceux qui étaient avec nous sont allés au sépulcre, et ils ont trouvé les choses comme les femmes l''''avaient dit; mais lui, ils ne l''''ont point vu."}, {"numero": 25, "texto": "Alors Jésus leur dit: O hommes sans intelligence, et dont le coeur est lent à croire tout ce qu''''ont dit les prophètes!"}, {"numero": 26, "texto": "Ne fallait-il pas que le Christ souffrît ces choses, et qu''''il entrât dans sa gloire?"}, {"numero": 27, "texto": "Et, commençant par Moïse et par tous les prophètes, il leur expliqua dans toutes les Ecritures ce qui le concernait."}, {"numero": 28, "texto": "Lorsqu''''ils furent près du village où ils allaient, il parut vouloir aller plus loin."}, {"numero": 29, "texto": "Mais ils le pressèrent, en disant: Reste avec nous, car le soir approche, le jour est sur son déclin. Et il entra, pour rester avec eux."}, {"numero": 30, "texto": "Pendant qu''''il était à table avec eux, il prit le pain; et, après avoir rendu grâces, il le rompit, et le leur donna."}, {"numero": 31, "texto": "Alors leurs yeux s''''ouvrirent, et ils le reconnurent; mais il disparut de devant eux."}, {"numero": 32, "texto": "Et ils se dirent l''''un à l''''autre: Notre coeur ne brûlait-il pas au dedans de nous, lorsqu''''il nous parlait en chemin et nous expliquait les Ecritures?"}, {"numero": 33, "texto": "Se levant à l''''heure même, ils retournèrent à Jérusalem, et ils trouvèrent les onze, et ceux qui étaient avec eux, assemblés"}, {"numero": 34, "texto": "et disant: Le Seigneur est réellement ressuscité, et il est apparu à Simon."}, {"numero": 35, "texto": "Et ils racontèrent ce qui leur était arrivé en chemin, et comment ils l''''avaient reconnu au moment où il rompit le pain."}, {"numero": 36, "texto": "Tandis qu''''ils parlaient de la sorte, lui-même se présenta au milieu d''''eux, et leur dit: La paix soit avec vous!"}, {"numero": 37, "texto": "Saisis de frayeur et d''''épouvante, ils croyaient voir un esprit."}, {"numero": 38, "texto": "Mais il leur dit: Pourquoi êtes-vous troublés, et pourquoi pareilles pensées s''''élèvent-elles dans vos coeurs?"}, {"numero": 39, "texto": "Voyez mes mains et mes pieds, c''''est bien moi; touchez-moi et voyez: un esprit n''''a ni chair ni os, comme vous voyez que j''''ai."}, {"numero": 40, "texto": "Et en disant cela, il leur montra ses mains et ses pieds."}, {"numero": 41, "texto": "Comme, dans leur joie, ils ne croyaient point encore, et qu''''ils étaient dans l''''étonnement, il leur dit: Avez-vous ici quelque chose à manger?"}, {"numero": 42, "texto": "Ils lui présentèrent du poisson rôti et un rayon de miel."}, {"numero": 43, "texto": "Il en prit, et il mangea devant eux."}, {"numero": 44, "texto": "Puis il leur dit: C''''est là ce que je vous disais lorsque j''''étais encore avec vous, qu''''il fallait que s''''accomplît tout ce qui est écrit de moi dans la loi de Moïse, dans les prophètes, et dans les psaumes."}, {"numero": 45, "texto": "Alors il leur ouvrit l''''esprit, afin qu''''ils comprissent les Ecritures."}, {"numero": 46, "texto": "Et il leur dit: Ainsi il est écrit que le Christ souffrirait, et qu''''il ressusciterait des morts le troisième jour,"}, {"numero": 47, "texto": "et que la repentance et le pardon des péchés seraient prêchés en son nom à toutes les nations, à commencer par Jérusalem."}, {"numero": 48, "texto": "Vous êtes témoins de ces choses."}, {"numero": 49, "texto": "Et voici, j''''enverrai sur vous ce que mon Père a promis; mais vous, restez dans la ville jusqu''''à ce que vous soyez revêtus de la puissance d''''en haut."}, {"numero": 50, "texto": "Il les conduisit jusque vers Béthanie, et, ayant levé les mains, il les bénit."}, {"numero": 51, "texto": "Pendant qu''''il les bénissait, il se sépara d''''eux, et fut enlevé au ciel."}, {"numero": 52, "texto": "Pour eux, après l''''avoir adoré, ils retournèrent à Jérusalem avec une grande joie;"}, {"numero": 53, "texto": "et ils étaient continuellement dans le temple, louant et bénissant Dieu."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 24, 'es', '[{"numero": 1, "texto": "Y EL primer día de la semana, muy de mañana, vinieron al sepulcro, trayendo las drogas aromáticas que habían aparejado, y algunas otras mujeres con ellas."}, {"numero": 2, "texto": "Y hallaron la piedra revuelta del sepulcro."}, {"numero": 3, "texto": "Y entrando, no hallaron el cuerpo del Señor Jesús."}, {"numero": 4, "texto": "Y aconteció, que estando ellas espantadas de esto, he aquí se pararon junto á ellas dos varones con vestiduras resplandecientes;"}, {"numero": 5, "texto": "Y como tuviesen ellas temor, y bajasen el rostro á tierra, les dijeron: ¿Por qué buscáis entre los muertos al que vive?"}, {"numero": 6, "texto": "No está aquí, mas ha resucitado: acordaos de lo que os habló, cuando aun estaba en Galilea,"}, {"numero": 7, "texto": "Diciendo: Es menester que el Hijo del hombre sea entregado en manos de hombres pecadores, y que sea crucificado, y resucite al tercer día."}, {"numero": 8, "texto": "Entonces ellas se acordaron de sus palabras,"}, {"numero": 9, "texto": "Y volviendo del sepulcro, dieron nuevas de todas estas cosas á los once, y á todos los demás."}, {"numero": 10, "texto": "Y eran María Magdalena, y Juana, y María madre de Jacobo, y las demás con ellas, las que dijeron estas cosas á los apóstoles."}, {"numero": 11, "texto": "Mas á ellos les parecían como locura las palabras de ellas, y no las creyeron."}, {"numero": 12, "texto": "Pero levantándose Pedro, corrió al sepulcro: y como miró dentro, vió solos los lienzos echados; y se fué maravillándose de lo que había sucedido."}, {"numero": 13, "texto": "Y he aquí, dos de ellos iban el mismo día á una aldea que estaba de Jerusalem sesenta estadios, llamada Emmaús."}, {"numero": 14, "texto": "E iban hablando entre sí de todas aquellas cosas que habían acaecido."}, {"numero": 15, "texto": "Y aconteció que yendo hablando entre sí, y preguntándose el uno al otro, el mismo Jesús se llegó, é iba con ellos juntamente."}, {"numero": 16, "texto": "Mas los ojos de ellos estaban embargados, para que no le conociesen."}, {"numero": 17, "texto": "Y díjoles: ¿Qué pláticas son estas que tratáis entre vosotros andando, y estáis tristes?"}, {"numero": 18, "texto": "Y respondiendo el uno, que se llamaba Cleofas, le dijo: ¿Tú sólo peregrino eres en Jerusalem, y no has sabido las cosas que en ella han acontecido estos días?"}, {"numero": 19, "texto": "Entonces él les dijo: ¿Qué cosas? Y ellos le dijeron: De Jesús Nazareno, el cual fué varón profeta, poderoso en obra y en palabra delante de Dios y de todo el pueblo;"}, {"numero": 20, "texto": "Y cómo le entregaron los príncipes de los sacerdotes y nuestros príncipes á condenación de muerte, y le crucificaron."}, {"numero": 21, "texto": "Mas nosotros esperábamos que él era el que había de redimir á Israel: y ahora sobre todo esto, hoy es el tercer día que esto ha acontecido."}, {"numero": 22, "texto": "Aunque también unas mujeres de los nuestros nos han espantado, las cuales antes del día fueron al sepulcro:"}, {"numero": 23, "texto": "Y no hallando su cuerpo, vinieron diciendo que también habían visto visión de ángeles, los cuales dijeron que él vive."}, {"numero": 24, "texto": "Y fueron algunos de los nuestros al sepulcro, y hallaron así como las mujeres habían dicho; mas á él no le vieron."}, {"numero": 25, "texto": "Entonces él les dijo: ¡Oh insensatos, y tardos de corazón para creer todo lo que los profetas han dicho!"}, {"numero": 26, "texto": "¿No era necesario que el Cristo padeciera estas cosas, y que entrara en su gloria?"}, {"numero": 27, "texto": "Y comenzando desde Moisés, y de todos los profetas, declarábales en todas las Escrituras lo que de él decían."}, {"numero": 28, "texto": "Y llegaron á la aldea á donde iban: y él hizo como que iba más lejos."}, {"numero": 29, "texto": "Mas ellos le detuvieron por fuerza, diciendo: Quédate con nosotros, porque se hace tarde, y el día ya ha declinado. Entró pues á estarse con ellos."}, {"numero": 30, "texto": "Y aconteció, que estando sentado con ellos á la mesa, tomando el pan, bendijo, y partió, y dióles."}, {"numero": 31, "texto": "Entonces fueron abiertos los ojos de ellos, y le conocieron; mas él se desapareció de los ojos de ellos."}, {"numero": 32, "texto": "Y decían el uno al otro: ¿No ardía nuestro corazón en nosotros, mientras nos hablaba en el camino, y cuando nos abría las Escrituras?"}, {"numero": 33, "texto": "Y levantándose en la misma hora, tornáronse á Jerusalem, y hallaron á los once reunidos, y á los que estaban con ellos."}, {"numero": 34, "texto": "Que decían: Ha resucitado el Señor verdaderamente, y ha aparecido á Simón."}, {"numero": 35, "texto": "Entonces ellos contaban las cosas que les habían acontecido en el camino, y cómo había sido conocido de ellos al partir el pan."}, {"numero": 36, "texto": "Y entre tanto que ellos hablaban estas cosas, él se puso en medio de ellos, y les dijo: Paz á vosotros."}, {"numero": 37, "texto": "Entonces ellos espantados y asombrados, pensaban que veían espíritu."}, {"numero": 38, "texto": "Mas él les dice: ¿Por qué estáis turbados, y suben pensamientos á vuestros corazones?"}, {"numero": 39, "texto": "Mirad mis manos y mis pies, que yo mismo soy: palpad, y ved; que el espíritu ni tiene carne ni huesos, como veis que yo tengo."}, {"numero": 40, "texto": "Y en diciendo esto, les mostró las manos y los pies."}, {"numero": 41, "texto": "Y no creyéndolo aún ellos de gozo, y maravillados, díjoles: ¿Tenéis aquí algo de comer?"}, {"numero": 42, "texto": "Entonces ellos le presentaron parte de un pez asado, y un panal de miel."}, {"numero": 43, "texto": "Y él tomó, y comió delante de ellos."}, {"numero": 44, "texto": "Y él les dijo: Estas son las palabras que os hablé, estando aún con vosotros: que era necesario que se cumpliesen todas las cosas que están escritas de mí en la ley de Moisés, y en los profetas, y en los salmos."}, {"numero": 45, "texto": "Entonces les abrió el sentido, para que entendiesen las Escrituras;"}, {"numero": 46, "texto": "Y díjoles: Así está escrito, y así fué necesario que el Cristo padeciese, y resucitase de los muertos al tercer día;"}, {"numero": 47, "texto": "Y que se predicase en su nombre el arrepentimiento y la remisión de pecados en todas las naciones, comenzando de Jerusalem."}, {"numero": 48, "texto": "Y vosotros sois testigos de estas cosas."}, {"numero": 49, "texto": "Y he aquí, yo enviaré la promesa de mi Padre sobre vosotros: mas vosotros asentad en la ciudad de Jerusalem, hasta que seáis investidos de potencia de lo alto."}, {"numero": 50, "texto": "Y sacólos fuera hasta Bethania, y alzando sus manos, los bendijo."}, {"numero": 51, "texto": "Y aconteció que bendiciéndolos, se fué de ellos; y era llevado arriba al cielo."}, {"numero": 52, "texto": "Y ellos, después de haberle adorado, se volvieron á Jerusalem con gran gozo;"}, {"numero": 53, "texto": "Y estaban siempre en el templo, alabando y bendiciendo á Dios. Amén."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lv', 11, 'pt', '[{"numero": 1, "texto": "E falou o SENHOR a Moisés e a Arão, dizendo-lhes:"}, {"numero": 2, "texto": "Falai aos filhos de Israel, dizendo: Estes são os animais que comereis de todos os animais que estão sobre a terra."}, {"numero": 3, "texto": "De entre os animais, todo o de casco, e que tem as unhas fendidas, e que rumina, este comereis."}, {"numero": 4, "texto": "Estes, porém, não comereis dos que ruminam e dos que têm casco: o camelo, porque rumina mas não tem casco fendido, haveis de tê-lo por impuro;"}, {"numero": 5, "texto": "Também o coelho, porque rumina, mas não tem unha fendida, o tereis por impuro;"}, {"numero": 6, "texto": "Assim a lebre, porque rumina, mas não tem unha fendida, a tereis por impura;"}, {"numero": 7, "texto": "Também o porco, porque tem unhas, e é de unhas fendidas, mas não rumina, o tereis por impuro."}, {"numero": 8, "texto": "Da carne deles não comereis, nem tocareis seu corpo morto: os tereis por impuros."}, {"numero": 9, "texto": "Isto comereis de todas as coisas que estão nas águas: todas as coisas que têm barbatanas e escamas nas águas do mar, e nos rios, aquelas comereis;"}, {"numero": 10, "texto": "Mas todas as coisas que não têm barbatanas nem escamas no mar e nos rios, tanto de todo réptil de água como de toda coisa vivente que está nas águas, as tereis em abominação."}, {"numero": 11, "texto": "Vos serão, pois, em abominação: de sua carne não comereis, e abominareis seus corpos mortos."}, {"numero": 12, "texto": "Tudo o que não tiver barbatanas e escamas nas águas, o tereis em abominação."}, {"numero": 13, "texto": "E das aves, estas tereis em abominação; não se comerão, serão abominação: a água, o quebra-ossos, o esmerilhão,"}, {"numero": 14, "texto": "O milhafre, e o falcão a segundo sua espécie;"}, {"numero": 15, "texto": "Todo corvo segundo sua espécie;"}, {"numero": 16, "texto": "O avestruz, e a coruja, e a gaivota, e o gavião segundo sua espécie;"}, {"numero": 17, "texto": "E o mocho, e o corvo-marinho, e o íbis,"}, {"numero": 18, "texto": "E a galinha-d''água, e o cisne, e o pelicano,"}, {"numero": 19, "texto": "E a cegonha, e a garça, segundo sua espécie, e a poupa, e o morcego."}, {"numero": 20, "texto": "Todo inseto de asas que andar sobre quatro pés, tereis em abominação."}, {"numero": 21, "texto": "Porém isto comereis de todo inseto de asas que anda sobre quatro patas, que tiver pernas além de suas patas para saltar com elas sobre a terra;"}, {"numero": 22, "texto": "Estes comereis deles: o gafanhoto migrador segundo sua espécie, e a esperança segundo sua espécie, e o grilo segundo sua espécie, e o gafanhoto comum segundo sua espécie."}, {"numero": 23, "texto": "Todo réptil de asas que tenha quatro pés, tereis em abominação."}, {"numero": 24, "texto": "E por estas coisas sereis impuros: qualquer um que tocar a seus corpos mortos, será impuro até à tarde:"}, {"numero": 25, "texto": "E qualquer um que levar de seus corpos mortos, lavará suas roupas, e será impuro até à tarde."}, {"numero": 26, "texto": "Todo animal de casco, mas que não tem unha fendida, nem rumina, tereis por impuro: qualquer um que os tocar será impuro."}, {"numero": 27, "texto": "E de todos os animais que andam a quatro patas, tereis por impuro qualquer um que ande sobre suas garras: qualquer um que tocar seus corpos mortos, será impuro até à tarde."}, {"numero": 28, "texto": "E o que levar seus corpos mortos, lavará suas roupas, e será impuro até à tarde: haveis de tê-los por impuros."}, {"numero": 29, "texto": "E estes tereis por impuros dos répteis que vão arrastando sobre a terra: a doninha, e o rato, e o lagarto segundo sua espécie,"}, {"numero": 30, "texto": "E a lagartixa, e o lagarto pintado, e a lagartixa de parede, e a salamandra, e o camaleão."}, {"numero": 31, "texto": "Estes tereis por impuros de todos os répteis: qualquer um que os tocar, quando estiverem mortos, será impuro até à tarde."}, {"numero": 32, "texto": "E tudo aquilo sobre que cair algum deles depois de mortos, será impuro; tanto vaso de madeira, como roupa, ou pele, ou saco, qualquer instrumento com que se faz obra, será posto em água, e será impuro até à tarde, e assim será limpo."}, {"numero": 33, "texto": "E toda vasilha de barro dentro da qual cair algum deles, tudo o que estiver nela será impuro, e quebrareis a vasilha:"}, {"numero": 34, "texto": "Toda comida que se come, sobre a qual vier a água de tais vasilhas, será imunda: e toda bebida que se beber, será em todas essas vasilhas impura:"}, {"numero": 35, "texto": "E tudo aquilo sobre que cair algo do corpo morto deles, será impuro: o forno ou aquecedores se derrubarão; são impuros, e por impuros os tereis."}, {"numero": 36, "texto": "Contudo, a fonte e a cisterna onde se recolhem águas, serão limpas: mas o que houver tocado em seus corpos mortos será impuro."}, {"numero": 37, "texto": "E se cair de seus corpos mortos sobre alguma semente que se haja de semear, será limpa."}, {"numero": 38, "texto": "Mas se se houver posto água na semente, e cair de seus corpos mortos sobre ela, a tereis por impura."}, {"numero": 39, "texto": "E se algum animal que tiverdes para comer se morrer, o que tocar seu corpo morto será impuro até à tarde:"}, {"numero": 40, "texto": "E o que comer de seu corpo morto, lavará suas roupas, e será impuro até à tarde: também o que tirar seu corpo morto, lavará suas roupas, e será impuro até à tarde."}, {"numero": 41, "texto": "E todo réptil que vai arrastando sobre a terra, é abominação; não se comerá."}, {"numero": 42, "texto": "Tudo o que anda sobre o peito, e tudo o que anda sobre quatro ou mais patas, de todo réptil que anda arrastando sobre a terra, não o comereis, porque é abominação."}, {"numero": 43, "texto": "Não torneis abomináveis vossas pessoas com nenhum réptil que anda arrastando, nem vos contamineis com eles, nem sejais impuros por eles."}, {"numero": 44, "texto": "Pois que eu sou o SENHOR vosso Deus, vós portanto vos santificareis, e sereis santos, porque eu sou santo: assim que não torneis abomináveis vossas pessoas com nenhum réptil que andar arrastando sobre a terra."}, {"numero": 45, "texto": "Porque eu sou o SENHOR, que vos faço subir da terra do Egito para vos ser por Deus: sereis pois santos, porque eu sou santo."}, {"numero": 46, "texto": "Esta é a lei dos animais e das aves, e de todo ser vivente que se move nas águas, e de todo animal que anda arrastando sobre a terra;"}, {"numero": 47, "texto": "Para fazer diferença entre impuro e limpo, e entre os animais que se podem comer e os animais que não se podem comer."}]'::jsonb, 'Almeida Livre'),
  ('Lv', 11, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses and to Aaron, saying unto them,"}, {"numero": 2, "texto": "Speak unto the children of Israel, saying, These are the beasts which ye shall eat among all the beasts that are on the earth."}, {"numero": 3, "texto": "Whatsoever parteth the hoof, and is clovenfooted, and cheweth the cud, among the beasts, that shall ye eat."}, {"numero": 4, "texto": "Nevertheless these shall ye not eat of them that chew the cud, or of them that divide the hoof: as the camel, because he cheweth the cud, but divideth not the hoof; he is unclean unto you."}, {"numero": 5, "texto": "And the coney, because he cheweth the cud, but divideth not the hoof; he is unclean unto you."}, {"numero": 6, "texto": "And the hare, because he cheweth the cud, but divideth not the hoof; he is unclean unto you."}, {"numero": 7, "texto": "And the swine, though he divide the hoof, and be clovenfooted, yet he cheweth not the cud; he is unclean to you."}, {"numero": 8, "texto": "Of their flesh shall ye not eat, and their carcase shall ye not touch; they are unclean to you."}, {"numero": 9, "texto": "These shall ye eat of all that are in the waters: whatsoever hath fins and scales in the waters, in the seas, and in the rivers, them shall ye eat."}, {"numero": 10, "texto": "And all that have not fins and scales in the seas, and in the rivers, of all that move in the waters, and of any living thing which is in the waters, they shall be an abomination unto you:"}, {"numero": 11, "texto": "They shall be even an abomination unto you; ye shall not eat of their flesh, but ye shall have their carcases in abomination."}, {"numero": 12, "texto": "Whatsoever hath no fins nor scales in the waters, that shall be an abomination unto you."}, {"numero": 13, "texto": "And these are they which ye shall have in abomination among the fowls; they shall not be eaten, they are an abomination: the eagle, and the ossifrage, and the ospray,"}, {"numero": 14, "texto": "And the vulture, and the kite after his kind;"}, {"numero": 15, "texto": "Every raven after his kind;"}, {"numero": 16, "texto": "And the owl, and the night hawk, and the cuckow, and the hawk after his kind,"}, {"numero": 17, "texto": "And the little owl, and the cormorant, and the great owl,"}, {"numero": 18, "texto": "And the swan, and the pelican, and the gier eagle,"}, {"numero": 19, "texto": "And the stork, the heron after her kind, and the lapwing, and the bat."}, {"numero": 20, "texto": "All fowls that creep, going upon all four, shall be an abomination unto you."}, {"numero": 21, "texto": "Yet these may ye eat of every flying creeping thing that goeth upon all four, which have legs above their feet, to leap withal upon the earth;"}, {"numero": 22, "texto": "Even these of them ye may eat; the locust after his kind, and the bald locust after his kind, and the beetle after his kind, and the grasshopper after his kind."}, {"numero": 23, "texto": "But all other flying creeping things, which have four feet, shall be an abomination unto you."}, {"numero": 24, "texto": "And for these ye shall be unclean: whosoever toucheth the carcase of them shall be unclean until the even."}, {"numero": 25, "texto": "And whosoever beareth ought of the carcase of them shall wash his clothes, and be unclean until the even."}, {"numero": 26, "texto": "The carcases of every beast which divideth the hoof, and is not clovenfooted, nor cheweth the cud, are unclean unto you: every one that toucheth them shall be unclean."}, {"numero": 27, "texto": "And whatsoever goeth upon his paws, among all manner of beasts that go on all four, those are unclean unto you: whoso toucheth their carcase shall be unclean until the even."}, {"numero": 28, "texto": "And he that beareth the carcase of them shall wash his clothes, and be unclean until the even: they are unclean unto you."}, {"numero": 29, "texto": "These also shall be unclean unto you among the creeping things that creep upon the earth; the weasel, and the mouse, and the tortoise after his kind,"}, {"numero": 30, "texto": "And the ferret, and the chameleon, and the lizard, and the snail, and the mole."}, {"numero": 31, "texto": "These are unclean to you among all that creep: whosoever doth touch them, when they be dead, shall be unclean until the even."}, {"numero": 32, "texto": "And upon whatsoever any of them, when they are dead, doth fall, it shall be unclean; whether it be any vessel of wood, or raiment, or skin, or sack, whatsoever vessel it be, wherein any work is done, it must be put into water, and it shall be unclean until the even; so it shall be cleansed."}, {"numero": 33, "texto": "And every earthen vessel, whereinto any of them falleth, whatsoever is in it shall be unclean; and ye shall break it."}, {"numero": 34, "texto": "Of all meat which may be eaten, that on which such water cometh shall be unclean: and all drink that may be drunk in every such vessel shall be unclean."}, {"numero": 35, "texto": "And every thing whereupon any part of their carcase falleth shall be unclean; whether it be oven, or ranges for pots, they shall be broken down: for they are unclean and shall be unclean unto you."}, {"numero": 36, "texto": "Nevertheless a fountain or pit, wherein there is plenty of water, shall be clean: but that which toucheth their carcase shall be unclean."}, {"numero": 37, "texto": "And if any part of their carcase fall upon any sowing seed which is to be sown, it shall be clean."}, {"numero": 38, "texto": "But if any water be put upon the seed, and any part of their carcase fall thereon, it shall be unclean unto you."}, {"numero": 39, "texto": "And if any beast, of which ye may eat, die; he that toucheth the carcase thereof shall be unclean until the even."}, {"numero": 40, "texto": "And he that eateth of the carcase of it shall wash his clothes, and be unclean until the even: he also that beareth the carcase of it shall wash his clothes, and be unclean until the even."}, {"numero": 41, "texto": "And every creeping thing that creepeth upon the earth shall be an abomination; it shall not be eaten."}, {"numero": 42, "texto": "Whatsoever goeth upon the belly, and whatsoever goeth upon all four, or whatsoever hath more feet among all creeping things that creep upon the earth, them ye shall not eat; for they are an abomination."}, {"numero": 43, "texto": "Ye shall not make yourselves abominable with any creeping thing that creepeth, neither shall ye make yourselves unclean with them, that ye should be defiled thereby."}, {"numero": 44, "texto": "For I am the Lord your God: ye shall therefore sanctify yourselves, and ye shall be holy; for I am holy: neither shall ye defile yourselves with any manner of creeping thing that creepeth upon the earth."}, {"numero": 45, "texto": "For I am the Lord that bringeth you up out of the land of Egypt, to be your God: ye shall therefore be holy, for I am holy."}, {"numero": 46, "texto": "This is the law of the beasts, and of the fowl, and of every living creature that moveth in the waters, and of every creature that creepeth upon the earth:"}, {"numero": 47, "texto": "To make a difference between the unclean and the clean, and between the beast that may be eaten and the beast that may not be eaten."}]'::jsonb, 'King James Version'),
  ('Lv', 11, 'fr', '[{"numero": 1, "texto": "L''''Eternel parla à Moïse et à Aaron, et leur dit:"}, {"numero": 2, "texto": "Parlez aux enfants d''''Israël, et dites: Voici les animaux dont vous mangerez parmi toutes les bêtes qui sont sur la terre."}, {"numero": 3, "texto": "Vous mangerez de tout animal qui a la corne fendue, le pied fourchu, et qui rumine."}, {"numero": 4, "texto": "Mais vous ne mangerez pas de ceux qui ruminent seulement, ou qui ont la corne fendue seulement. Ainsi, vous ne mangerez pas le chameau, qui rumine, mais qui n''''a pas la corne fendue: vous le regarderez comme impur."}, {"numero": 5, "texto": "Vous ne mangerez pas le daman, qui rumine, mais qui n''''a pas la corne fendue: vous le regarderez comme impur."}, {"numero": 6, "texto": "Vous ne mangerez pas le lièvre, qui rumine, mais qui n''''a pas la corne fendue: vous le regarderez comme impur."}, {"numero": 7, "texto": "Vous ne mangerez pas le porc, qui a la corne fendue et le pied fourchu, mais qui ne rumine pas: vous le regarderez comme impur."}, {"numero": 8, "texto": "Vous ne mangerez pas de leur chair, et vous ne toucherez pas leurs corps morts: vous les regarderez comme impurs."}, {"numero": 9, "texto": "Voici les animaux dont vous mangerez parmi tous ceux qui sont dans les eaux. Vous mangerez de tous ceux qui ont des nageoires et des écailles, et qui sont dans les eaux, soit dans les mers, soit dans les rivières."}, {"numero": 10, "texto": "Mais vous aurez en abomination tous ceux qui n''''ont pas des nageoires et des écailles, parmi tout ce qui se meut dans les eaux et tout ce qui est vivant dans les eaux, soit dans les mers, soit dans les rivières."}, {"numero": 11, "texto": "Vous les aurez en abomination, vous ne mangerez pas de leur chair, et vous aurez en abomination leurs corps morts."}, {"numero": 12, "texto": "Vous aurez en abomination tous ceux qui, dans les eaux, n''''ont pas des nageoires et des écailles."}, {"numero": 13, "texto": "Voici, parmi les oiseaux, ceux que vous aurez en abomination, et dont on ne mangera pas: l''''aigle, l''''orfraie et l''''aigle de mer;"}, {"numero": 14, "texto": "le milan, l''''autour et ce qui est de son espèce;"}, {"numero": 15, "texto": "le corbeau et toutes ses espèces;"}, {"numero": 16, "texto": "l''''autruche, le hibou, la mouette, l''''épervier et ce qui est de son espèce;"}, {"numero": 17, "texto": "le chat-huant, le plongeon et la chouette;"}, {"numero": 18, "texto": "le cygne, le pélican et le cormoran;"}, {"numero": 19, "texto": "la cigogne, le héron et ce qui est de son espèce, la huppe et la chauve-souris."}, {"numero": 20, "texto": "Vous aurez en abomination tout reptile qui vole et qui marche sur quatre pieds."}, {"numero": 21, "texto": "Mais, parmi tous les reptiles qui volent et qui marchent sur quatre pieds, vous mangerez ceux qui ont des jambes au-dessus de leurs pieds, pour sauter sur la terre."}, {"numero": 22, "texto": "Voici ceux que vous mangerez: la sauterelle, le solam, le hargol et le hagab, selon leurs espèces."}, {"numero": 23, "texto": "Vous aurez en abomination tous les autres reptiles qui volent et qui ont quatre pieds."}, {"numero": 24, "texto": "Ils vous rendront impurs: quiconque touchera leurs corps morts sera impur jusqu''''au soir,"}, {"numero": 25, "texto": "et quiconque portera leurs corps morts lavera ses vêtements et sera impur jusqu''''au soir."}, {"numero": 26, "texto": "Vous regarderez comme impur tout animal qui a la corne fendue, mais qui n''''a pas le pied fourchu et qui ne rumine pas: quiconque le touchera sera impur."}, {"numero": 27, "texto": "Vous regarderez comme impurs tous ceux des animaux à quatre pieds qui marchent sur leurs pattes: quiconque touchera leurs corps morts sera impur jusqu''''au soir,"}, {"numero": 28, "texto": "et quiconque portera leurs corps morts lavera ses vêtements et sera impur jusqu''''au soir. Vous les regarderez comme impurs."}, {"numero": 29, "texto": "Voici, parmi les animaux qui rampent sur la terre, ceux que vous regarderez comme impurs: la taupe, la souris et le lézard, selon leurs espèces;"}, {"numero": 30, "texto": "le hérisson, la grenouille, la tortue, le limaçon et le caméléon."}, {"numero": 31, "texto": "Vous les regarderez comme impurs parmi tous les reptiles: quiconque les touchera morts sera impur jusqu''''au soir."}, {"numero": 32, "texto": "Tout objet sur lequel tombera quelque chose de leurs corps morts sera souillé, ustensile de bois, vêtement, peau, sac, tout objet dont on fait usage; il sera mis dans l''''eau, et restera souillé jusqu''''au soir; après quoi, il sera pur."}, {"numero": 33, "texto": "Tout ce qui se trouvera dans un vase de terre où il en tombera quelque chose, sera souillé, et vous briserez le vase."}, {"numero": 34, "texto": "Tout aliment qui sert à la nourriture, et sur lequel il sera tombé de cette eau, sera souillé; et toute boisson dont on fait usage, quel que soit le vase qui la contienne, sera souillée."}, {"numero": 35, "texto": "Tout objet sur lequel tombera quelque chose de leurs corps morts sera souillé; le four et le foyer seront détruits: ils seront souillés, et vous les regarderez comme souillés."}, {"numero": 36, "texto": "Il n''''y aura que les sources et les citernes, formant des amas d''''eaux, qui resteront pures; mais celui qui y touchera de leurs corps morts sera impur."}, {"numero": 37, "texto": "S''''il tombe quelque chose de leurs corps morts sur une semence qui doit être semée, elle restera pure;"}, {"numero": 38, "texto": "mais si l''''on a mis de l''''eau sur la semence, et qu''''il y tombe quelque chose de leurs corps morts, vous la regarderez comme souillée."}, {"numero": 39, "texto": "S''''il meurt un des animaux qui vous servent de nourriture, celui qui touchera son corps mort sera impur jusqu''''au soir;"}, {"numero": 40, "texto": "celui qui mangera de son corps mort lavera ses vêtements et sera impur jusqu''''au soir, et celui qui portera son corps mort lavera ses vêtements et sera impur jusqu''''au soir."}, {"numero": 41, "texto": "Vous aurez en abomination tout reptile qui rampe sur la terre: on n''''en mangera point."}, {"numero": 42, "texto": "Vous ne mangerez point, parmi tous les reptiles qui rampent sur la terre, de tous ceux qui se traînent sur le ventre, ni de tous ceux qui marchent sur quatre pieds ou sur un grand nombre de pieds; car vous les aurez en abomination."}, {"numero": 43, "texto": "Ne rendez point vos personnes abominables par tous ces reptiles qui rampent; ne vous rendez point impurs par eux, ne vous souillez point par eux."}, {"numero": 44, "texto": "Car je suis l''''Eternel, votre Dieu; vous vous sanctifierez, et vous serez saints, car je suis saint; et vous ne vous rendrez point impurs par tous ces reptiles qui rampent sur la terre."}, {"numero": 45, "texto": "Car je suis l''''Eternel, qui vous ai fait monter du pays d''''Egypte, pour être votre Dieu, et pour que vous soyez saints; car je suis saint."}, {"numero": 46, "texto": "Telle est la loi touchant les animaux, les oiseaux, tous les êtres vivants qui se meuvent dans les eaux, et tous les êtres qui rampent sur la terre,"}, {"numero": 47, "texto": "afin que vous distinguiez ce qui est impur et ce qui est pur, l''''animal qui se mange et l''''animal qui ne se mange pas."}]'::jsonb, 'Louis Segond 1910'),
  ('Lv', 11, 'es', '[{"numero": 1, "texto": "Y HABLÓ Jehová á Moisés y á Aarón, diciéndoles:"}, {"numero": 2, "texto": "Hablad á los hijos de Israel, diciendo: Estos son los animales que comeréis de todos los animales que están sobre la tierra."}, {"numero": 3, "texto": "De entre los animales, todo el de pezuña, y que tiene las pezuñas hendidas, y que rumia, éste comeréis."}, {"numero": 4, "texto": "Estos empero no comeréis de los que rumian, y de los que tienen pezuña: el camello, porque rumia mas no tiene pezuña hendida, habéis de tenerlo por inmundo;"}, {"numero": 5, "texto": "También el conejo, porque rumia, mas no tiene pezuña, tendréislo por inmundo;"}, {"numero": 6, "texto": "Asimismo la liebre, porque rumia, mas no tiene pezuña, tendréisla por inmunda;"}, {"numero": 7, "texto": "También el puerco, porque tiene pezuñas, y es de pezuñas hendidas, mas no rumia, tendréislo por inmundo."}, {"numero": 8, "texto": "De la carne de ellos no comeréis, ni tocaréis su cuerpo muerto: tendréislos por inmundos."}, {"numero": 9, "texto": "Esto comeréis de todas las cosas que están en las aguas: todas las cosas que tienen aletas y escamas en las aguas de la mar, y en los ríos, aquellas comeréis;"}, {"numero": 10, "texto": "Mas todas las cosas que no tienen aletas ni escamas en la mar y en los ríos, así de todo reptil de agua como de toda cosa viviente que está en las aguas, las tendréis en abominación."}, {"numero": 11, "texto": "Os serán, pues, en abominación: de su carne no comeréis, y abominaréis sus cuerpos muertos."}, {"numero": 12, "texto": "Todo lo que no tuviere aletas y escamas en las aguas, tendréislo en abominación."}, {"numero": 13, "texto": "Y de las aves, éstas tendréis en abominación; no se comerán, serán abominación: el águila, el quebrantahuesos, el esmerejón,"}, {"numero": 14, "texto": "El milano, y el buitre según su especie;"}, {"numero": 15, "texto": "Todo cuervo según su especie;"}, {"numero": 16, "texto": "El avestruz, y la lechuza, y el laro, y el gavilán según su especie,"}, {"numero": 17, "texto": "Y el buho, y el somormujo, y el ibis,"}, {"numero": 18, "texto": "Y el calamón, y el cisne, y el onocrótalo,"}, {"numero": 19, "texto": "Y el herodión, y el caradrión, según su especie, y la abubilla, y el murciélago."}, {"numero": 20, "texto": "Todo reptil alado que anduviere sobre cuatro pies, tendréis en abominación."}, {"numero": 21, "texto": "Empero esto comeréis de todo reptil alado que anda sobre cuatro pies, que tuviere piernas además de sus pies para saltar con ellas sobre la tierra;"}, {"numero": 22, "texto": "Estos comeréis de ellos: la langosta según su especie, y el langostín según su especie, y el aregol según su especie, y el haghab según su especie."}, {"numero": 23, "texto": "Todo reptil alado que tenga cuatro pies, tendréis en abominación."}, {"numero": 24, "texto": "Y por estas cosas seréis inmundos: cualquiera que tocare á sus cuerpos muertos, será inmundo hasta la tarde:"}, {"numero": 25, "texto": "Y cualquiera que llevare de sus cuerpos muertos, lavará sus vestidos, y será inmundo hasta la tarde."}, {"numero": 26, "texto": "Todo animal de pezuña, pero que no tiene pezuña hendida, ni rumia, tendréis por inmundo: cualquiera que los tocare será inmundo."}, {"numero": 27, "texto": "Y de todos los animales que andan á cuatro pies, tendréis por inmundo cualquiera que ande sobre sus garras: cualquiera que tocare sus cuerpos muertos, será inmundo hasta la tarde."}, {"numero": 28, "texto": "Y el que llevare sus cuerpos muertos, lavará sus vestidos, y será inmundo hasta la tarde: habéis de tenerlos por inmundos."}, {"numero": 29, "texto": "Y estos tendréis por inmundos de los reptiles que van arrastrando sobre la tierra: la comadreja, y el ratón, y la rana según su especie,"}, {"numero": 30, "texto": "Y el erizo, y el lagarto, y el caracol, y la babosa, y el topo."}, {"numero": 31, "texto": "Estos tendréis por inmundos de todos los reptiles: cualquiera que los tocare, cuando estuvieren muertos, será inmundo hasta la tarde."}, {"numero": 32, "texto": "Y todo aquello sobre que cayere alguno de ellos después de muertos, será inmundo; así vaso de madera, como vestido, ó piel, ó saco, cualquier instrumento con que se hace obra, será metido en agua, y será inmundo hasta la tarde, y así será limpio."}, {"numero": 33, "texto": "Y toda vasija de barro dentro de la cual cayere alguno de ellos, todo lo que estuviere en ella será inmundo, y quebraréis la vasija:"}, {"numero": 34, "texto": "Toda vianda que se come, sobre la cual viniere el agua de tales vasijas, será inmunda: y toda bebida que se bebiere, será en todas esas vasijas inmunda:"}, {"numero": 35, "texto": "Y todo aquello sobre que cayere algo del cuerpo muerto de ellos, será inmundo: el horno ú hornillos se derribarán; son inmundos, y por inmundos los tendréis."}, {"numero": 36, "texto": "Con todo, la fuente y la cisterna donde se recogen aguas, serán limpias: mas lo que hubiere tocado en sus cuerpos muertos será inmundo."}, {"numero": 37, "texto": "Y si cayere de sus cuerpos muertos sobre alguna simiente que se haya de sembrar, será limpia."}, {"numero": 38, "texto": "Mas si se hubiere puesto agua en la simiente, y cayere de sus cuerpos muertos sobre ella, tendréisla por inmunda."}, {"numero": 39, "texto": "Y si algún animal que tuviereis para comer se muriere, el que tocare su cuerpo muerto será inmundo hasta la tarde:"}, {"numero": 40, "texto": "Y el que comiere de su cuerpo muerto, lavará sus vestidos, y será inmundo hasta la tarde: asimismo el que sacare su cuerpo muerto, lavará sus vestidos, y será inmundo hasta la tarde."}, {"numero": 41, "texto": "Y todo reptil que va arrastrando sobre la tierra, es abominación; no se comerá."}, {"numero": 42, "texto": "Todo lo que anda sobre el pecho, y todo lo que anda sobre cuatro ó más pies, de todo reptil que anda arrastrando sobre la tierra, no lo comeréis, porque es abominación."}, {"numero": 43, "texto": "No ensuciéis vuestras personas con ningún reptil que anda arrastrando, ni os contaminéis con ellos, ni seáis inmundos por ellos."}, {"numero": 44, "texto": "Pues que yo soy Jehová vuestro Dios, vosotros por tanto os santificaréis, y seréis santos, porque yo soy santo: así que no ensuciéis vuestras personas con ningún reptil que anduviere arrastrando sobre la tierra."}, {"numero": 45, "texto": "Porque yo soy Jehová, que os hago subir de la tierra de Egipto para seros por Dios: seréis pues santos, porque yo soy santo."}, {"numero": 46, "texto": "Esta es la ley de los animales y de las aves, y de todo ser viviente que se mueve en las aguas, y de todo animal que anda arrastrando sobre la tierra;"}, {"numero": 47, "texto": "Para hacer diferencia entre inmundo y limpio, y entre los animales que se pueden comer y los animales que no se pueden comer."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 1, 'pt', '[{"numero": 1, "texto": "Princípio do Evangelho de Jesus Cristo, Filho de Deus."}, {"numero": 2, "texto": "Como está escrito nos profetas: Eis que eu envio o meu mensageiro diante de tua face, que preparará o teu caminho diante de ti ."}, {"numero": 3, "texto": "Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai suas veredas."}, {"numero": 4, "texto": "João veio a batizar no deserto, e a pregar o batismo de arrependimento para perdão dos pecados."}, {"numero": 5, "texto": "E toda a província da Judeia e os de Jerusalém saíam até ele; e eram todos batizados por ele no rio Jordão, confessando os seus pecados."}, {"numero": 6, "texto": "João se vestia de pelos de camelo, e um cinto de couro em sua cintura; e comia gafanhotos e mel do campo."}, {"numero": 7, "texto": "Ele pregava assim: Após mim vem aquele que é mais forte do que eu. A ele não sou digno de me abaixar para desatar a tira das suas sandálias."}, {"numero": 8, "texto": "De fato eu tenho vos batizado com água, porém ele vos batizará com Espírito Santo."}, {"numero": 9, "texto": "E aconteceu que, naqueles dias, Jesus de Nazaré da Galileia veio, e foi batizado por João no Jordão."}, {"numero": 10, "texto": "E assim que saiu da água, viu os céus se abrirem, e o Espírito, que como pomba descia sobre ele."}, {"numero": 11, "texto": "E veio uma voz dos céus: Tu és meu Filho amado, em quem me agrado."}, {"numero": 12, "texto": "E logo o Espírito o impeliu ao deserto."}, {"numero": 13, "texto": "Ele esteve ali no deserto quarenta dias, tentado por Satanás. Ele estava com os animais selvagens, e os anjos o serviam."}, {"numero": 14, "texto": "Depois que João foi preso, Jesus veio para a Galileia, pregando o Evangelho do Reino de Deus,"}, {"numero": 15, "texto": "e dizendo: O tempo se cumpriu, e o Reino de Deus está perto; arrependei-vos, e crede no Evangelho."}, {"numero": 16, "texto": "E enquanto andava junto ao mar da Galileia, ele viu Simão e seu irmão André, que lançavam uma rede ao mar, porque eram pescadores;"}, {"numero": 17, "texto": "Jesus lhes disse: Vinde após mim, e farei serdes pescadores de gente."}, {"numero": 18, "texto": "Então logo deixaram suas redes, e o seguiram."}, {"numero": 19, "texto": "E passando dali um pouco mais adiante, viu Tiago [filho] de Zebedeu, e seu irmão João, que estavam no barco, consertando as redes."}, {"numero": 20, "texto": "E logo os chamou; então eles deixaram o seu pai Zebedeu no barco com os empregados, foram após ele."}, {"numero": 21, "texto": "Eles entraram em Cafarnaum; e assim que chegou o sábado, [Jesus] entrou na sinagoga e começou a ensinar."}, {"numero": 22, "texto": "E ficavam admirados com o seu ensinamento, pois, diferentemente dos escribas, ele os ensinava como quem temautoridade."}, {"numero": 23, "texto": "E havia na sinagoga deles um homem com um espírito imundo, que gritou,"}, {"numero": 24, "texto": "dizendo: Ah, que temos contigo, Jesus Nazareno? Vieste para nos destruir? Bem sei quem és: o Santo de Deus."}, {"numero": 25, "texto": "Jesus o repreendeu, dizendo: Cala-te, e sai dele."}, {"numero": 26, "texto": "E o espírito imundo, provocando convulsão nele, e gritando em alta voz, saiu dele."}, {"numero": 27, "texto": "Assim todos ficaram admirados, e perguntavam entre si: Que é isto? Que novo ensinamento é este que, com autoridade, ordena até aos espíritos imundos, e eles lhe obedecem?"}, {"numero": 28, "texto": "E logo sua fama se espalhou por toda a região da Galileia."}, {"numero": 29, "texto": "Logo depois de saírem da sinagoga, vieram à casa de Simão e de André, com Tiago e João."}, {"numero": 30, "texto": "A sogra de Simão estava deitada com febre, e logo falaram dela [a Jesus] ."}, {"numero": 31, "texto": "Então ele aproximou-se dela, tomou-a pela mão, e a levantou; logo a febre a deixou, e ela começou a servi-los."}, {"numero": 32, "texto": "Ao entardecer, quando o sol já se punha, trouxeram-lhe todos os doentes e endemoninhados;"}, {"numero": 33, "texto": "e toda a cidade se juntou à porta."}, {"numero": 34, "texto": "Ele curou muitos que se achavam mal de diversas enfermidades, e expulsou muitos demônios. Ele não deixava os demônios falarem, porque o conheciam."}, {"numero": 35, "texto": "De madrugada, ainda escuro, ele se levantou para sair, foi a um lugar deserto, e ali esteve a orar."}, {"numero": 36, "texto": "Simão e os que estavam com ele o seguiram."}, {"numero": 37, "texto": "Quando o acharam, disseram-lhe: Todos estão te procurando."}, {"numero": 38, "texto": "[Jesus] lhes respondeu: Vamos para as aldeias vizinhas, para que eu também pregue ali, pois vim para isso."}, {"numero": 39, "texto": "Ele pregava em suas sinagogas por toda a Galileia, e expulsava os demônios."}, {"numero": 40, "texto": "Um leproso aproximou-se dele, rogando-lhe, pondo-se de joelhos diante dele, e dizendo-lhe: Se quiseres, tu podes limpar-me."}, {"numero": 41, "texto": "E Jesus , movido de compaixão, estendeu a mão, tocou-o, e disse-lhe: Quero; sê limpo."}, {"numero": 42, "texto": "Quando disse isso, logo a lepra saiu dele, e ficou limpo."}, {"numero": 43, "texto": "[Jesus] advertiu-o, e logo o despediu,"}, {"numero": 44, "texto": "dizendo-lhe: Cuidado, não digas nada a ninguém. Mas vai, mostra-te ao Sacerdote, e oferece por teres ficado limpo o que Moisés mandou, para lhes servir de testemunho."}, {"numero": 45, "texto": "Porém, quando ele saiu, começou a anunciar muitas coisas, e a divulgar a notícia, de maneira que [Jesus] já não podia entrar publicamente na cidade; em vez disso, ficava do lado de fora em lugares desertos, e [pessoas] de todas as partes vinham até ele."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 1, 'en', '[{"numero": 1, "texto": "The beginning of the gospel of Jesus Christ, the Son of God;"}, {"numero": 2, "texto": "As it is written in the prophets, Behold, I send my messenger before thy face, which shall prepare thy way before thee."}, {"numero": 3, "texto": "The voice of one crying in the wilderness, Prepare ye the way of the Lord, make his paths straight."}, {"numero": 4, "texto": "John did baptize in the wilderness, and preach the baptism of repentance for the remission of sins."}, {"numero": 5, "texto": "And there went out unto him all the land of Judaea, and they of Jerusalem, and were all baptized of him in the river of Jordan, confessing their sins."}, {"numero": 6, "texto": "And John was clothed with camel''s hair, and with a girdle of a skin about his loins; and he did eat locusts and wild honey;"}, {"numero": 7, "texto": "And preached, saying, There cometh one mightier than I after me, the latchet of whose shoes I am not worthy to stoop down and unloose."}, {"numero": 8, "texto": "I indeed have baptized you with water: but he shall baptize you with the Holy Ghost."}, {"numero": 9, "texto": "And it came to pass in those days, that Jesus came from Nazareth of Galilee, and was baptized of John in Jordan."}, {"numero": 10, "texto": "And straightway coming up out of the water, he saw the heavens opened, and the Spirit like a dove descending upon him:"}, {"numero": 11, "texto": "And there came a voice from heaven, saying, Thou art my beloved Son, in whom I am well pleased."}, {"numero": 12, "texto": "And immediately the spirit driveth him into the wilderness."}, {"numero": 13, "texto": "And he was there in the wilderness forty days, tempted of Satan; and was with the wild beasts; and the angels ministered unto him."}, {"numero": 14, "texto": "Now after that John was put in prison, Jesus came into Galilee, preaching the gospel of the kingdom of God,"}, {"numero": 15, "texto": "And saying, The time is fulfilled, and the kingdom of God is at hand: repent ye, and believe the gospel."}, {"numero": 16, "texto": "Now as he walked by the sea of Galilee, he saw Simon and Andrew his brother casting a net into the sea: for they were fishers."}, {"numero": 17, "texto": "And Jesus said unto them, Come ye after me, and I will make you to become fishers of men."}, {"numero": 18, "texto": "And straightway they forsook their nets, and followed him."}, {"numero": 19, "texto": "And when he had gone a little farther thence, he saw James the son of Zebedee, and John his brother, who also were in the ship mending their nets."}, {"numero": 20, "texto": "And straightway he called them: and they left their father Zebedee in the ship with the hired servants, and went after him."}, {"numero": 21, "texto": "And they went into Capernaum; and straightway on the sabbath day he entered into the synagogue, and taught."}, {"numero": 22, "texto": "And they were astonished at his doctrine: for he taught them as one that had authority, and not as the scribes."}, {"numero": 23, "texto": "And there was in their synagogue a man with an unclean spirit; and he cried out,"}, {"numero": 24, "texto": "Saying, Let us alone; what have we to do with thee, thou Jesus of Nazareth? art thou come to destroy us? I know thee who thou art, the Holy One of God."}, {"numero": 25, "texto": "And Jesus rebuked him, saying, Hold thy peace, and come out of him."}, {"numero": 26, "texto": "And when the unclean spirit had torn him, and cried with a loud voice, he came out of him."}, {"numero": 27, "texto": "And they were all amazed, insomuch that they questioned among themselves, saying, What thing is this? what new doctrine is this? for with authority commandeth he even the unclean spirits, and they do obey him."}, {"numero": 28, "texto": "And immediately his fame spread abroad throughout all the region round about Galilee."}, {"numero": 29, "texto": "And forthwith, when they were come out of the synagogue, they entered into the house of Simon and Andrew, with James and John."}, {"numero": 30, "texto": "But Simon''s wife''s mother lay sick of a fever, and anon they tell him of her."}, {"numero": 31, "texto": "And he came and took her by the hand, and lifted her up; and immediately the fever left her, and she ministered unto them."}, {"numero": 32, "texto": "And at even, when the sun did set, they brought unto him all that were diseased, and them that were possessed with devils."}, {"numero": 33, "texto": "And all the city was gathered together at the door."}, {"numero": 34, "texto": "And he healed many that were sick of divers diseases, and cast out many devils; and suffered not the devils to speak, because they knew him."}, {"numero": 35, "texto": "And in the morning, rising up a great while before day, he went out, and departed into a solitary place, and there prayed."}, {"numero": 36, "texto": "And Simon and they that were with him followed after him."}, {"numero": 37, "texto": "And when they had found him, they said unto him, All men seek for thee."}, {"numero": 38, "texto": "And he said unto them, Let us go into the next towns, that I may preach there also: for therefore came I forth."}, {"numero": 39, "texto": "And he preached in their synagogues throughout all Galilee, and cast out devils."}, {"numero": 40, "texto": "And there came a leper to him, beseeching him, and kneeling down to him, and saying unto him, If thou wilt, thou canst make me clean."}, {"numero": 41, "texto": "And Jesus, moved with compassion, put forth his hand, and touched him, and saith unto him, I will; be thou clean."}, {"numero": 42, "texto": "And as soon as he had spoken, immediately the leprosy departed from him, and he was cleansed."}, {"numero": 43, "texto": "And he straitly charged him, and forthwith sent him away;"}, {"numero": 44, "texto": "And saith unto him, See thou say nothing to any man: but go thy way, shew thyself to the priest, and offer for thy cleansing those things which Moses commanded, for a testimony unto them."}, {"numero": 45, "texto": "But he went out, and began to publish it much, and to blaze abroad the matter, insomuch that Jesus could no more openly enter into the city, but was without in desert places: and they came to him from every quarter."}]'::jsonb, 'King James Version'),
  ('Mc', 1, 'fr', '[{"numero": 1, "texto": "Commencement de l''''Evangile de Jésus-Christ, Fils de Dieu."}, {"numero": 2, "texto": "Selon ce qui est écrit dans Esaïe, le prophète: Voici, j''''envoie devant toi mon messager, Qui préparera ton chemin;"}, {"numero": 3, "texto": "C''''est la voix de celui qui crie dans le désert: Préparez le chemin du Seigneur, Aplanissez ses sentiers."}, {"numero": 4, "texto": "Jean parut, baptisant dans le désert, et prêchant le baptême de repentance, pour la rémission des péchés."}, {"numero": 5, "texto": "Tout le pays de Judée et tous les habitants de Jérusalem se rendaient auprès de lui; et, confessant leurs péchés, ils se faisaient baptiser par lui dans le fleuve du Jourdain."}, {"numero": 6, "texto": "Jean avait un vêtement de poils de chameau, et une ceinture de cuir autour des reins. Il se nourrissait de sauterelles et de miel sauvage."}, {"numero": 7, "texto": "Il prêchait, disant: Il vient après moi celui qui est plus puissant que moi, et je ne suis pas digne de délier, en me baissant, la courroie de ses souliers."}, {"numero": 8, "texto": "Moi, je vous ai baptisés d''''eau; lui, il vous baptisera du Saint-Esprit."}, {"numero": 9, "texto": "En ce temps-là, Jésus vint de Nazareth en Galilée, et il fut baptisé par Jean dans le Jourdain."}, {"numero": 10, "texto": "Au moment où il sortait de l''''eau, il vit les cieux s''''ouvrir, et l''''Esprit descendre sur lui comme une colombe."}, {"numero": 11, "texto": "Et une voix fit entendre des cieux ces paroles: Tu es mon Fils bien-aimé, en toi j''''ai mis toute mon affection."}, {"numero": 12, "texto": "Aussitôt, l''''Esprit poussa Jésus dans le désert,"}, {"numero": 13, "texto": "où il passa quarante jours, tenté par Satan. Il était avec les bêtes sauvages, et les anges le servaient."}, {"numero": 14, "texto": "Après que Jean eut été livré, Jésus alla dans la Galilée, prêchant l''''Evangile de Dieu."}, {"numero": 15, "texto": "Il disait: Le temps est accompli, et le royaume de Dieu est proche. Repentez-vous, et croyez à la bonne nouvelle."}, {"numero": 16, "texto": "Comme il passait le long de la mer de Galilée, il vit Simon et André, frère de Simon, qui jetaient un filet dans la mer; car ils étaient pêcheurs."}, {"numero": 17, "texto": "Jésus leur dit: Suivez-moi, et je vous ferai pêcheurs d''''hommes."}, {"numero": 18, "texto": "Aussitôt, ils laissèrent leurs filets, et le suivirent."}, {"numero": 19, "texto": "Etant allé un peu plus loin, il vit Jacques, fils de Zébédée, et Jean, son frère, qui, eux aussi, étaient dans une barque et réparaient les filets."}, {"numero": 20, "texto": "Aussitôt, il les appela; et, laissant leur père Zébédée dans la barque avec les ouvriers, ils le suivirent."}, {"numero": 21, "texto": "Ils se rendirent à Capernaüm. Et, le jour du sabbat, Jésus entra d''''abord dans la synagogue, et il enseigna."}, {"numero": 22, "texto": "Ils étaient frappés de sa doctrine; car il enseignait comme ayant autorité, et non pas comme les scribes."}, {"numero": 23, "texto": "Il se trouva dans leur synagogue un homme qui avait un esprit impur, et qui s''''écria:"}, {"numero": 24, "texto": "Qu''''y a-t-il entre nous et toi, Jésus de Nazareth? Tu es venu pour nous perdre. Je sais qui tu es: le Saint de Dieu."}, {"numero": 25, "texto": "Jésus le menaça, disant: Tais-toi, et sors de cet homme."}, {"numero": 26, "texto": "Et l''''esprit impur sortit de cet homme, en l''''agitant avec violence, et en poussant un grand cri."}, {"numero": 27, "texto": "Tous furent saisis de stupéfaction, de sorte qu''''ils se demandaient les uns aux autres: Qu''''est-ce que ceci? Une nouvelle doctrine! Il commande avec autorité même aux esprits impurs, et ils lui obéissent!"}, {"numero": 28, "texto": "Et sa renommée se répandit aussitôt dans tous les lieux environnants de la Galilée."}, {"numero": 29, "texto": "En sortant de la synagogue, ils se rendirent avec Jacques et Jean à la maison de Simon et d''''André."}, {"numero": 30, "texto": "La belle-mère de Simon était couchée, ayant la fièvre; et aussitôt on parla d''''elle à Jésus."}, {"numero": 31, "texto": "S''''étant approché, il la fit lever en lui prenant la main, et à l''''instant la fièvre la quitta. Puis elle les servit."}, {"numero": 32, "texto": "Le soir, après le coucher du soleil, on lui amena tous les malades et les démoniaques."}, {"numero": 33, "texto": "Et toute la ville était rassemblée devant sa porte."}, {"numero": 34, "texto": "Il guérit beaucoup de gens qui avaient diverses maladies; il chassa aussi beaucoup de démons, et il ne permettait pas aux démons de parler, parce qu''''ils le connaissaient."}, {"numero": 35, "texto": "Vers le matin, pendant qu''''il faisait encore très sombre, il se leva, et sortit pour aller dans un lieu désert, où il pria."}, {"numero": 36, "texto": "Simon et ceux qui étaient avec lui se mirent à sa recherche;"}, {"numero": 37, "texto": "et, quand ils l''''eurent trouvé, ils lui dirent: Tous te cherchent."}, {"numero": 38, "texto": "Il leur répondit: Allons ailleurs, dans les bourgades voisines, afin que j''''y prêche aussi; car c''''est pour cela que je suis sorti."}, {"numero": 39, "texto": "Et il alla prêcher dans les synagogues, par toute la Galilée, et il chassa les démons."}, {"numero": 40, "texto": "Un lépreux vint à lui; et, se jetant à genoux, il lui dit d''''un ton suppliant: Si tu le veux, tu peux me rendre pur."}, {"numero": 41, "texto": "Jésus, ému de compassion, étendit la main, le toucha, et dit: Je le veux, sois pur."}, {"numero": 42, "texto": "Aussitôt la lèpre le quitta, et il fut purifié."}, {"numero": 43, "texto": "Jésus le renvoya sur-le-champ, avec de sévères recommandations,"}, {"numero": 44, "texto": "et lui dit: Garde-toi de rien dire à personne; mais va te montrer au sacrificateur, et offre pour ta purification ce que Moïse a prescrit, afin que cela leur serve de témoignage."}, {"numero": 45, "texto": "Mais cet homme, s''''en étant allé, se mit à publier hautement la chose et à la divulguer, de sorte que Jésus ne pouvait plus entrer publiquement dans une ville. Il se tenait dehors, dans des lieux déserts, et l''''on venait à lui de toutes parts."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 1, 'es', '[{"numero": 1, "texto": "PRINCIPIO del evangelio de Jesucristo, Hijo de Dios."}, {"numero": 2, "texto": "Como está escrito en Isaías el profeta: He aquí yo envío á mi mensajero delante de tu faz, que apareje tu camino delante de ti."}, {"numero": 3, "texto": "Voz del que clama en el desierto: Aparejad el camino del Señor; enderezad sus veredas."}, {"numero": 4, "texto": "Bautizaba Juan en el desierto, y predicaba el bautismo del arrepentimiento para remisión de pecados."}, {"numero": 5, "texto": "Y salía á él toda la provincia de Judea, y los de Jerusalem; y eran todos bautizados por él en el río de Jordán, confesando sus pecados."}, {"numero": 6, "texto": "Y Juan andaba vestido de pelos de camello, y con un cinto de cuero alrededor de sus lomos; y comía langostas y miel silvestre."}, {"numero": 7, "texto": "Y predicaba, diciendo: Viene tras mí el que es más poderoso que yo, al cual no soy digno de desatar encorvado la correa de sus zapatos."}, {"numero": 8, "texto": "Yo á la verdad os he bautizado con agua; mas él os bautizará con Espíritu Santo."}, {"numero": 9, "texto": "Y aconteció en aquellos días, que Jesús vino de Nazaret de Galilea, y fué bautizado por Juan en el Jordán."}, {"numero": 10, "texto": "Y luego, subiendo del agua, vió abrirse los cielos, y al Espíritu como paloma, que descendía sobre él."}, {"numero": 11, "texto": "Y hubo una voz de los cielos que decía: Tú eres mi Hijo amado; en ti tomo contentamiento."}, {"numero": 12, "texto": "Y luego el Espíritu le impele al desierto."}, {"numero": 13, "texto": "Y estuvo allí en el desierto cuarenta días, y era tentado de Satanás; y estaba con las fieras; y los ángeles le servían."}, {"numero": 14, "texto": "Mas después que Juan fué encarcelado, Jesús vino á Galilea predicando el evangelio del reino de Dios,"}, {"numero": 15, "texto": "Y diciendo: El tiempo es cumplido, y el reino de Dios está cerca: arrepentíos, y creed al evangelio."}, {"numero": 16, "texto": "Y pasando junto á la mar de Galilea, vió á Simón, y á Andrés su hermano, que echaban la red en la mar; porque eran pescadores."}, {"numero": 17, "texto": "Y les dijo Jesús: Venid en pos de mí, y haré que seáis pescadores de hombres."}, {"numero": 18, "texto": "Y luego, dejadas sus redes, le siguieron."}, {"numero": 19, "texto": "Y pasando de allí un poco más adelante, vió á Jacobo, hijo de Zebedeo, y á Juan su hermano, también ellos en el navío, que aderezaban las redes."}, {"numero": 20, "texto": "Y luego los llamó: y dejando á su padre Zebedeo en el barco con los jornaleros, fueron en pos de él."}, {"numero": 21, "texto": "Y entraron en Capernaum; y luego los sábados, entrando en la sinagoga, enseñaba."}, {"numero": 22, "texto": "Y se admiraban de su doctrina; porque les enseñaba como quien tiene potestad, y no como los escribas."}, {"numero": 23, "texto": "Y había en la sinagoga de ellos un hombre con espíritu inmundo, el cual dió voces,"}, {"numero": 24, "texto": "Diciendo: ¡Ah! ¿qué tienes con nosotros, Jesús Nazareno? ¿Has venido á destruirnos? Sé quién eres, el Santo de Dios."}, {"numero": 25, "texto": "Y Jesús le riñó, diciendo: Enmudece, y sal de él."}, {"numero": 26, "texto": "Y el espíritu inmundo, haciéndole pedazos, y clamando á gran voz, salió de él."}, {"numero": 27, "texto": "Y todos se maravillaron, de tal manera que inquirían entre sí, diciendo: ¿Qué es esto? ¿Qué nueva doctrina es ésta, que con potestad aun á los espíritus inmundos manda, y le obedecen?"}, {"numero": 28, "texto": "Y vino luego su fama por toda la provincia alrededor de Galilea."}, {"numero": 29, "texto": "Y luego saliendo de la sinagoga, vinieron á casa de Simón y de Andrés, con Jacobo y Juan."}, {"numero": 30, "texto": "Y la suegra de Simón estaba acostada con calentura; y le hablaron luego de ella."}, {"numero": 31, "texto": "Entonces llegando él, la tomó de su mano y la levantó; y luego la dejó la calentura, y les servía."}, {"numero": 32, "texto": "Y cuando fué la tarde, luego que el sol se puso, traían á él todos los que tenían mal, y endemoniados;"}, {"numero": 33, "texto": "Y toda la ciudad se juntó á la puerta."}, {"numero": 34, "texto": "Y sanó á muchos que estaban enfermos de diversas enfermedades, y echó fuera muchos demonios; y no dejaba decir á los demonios que le conocían."}, {"numero": 35, "texto": "Y levantándose muy de mañana, aun muy de noche, salió y se fué á un lugar desierto, y allí oraba."}, {"numero": 36, "texto": "Y le siguió Simón, y los que estaban con él;"}, {"numero": 37, "texto": "Y hallándole, le dicen: Todos te buscan."}, {"numero": 38, "texto": "Y les dice: Vamos á los lugares vecinos, para que predique también allí; porque para esto he venido."}, {"numero": 39, "texto": "Y predicaba en las sinagogas de ellos en toda Galilea, y echaba fuera los demonios."}, {"numero": 40, "texto": "Y un leproso vino á él, rogándole; é hincada la rodilla, le dice: Si quieres, puedes limpiarme."}, {"numero": 41, "texto": "Y Jesús, teniendo misericordia de él, extendió su mano, y le tocó, y le dice: Quiero, sé limpio."}, {"numero": 42, "texto": "Y así que hubo él hablado, la lepra se fué luego de aquél, y fué limpio."}, {"numero": 43, "texto": "Entonces le apercibió, y despidióle luego,"}, {"numero": 44, "texto": "Y le dice: Mira, no digas á nadie nada; sino ve, muéstrate al sacerdote, y ofrece por tu limpieza lo que Moisés mandó, para testimonio á ellos."}, {"numero": 45, "texto": "Mas él salido, comenzó á publicarlo mucho, y á divulgar el hecho, de manera que ya Jesús no podía entrar manifiestamente en la ciudad, sino que estaba fuera en los lugares desiertos; y venían á él de todas partes."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 2, 'pt', '[{"numero": 1, "texto": "Dias depois, [Jesus] entrou outra vez em Cafarnaum, e ouviu-se que estava em casa."}, {"numero": 2, "texto": "Logo juntaram-se tantos, que nem mesmo perto da porta cabiam; e ele lhes falava a palavra."}, {"numero": 3, "texto": "E vieram a ele uns que traziam um paralítico carregado por quatro."}, {"numero": 4, "texto": "Como não podiam se aproximar dele por causa da multidão, descobriram o telhado onde ele estava, fizeram um buraco, e baixaram [por ele] o leito em que jazia o paralítico."}, {"numero": 5, "texto": "Quando Jesus viu a fé deles, disse ao paralítico: Filho, os teus pecados te são perdoados."}, {"numero": 6, "texto": "E estavam ali sentados alguns escribas, que pensavam em seus corações:"}, {"numero": 7, "texto": "Por que este [homem] fala essas blasfêmias? Quem pode perdoar pecados, a não ser somente Deus?"}, {"numero": 8, "texto": "Imediatamente Jesus percebeu em seu espírito que assim pensavam em si mesmos. Então perguntou-lhes: Por que pensais assim em vossos corações?"}, {"numero": 9, "texto": "O que é mais fácil? Dizer ao paralítico: “Os teus pecados estão perdoados”, ou dizer, “Levanta-te, toma o teu leito, e anda”?"}, {"numero": 10, "texto": "Mas para que saibais que o Filho do homem tem poder na terra para perdoar pecados,(disse ao paralítico):"}, {"numero": 11, "texto": "A ti eu digo: levanta-te, toma o teu leito, e vai para a tua casa."}, {"numero": 12, "texto": "E logo ele se levantou, tomou o leito, e saiu na presença de todos, de tal maneira, que todos ficaram admirados, e glorificaram a Deus, dizendo: Nunca vimos algo assim."}, {"numero": 13, "texto": "[Jesus] voltou a sair para o mar; toda a multidão veio até ele, e ele os ensinava."}, {"numero": 14, "texto": "E enquanto passava, ele viu Levi, [filho] de Alfeu, sentado no posto de coleta de impostos, e disse-lhe: Segue-me.Então [Levi] se levantou e o seguiu."}, {"numero": 15, "texto": "E aconteceu que enquanto estava sentado à mesa na casa dele, muitos publicanos e pecadores também estavam assentados à mesa com Jesus e os seus discípulos; porque eram muitos, e o haviam seguido."}, {"numero": 16, "texto": "Quando os escribas e os fariseus o viram comer com os publicanos e pecadores, disseram a seus discípulos: Por que é que ele come e bebe com os publicanos e os pecadores?"}, {"numero": 17, "texto": "Jesus ouviu e lhes respondeu: Os que têm saúde não precisam de médico, mas sim os que estão doentes. Eu não vim para chamar os justos, mas sim, os pecadores, ao arrependimento."}, {"numero": 18, "texto": "Os discípulos de João e os dos fariseus estavam jejuando; então vieram lhe perguntar: Por que os discípulos de João e os dos fariseus jejuam, e os teus discípulos não jejuam?"}, {"numero": 19, "texto": "Jesus lhes respondeu: Podem os convidados do casamento jejuar enquanto o noivo estiver com eles? Enquanto tiverem o noivo consigo, eles não podem jejuar."}, {"numero": 20, "texto": "Mas dias virão, quando o noivo lhes for tirado; e então naqueles dias jejuarão."}, {"numero": 21, "texto": "Ninguém costura remendo de pano novo em roupa velha; senão o remendo novo rompe o velho, e se faz pior rasgo."}, {"numero": 22, "texto": "E ninguém põe vinho novo em odres velhos; senão o vinho novo rompe os odres, derrama-se o vinho, e os odres se danificam; mas o vinho novo deve ser posto em odres novos."}, {"numero": 23, "texto": "E aconteceu que, enquanto [Jesus] passava pelas plantações no sábado, os seus discípulos, andando, começaram a arrancar espigas."}, {"numero": 24, "texto": "Os fariseus lhe disseram: Olha! Por que estão fazendo o que não é lícito no sábado?"}, {"numero": 25, "texto": "E ele lhes disse: Nunca lestes o que fez Davi, quando teve necessidade e fome, ele e os que com ele estavam?"}, {"numero": 26, "texto": "Como ele entrou na Casa de Deus, quando Abiatar era sumo sacerdote, e comeu os pães da proposição (dos quais não é lícito comer, a não ser aos sacerdotes), e também deu aos que com ele estavam?"}, {"numero": 27, "texto": "Disse-lhes mais: O sábado foi feito por causa do ser humano, não o ser humano por causa do sábado."}, {"numero": 28, "texto": "Por isso o Filho do homem é Senhor até do sábado."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 2, 'en', '[{"numero": 1, "texto": "And again he entered into Capernaum after some days; and it was noised that he was in the house."}, {"numero": 2, "texto": "And straightway many were gathered together, insomuch that there was no room to receive them, no, not so much as about the door: and he preached the word unto them."}, {"numero": 3, "texto": "And they come unto him, bringing one sick of the palsy, which was borne of four."}, {"numero": 4, "texto": "And when they could not come nigh unto him for the press, they uncovered the roof where he was: and when they had broken it up, they let down the bed wherein the sick of the palsy lay."}, {"numero": 5, "texto": "When Jesus saw their faith, he said unto the sick of the palsy, Son, thy sins be forgiven thee."}, {"numero": 6, "texto": "But there was certain of the scribes sitting there, and reasoning in their hearts,"}, {"numero": 7, "texto": "Why doth this man thus speak blasphemies? who can forgive sins but God only?"}, {"numero": 8, "texto": "And immediately when Jesus perceived in his spirit that they so reasoned within themselves, he said unto them, Why reason ye these things in your hearts?"}, {"numero": 9, "texto": "Whether is it easier to say to the sick of the palsy, Thy sins be forgiven thee; or to say, Arise, and take up thy bed, and walk?"}, {"numero": 10, "texto": "But that ye may know that the Son of man hath power on earth to forgive sins, (he saith to the sick of the palsy,)"}, {"numero": 11, "texto": "I say unto thee, Arise, and take up thy bed, and go thy way into thine house."}, {"numero": 12, "texto": "And immediately he arose, took up the bed, and went forth before them all; insomuch that they were all amazed, and glorified God, saying, We never saw it on this fashion."}, {"numero": 13, "texto": "And he went forth again by the sea side; and all the multitude resorted unto him, and he taught them."}, {"numero": 14, "texto": "And as he passed by, he saw Levi the son of Alphaeus sitting at the receipt of custom, and said unto him, Follow me. And he arose and followed him."}, {"numero": 15, "texto": "And it came to pass, that, as Jesus sat at meat in his house, many publicans and sinners sat also together with Jesus and his disciples: for there were many, and they followed him."}, {"numero": 16, "texto": "And when the scribes and Pharisees saw him eat with publicans and sinners, they said unto his disciples, How is it that he eateth and drinketh with publicans and sinners?"}, {"numero": 17, "texto": "When Jesus heard it, he saith unto them, They that are whole have no need of the physician, but they that are sick: I came not to call the righteous, but sinners to repentance."}, {"numero": 18, "texto": "And the disciples of John and of the Pharisees used to fast: and they come and say unto him, Why do the disciples of John and of the Pharisees fast, but thy disciples fast not?"}, {"numero": 19, "texto": "And Jesus said unto them, Can the children of the bridechamber fast, while the bridegroom is with them? as long as they have the bridegroom with them, they cannot fast."}, {"numero": 20, "texto": "But the days will come, when the bridegroom shall be taken away from them, and then shall they fast in those days."}, {"numero": 21, "texto": "No man also seweth a piece of new cloth on an old garment: else the new piece that filled it up taketh away from the old, and the rent is made worse."}, {"numero": 22, "texto": "And no man putteth new wine into old bottles: else the new wine doth burst the bottles, and the wine is spilled, and the bottles will be marred: but new wine must be put into new bottles."}, {"numero": 23, "texto": "And it came to pass, that he went through the corn fields on the sabbath day; and his disciples began, as they went, to pluck the ears of corn."}, {"numero": 24, "texto": "And the Pharisees said unto him, Behold, why do they on the sabbath day that which is not lawful?"}, {"numero": 25, "texto": "And he said unto them, Have ye never read what David did, when he had need, and was an hungred, he, and they that were with him?"}, {"numero": 26, "texto": "How he went into the house of God in the days of Abiathar the high priest, and did eat the shewbread, which is not lawful to eat but for the priests, and gave also to them which were with him?"}, {"numero": 27, "texto": "And he said unto them, The sabbath was made for man, and not man for the sabbath:"}, {"numero": 28, "texto": "Therefore the Son of man is Lord also of the sabbath."}]'::jsonb, 'King James Version'),
  ('Mc', 2, 'fr', '[{"numero": 1, "texto": "Quelques jours après, Jésus revint à Capernaüm. On apprit qu''''il était à la maison,"}, {"numero": 2, "texto": "et il s''''assembla un si grand nombre de personnes que l''''espace devant la porte ne pouvait plus les contenir. Il leur annonçait la parole."}, {"numero": 3, "texto": "Des gens vinrent à lui, amenant un paralytique porté par quatre hommes."}, {"numero": 4, "texto": "Comme ils ne pouvaient l''''aborder, à cause de la foule, ils découvrirent le toit de la maison où il était, et ils descendirent par cette ouverture le lit sur lequel le paralytique était couché."}, {"numero": 5, "texto": "Jésus, voyant leur foi, dit au paralytique: Mon enfant, tes péchés sont pardonnés."}, {"numero": 6, "texto": "Il y avait là quelques scribes, qui étaient assis, et qui se disaient au dedans d''''eux:"}, {"numero": 7, "texto": "Comment cet homme parle-t-il ainsi? Il blasphème. Qui peut pardonner les péchés, si ce n''''est Dieu seul?"}, {"numero": 8, "texto": "Jésus, ayant aussitôt connu par son esprit ce qu''''ils pensaient au dedans d''''eux, leur dit: Pourquoi avez-vous de telles pensées dans vos coeurs?"}, {"numero": 9, "texto": "Lequel est le plus aisé, de dire au paralytique: Tes péchés sont pardonnés, ou de dire: Lève-toi, prends ton lit, et marche?"}, {"numero": 10, "texto": "Or, afin que vous sachiez que le Fils de l''''homme a sur la terre le pouvoir de pardonner les péchés:"}, {"numero": 11, "texto": "Je te l''''ordonne, dit-il au paralytique, lève-toi, prends ton lit, et va dans ta maison."}, {"numero": 12, "texto": "Et, à l''''instant, il se leva, prit son lit, et sortit en présence de tout le monde, de sorte qu''''ils étaient tous dans l''''étonnement et glorifiaient Dieu, disant: Nous n''''avons jamais rien vu de pareil."}, {"numero": 13, "texto": "Jésus sortit de nouveau du côté de la mer. Toute la foule venait à lui, et il les enseignait."}, {"numero": 14, "texto": "En passant, il vit Lévi, fils d''''Alphée, assis au bureau des péages. Il lui dit: Suis-moi. Lévi se leva, et le suivit."}, {"numero": 15, "texto": "Comme Jésus était à table dans la maison de Lévi, beaucoup de publicains et de gens de mauvaise vie se mirent aussi à table avec lui et avec ses disciples; car ils étaient nombreux, et l''''avaient suivi."}, {"numero": 16, "texto": "Les scribes et les pharisiens, le voyant manger avec les publicains et les gens de mauvaise vie, dirent à ses disciples: Pourquoi mange-t-il et boit-il avec les publicains et les gens de mauvaise vie?"}, {"numero": 17, "texto": "Ce que Jésus ayant entendu, il leur dit: Ce ne sont pas ceux qui se portent bien qui ont besoin de médecin, mais les malades. Je ne suis pas venu appeler des justes, mais des pécheurs."}, {"numero": 18, "texto": "Les disciples de Jean et les pharisiens jeûnaient. Ils vinrent dire à Jésus: Pourquoi les disciples de Jean et ceux des pharisiens jeûnent-ils, tandis que tes disciples ne jeûnent point?"}, {"numero": 19, "texto": "Jésus leur répondit: Les amis de l''''époux peuvent-ils jeûner pendant que l''''époux est avec eux? Aussi longtemps qu''''ils ont avec eux l''''époux, ils ne peuvent jeûner."}, {"numero": 20, "texto": "Les jours viendront où l''''époux leur sera enlevé, et alors ils jeûneront en ce jour-là."}, {"numero": 21, "texto": "Personne ne coud une pièce de drap neuf à un vieil habit; autrement, la pièce de drap neuf emporterait une partie du vieux, et la déchirure serait pire."}, {"numero": 22, "texto": "Et personne ne met du vin nouveau dans de vieilles outres; autrement, le vin fait rompre les outres, et le vin et les outres sont perdus; mais il faut mettre le vin nouveau dans des outres neuves."}, {"numero": 23, "texto": "Il arriva, un jour de sabbat, que Jésus traversa des champs de blé. Ses disciples, chemin faisant, se mirent à arracher des épis."}, {"numero": 24, "texto": "Les pharisiens lui dirent: Voici, pourquoi font-ils ce qui n''''est pas permis pendant le sabbat?"}, {"numero": 25, "texto": "Jésus leur répondit: N''''avez-vous jamais lu ce que fit David, lorsqu''''il fut dans la nécessité et qu''''il eut faim, lui et ceux qui étaient avec lui;"}, {"numero": 26, "texto": "comment il entra dans la maison de Dieu, du temps du souverain sacrificateur Abiathar, et mangea les pains de proposition, qu''''il n''''est permis qu''''aux sacrificateurs de manger, et en donna même à ceux qui étaient avec lui!"}, {"numero": 27, "texto": "Puis il leur dit: Le sabbat a été fait pour l''''homme, et non l''''homme pour le sabbat,"}, {"numero": 28, "texto": "de sorte que le Fils de l''''homme est maître même du sabbat."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 2, 'es', '[{"numero": 1, "texto": "Y ENTRÓ otra vez en Capernaum después de algunos días, y se oyó que estaba en casa."}, {"numero": 2, "texto": "Y luego se juntaron á él muchos, que ya no cabían ni aun á la puerta; y les predicaba la palabra."}, {"numero": 3, "texto": "Entonces vinieron á él unos trayendo un paralítico, que era traído por cuatro."}, {"numero": 4, "texto": "Y como no podían llegar á él á causa del gentío, descubrieron el techo de donde estaba, y haciendo abertura, bajaron el lecho en que yacía el paralítico."}, {"numero": 5, "texto": "Y viendo Jesús la fe de ellos, dice al paralítico: Hijo, tus pecados te son perdonados."}, {"numero": 6, "texto": "Y estaban allí sentados algunos de los escribas, los cuales pensando en sus corazones,"}, {"numero": 7, "texto": "Decían: ¿Por qué habla éste así? Blasfemias dice. ¿Quién puede perdonar pecados, sino solo Dios?"}, {"numero": 8, "texto": "Y conociendo luego Jesús en su espíritu que pensaban así dentro de sí mismos, les dijo: ¿Por qué pensáis estas cosas en vuestros corazones?"}, {"numero": 9, "texto": "¿Qué es más fácil, decir al paralítico: Tus pecados te son perdonados, ó decirle: Levántate, y toma tu lecho y anda?"}, {"numero": 10, "texto": "Pues para que sepáis que el Hijo del hombre tiene potestad en la tierra de perdonar los pecados, (dice al paralítico):"}, {"numero": 11, "texto": "A ti te digo: Levántate, y toma tu lecho, y vete á tu casa."}, {"numero": 12, "texto": "Entonces él se levantó luego, y tomando su lecho, se salió delante de todos, de manera que todos se asombraron, y glorificaron á Dios, diciendo: Nunca tal hemos visto."}, {"numero": 13, "texto": "Y volvió á salir á la mar, y toda la gente venía á él, y los enseñaba."}, {"numero": 14, "texto": "Y pasando, vió á Leví, hijo de Alfeo, sentado al banco de los públicos tributos, y le dice: Sígueme. Y levantándose le siguió."}, {"numero": 15, "texto": "Y aconteció que estando Jesús á la mesa en casa de él, muchos publicanos y pecadores estaban también á la mesa juntamente con Jesús y con sus discípulos: porque había muchos, y le habían seguido."}, {"numero": 16, "texto": "Y los escribas y los Fariseos, viéndole comer con los publicanos y con los pecadores, dijeron á sus discípulos: ¿Qué es esto, que él come y bebe con los publicanos y con los pecadores?"}, {"numero": 17, "texto": "Y oyéndolo Jesús, les dice: Los sanos no tienen necesidad de médico, mas los que tienen mal. No he venido á llamar á los justos, sino á los pecadores."}, {"numero": 18, "texto": "Y los discípulos de Juan, y de los Fariseos ayunaban; y vienen, y le dicen: ¿Por qué los discípulos de Juan y los de los Fariseos ayunan, y tus discípulos no ayunan?"}, {"numero": 19, "texto": "Y Jesús les dice: ¿Pueden ayunar los que están de bodas, cuando el esposo está con ellos? Entre tanto que tienen consigo al esposo no pueden ayunar."}, {"numero": 20, "texto": "Mas vendrán días, cuando el esposo les será quitado, y entonces en aquellos días ayunarán."}, {"numero": 21, "texto": "Nadie echa remiendo de paño recio en vestido viejo; de otra manera el mismo remiendo nuevo tira del viejo, y la rotura se hace peor."}, {"numero": 22, "texto": "Ni nadie echa vino nuevo en odres viejos; de otra manera, el vino nuevo rompe los odres, y se derrama el vino, y los odres se pierden; mas el vino nuevo en odres nuevos se ha de echar."}, {"numero": 23, "texto": "Y aconteció que pasando él por los sembrados en sábado, sus discípulos andando comenzaron á arrancar espigas."}, {"numero": 24, "texto": "Entonces los Fariseos le dijeron: He aquí, ¿por qué hacen en sábado lo que no es lícito?"}, {"numero": 25, "texto": "Y él les dijo: ¿Nunca leísteis qué hizo David cuando tuvo necesidad, y tuvo hambre, él y los que con él estaban:"}, {"numero": 26, "texto": "Cómo entró en la casa de Dios, siendo Abiathar sumo pontífice, y comió los panes de la proposición, de los cuales no es lícito comer sino á los sacerdotes, y aun dió á los que con él estaban?"}, {"numero": 27, "texto": "También les dijo: El sábado por causa del hombre es hecho; no el hombre por causa del sábado."}, {"numero": 28, "texto": "Así que el Hijo del hombre es Señor aun del sábado."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 3, 'pt', '[{"numero": 1, "texto": "[Jesus] entrou outra vez na sinagoga; e estava ali um homem que tinha uma mão definhada."}, {"numero": 2, "texto": "E prestavam atenção nele, se o curaria no sábado, para o acusarem."}, {"numero": 3, "texto": "E [Jesus] disse ao homem que tinha a mão definhada: Levanta-te, e vem para o meio."}, {"numero": 4, "texto": "E disse-lhes:É lícito no sábado fazer o bem, ou o mal? Salvar uma pessoa, ou matá-la? E mantiveram-se calados."}, {"numero": 5, "texto": "E olhando ao redor para eles com indignação, sentindo pena da dureza dos seus corações, disse ao homem: Estende a tua mão. E ele estendeu; e sua mão foi restaurada , sã como a outra."}, {"numero": 6, "texto": "Assim que os fariseus saíram, tiveram reunião com os herodianos contra ele, para combinarem sobre como o matariam."}, {"numero": 7, "texto": "E Jesus retirou-se com os seus discípulos para o mar; e seguiu-o uma grande multidão da Galileia, da Judeia,"}, {"numero": 8, "texto": "de Jerusalém, da Idumeia, dalém do Jordão, e os das proximidades de Tiro e de Sidom; uma grande multidão, tendo ouvido quão grandes coisas fazia, vieram a ele."}, {"numero": 9, "texto": "E disse aos seus discípulos que um barquinho ficasse continuamente perto dele, por causa das multidões; para que não o apertassem."}, {"numero": 10, "texto": "Pois havia curado muitos, de maneira que todos quantos tinham algum mal lançavam-se sobre ele a fim de tocá-lo."}, {"numero": 11, "texto": "E os espíritos imundos, quando o viam, prostravam-se diante dele, e exclamavam: Tu és o Filho de Deus."}, {"numero": 12, "texto": "Mas [Jesus] os repreendia muito, para que não manifestassem quem ele era."}, {"numero": 13, "texto": "Ele subiu ao monte, e chamou para si os que quis; então vieram a ele."}, {"numero": 14, "texto": "E constituiu doze para que estivessem com ele, para enviá-los a pregar,"}, {"numero": 15, "texto": "para que tivessem poder de curar as enfermidades e expulsar os demônios."}, {"numero": 16, "texto": "Eram eles: Simão, a quem pôs por nome Pedro;"}, {"numero": 17, "texto": "Tiago [filho] de Zebedeu, e João, irmão de Tiago; e pôs-lhes por nome Boanerges, que significa “filhos do trovão”;"}, {"numero": 18, "texto": "e André, Filipe, Bartolomeu, Mateus, Tomé; Tiago [filho] de Alfeu; Tadeu; Simão o zelote;"}, {"numero": 19, "texto": "e Judas Iscariotes, o que o traiu."}, {"numero": 20, "texto": "Quando foram para uma casa, outra vez se ajuntou uma multidão, de maneira que nem sequer podiam comer pão."}, {"numero": 21, "texto": "Os seus [familiares] , ao ouvirem isso, saíram para detê-lo, porque diziam: “Ele stá fora de si”."}, {"numero": 22, "texto": "E os escribas que haviam descido de Jerusalém diziam: Ele tem Belzebu, e é pelo chefe dos demônios que expulsa demônios."}, {"numero": 23, "texto": "Então [Jesus] os chamou, e lhes disse por parábolas: Como pode Satanás expulsar Satanás?"}, {"numero": 24, "texto": "Se algum reino estiver dividido contra si mesmo, tal reino não pode durar;"}, {"numero": 25, "texto": "e se alguma casa estiver dividida contra si mesma, tal casa não pode durar firme."}, {"numero": 26, "texto": "E se Satanás se levantar contra si mesmo, e for dividido, não pode durar, mas tem fim."}, {"numero": 27, "texto": "Ninguém pode roubar os bens do valente, quando se entra na casa dele, se antes não amarrar ao valente; depois disso roubará a sua casa."}, {"numero": 28, "texto": "Em verdade vos digo que todos os pecados serão perdoados aos filhos dos homens, e todas as blasfêmias com que blasfemarem;"}, {"numero": 29, "texto": "mas quem blasfemar contra o Espírito Santo ficará sem perdão para sempre; em vez disso, é culpado do juízo eterno."}, {"numero": 30, "texto": "Pois diziam: “Ele tem espírito imundo”."}, {"numero": 31, "texto": "Então chegaram os seus irmãos e a sua mãe ; e estando de fora, mandaram chamá-lo."}, {"numero": 32, "texto": "A multidão estava sentada ao redor dele. Então disseram-lhe: Eis que a tua mãe e os teus irmãos estão lá fora a te procurar."}, {"numero": 33, "texto": "Ele lhes respondeu: Quem é a minha mãe ou os meus irmãos?"}, {"numero": 34, "texto": "E, olhando em redor aos que estavam sentados perto dele, disse: Eis aqui minha mãe e meus irmãos."}, {"numero": 35, "texto": "Pois quem fizer a vontade de Deus, esse é meu irmão, minha irmã, e mãe."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 3, 'en', '[{"numero": 1, "texto": "And he entered again into the synagogue; and there was a man there which had a withered hand."}, {"numero": 2, "texto": "And they watched him, whether he would heal him on the sabbath day; that they might accuse him."}, {"numero": 3, "texto": "And he saith unto the man which had the withered hand, Stand forth."}, {"numero": 4, "texto": "And he saith unto them, Is it lawful to do good on the sabbath days, or to do evil? to save life, or to kill? But they held their peace."}, {"numero": 5, "texto": "And when he had looked round about on them with anger, being grieved for the hardness of their hearts, he saith unto the man, Stretch forth thine hand. And he stretched it out: and his hand was restored whole as the other."}, {"numero": 6, "texto": "And the Pharisees went forth, and straightway took counsel with the Herodians against him, how they might destroy him."}, {"numero": 7, "texto": "But Jesus withdrew himself with his disciples to the sea: and a great multitude from Galilee followed him, and from Judaea,"}, {"numero": 8, "texto": "And from Jerusalem, and from Idumaea, and from beyond Jordan; and they about Tyre and Sidon, a great multitude, when they had heard what great things he did, came unto him."}, {"numero": 9, "texto": "And he spake to his disciples, that a small ship should wait on him because of the multitude, lest they should throng him."}, {"numero": 10, "texto": "For he had healed many; insomuch that they pressed upon him for to touch him, as many as had plagues."}, {"numero": 11, "texto": "And unclean spirits, when they saw him, fell down before him, and cried, saying, Thou art the Son of God."}, {"numero": 12, "texto": "And he straitly charged them that they should not make him known."}, {"numero": 13, "texto": "And he goeth up into a mountain, and calleth unto him whom he would: and they came unto him."}, {"numero": 14, "texto": "And he ordained twelve, that they should be with him, and that he might send them forth to preach,"}, {"numero": 15, "texto": "And to have power to heal sicknesses, and to cast out devils:"}, {"numero": 16, "texto": "And Simon he surnamed Peter;"}, {"numero": 17, "texto": "And James the son of Zebedee, and John the brother of James; and he surnamed them Boanerges, which is, The sons of thunder:"}, {"numero": 18, "texto": "And Andrew, and Philip, and Bartholomew, and Matthew, and Thomas, and James the son of Alphaeus, and Thaddaeus, and Simon the Canaanite,"}, {"numero": 19, "texto": "And Judas Iscariot, which also betrayed him: and they went into an house."}, {"numero": 20, "texto": "And the multitude cometh together again, so that they could not so much as eat bread."}, {"numero": 21, "texto": "And when his friends heard of it, they went out to lay hold on him: for they said, He is beside himself."}, {"numero": 22, "texto": "And the scribes which came down from Jerusalem said, He hath Beelzebub, and by the prince of the devils casteth he out devils."}, {"numero": 23, "texto": "And he called them unto him, and said unto them in parables, How can Satan cast out Satan?"}, {"numero": 24, "texto": "And if a kingdom be divided against itself, that kingdom cannot stand."}, {"numero": 25, "texto": "And if a house be divided against itself, that house cannot stand."}, {"numero": 26, "texto": "And if Satan rise up against himself, and be divided, he cannot stand, but hath an end."}, {"numero": 27, "texto": "No man can enter into a strong man''s house, and spoil his goods, except he will first bind the strong man; and then he will spoil his house."}, {"numero": 28, "texto": "Verily I say unto you, All sins shall be forgiven unto the sons of men, and blasphemies wherewith soever they shall blaspheme:"}, {"numero": 29, "texto": "But he that shall blaspheme against the Holy Ghost hath never forgiveness, but is in danger of eternal damnation."}, {"numero": 30, "texto": "Because they said, He hath an unclean spirit."}, {"numero": 31, "texto": "There came then his brethren and his mother, and, standing without, sent unto him, calling him."}, {"numero": 32, "texto": "And the multitude sat about him, and they said unto him, Behold, thy mother and thy brethren without seek for thee."}, {"numero": 33, "texto": "And he answered them, saying, Who is my mother, or my brethren?"}, {"numero": 34, "texto": "And he looked round about on them which sat about him, and said, Behold my mother and my brethren!"}, {"numero": 35, "texto": "For whosoever shall do the will of God, the same is my brother, and my sister, and mother."}]'::jsonb, 'King James Version'),
  ('Mc', 3, 'fr', '[{"numero": 1, "texto": "Jésus entra de nouveau dans la synagogue. Il s''''y trouvait un homme qui avait la main sèche."}, {"numero": 2, "texto": "Ils observaient Jésus, pour voir s''''il le guérirait le jour du sabbat: c''''était afin de pouvoir l''''accuser."}, {"numero": 3, "texto": "Et Jésus dit à l''''homme qui avait la main sèche: Lève-toi, là au milieu."}, {"numero": 4, "texto": "Puis il leur dit: Est-il permis, le jour du sabbat, de faire du bien ou de faire du mal, de sauver une personne ou de la tuer? Mais ils gardèrent le silence."}, {"numero": 5, "texto": "Alors, promenant ses regards sur eux avec indignation, et en même temps affligé de l''''endurcissement de leur coeur, il dit à l''''homme: Etends ta main. Il l''''étendit, et sa main fut guérie."}, {"numero": 6, "texto": "Les pharisiens sortirent, et aussitôt ils se consultèrent avec les hérodiens sur les moyens de le faire périr."}, {"numero": 7, "texto": "Jésus se retira vers la mer avec ses disciples. Une grande multitude le suivit de la Galilée; et de la Judée,"}, {"numero": 8, "texto": "et de Jérusalem, et de l''''Idumée, et d''''au delà du Jourdain, et des environs de Tyr et de Sidon, une grande multitude, apprenant tout ce qu''''il faisait, vint à lui."}, {"numero": 9, "texto": "Il chargea ses disciples de tenir toujours à sa disposition une petite barque, afin de ne pas être pressé par la foule."}, {"numero": 10, "texto": "Car, comme il guérissait beaucoup de gens, tous ceux qui avaient des maladies se jetaient sur lui pour le toucher."}, {"numero": 11, "texto": "Les esprits impurs, quand ils le voyaient, se prosternaient devant lui, et s''''écriaient: Tu es le Fils de Dieu."}, {"numero": 12, "texto": "Mais il leur recommandait très sévèrement de ne pas le faire connaître."}, {"numero": 13, "texto": "Il monta ensuite sur la montagne; il appela ceux qu''''il voulut, et ils vinrent auprès de lui."}, {"numero": 14, "texto": "Il en établit douze, pour les avoir avec lui, et pour les envoyer prêcher"}, {"numero": 15, "texto": "avec le pouvoir de chasser les démons."}, {"numero": 16, "texto": "Voici les douze qu''''il établit: Simon, qu''''il nomma Pierre;"}, {"numero": 17, "texto": "Jacques, fils de Zébédée, et Jean, frère de Jacques, auxquels il donna le nom de Boanergès, qui signifie fils du tonnerre;"}, {"numero": 18, "texto": "André; Philippe; Barthélemy; Matthieu; Thomas; Jacques, fils d''''Alphée; Thaddée; Simon le Cananite;"}, {"numero": 19, "texto": "et Judas Iscariot, celui qui livra Jésus. Ils se rendirent à la maison,"}, {"numero": 20, "texto": "et la foule s''''assembla de nouveau, en sorte qu''''ils ne pouvaient pas même prendre leur repas."}, {"numero": 21, "texto": "Les parents de Jésus, ayant appris ce qui se passait, vinrent pour se saisir de lui; car ils disaient: Il est hors de sens."}, {"numero": 22, "texto": "Et les scribes, qui étaient descendus de Jérusalem, dirent: Il est possédé de Béelzébul; c''''est par le prince des démons qu''''il chasse les démons."}, {"numero": 23, "texto": "Jésus les appela, et leur dit sous forme de paraboles: Comment Satan peut-il chasser Satan?"}, {"numero": 24, "texto": "Si un royaume est divisé contre lui-même, ce royaume ne peut subsister;"}, {"numero": 25, "texto": "et si une maison est divisée contre elle-même, cette maison ne peut subsister."}, {"numero": 26, "texto": "Si donc Satan se révolte contre lui-même, il est divisé, et il ne peut subsister, mais c''''en est fait de lui."}, {"numero": 27, "texto": "Personne ne peut entrer dans la maison d''''un homme fort et piller ses biens, sans avoir auparavant lié cet homme fort; alors il pillera sa maison."}, {"numero": 28, "texto": "Je vous le dis en vérité, tous les péchés seront pardonnés aux fils des hommes, et les blasphèmes qu''''ils auront proférés;"}, {"numero": 29, "texto": "mais quiconque blasphémera contre le Saint-Esprit n''''obtiendra jamais de pardon: il est coupable d''''un péché éternel."}, {"numero": 30, "texto": "Jésus parla ainsi parce qu''''ils disaient: Il est possédé d''''un esprit impur."}, {"numero": 31, "texto": "Survinrent sa mère et ses frères, qui, se tenant dehors, l''''envoyèrent appeler."}, {"numero": 32, "texto": "La foule était assise autour de lui, et on lui dit: Voici, ta mère et tes frères sont dehors et te demandent."}, {"numero": 33, "texto": "Et il répondit: Qui est ma mère, et qui sont mes frères?"}, {"numero": 34, "texto": "Puis, jetant les regards sur ceux qui étaient assis tout autour de lui: Voici, dit-il, ma mère et mes frères."}, {"numero": 35, "texto": "Car, quiconque fait la volonté de Dieu, celui-là est mon frère, ma soeur, et ma mère."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 3, 'es', '[{"numero": 1, "texto": "Y OTRA vez entró en la sinagoga; y había allí un hombre que tenía una mano seca."}, {"numero": 2, "texto": "Y le acechaban si en sábado le sanaría, para acusarle."}, {"numero": 3, "texto": "Entonces dijo al hombre que tenía la mano seca: Levántate en medio."}, {"numero": 4, "texto": "Y les dice: ¿Es lícito hacer bien en sábado, ó hacer mal? ¿salvar la vida, ó quitarla? Mas ellos callaban."}, {"numero": 5, "texto": "Y mirándolos alrededor con enojo, condoleciéndose de la ceguedad de su corazón, dice al hombre: Extiende tu mano. Y la extendió, y su mano fué restituída sana."}, {"numero": 6, "texto": "Entonces saliendo los Fariseos, tomaron consejo con los Herodianos contra él, para matarle."}, {"numero": 7, "texto": "Mas Jesús se apartó á la mar con sus discípulos: y le siguió gran multitud de Galilea, y de Judea,"}, {"numero": 8, "texto": "Y de Jerusalem, y de Idumea, y de la otra parte del Jordán. Y los de alrededor de Tiro y de Sidón, grande multitud, oyendo cuán grandes cosas hacía, vinieron á él."}, {"numero": 9, "texto": "Y dijo á sus discípulos que le estuviese siempre apercibida la barquilla, por causa del gentío, para que no le oprimiesen."}, {"numero": 10, "texto": "Porque había sanado á muchos; de manera que caían sobre él cuantos tenían plagas, por tocarle."}, {"numero": 11, "texto": "Y los espíritus inmundos, al verle, se postraban delante de él, y daban voces, diciendo: Tú eres el Hijo de Dios."}, {"numero": 12, "texto": "Mas él les reñía mucho que no le manifestasen."}, {"numero": 13, "texto": "Y subió al monte, y llamó á sí á los que él quiso; y vinieron á él."}, {"numero": 14, "texto": "Y estableció doce, para que estuviesen con él, y para enviarlos á predicar,"}, {"numero": 15, "texto": "Y que tuviesen potestad de sanar enfermedades, y de echar fuera demonios:"}, {"numero": 16, "texto": "A Simón, al cual puso por nombre Pedro;"}, {"numero": 17, "texto": "Y á Jacobo, hijo de Zebedeo, y á Juan hermano de Jacobo; y les apellidó Boanerges, que es, Hijos del trueno;"}, {"numero": 18, "texto": "Y á Andrés, y á Felipe, y á Bartolomé, y á Mateo, y á Tomás, y á Jacobo hijo de Alfeo, y á Tadeo, y á Simón el Cananita,"}, {"numero": 19, "texto": "Y á Judas Iscariote, el que le entregó. Y vinieron á casa."}, {"numero": 20, "texto": "Y agolpóse de nuevo la gente, de modo que ellos ni aun podían comer pan."}, {"numero": 21, "texto": "Y como lo oyeron los suyos, vinieron para prenderle: porque decían: Está fuera de sí."}, {"numero": 22, "texto": "Y los escribas que habían venido de Jerusalem, decían que tenía á Beelzebub, y que por el príncipe de los demonios echaba fuera los demonios."}, {"numero": 23, "texto": "Y habiéndolos llamado, les decía en parábolas: ¿Cómo puede Satanás echar fuera á Satanás?"}, {"numero": 24, "texto": "Y si algún reino contra sí mismo fuere dividido, no puede permanecer el tal reino."}, {"numero": 25, "texto": "Y si alguna casa fuere dividida contra sí misma, no puede permanecer la tal casa."}, {"numero": 26, "texto": "Y si Satanás se levantare contra sí mismo, y fuere dividido, no puede permanecer; antes tiene fin."}, {"numero": 27, "texto": "Nadie puede saquear las alhajas del valiente entrando en su casa, si antes no atare al valiente y entonces saqueará su casa."}, {"numero": 28, "texto": "De cierto os digo que todos los pecados serán perdonados á los hijos de los hombres, y las blasfemias cualesquiera con que blasfemaren;"}, {"numero": 29, "texto": "Mas cualquiera que blasfemare contra el Espíritu Santo, no tiene jamás perdón, mas está expuesto á eterno juicio."}, {"numero": 30, "texto": "Porque decían: Tiene espíritu inmundo."}, {"numero": 31, "texto": "Vienen después sus hermanos y su madre, y estando fuera, enviaron á él llamándole."}, {"numero": 32, "texto": "Y la gente estaba sentada alrededor de él, y le dijeron: He aquí, tu madre y tus hermanos te buscan fuera."}, {"numero": 33, "texto": "Y él les respondió, diciendo: ¿Quién es mi madre y mis hermanos?"}, {"numero": 34, "texto": "Y mirando á los que estaban sentados alrededor de él, dijo: He aquí mi madre y hermanos."}, {"numero": 35, "texto": "Porque cualquiera que hiciere la voluntad de Dios, éste es mi hermano, y mi hermana, y mi madre."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 4, 'pt', '[{"numero": 1, "texto": "[Jesus] começou outra vez a ensinar junto ao mar, e uma grande multidão se ajuntou a ele, de maneira que ele entrou num barco e ficou sentado no mar; e toda a multidão estava em terra junto ao mar."}, {"numero": 2, "texto": "E ensinava-lhes muitas coisas por parábolas; e dizia-lhes em seu ensinamento:"}, {"numero": 3, "texto": "Ouvi: eis que o semeador saiu a semear;"}, {"numero": 4, "texto": "E aconteceu que, enquanto semeava, uma [parte das sementes] caiu junto ao caminho, e os pássaros do céu vieram, e a comeram."}, {"numero": 5, "texto": "E outra caiu em pedregulhos, onde não havia muita terra; e logo nasceu, porque não tinha terra profunda."}, {"numero": 6, "texto": "Mas, quando saiu o sol, queimou-se; e porque não tinha raiz, secou-se."}, {"numero": 7, "texto": "E outra caiu entre espinhos; e os espinhos cresceram e a sufocaram, e não deu fruto."}, {"numero": 8, "texto": "Mas outra caiu em boa terra, e deu fruto, que subiu, e cresceu; e um deu trinta, outro sessenta, e outro cem."}, {"numero": 9, "texto": "E disse-lhes : Quem tem ouvidos para ouvir, ouça."}, {"numero": 10, "texto": "E quando [Jesus] esteve só, os que estavam junto dele, com os doze, perguntaram-lhe acerca da parábola ."}, {"numero": 11, "texto": "E respondeu-lhes: A vós é concedido saber o mistério do Reino de Deus; mas aos que são de fora, todas estas coisas se fazem por meio de parábolas;"}, {"numero": 12, "texto": "para que vendo, vejam, e não percebam; e ouvindo, ouçam, e não entendam; para não haver de se converterem, e lhes sejam perdoados os pecados ."}, {"numero": 13, "texto": "E disse-lhes: Não sabeis o significado desta parábola? Como, pois, entendereis todas as parábolas?"}, {"numero": 14, "texto": "O semeador semeia a palavra."}, {"numero": 15, "texto": "E estes são os de junto ao caminho: nos quais a palavra é semeada; mas depois de a ouvirem, Satanás logo vem, e tira a palavra que foi semeada nos seus corações ."}, {"numero": 16, "texto": "E, semelhantemente, estes são os que se semeiam em pedregulhos: os que havendo ouvido a palavra, logo a recebem com alegria."}, {"numero": 17, "texto": "Mas não têm raiz em si mesmos; em vez disso, são temporários. Depois, quando se levanta a tribulação ou a perseguição por causa da palavra, logo tropeçam na fé."}, {"numero": 18, "texto": "E estes são os que se semeiam entre espinhos: os que ouvem a palavra;"}, {"numero": 19, "texto": "mas as preocupações deste mundo, a sedução das riquezas, e as cobiças por outras coisas, entram, sufocam a palavra, e ela fica sem gerar fruto."}, {"numero": 20, "texto": "E estes são os que foram semeados em boa terra: os que ouvem a palavra, recebem-na, e dão fruto, um trinta, e outro sessenta, e outro cem."}, {"numero": 21, "texto": "E ele lhes disse: Por acaso a lâmpada vem a ser posta debaixo de uma caixa ou sob da cama? Não deve ela ser posta na luminária?"}, {"numero": 22, "texto": "Pois não há nada encoberto que não haja de ser revelado; e nada se faz [para ficar] encoberto, mas sim, para ser vir à luz."}, {"numero": 23, "texto": "Se alguém tem ouvidos para ouvir, ouça."}, {"numero": 24, "texto": "E disse-lhes: Prestai atenção ao que ouvis: com a medida que medirdes a vós mesmos se medirá, e será acrescentado a vós que ouvis ."}, {"numero": 25, "texto": "Pois ao que tem, lhe será dado; e ao que não tem, até o que tem lhe será tirado."}, {"numero": 26, "texto": "E dizia: Assim é o Reino de Deus, como se um homem lançasse semente na terra;"}, {"numero": 27, "texto": "e dormisse, e se levantasse, de noite e de dia, e a semente brotasse, e crescesse, sem que ele saiba como."}, {"numero": 28, "texto": "Pois a terra de si mesma frutifica, primeiro a erva, depois a espiga, depois o grão cheio na espiga."}, {"numero": 29, "texto": "E quando o fruto se mostra pronto, logo mete a foice, pois a colheita chegou."}, {"numero": 30, "texto": "E dizia: A que assemelharemos o Reino de Deus? Ou com que parábola o compararemos?"}, {"numero": 31, "texto": "Com um grão da mostarda que, quando semeado na terra, é a menor de todas as sementes na terra."}, {"numero": 32, "texto": "Mas, depois de semeado, cresce, e se torna a maior de todas as hortaliças, e cria grandes ramos, de maneira que os pássaros do céu podem fazer ninhos sob a sua sombra."}, {"numero": 33, "texto": "E com muitas parábolas como essas [Jesus ] lhes falava a palavra, conforme o que podiam ouvir."}, {"numero": 34, "texto": "E não lhes falava sem parábola; mas aos seus discípulos explicava tudo em particular."}, {"numero": 35, "texto": "Naquele dia, chegando o entardecer, disse-lhes: Passemos para o outro lado."}, {"numero": 36, "texto": "Então despediram a multidão, e o levaram consigo assim como estava no barco; mas havia também outros barquinhos com ele."}, {"numero": 37, "texto": "E levantou-se uma grande tempestade de vento; as ondas atingiam por cima do barco, de maneira que já se enchia."}, {"numero": 38, "texto": "[Jesus] estava na popa dormindo sobre uma almofada. Então despertaram-no, e disseram-lhe: Mestre, não te importas que pereçamos?"}, {"numero": 39, "texto": "Então ele se levantou, repreendeu o vento, e disse ao mar: Cala-te, aquieta-te! E o vento se aquietou, e fez-se grande bonança."}, {"numero": 40, "texto": "E perguntou-lhes: Por que sois tão covardes? Como não tendes fé?"}, {"numero": 41, "texto": "E ficaram muito atemorizados, e diziam uns aos outros: Quem é este, que até o vento e o mar lhe obedecem?"}]'::jsonb, 'Almeida Livre'),
  ('Mc', 4, 'en', '[{"numero": 1, "texto": "And he began again to teach by the sea side: and there was gathered unto him a great multitude, so that he entered into a ship, and sat in the sea; and the whole multitude was by the sea on the land."}, {"numero": 2, "texto": "And he taught them many things by parables, and said unto them in his doctrine,"}, {"numero": 3, "texto": "Hearken; Behold, there went out a sower to sow:"}, {"numero": 4, "texto": "And it came to pass, as he sowed, some fell by the way side, and the fowls of the air came and devoured it up."}, {"numero": 5, "texto": "And some fell on stony ground, where it had not much earth; and immediately it sprang up, because it had no depth of earth:"}, {"numero": 6, "texto": "But when the sun was up, it was scorched; and because it had no root, it withered away."}, {"numero": 7, "texto": "And some fell among thorns, and the thorns grew up, and choked it, and it yielded no fruit."}, {"numero": 8, "texto": "And other fell on good ground, and did yield fruit that sprang up and increased; and brought forth, some thirty, and some sixty, and some an hundred."}, {"numero": 9, "texto": "And he said unto them, He that hath ears to hear, let him hear."}, {"numero": 10, "texto": "And when he was alone, they that were about him with the twelve asked of him the parable."}, {"numero": 11, "texto": "And he said unto them, Unto you it is given to know the mystery of the kingdom of God: but unto them that are without, all these things are done in parables:"}, {"numero": 12, "texto": "That seeing they may see, and not perceive; and hearing they may hear, and not understand; lest at any time they should be converted, and their sins should be forgiven them."}, {"numero": 13, "texto": "And he said unto them, Know ye not this parable? and how then will ye know all parables?"}, {"numero": 14, "texto": "The sower soweth the word."}, {"numero": 15, "texto": "And these are they by the way side, where the word is sown; but when they have heard, Satan cometh immediately, and taketh away the word that was sown in their hearts."}, {"numero": 16, "texto": "And these are they likewise which are sown on stony ground; who, when they have heard the word, immediately receive it with gladness;"}, {"numero": 17, "texto": "And have no root in themselves, and so endure but for a time: afterward, when affliction or persecution ariseth for the word''s sake, immediately they are offended."}, {"numero": 18, "texto": "And these are they which are sown among thorns; such as hear the word,"}, {"numero": 19, "texto": "And the cares of this world, and the deceitfulness of riches, and the lusts of other things entering in, choke the word, and it becometh unfruitful."}, {"numero": 20, "texto": "And these are they which are sown on good ground; such as hear the word, and receive it, and bring forth fruit, some thirtyfold, some sixty, and some an hundred."}, {"numero": 21, "texto": "And he said unto them, Is a candle brought to be put under a bushel, or under a bed? and not to be set on a candlestick?"}, {"numero": 22, "texto": "For there is nothing hid, which shall not be manifested; neither was any thing kept secret, but that it should come abroad."}, {"numero": 23, "texto": "If any man have ears to hear, let him hear."}, {"numero": 24, "texto": "And he said unto them, Take heed what ye hear: with what measure ye mete, it shall be measured to you: and unto you that hear shall more be given."}, {"numero": 25, "texto": "For he that hath, to him shall be given: and he that hath not, from him shall be taken even that which he hath."}, {"numero": 26, "texto": "And he said, So is the kingdom of God, as if a man should cast seed into the ground;"}, {"numero": 27, "texto": "And should sleep, and rise night and day, and the seed should spring and grow up, he knoweth not how."}, {"numero": 28, "texto": "For the earth bringeth forth fruit of herself; first the blade, then the ear, after that the full corn in the ear."}, {"numero": 29, "texto": "But when the fruit is brought forth, immediately he putteth in the sickle, because the harvest is come."}, {"numero": 30, "texto": "And he said, Whereunto shall we liken the kingdom of God? or with what comparison shall we compare it?"}, {"numero": 31, "texto": "It is like a grain of mustard seed, which, when it is sown in the earth, is less than all the seeds that be in the earth:"}, {"numero": 32, "texto": "But when it is sown, it groweth up, and becometh greater than all herbs, and shooteth out great branches; so that the fowls of the air may lodge under the shadow of it."}, {"numero": 33, "texto": "And with many such parables spake he the word unto them, as they were able to hear it."}, {"numero": 34, "texto": "But without a parable spake he not unto them: and when they were alone, he expounded all things to his disciples."}, {"numero": 35, "texto": "And the same day, when the even was come, he saith unto them, Let us pass over unto the other side."}, {"numero": 36, "texto": "And when they had sent away the multitude, they took him even as he was in the ship. And there were also with him other little ships."}, {"numero": 37, "texto": "And there arose a great storm of wind, and the waves beat into the ship, so that it was now full."}, {"numero": 38, "texto": "And he was in the hinder part of the ship, asleep on a pillow: and they awake him, and say unto him, Master, carest thou not that we perish?"}, {"numero": 39, "texto": "And he arose, and rebuked the wind, and said unto the sea, Peace, be still. And the wind ceased, and there was a great calm."}, {"numero": 40, "texto": "And he said unto them, Why are ye so fearful? how is it that ye have no faith?"}, {"numero": 41, "texto": "And they feared exceedingly, and said one to another, What manner of man is this, that even the wind and the sea obey him?"}]'::jsonb, 'King James Version'),
  ('Mc', 4, 'fr', '[{"numero": 1, "texto": "Jésus se mit de nouveau à enseigner au bord de la mer. Une grande foule s''''étant assemblée auprès de lui, il monta et s''''assit dans une barque, sur la mer. Toute la foule était à terre sur le rivage."}, {"numero": 2, "texto": "Il leur enseigna beaucoup de choses en paraboles, et il leur dit dans son enseignement:"}, {"numero": 3, "texto": "Ecoutez. Un semeur sortit pour semer."}, {"numero": 4, "texto": "Comme il semait, une partie de la semence tomba le long du chemin: les oiseaux vinrent, et la mangèrent."}, {"numero": 5, "texto": "Une autre partie tomba dans un endroit pierreux, où elle n''''avait pas beaucoup de terre; elle leva aussitôt, parce qu''''elle ne trouva pas un sol profond;"}, {"numero": 6, "texto": "mais, quand le soleil parut, elle fut brûlée et sécha, faute de racines."}, {"numero": 7, "texto": "Une autre partie tomba parmi les épines: les épines montèrent, et l''''étouffèrent, et elle ne donna point de fruit."}, {"numero": 8, "texto": "Une autre partie tomba dans la bonne terre: elle donna du fruit qui montait et croissait, et elle rapporta trente, soixante, et cent pour un."}, {"numero": 9, "texto": "Puis il dit: Que celui qui a des oreilles pour entendre entende."}, {"numero": 10, "texto": "Lorsqu''''il fut en particulier, ceux qui l''''entouraient avec les douze l''''interrogèrent sur les paraboles."}, {"numero": 11, "texto": "Il leur dit: C''''est à vous qu''''a été donné le mystère du royaume de Dieu; mais pour ceux qui sont dehors tout se passe en paraboles,"}, {"numero": 12, "texto": "afin qu''''en voyant ils voient et n''''aperçoivent point, et qu''''en entendant ils entendent et ne comprennent point, de peur qu''''ils ne se convertissent, et que les péchés ne leur soient pardonnés."}, {"numero": 13, "texto": "Il leur dit encore: Vous ne comprenez pas cette parabole? Comment donc comprendrez-vous toutes les paraboles?"}, {"numero": 14, "texto": "Le semeur sème la parole."}, {"numero": 15, "texto": "Les uns sont le long du chemin, où la parole est semée; quand ils l''''ont entendue, aussitôt Satan vient et enlève la parole qui a été semée en eux."}, {"numero": 16, "texto": "Les autres, pareillement, reçoivent la semence dans les endroits pierreux; quand ils entendent la parole, ils la reçoivent d''''abord avec joie;"}, {"numero": 17, "texto": "mais ils n''''ont pas de racine en eux-mêmes, ils manquent de persistance, et, dès que survient une tribulation ou une persécution à cause de la parole, ils y trouvent une occasion de chute."}, {"numero": 18, "texto": "D''''autres reçoivent la semence parmi les épines; ce sont ceux qui entendent la parole,"}, {"numero": 19, "texto": "mais en qui les soucis du siècle, la séduction des richesses et l''''invasion des autres convoitises, étouffent la parole, et la rendent infructueuse."}, {"numero": 20, "texto": "D''''autres reçoivent la semence dans la bonne terre; ce sont ceux qui entendent la parole, la reçoivent, et portent du fruit, trente, soixante, et cent pour un."}, {"numero": 21, "texto": "Il leur dit encore: Apporte-t-on la lampe pour la mettre sous le boisseau, ou sous le lit? N''''est-ce pas pour la mettre sur le chandelier?"}, {"numero": 22, "texto": "Car il n''''est rien de caché qui ne doive être découvert, rien de secret qui ne doive être mis au jour."}, {"numero": 23, "texto": "Si quelqu''''un a des oreilles pour entendre, qu''''il entende."}, {"numero": 24, "texto": "Il leur dit encore: Prenez garde à ce que vous entendez. On vous mesurera avec la mesure dont vous vous serez servis, et on y ajoutera pour vous."}, {"numero": 25, "texto": "Car on donnera à celui qui a; mais à celui qui n''''a pas on ôtera même ce qu''''il a."}, {"numero": 26, "texto": "Il dit encore: Il en est du royaume de Dieu comme quand un homme jette de la semence en terre;"}, {"numero": 27, "texto": "qu''''il dorme ou qu''''il veille, nuit et jour, la semence germe et croît sans qu''''il sache comment."}, {"numero": 28, "texto": "La terre produit d''''elle-même, d''''abord l''''herbe, puis l''''épi, puis le grain tout formé dans l''''épi;"}, {"numero": 29, "texto": "et, dès que le fruit est mûr, on y met la faucille, car la moisson est là."}, {"numero": 30, "texto": "Il dit encore: A quoi comparerons-nous le royaume de Dieu, ou par quelle parabole le représenterons-nous?"}, {"numero": 31, "texto": "Il est semblable à un grain de sénevé, qui, lorsqu''''on le sème en terre, est la plus petite de toutes les semences qui sont sur la terre;"}, {"numero": 32, "texto": "mais, lorsqu''''il a été semé, il monte, devient plus grand que tous les légumes, et pousse de grandes branches, en sorte que les oiseaux du ciel peuvent habiter sous son ombre."}, {"numero": 33, "texto": "C''''est par beaucoup de paraboles de ce genre qu''''il leur annonçait la parole, selon qu''''ils étaient capables de l''''entendre."}, {"numero": 34, "texto": "Il ne leur parlait point sans parabole; mais, en particulier, il expliquait tout à ses disciples."}, {"numero": 35, "texto": "Ce même jour, sur le soir, Jésus leur dit: Passons à l''''autre bord."}, {"numero": 36, "texto": "Après avoir renvoyé la foule, ils l''''emmenèrent dans la barque où il se trouvait; il y avait aussi d''''autres barques avec lui."}, {"numero": 37, "texto": "Il s''''éleva un grand tourbillon, et les flots se jetaient dans la barque, au point qu''''elle se remplissait déjà."}, {"numero": 38, "texto": "Et lui, il dormait à la poupe sur le coussin. Ils le réveillèrent, et lui dirent: Maître, ne t''''inquiètes-tu pas de ce que nous périssons?"}, {"numero": 39, "texto": "S''''étant réveillé, il menaça le vent, et dit à la mer: Silence! tais-toi! Et le vent cessa, et il y eut un grand calme."}, {"numero": 40, "texto": "Puis il leur dit: Pourquoi avez-vous ainsi peur? Comment n''''avez-vous point de foi?"}, {"numero": 41, "texto": "Ils furent saisis d''''une grande frayeur, et ils se dirent les uns aux autres: Quel est donc celui-ci, à qui obéissent même le vent et la mer?"}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 4, 'es', '[{"numero": 1, "texto": "Y OTRA vez comenzó á enseñar junto á la mar, y se juntó á él mucha gente; tanto, que entrándose él en un barco, se sentó en la mar: y toda la gente estaba en tierra junto á la mar."}, {"numero": 2, "texto": "Y les enseñaba por parábolas muchas cosas, y les decía en su doctrina:"}, {"numero": 3, "texto": "Oid: He aquí, el sembrador salió á sembrar."}, {"numero": 4, "texto": "Y aconteció sembrando, que una parte cayó junto al camino; y vinieron las aves del cielo, y la tragaron."}, {"numero": 5, "texto": "Y otra parte cayó en pedregales, donde no tenía mucha tierra; y luego salió, porque no tenía la tierra profunda:"}, {"numero": 6, "texto": "Mas salido el sol, se quemó; y por cuanto no tenía raíz, se secó."}, {"numero": 7, "texto": "Y otra parte cayó en espinas; y subieron las espinas, y la ahogaron, y no dió fruto."}, {"numero": 8, "texto": "Y otra parte cayó en buena tierra, y dió fruto, que subió y creció: y llevó uno á treinta, y otro á sesenta, y otro á ciento."}, {"numero": 9, "texto": "Entonces les dijo: El que tiene oídos para oir, oiga."}, {"numero": 10, "texto": "Y cuando estuvo solo, le preguntaron los que estaban cerca de él con los doce, sobre la parábola."}, {"numero": 11, "texto": "Y les dijo: A vosotros es dado saber el misterio del reino de Dios; mas á los que están fuera, por parábolas todas las cosas;"}, {"numero": 12, "texto": "Para que viendo, vean y no echen de ver; y oyendo, oigan y no entiendan: porque no se conviertan, y les sean perdonados los pecados."}, {"numero": 13, "texto": "Y les dijo: ¿No sabéis esta parábola? ¿Cómo, pues, entenderéis todas las parábolas?"}, {"numero": 14, "texto": "El que siembra es el que siembra la palabra."}, {"numero": 15, "texto": "Y éstos son los de junto al camino: en los que la palabra es sembrada: mas después que la oyeron, luego viene Satanás, y quita la palabra que fué sembrada en sus corazones."}, {"numero": 16, "texto": "Y asimismo éstos son los que son sembrados en pedregales: los que cuando han oído la palabra, luego la toman con gozo;"}, {"numero": 17, "texto": "Mas no tienen raíz en sí, antes son temporales, que en levantándose la tribulación ó la persecución por causa de la palabra, luego se escandalizan."}, {"numero": 18, "texto": "Y éstos son los que son sembrados entre espinas: los que oyen la palabra;"}, {"numero": 19, "texto": "Mas los cuidados de este siglo, y el engaño de las riquezas, y las codicias que hay en las otras cosas, entrando, ahogan la palabra, y se hace infructuosa."}, {"numero": 20, "texto": "Y éstos son los que fueron sembrados en buena tierra: los que oyen la palabra, y la reciben, y hacen fruto, uno á treinta, otro á sesenta, y otro á ciento."}, {"numero": 21, "texto": "También les dijo: ¿Tráese la antorcha para ser puesta debajo del almud, ó debajo de la cama? ¿No es para ser puesta en el candelero?"}, {"numero": 22, "texto": "Porque no hay nada oculto que no haya de ser manifestado, ni secreto que no haya de descubrirse."}, {"numero": 23, "texto": "Si alguno tiene oídos para oir, oiga."}, {"numero": 24, "texto": "Les dijo también: Mirad lo que oís: con la medida que medís, os medirán otros, y será añadido á vosotros los que oís."}, {"numero": 25, "texto": "Porque al que tiene, le será dado; y al que no tiene, aun lo que tiene le será quitado."}, {"numero": 26, "texto": "Decía más: Así es el reino de Dios, como si un hombre echa simiente en la tierra;"}, {"numero": 27, "texto": "Y duerme, y se levanta de noche y de día, y la simiente brota y crece como él no sabe."}, {"numero": 28, "texto": "Porque de suyo fructifica la tierra, primero hierba, luego espiga, después grano lleno en la espiga;"}, {"numero": 29, "texto": "Y cuando el fruto fuere producido, luego se mete la hoz, porque la siega es llegada."}, {"numero": 30, "texto": "Y decía: ¿A qué haremos semejante el reino de Dios? ¿ó con qué parábola le compararemos?"}, {"numero": 31, "texto": "Es como el grano de mostaza, que, cuando se siembra en tierra, es la más pequeña de todas las simientes que hay en la tierra;"}, {"numero": 32, "texto": "Mas después de sembrado, sube, y se hace la mayor de todas las legumbres, y echa grandes ramas, de tal manera que las aves del cielo puedan morar bajo su sombra."}, {"numero": 33, "texto": "Y con muchas tales parábolas les hablaba la palabra, conforme á lo que podían oir."}, {"numero": 34, "texto": "Y sin parábola no les hablaba; mas á sus discípulos en particular declaraba todo."}, {"numero": 35, "texto": "Y les dijo aquel día cuando fué tarde: Pasemos de la otra parte."}, {"numero": 36, "texto": "Y despachando la multitud, le tomaron como estaba, en el barco; y había también con él otros barquitos."}, {"numero": 37, "texto": "Y se levantó una grande tempestad de viento, y echaba las olas en el barco, de tal manera que ya se henchía."}, {"numero": 38, "texto": "Y él estaba en la popa, durmiendo sobre un cabezal, y le despertaron, y le dicen: ¿Maestro, no tienes cuidado que perecemos?"}, {"numero": 39, "texto": "Y levantándose, increpó al viento, y dijo á la mar: Calla, enmudece. Y cesó el viento, y fué hecha grande bonanza."}, {"numero": 40, "texto": "Y á ellos dijo: ¿Por qué estáis así amedrentados? ¿Cómo no tenéis fe?"}, {"numero": 41, "texto": "Y temieron con gran temor, y decían el uno al otro. ¿Quién es éste, que aun el viento y la mar le obedecen?"}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 5, 'pt', '[{"numero": 1, "texto": "E chegaram ao outro lado do mar, à terra dos Gadarenos."}, {"numero": 2, "texto": "Assim que [Jesus] saiu do barco, veio das sepulturas ao seu encontro um homem com um espírito imundo,"}, {"numero": 3, "texto": "que morava nas sepulturas, e nem mesmo com correntes conseguiam prendê-lo;"}, {"numero": 4, "texto": "pois muitas vezes fora preso com grilhões e correntes; mas as correntes eram por ele feitas em pedaços, os grilhões eram esmigalhados, e ninguém o conseguia controlar."}, {"numero": 5, "texto": "E sempre dia e noite andava gritando pelos montes e pelas sepulturas, e ferindo-se com pedras."}, {"numero": 6, "texto": "Quando ele viu Jesus de longe, correu e prostrou-se diante dele."}, {"numero": 7, "texto": "E gritou em alta voz: Que tenho eu contigo Jesus, Filho do Deus Altíssimo? Imploro-te por Deus que não me atormentes."}, {"numero": 8, "texto": "(Pois [Jesus] havia lhe dito: “Sai deste homem, espírito imundo”.)"}, {"numero": 9, "texto": "Então perguntou-lhe: Qual é o teu nome? E respondeu: Legião é o meu nome, porque somos muitos."}, {"numero": 10, "texto": "E rogava-lhe muito que não os expulsasse daquela terra."}, {"numero": 11, "texto": "Havia ali perto dos montes uma grande manada de porcos pastando."}, {"numero": 12, "texto": "E todos [aqueles ] demônios rogaram-lhe, dizendo: Manda-nos para aqueles porcos, para que entremos neles."}, {"numero": 13, "texto": "Imediatamente Jesus lhes permitiu. Então aqueles espíritos imundos saíram para entrar nos porcos; e a manada lançou-se abaixo no mar; (eram quase dois mil) e afogaram-se no mar."}, {"numero": 14, "texto": "Os que apascentavam os porcos fugiram, e avisaram na cidade e nos campos; e [as pessoas] foram ver o que havia acontecido."}, {"numero": 15, "texto": "Então aproximaram-se de Jesus, e viram o endemoninhado sentado, vestido, e em sã consciência o que tivera a legião; e ficaram apavorados."}, {"numero": 16, "texto": "E os que haviam visto contaram-lhes o que acontecera ao endemoninhado, e sobre os porcos."}, {"numero": 17, "texto": "Então começaram a rogar-lhe que saísse do território deles."}, {"numero": 18, "texto": "Quando [Jesus] entrava no barco, o que fora endemoninhado rogou-lhe que estivesse com ele."}, {"numero": 19, "texto": "Jesus se recusou, porém lhe disse: Vai para a tua casa, aos teus, e anuncia-lhes quão grandes coisas o Senhor fez contigo, e [como] teve misericórdia de ti."}, {"numero": 20, "texto": "Então ele foi embora, e começou a anunciar em Decápolis quão grandes coisas Jesus havia feito com ele; e todos se admiravam."}, {"numero": 21, "texto": "Depois de Jesus passar outra vez num barco para o outro lado, uma grande multidão se ajuntou a ele; e ele ficou junto ao mar."}, {"numero": 22, "texto": "E eis que veio um dos líderes de sinagoga, por nome Jairo; e quando o viu, prostrou-se aos seus pés."}, {"numero": 23, "texto": "E implorava-lhe muito, dizendo: Minha filhinha está a ponto de morrer. [Rogo-te] que venhas pôr as mãos sobre ela, para que seja curada, e viva."}, {"numero": 24, "texto": "[Jesus] foi com ele. Uma grande multidão o seguia, e o apertavam."}, {"numero": 25, "texto": "E havia uma certa mulher, que tinha um fluxo de sangue havia doze anos,"}, {"numero": 26, "texto": "que tinha sofrido muito por meio de muitos médicos, e gastado tudo quanto possuía, e nada havia lhe dado bom resultado; ao invés disso, piorava."}, {"numero": 27, "texto": "Quando ela ouviu falar de Jesus, veio entre a multidão por detrás, e tocou a roupa dele."}, {"numero": 28, "texto": "Pois dizia: Se tão somente tocar as suas roupas, serei curada."}, {"numero": 29, "texto": "E imediatamente a fonte do seu sangue parou se secou; e sentiu no corpo que já havia sido curada daquele flagelo."}, {"numero": 30, "texto": "Jesus logo notou em si o poder que dele havia saído. Então virou-se na multidão, e perguntou: Quem tocou as minhas roupas?"}, {"numero": 31, "texto": "E seus discípulos lhe disseram: Eis que a multidão te aperta, e perguntas: Quem me tocou?"}, {"numero": 32, "texto": "E ele olhava em redor, para ver quem havia lhe feito isso."}, {"numero": 33, "texto": "Então a mulher temendo, e tremendo, sabendo o que havia sido feito em si, veio, prostrou-se diante dele, e disse-lhe toda a verdade."}, {"numero": 34, "texto": "E ele lhe disse: Filha, a tua fé te salvou. Vai em paz, e estejas curada deste teu flagelo."}, {"numero": 35, "texto": "Estando ele ainda falando, alguns vieram [da casa] do líder de sinagoga, e disseram: A tua filha já morreu; por que ainda estás incomodando o Mestre?"}, {"numero": 36, "texto": "Mas Jesus, assim que ouviu essa palavra que havia sido falada, disse ao líder de sinagoga: Não temas; crê somente."}, {"numero": 37, "texto": "E não permitiu que ninguém o seguisse, a não ser Pedro, Tiago, e João irmão de Tiago."}, {"numero": 38, "texto": "Ele chegou à casa do líder de sinagoga, e viu o alvoroço, os que choravam muito e pranteavam."}, {"numero": 39, "texto": "E ao entrar, disse-lhes: Por que fazeis alvoroço e chorais? A menina não morreu, mas está dormindo."}, {"numero": 40, "texto": "E riram dele. Porém ele, depois de pôr todos fora, tomou consigo o pai e a mãe da menina, e os que estavam com ele. Em seguida, entrou onde a menina estava deitada."}, {"numero": 41, "texto": "Ele pegou a mão da menina, e lhe disse: “Talita cumi”, (que significa: “Menina, eu te digo, levanta-te”)."}, {"numero": 42, "texto": "E logo a menina se levantou e andou, pois já tinha doze anos de idade. E ficaram grandemente espantados."}, {"numero": 43, "texto": "E mandou-lhes muito que ninguém o soubesse; e mandou que dessem a ela de comer."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 5, 'en', '[{"numero": 1, "texto": "And they came over unto the other side of the sea, into the country of the Gadarenes."}, {"numero": 2, "texto": "And when he was come out of the ship, immediately there met him out of the tombs a man with an unclean spirit,"}, {"numero": 3, "texto": "Who had his dwelling among the tombs; and no man could bind him, no, not with chains:"}, {"numero": 4, "texto": "Because that he had been often bound with fetters and chains, and the chains had been plucked asunder by him, and the fetters broken in pieces: neither could any man tame him."}, {"numero": 5, "texto": "And always, night and day, he was in the mountains, and in the tombs, crying, and cutting himself with stones."}, {"numero": 6, "texto": "But when he saw Jesus afar off, he ran and worshipped him,"}, {"numero": 7, "texto": "And cried with a loud voice, and said, What have I to do with thee, Jesus, thou Son of the most high God? I adjure thee by God, that thou torment me not."}, {"numero": 8, "texto": "For he said unto him, Come out of the man, thou unclean spirit."}, {"numero": 9, "texto": "And he asked him, What is thy name? And he answered, saying, My name is Legion: for we are many."}, {"numero": 10, "texto": "And he besought him much that he would not send them away out of the country."}, {"numero": 11, "texto": "Now there was there nigh unto the mountains a great herd of swine feeding."}, {"numero": 12, "texto": "And all the devils besought him, saying, Send us into the swine, that we may enter into them."}, {"numero": 13, "texto": "And forthwith Jesus gave them leave. And the unclean spirits went out, and entered into the swine: and the herd ran violently down a steep place into the sea, (they were about two thousand;) and were choked in the sea."}, {"numero": 14, "texto": "And they that fed the swine fled, and told it in the city, and in the country. And they went out to see what it was that was done."}, {"numero": 15, "texto": "And they come to Jesus, and see him that was possessed with the devil, and had the legion, sitting, and clothed, and in his right mind: and they were afraid."}, {"numero": 16, "texto": "And they that saw it told them how it befell to him that was possessed with the devil, and also concerning the swine."}, {"numero": 17, "texto": "And they began to pray him to depart out of their coasts."}, {"numero": 18, "texto": "And when he was come into the ship, he that had been possessed with the devil prayed him that he might be with him."}, {"numero": 19, "texto": "Howbeit Jesus suffered him not, but saith unto him, Go home to thy friends, and tell them how great things the Lord hath done for thee, and hath had compassion on thee."}, {"numero": 20, "texto": "And he departed, and began to publish in Decapolis how great things Jesus had done for him: and all men did marvel."}, {"numero": 21, "texto": "And when Jesus was passed over again by ship unto the other side, much people gathered unto him: and he was nigh unto the sea."}, {"numero": 22, "texto": "And, behold, there cometh one of the rulers of the synagogue, Jairus by name; and when he saw him, he fell at his feet,"}, {"numero": 23, "texto": "And besought him greatly, saying, My little daughter lieth at the point of death: I pray thee, come and lay thy hands on her, that she may be healed; and she shall live."}, {"numero": 24, "texto": "And Jesus went with him; and much people followed him, and thronged him."}, {"numero": 25, "texto": "And a certain woman, which had an issue of blood twelve years,"}, {"numero": 26, "texto": "And had suffered many things of many physicians, and had spent all that she had, and was nothing bettered, but rather grew worse,"}, {"numero": 27, "texto": "When she had heard of Jesus, came in the press behind, and touched his garment."}, {"numero": 28, "texto": "For she said, If I may touch but his clothes, I shall be whole."}, {"numero": 29, "texto": "And straightway the fountain of her blood was dried up; and she felt in her body that she was healed of that plague."}, {"numero": 30, "texto": "And Jesus, immediately knowing in himself that virtue had gone out of him, turned him about in the press, and said, Who touched my clothes?"}, {"numero": 31, "texto": "And his disciples said unto him, Thou seest the multitude thronging thee, and sayest thou, Who touched me?"}, {"numero": 32, "texto": "And he looked round about to see her that had done this thing."}, {"numero": 33, "texto": "But the woman fearing and trembling, knowing what was done in her, came and fell down before him, and told him all the truth."}, {"numero": 34, "texto": "And he said unto her, Daughter, thy faith hath made thee whole; go in peace, and be whole of thy plague."}, {"numero": 35, "texto": "While he yet spake, there came from the ruler of the synagogue''s house certain which said, Thy daughter is dead: why troublest thou the Master any further?"}, {"numero": 36, "texto": "As soon as Jesus heard the word that was spoken, he saith unto the ruler of the synagogue, Be not afraid, only believe."}, {"numero": 37, "texto": "And he suffered no man to follow him, save Peter, and James, and John the brother of James."}, {"numero": 38, "texto": "And he cometh to the house of the ruler of the synagogue, and seeth the tumult, and them that wept and wailed greatly."}, {"numero": 39, "texto": "And when he was come in, he saith unto them, Why make ye this ado, and weep? the damsel is not dead, but sleepeth."}, {"numero": 40, "texto": "And they laughed him to scorn. But when he had put them all out, he taketh the father and the mother of the damsel, and them that were with him, and entereth in where the damsel was lying."}, {"numero": 41, "texto": "And he took the damsel by the hand, and said unto her, Talitha cumi; which is, being interpreted, Damsel, I say unto thee, arise."}, {"numero": 42, "texto": "And straightway the damsel arose, and walked; for she was of the age of twelve years. And they were astonished with a great astonishment."}, {"numero": 43, "texto": "And he charged them straitly that no man should know it; and commanded that something should be given her to eat."}]'::jsonb, 'King James Version'),
  ('Mc', 5, 'fr', '[{"numero": 1, "texto": "Ils arrivèrent à l''''autre bord de la mer, dans le pays des Gadaréniens."}, {"numero": 2, "texto": "Aussitôt que Jésus fut hors de la barque, il vint au-devant de lui un homme, sortant des sépulcres, et possédé d''''un esprit impur."}, {"numero": 3, "texto": "Cet homme avait sa demeure dans les sépulcres, et personne ne pouvait plus le lier, même avec une chaîne."}, {"numero": 4, "texto": "Car souvent il avait eu les fers aux pieds et avait été lié de chaînes, mais il avait rompu les chaînes et brisé les fers, et personne n''''avait la force de le dompter."}, {"numero": 5, "texto": "Il était sans cesse, nuit et jour, dans les sépulcres et sur les montagnes, criant, et se meurtrissant avec des pierres."}, {"numero": 6, "texto": "Ayant vu Jésus de loin, il accourut, se prosterna devant lui,"}, {"numero": 7, "texto": "et s''''écria d''''une voix forte: Qu''''y a-t-il entre moi et toi, Jésus, Fils du Dieu Très-Haut? Je t''''en conjure au nom de Dieu, ne me tourmente pas."}, {"numero": 8, "texto": "Car Jésus lui disait: Sors de cet homme, esprit impur!"}, {"numero": 9, "texto": "Et, il lui demanda: Quel est ton nom? Légion est mon nom, lui répondit-il, car nous sommes plusieurs."}, {"numero": 10, "texto": "Et il le priait instamment de ne pas les envoyer hors du pays."}, {"numero": 11, "texto": "Il y avait là, vers la montagne, un grand troupeau de pourceaux qui paissaient."}, {"numero": 12, "texto": "Et les démons le prièrent, disant: Envoie-nous dans ces pourceaux, afin que nous entrions en eux."}, {"numero": 13, "texto": "Il le leur permit. Et les esprits impurs sortirent, entrèrent dans les pourceaux, et le troupeau se précipita des pentes escarpées dans la mer: il y en avait environ deux mille, et ils se noyèrent dans la mer."}, {"numero": 14, "texto": "Ceux qui les faisaient paître s''''enfuirent, et répandirent la nouvelle dans la ville et dans les campagnes. Les gens allèrent voir ce qui était arrivé."}, {"numero": 15, "texto": "Ils vinrent auprès de Jésus, et ils virent le démoniaque, celui qui avait eu la légion, assis, vêtu, et dans son bon sens; et ils furent saisis de frayeur."}, {"numero": 16, "texto": "Ceux qui avaient vu ce qui s''''était passé leur racontèrent ce qui était arrivé au démoniaque et aux pourceaux."}, {"numero": 17, "texto": "Alors ils se mirent à supplier Jésus de quitter leur territoire."}, {"numero": 18, "texto": "Comme il montait dans la barque, celui qui avait été démoniaque lui demanda la permission de rester avec lui."}, {"numero": 19, "texto": "Jésus ne le lui permit pas, mais il lui dit: Va dans ta maison, vers les tiens, et raconte-leur tout ce que le Seigneur t''''a fait, et comment il a eu pitié de toi."}, {"numero": 20, "texto": "Il s''''en alla, et se mit à publier dans la Décapole tout ce que Jésus avait fait pour lui. Et tous furent dans l''''étonnement."}, {"numero": 21, "texto": "Jésus dans la barque regagna l''''autre rive, où une grande foule s''''assembla près de lui. Il était au bord de la mer."}, {"numero": 22, "texto": "Alors vint un des chefs de la synagogue, nommé Jaïrus, qui, l''''ayant aperçu, se jeta à ses pieds,"}, {"numero": 23, "texto": "et lui adressa cette instante prière: Ma petite fille est à l''''extrémité, viens, impose-lui les mains, afin qu''''elle soit sauvée et qu''''elle vive."}, {"numero": 24, "texto": "Jésus s''''en alla avec lui. Et une grande foule le suivait et le pressait."}, {"numero": 25, "texto": "Or, il y avait une femme atteinte d''''une perte de sang depuis douze ans."}, {"numero": 26, "texto": "Elle avait beaucoup souffert entre les mains de plusieurs médecins, elle avait dépensé tout ce qu''''elle possédait, et elle n''''avait éprouvé aucun soulagement, mais était allée plutôt en empirant."}, {"numero": 27, "texto": "Ayant entendu parler de Jésus, elle vint dans la foule par derrière, et toucha son vêtement."}, {"numero": 28, "texto": "Car elle disait: Si je puis seulement toucher ses vêtements, je serai guérie."}, {"numero": 29, "texto": "Au même instant la perte de sang s''''arrêta, et elle sentit dans son corps qu''''elle était guérie de son mal."}, {"numero": 30, "texto": "Jésus connut aussitôt en lui-même qu''''une force était sortie de lui; et, se retournant au milieu de la foule, il dit: Qui a touché mes vêtements?"}, {"numero": 31, "texto": "Ses disciples lui dirent: Tu vois la foule qui te presse, et tu dis: Qui m''''a touché?"}, {"numero": 32, "texto": "Et il regardait autour de lui, pour voir celle qui avait fait cela."}, {"numero": 33, "texto": "La femme, effrayée et tremblante, sachant ce qui s''''était passé en elle, vint se jeter à ses pieds, et lui dit toute la vérité."}, {"numero": 34, "texto": "Mais Jésus lui dit: Ma fille, ta foi t''''a sauvée; va en paix, et sois guérie de ton mal."}, {"numero": 35, "texto": "Comme il parlait encore, survinrent de chez le chef de la synagogue des gens qui dirent: Ta fille est morte; pourquoi importuner davantage le maître?"}, {"numero": 36, "texto": "Mais Jésus, sans tenir compte de ces paroles, dit au chef de la synagogue: Ne crains pas, crois seulement."}, {"numero": 37, "texto": "Et il ne permit à personne de l''''accompagner, si ce n''''est à Pierre, à Jacques, et à Jean, frère de Jacques."}, {"numero": 38, "texto": "Ils arrivèrent à la maison du chef de la synagogue, où Jésus vit une foule bruyante et des gens qui pleuraient et poussaient de grands cris."}, {"numero": 39, "texto": "Il entra, et leur dit: Pourquoi faites-vous du bruit, et pourquoi pleurez-vous? L''''enfant n''''est pas morte, mais elle dort."}, {"numero": 40, "texto": "Et ils se moquaient de lui. Alors, ayant fait sortir tout le monde, il prit avec lui le père et la mère de l''''enfant, et ceux qui l''''avaient accompagné, et il entra là où était l''''enfant."}, {"numero": 41, "texto": "Il la saisit par la main, et lui dit: Talitha koumi, ce qui signifie: Jeune fille, lève-toi, je te le dis."}, {"numero": 42, "texto": "Aussitôt la jeune fille se leva, et se mit à marcher; car elle avait douze ans. Et ils furent dans un grand étonnement."}, {"numero": 43, "texto": "Jésus leur adressa de fortes recommandations, pour que personne ne sût la chose; et il dit qu''''on donnât à manger à la jeune fille."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 5, 'es', '[{"numero": 1, "texto": "Y VINIERON de la otra parte de la mar á la provincia de los Gadarenos."}, {"numero": 2, "texto": "Y salido él del barco, luego le salió al encuentro, de los sepulcros, un hombre con un espíritu inmundo,"}, {"numero": 3, "texto": "Que tenía domicilio en los sepulcros, y ni aun con cadenas le podía alguien atar;"}, {"numero": 4, "texto": "Porque muchas veces había sido atado con grillos y cadenas, mas las cadenas habían sido hechas pedazos por él, y los grillos desmenuzados; y nadie le podía domar."}, {"numero": 5, "texto": "Y siempre, de día y de noche, andaba dando voces en los montes y en los sepulcros, é hiriéndose con las piedras."}, {"numero": 6, "texto": "Y como vió á Jesús de lejos, corrió, y le adoró."}, {"numero": 7, "texto": "Y clamando á gran voz, dijo: ¿Qué tienes conmigo, Jesús, Hijo del Dios Altísimo? Te conjuro por Dios que no me atormentes."}, {"numero": 8, "texto": "Porque le decía: Sal de este hombre, espíritu inmundo."}, {"numero": 9, "texto": "Y le preguntó: ¿Cómo te llamas? Y respondió diciendo: Legión me llamo; porque somos muchos."}, {"numero": 10, "texto": "Y le rogaba mucho que no le enviase fuera de aquella provincia."}, {"numero": 11, "texto": "Y estaba allí cerca del monte una grande manada de puercos paciendo."}, {"numero": 12, "texto": "Y le rogaron todos los demonios, diciendo: Envíanos á los puercos para que entremos en ellos."}, {"numero": 13, "texto": "Y luego Jesús se lo permitió. Y saliendo aquellos espíritus inmundos, entraron en los puercos, y la manada cayó por un despeñadero en la mar; los cuales eran como dos mil; y en la mar se ahogaron."}, {"numero": 14, "texto": "Y los que apacentaban los puercos huyeron, y dieron aviso en la ciudad y en los campos. Y salieron para ver qué era aquello que había acontecido."}, {"numero": 15, "texto": "Y vienen á Jesús, y ven al que había sido atormentado del demonio, y que había tenido la legión, sentado y vestido, y en su juicio cabal; y tuvieron miedo."}, {"numero": 16, "texto": "Y les contaron los que lo habían visto, cómo había acontecido al que había tenido el demonio, y lo de los puercos."}, {"numero": 17, "texto": "Y comenzaron á rogarle que se fuese de los términos de ellos."}, {"numero": 18, "texto": "Y entrando él en el barco, le rogaba el que había sido fatigado del demonio, para estar con él."}, {"numero": 19, "texto": "Mas Jesús no le permitió, sino le dijo: Vete á tu casa, á los tuyos, y cuéntales cuán grandes cosas el Señor ha hecho contigo, y cómo ha tenido misericordia de ti."}, {"numero": 20, "texto": "Y se fué, y comenzó á publicar en Decápolis cuán grandes cosas Jesús había hecho con él: y todos se maravillaban."}, {"numero": 21, "texto": "Y pasando otra vez Jesús en un barco á la otra parte, se juntó á él gran compañía; y estaba junto á la mar."}, {"numero": 22, "texto": "Y vino uno de los príncipes de la sinagoga, llamado Jairo; y luego que le vió, se postró á sus pies,"}, {"numero": 23, "texto": "Y le rogaba mucho, diciendo: Mi hija está á la muerte: ven y pondrás las manos sobre ella para que sea salva, y vivirá."}, {"numero": 24, "texto": "Y fué con él, y le seguía gran compañía, y le apretaban."}, {"numero": 25, "texto": "Y una mujer que estaba con flujo de sangre doce años hacía,"}, {"numero": 26, "texto": "Y había sufrido mucho de muchos médicos, y había gastado todo lo que tenía, y nada había aprovechado, antes le iba peor,"}, {"numero": 27, "texto": "Como oyó hablar de Jesús, llegó por detrás entre la compañía, y tocó su vestido."}, {"numero": 28, "texto": "Porque decía: Si tocare tan solamente su vestido, seré salva."}, {"numero": 29, "texto": "Y luego la fuente de su sangre se secó; y sintió en el cuerpo que estaba sana de aquel azote."}, {"numero": 30, "texto": "Y luego Jesús, conociendo en sí mismo la virtud que había salido de él, volviéndose á la compañía, dijo: ¿Quién ha tocado mis vestidos?"}, {"numero": 31, "texto": "Y le dijeron sus discípulos: Ves que la multitud te aprieta, y dices: ¿Quién me ha tocado?"}, {"numero": 32, "texto": "Y él miraba alrededor para ver á la que había hecho esto."}, {"numero": 33, "texto": "Entonces la mujer, temiendo y temblando, sabiendo lo que en sí había sido hecho, vino y se postró delante de él, y le dijo toda la verdad."}, {"numero": 34, "texto": "Y él le dijo: Hija, tu fe te ha hecho salva: ve en paz, y queda sana de tu azote."}, {"numero": 35, "texto": "Hablando aún él, vinieron de casa del príncipe de la sinagoga, diciendo: Tu hija es muerta; ¿para qué fatigas más al Maestro?"}, {"numero": 36, "texto": "Mas luego Jesús, oyendo esta razón que se decía, dijo al príncipe de la sinagoga: No temas, cree solamente."}, {"numero": 37, "texto": "Y no permitió que alguno viniese tras él sino Pedro, y Jacobo, y Juan hermano de Jacobo."}, {"numero": 38, "texto": "Y vino á casa del príncipe de la sinagoga, y vió el alboroto, los que lloraban y gemían mucho."}, {"numero": 39, "texto": "Y entrando, les dice: ¿Por qué alborotáis y lloráis? La muchacha no es muerta, mas duerme."}, {"numero": 40, "texto": "Y hacían burla de él: mas él, echados fuera todos, toma al padre y á la madre de la muchacha, y á los que estaban con él, y entra donde la muchacha estaba."}, {"numero": 41, "texto": "Y tomando la mano de la muchacha, le dice: Talitha cumi; que es, si lo interpretares: Muchacha, á ti digo, levántate."}, {"numero": 42, "texto": "Y luego la muchacha se levantó, y andaba; porque tenía doce años. Y se espantaron de grande espanto."}, {"numero": 43, "texto": "Mas él les mandó mucho que nadie lo supiese, y dijo que le diesen de comer."}]'::jsonb, 'Reina-Valera 1909')
